export const VOCABULARY=[{"word":"good","pos":"adjective","chinese":"好的；好","level":"A1","sentences":[{"en":"This coffee is really good — what blend is it?","zh":"這咖啡真的很好喝——是什麼配方？"},{"en":"You did a good job on that presentation.","zh":"你的報告做得很好。"},{"en":"Is the weather good there right now?","zh":"那裡的天氣現在好嗎？"},{"en":"She has a good heart — always thinking of others.","zh":"她心地很好——總是想到別人。"},{"en":"That is a good idea. Let's try it.","zh":"那是個好主意，我們試試看。"},{"en":"I do not feel so good today — might be coming down with something.","zh":"我今天感覺不太好——可能要生病了。"},{"en":"He speaks good English for someone who just started.","zh":"對於剛開始學的人來說，他的英文說得很好。"},{"en":"That film was really good — I did not expect it.","zh":"那部電影真的很好看——我沒想到。"},{"en":"Good morning! How did you sleep?","zh":"早安！你睡得怎麼樣？"},{"en":"It feels good to finish what you started.","zh":"完成你開始的事情感覺很好。"}]},{"word":"nice","pos":"adjective","chinese":"好的；友善的","level":"A1","sentences":[{"en":"That is such a nice thing to say — thank you.","zh":"說這話真的很好——謝謝你。"},{"en":"It was nice seeing you again after so long.","zh":"這麼久之後再見到你真的很好。"},{"en":"She is really nice — everyone gets along with her.","zh":"她真的很友善——每個人都和她相處得很好。"},{"en":"This is a nice area — very quiet and clean.","zh":"這是個不錯的地方——很安靜很乾淨。"},{"en":"Have a nice weekend! See you Monday.","zh":"祝你週末愉快！週一見。"},{"en":"The weather is so nice today — let's sit outside.","zh":"今天天氣真好——我們坐外面吧。"},{"en":"It would be nice to travel again someday.","zh":"希望有一天能再去旅行。"},{"en":"That is a nice colour on you.","zh":"那個顏色很適合你。"},{"en":"He has a nice way of explaining complicated things.","zh":"他有一種很好的方式來解釋複雜的事情。"},{"en":"It is nice to have someone to talk to.","zh":"有人可以傾訴真的很好。"}]},{"word":"great","pos":"adjective","chinese":"很棒的","level":"A1","sentences":[{"en":"That sounds like a great idea — count me in.","zh":"那聽起來是個好主意——算我一個。"},{"en":"She did a great job under a lot of pressure.","zh":"她在很大壓力下表現得很棒。"},{"en":"We had a great time at the festival last weekend.","zh":"我們上週末在節慶上玩得很開心。"},{"en":"I feel great today — slept well and ate well.","zh":"我今天感覺很棒——睡得好，吃得好。"},{"en":"That is great news! I am so happy for you.","zh":"那是個好消息！我真的為你高興。"},{"en":"He is a great listener — never interrupts.","zh":"他是個很好的傾聽者——從不打斷。"},{"en":"The view from up here is great.","zh":"從這上面看的風景很棒。"},{"en":"It is great to finally meet you in person.","zh":"終於見到你本人真的很好。"},{"en":"She always has great recommendations for food.","zh":"她在食物方面總是有很棒的推薦。"},{"en":"Being in a great mood today — no reason really.","zh":"今天心情很好——沒有特別的原因。"}]},{"word":"bad","pos":"adjective","chinese":"壞的；不好的","level":"A1","sentences":[{"en":"I had a really bad day — everything went wrong.","zh":"我今天真的很倒霉——什麼都出了問題。"},{"en":"That is bad news — I am sorry to hear that.","zh":"那是個壞消息——很遺憾聽到這個。"},{"en":"She is not bad at cooking — just needs more practice.","zh":"她的廚藝不差——只是需要更多練習。"},{"en":"I feel bad about missing your birthday.","zh":"我對錯過你的生日感到很抱歉。"},{"en":"That decision turned out to be a bad one.","zh":"那個決定結果是個壞決定。"},{"en":"The traffic was so bad I was an hour late.","zh":"交通太糟了，我遲到了一個小時。"},{"en":"He had a bad week — give him some space.","zh":"他這週很糟糕——給他一些空間。"},{"en":"Bad weather always puts me in a bad mood.","zh":"壞天氣總是讓我心情不好。"},{"en":"It is not as bad as it seems from the outside.","zh":"它不像從外面看起來那麼糟。"},{"en":"She turned a bad situation into something positive.","zh":"她把一個糟糕的情況轉變成了積極的事情。"}]},{"word":"hot","pos":"adjective","chinese":"熱的；辣的","level":"A1","sentences":[{"en":"It is so hot today — I cannot go outside.","zh":"今天真的很熱——我沒辦法出去。"},{"en":"Be careful — the plate is still hot.","zh":"小心——盤子還是熱的。"},{"en":"She drinks hot water every morning before coffee.","zh":"她每天早上喝熱水，再喝咖啡。"},{"en":"Is that too hot? I can wait for it to cool down.","zh":"那個太燙嗎？我可以等它冷卻。"},{"en":"The soup is piping hot — give it a minute.","zh":"湯非常燙——等一下再喝。"},{"en":"I love hot showers — especially in winter.","zh":"我喜歡熱水澡——尤其是在冬天。"},{"en":"That chilli was so hot my eyes watered.","zh":"那個辣椒太辣了，我的眼睛都流淚了。"},{"en":"Can I get a hot chocolate, please?","zh":"我可以要一杯熱巧克力嗎？"},{"en":"The room gets hot in summer without air conditioning.","zh":"夏天沒有空調，房間會變得很熱。"},{"en":"Hot tea on a cold day is the best.","zh":"寒冷的日子裡喝熱茶是最好的。"}]},{"word":"cold","pos":"adjective","chinese":"冷的；寒冷的","level":"A1","sentences":[{"en":"I am so cold — where is my jacket?","zh":"我好冷——我的夾克在哪裡？"},{"en":"The water is cold — too cold to swim.","zh":"水很冷——太冷了，不能游泳。"},{"en":"She caught a cold from working in the rain.","zh":"她因在雨中工作而感冒了。"},{"en":"Can I have a cold drink? I am thirsty.","zh":"我可以要一杯冷飲嗎？我渴了。"},{"en":"It gets very cold here in January.","zh":"這裡一月份會變得很冷。"},{"en":"I left the window open and now it is freezing cold inside.","zh":"我把窗戶開著，現在室內冰冷。"},{"en":"The leftovers are cold — should I heat them up?","zh":"剩菜是冷的——我應該加熱嗎？"},{"en":"She does not mind the cold — she loves winter.","zh":"她不介意寒冷——她喜歡冬天。"},{"en":"My hands are so cold I can barely type.","zh":"我的手太冷了，幾乎無法打字。"},{"en":"Cold weather makes me want to stay home.","zh":"寒冷的天氣讓我想待在家裡。"}]},{"word":"want","pos":"verb","chinese":"想要","level":"A1","sentences":[{"en":"I want to travel more this year.","zh":"我今年想要多旅行。"},{"en":"What do you want for dinner tonight?","zh":"你今晚想吃什麼？"},{"en":"She wants to change jobs but is not sure where to start.","zh":"她想換工作，但不確定從哪裡開始。"},{"en":"I want to tell you something but I am not sure how.","zh":"我想告訴你一些事情，但我不確定怎麼說。"},{"en":"Do you want another cup of coffee?","zh":"你想再來一杯咖啡嗎？"},{"en":"He wants to learn how to cook.","zh":"他想學如何烹飪。"},{"en":"I do not want to be late — let's leave now.","zh":"我不想遲到——我們現在走吧。"},{"en":"All I want is a quiet evening at home.","zh":"我想要的只是一個安靜的居家夜晚。"},{"en":"She wants more time for herself.","zh":"她想要更多屬於自己的時間。"},{"en":"Just say what you want — I will not judge.","zh":"就說你想要什麼——我不會評判你。"}]},{"word":"need","pos":"verb","chinese":"需要","level":"A1","sentences":[{"en":"I need to call my parents — it has been a while.","zh":"我需要打電話給我的父母——已經有一段時間了。"},{"en":"Do you need help with that?","zh":"你需要幫忙嗎？"},{"en":"She needs more time to think about her decision.","zh":"她需要更多時間來思考她的決定。"},{"en":"I need a break — I have been working all day.","zh":"我需要休息——我工作了一整天。"},{"en":"We need to talk. Can you call me later?","zh":"我們需要談談，你稍後可以打電話給我嗎？"},{"en":"He needs reminding or he forgets everything.","zh":"他需要有人提醒，否則他會忘記一切。"},{"en":"I do not need advice — I just need someone to listen.","zh":"我不需要建議——我只是需要有人傾聽。"},{"en":"What do you need from the supermarket?","zh":"你需要從超市買什麼？"},{"en":"She needs a change of scenery — same place every day is hard.","zh":"她需要換個環境——每天待在同一個地方很難。"},{"en":"I need coffee to function in the morning.","zh":"我早上需要咖啡才能運作。"}]},{"word":"love","pos":"verb/noun","chinese":"愛；喜愛","level":"A1","sentences":[{"en":"I love the smell of coffee in the morning.","zh":"我喜歡早晨咖啡的香味。"},{"en":"She loves her job — you can see it in everything she does.","zh":"她熱愛她的工作——從她做的每一件事都能看出來。"},{"en":"I love spending lazy weekends at home.","zh":"我喜歡在家度過慵懶的週末。"},{"en":"He told her he loved her for the first time.","zh":"他第一次告訴她他愛她。"},{"en":"I love this song — turn it up!","zh":"我喜歡這首歌——把音量調大！"},{"en":"She fell in love with the city from the first day.","zh":"她從第一天就愛上了這座城市。"},{"en":"I love how honest you are with me.","zh":"我喜歡你對我如此誠實。"},{"en":"We love going to that café on Sunday mornings.","zh":"我們喜歡在週日早上去那家咖啡廳。"},{"en":"I love you — not just as a saying, but for real.","zh":"我愛你——不只是說說，是真的。"},{"en":"She loves cooking for people — it is how she shows care.","zh":"她喜歡為別人做飯——那是她表達關懷的方式。"}]},{"word":"like","pos":"verb","chinese":"喜歡","level":"A1","sentences":[{"en":"I like this place — can we come back here?","zh":"我喜歡這個地方——我們可以再來嗎？"},{"en":"Do you like spicy food or do you prefer mild?","zh":"你喜歡辣的食物還是淡的？"},{"en":"She likes working alone — gets more done that way.","zh":"她喜歡獨自工作——那樣效率更高。"},{"en":"I like how you explained that — very clear.","zh":"我喜歡你解釋那個的方式——非常清楚。"},{"en":"He likes simple things — a good book and a quiet evening.","zh":"他喜歡簡單的事情——一本好書和一個安靜的夜晚。"},{"en":"I did not like the movie — not my type.","zh":"我不喜歡那部電影——不是我的類型。"},{"en":"What kind of music do you like?","zh":"你喜歡什麼類型的音樂？"},{"en":"I like the idea but I am not sure about the timing.","zh":"我喜歡這個想法，但我不確定時機是否合適。"},{"en":"She likes being around people who make her laugh.","zh":"她喜歡和讓她發笑的人在一起。"},{"en":"Do you like your new flat? Is it comfortable?","zh":"你喜歡你的新公寓嗎？舒適嗎？"}]},{"word":"think","pos":"verb","chinese":"認為；想","level":"A1","sentences":[{"en":"I think we should leave before it gets dark.","zh":"我認為我們應該在天黑前離開。"},{"en":"She thinks too much and ends up doing nothing.","zh":"她想太多了，結果什麼都沒做。"},{"en":"What do you think of the new design?","zh":"你覺得新設計怎麼樣？"},{"en":"I did not think it would be this hard.","zh":"我沒想到會這麼難。"},{"en":"He thinks deeply before he speaks — I admire that.","zh":"他說話之前深思熟慮——我很欽佩這一點。"},{"en":"I think she is right but I am not sure.","zh":"我認為她是對的，但我不確定。"},{"en":"Do not overthink it — just decide.","zh":"不要想太多——就做決定吧。"},{"en":"I think we need to change the plan.","zh":"我認為我們需要改變計畫。"},{"en":"She thinks of everyone else before herself.","zh":"她總是先考慮別人，再考慮自己。"},{"en":"Just let me think for a moment.","zh":"讓我想一下。"}]},{"word":"feel","pos":"verb","chinese":"感覺；感受","level":"A1","sentences":[{"en":"I feel a lot better after talking to you.","zh":"和你聊過之後我感覺好多了。"},{"en":"She feels anxious before big presentations.","zh":"她在大型報告前感到焦慮。"},{"en":"How do you feel about the changes?","zh":"你對這些改變有什麼感受？"},{"en":"I feel like something is off today but I cannot explain it.","zh":"我今天感覺有什麼不對勁，但說不清楚。"},{"en":"He feels most alive when he is creating.","zh":"他在創作時感到最有活力。"},{"en":"I feel proud of how far I have come.","zh":"我為自己走了多遠感到驕傲。"},{"en":"She feels more like herself after some alone time.","zh":"獨處一段時間後，她感覺更像自己了。"},{"en":"Do not ignore how you feel — it matters.","zh":"不要忽視你的感受——那很重要。"},{"en":"I feel grateful for small things lately.","zh":"最近我對小事感到感激。"},{"en":"Feeling understood is one of the best feelings.","zh":"感到被理解是最好的感受之一。"}]},{"word":"know","pos":"verb","chinese":"知道；了解","level":"A1","sentences":[{"en":"I do not know the answer — let me look it up.","zh":"我不知道答案——讓我查一下。"},{"en":"She knows everyone in the neighbourhood.","zh":"她認識附近所有的人。"},{"en":"I know I should go to bed earlier — I just cannot.","zh":"我知道我應該早點睡——但我就是做不到。"},{"en":"Do you know a good dentist in this area?","zh":"你知道這一帶有好的牙醫嗎？"},{"en":"He knows a lot about history — ask him anything.","zh":"他對歷史了解很多——問他什麼都可以。"},{"en":"I know how you feel — I went through the same thing.","zh":"我了解你的感受——我也經歷過同樣的事情。"},{"en":"She does not know what she wants and that is okay.","zh":"她不知道自己想要什麼，這沒關係。"},{"en":"I know it sounds crazy but it actually worked.","zh":"我知道聽起來很瘋狂，但它真的奏效了。"},{"en":"You never know until you try.","zh":"不試永遠不知道。"},{"en":"I knew this would happen — I had a feeling.","zh":"我就知道這會發生——我有預感。"}]},{"word":"say","pos":"verb","chinese":"說","level":"A1","sentences":[{"en":"What did she say about the meeting?","zh":"她對這個會議說了什麼？"},{"en":"He said something really kind and it stayed with me.","zh":"他說了一些非常友善的話，一直留在我心裡。"},{"en":"I did not know what to say so I said nothing.","zh":"我不知道說什麼，所以什麼都沒說。"},{"en":"She always says exactly what she thinks.","zh":"她總是直接說出她的想法。"},{"en":"Say it again — I could not hear you.","zh":"再說一遍——我聽不到你說什麼。"},{"en":"They say the best things in life are free.","zh":"人們說生命中最美好的事情是免費的。"},{"en":"I said I was sorry and I meant it.","zh":"我說了對不起，我是認真的。"},{"en":"What are you trying to say? Just say it.","zh":"你想說什麼？就說出來。"},{"en":"She said yes and everything changed.","zh":"她說了好，一切都改變了。"},{"en":"I said no and felt completely fine about it.","zh":"我說了不，感覺完全沒問題。"}]},{"word":"go","pos":"verb","chinese":"去；走","level":"A1","sentences":[{"en":"Let us go before it gets crowded.","zh":"我們去吧，在變得擁擠之前。"},{"en":"Where do you want to go this weekend?","zh":"你這個週末想去哪裡？"},{"en":"She goes for a run every morning without fail.","zh":"她每天早上都固定去跑步。"},{"en":"I did not want to go but I am glad I did.","zh":"我當初不想去，但很高興我去了。"},{"en":"How did the interview go?","zh":"面試進行得怎樣？"},{"en":"Go on — tell me what happened.","zh":"繼續——告訴我發生了什麼。"},{"en":"Time goes so fast when I am busy.","zh":"我忙的時候時間過得好快。"},{"en":"She goes to the library every Sunday.","zh":"她每個週日都去圖書館。"},{"en":"Let it go — it is not worth the stress.","zh":"放手吧——不值得費心。"},{"en":"Everything is going to be okay.","zh":"一切都會沒事的。"}]},{"word":"come","pos":"verb","chinese":"來；到來","level":"A1","sentences":[{"en":"Can you come over later? I need help.","zh":"你稍後可以過來嗎？我需要幫忙。"},{"en":"She came all the way just to check on me.","zh":"她特地趕來只是為了關心我。"},{"en":"Come and sit with me for a bit.","zh":"過來陪我坐一會兒。"},{"en":"I did not come here to argue.","zh":"我來這裡不是為了爭論。"},{"en":"Success does not come overnight.","zh":"成功不是一蹴而就的。"},{"en":"He came back changed after his year abroad.","zh":"他在國外一年後回來，已經變了一個人。"},{"en":"Come on — we are going to be late.","zh":"快點——我們要遲到了。"},{"en":"When the opportunity comes, take it.","zh":"機會來臨時，就抓住它。"},{"en":"She comes to mind when I see anything beautiful.","zh":"每當我看到美麗的事物，就會想起她。"},{"en":"Spring always comes — even after the hardest winter.","zh":"春天總會來臨——即使在最嚴酷的冬天之後。"}]},{"word":"take","pos":"verb","chinese":"拿；帶；需要","level":"A1","sentences":[{"en":"Can you take a photo of us?","zh":"你能幫我們拍張照嗎？"},{"en":"It takes time to build real trust.","zh":"建立真正的信任需要時間。"},{"en":"She took a deep breath before speaking.","zh":"她在說話前深吸一口氣。"},{"en":"Take your time — there is no rush.","zh":"慢慢來——不用急。"},{"en":"I take the bus every morning to work.","zh":"我每天早上坐公車上班。"},{"en":"He took a chance and it paid off.","zh":"他冒了一個險，結果得到了回報。"},{"en":"Can I take a look at that?","zh":"我可以看看那個嗎？"},{"en":"She takes great care of the people around her.","zh":"她非常照顧身邊的人。"},{"en":"It took me a year to feel settled here.","zh":"我花了一年時間才在這裡安定下來。"},{"en":"Take it easy — you have done enough for today.","zh":"放鬆一下——你今天已經做得夠多了。"}]},{"word":"make","pos":"verb","chinese":"做；製作；使","level":"A1","sentences":[{"en":"I will make dinner tonight — you rest.","zh":"我今晚做晚飯——你休息。"},{"en":"She makes everything look easy.","zh":"她讓一切看起來都很容易。"},{"en":"What makes you happy on a regular day?","zh":"在平常的日子裡，什麼讓你快樂？"},{"en":"I made a mistake and I own it.","zh":"我犯了一個錯誤，我承擔責任。"},{"en":"Can you make time to meet this week?","zh":"你這週有時間見面嗎？"},{"en":"He makes people feel welcome wherever he goes.","zh":"他走到哪裡都讓人感到受歡迎。"},{"en":"I am trying to make better decisions.","zh":"我在努力做出更好的決定。"},{"en":"She made a big change and never looked back.","zh":"她做了一個大改變，從此再也沒有回頭看。"},{"en":"Make the most of every moment.","zh":"充分利用每一個時刻。"},{"en":"That made my whole day — thank you.","zh":"那讓我整天都很開心——謝謝你。"}]},{"word":"give","pos":"verb","chinese":"給","level":"A1","sentences":[{"en":"She gave me the best advice I have ever received.","zh":"她給了我我曾收到過的最好的建議。"},{"en":"I want to give back to my community.","zh":"我想回饋我的社區。"},{"en":"Can you give me a hand with this?","zh":"你能幫我一下嗎？"},{"en":"He gives everything he has to the people he loves.","zh":"他把他所有的一切都給了他愛的人。"},{"en":"I gave up on that habit and do not regret it.","zh":"我放棄了那個習慣，不後悔。"},{"en":"Give it time — things will improve.","zh":"給它時間——事情會改善的。"},{"en":"She gave me a hug and I needed it.","zh":"她給了我一個擁抱，我很需要那個。"},{"en":"I will give it another try — one more chance.","zh":"我會再試一次——再給一次機會。"},{"en":"He gives the best gifts — always thoughtful.","zh":"他送的禮物最好——總是很用心。"},{"en":"Give yourself credit for how far you have come.","zh":"為你走過的路給自己一些認可。"}]},{"word":"get","pos":"verb","chinese":"得到；變得","level":"A1","sentences":[{"en":"I got a call from an old friend today.","zh":"我今天接到了一個老朋友的電話。"},{"en":"She gets nervous before every performance.","zh":"她每次表演前都會緊張。"},{"en":"Can you get me a coffee while you are up?","zh":"你站起來的時候可以幫我拿一杯咖啡嗎？"},{"en":"I am getting better at saying no.","zh":"我越來越擅長說不了。"},{"en":"He gets along with everyone — very likeable.","zh":"他和所有人都相處得很好——非常討人喜歡。"},{"en":"We are getting closer to our goal.","zh":"我們正在接近我們的目標。"},{"en":"I got what I needed from that conversation.","zh":"我從那次對話中得到了我需要的東西。"},{"en":"She gets up at five every morning — impressive.","zh":"她每天早上五點起床——令人印象深刻。"},{"en":"Get some rest — you look exhausted.","zh":"好好休息——你看起來很疲憊。"},{"en":"I cannot get this song out of my head.","zh":"我腦海中一直循環著這首歌。"}]},{"word":"see","pos":"verb","chinese":"看見;見到","level":"A1","sentences":[{"en":"I see what you mean now — that makes sense.","zh":"我現在明白你的意思了——這說得通。"},{"en":"Can you see the mountains from your window?","zh":"你從窗戶能看到山嗎？"},{"en":"She saw him across the room and smiled.","zh":"她在房間另一頭看到他，笑了。"},{"en":"Let me see — where did I put my keys?","zh":"讓我想想——我把鑰匙放在哪裡了？"},{"en":"I see her every Tuesday at the café.","zh":"我每個星期二在咖啡廳見到她。"},{"en":"Do you see that building? That is where I work.","zh":"你看到那棟大樓嗎？那是我工作的地方。"},{"en":"I saw the most beautiful sunset yesterday.","zh":"我昨天看到了最美麗的日落。"},{"en":"He could not see the screen from where he was sitting.","zh":"他從他坐的地方看不到螢幕。"},{"en":"See you tomorrow!","zh":"明天見！"},{"en":"I see your point — let me think about it.","zh":"我明白你的觀點——讓我想一想。"}]},{"word":"look","pos":"verb","chinese":"看；看起來","level":"A1","sentences":[{"en":"You look really tired — are you okay?","zh":"你看起來真的很累——你還好嗎？"},{"en":"Look at this photo — is that not beautiful?","zh":"看看這張照片——是不是很漂亮？"},{"en":"She looks exactly like her mother.","zh":"她看起來和她媽媽一模一樣。"},{"en":"Can you look this up for me? I do not know the word.","zh":"你能幫我查一下嗎？我不認識這個詞。"},{"en":"He looked at her and smiled without saying anything.","zh":"他看著她，什麼都沒說，微笑了。"},{"en":"Look out! There is a step there.","zh":"小心！那裡有一個臺階。"},{"en":"This looks delicious — what is it?","zh":"這看起來很好吃——這是什麼？"},{"en":"I looked everywhere but could not find it.","zh":"我到處找，但找不到。"},{"en":"Do not look at me like that — I did nothing wrong.","zh":"不要那樣看著我——我沒有做錯任何事。"},{"en":"You should look at this — it is really interesting.","zh":"你應該看看這個——真的很有趣。"}]},{"word":"hear","pos":"verb","chinese":"聽到;聽說","level":"A1","sentences":[{"en":"Did you hear that? It sounded like someone knocked.","zh":"你聽到了嗎？聽起來像是有人在敲。"},{"en":"I heard she got promoted — good for her.","zh":"我聽說她升職了——替她高興。"},{"en":"Can you speak up? I cannot hear you well.","zh":"你能大聲點嗎？我聽不清楚你說話。"},{"en":"She heard the news and immediately called me.","zh":"她聽到消息後立刻打電話給我。"},{"en":"I have heard that restaurant is amazing.","zh":"我聽說那家餐廳很棒。"},{"en":"He heard her singing and stopped to listen.","zh":"他聽到她在唱歌，停下來聆聽。"},{"en":"I do not want to hear any excuses.","zh":"我不想聽任何藉口。"},{"en":"Have you heard from her recently?","zh":"你最近有她的消息嗎？"},{"en":"I hear you — that sounds really frustrating.","zh":"我明白你——那聽起來真的很令人沮喪。"},{"en":"She did not hear her alarm and woke up late.","zh":"她沒有聽到鬧鐘，起床晚了。"}]},{"word":"help","pos":"verb/noun","chinese":"幫助；幫忙","level":"A1","sentences":[{"en":"Can you help me with this? I am stuck.","zh":"你能幫我解決這個嗎？我卡住了。"},{"en":"She helped me move last weekend — such a good friend.","zh":"她上週末幫我搬家——真是個好朋友。"},{"en":"Is there anything I can help with?","zh":"有什麼我可以幫忙的嗎？"},{"en":"That advice really helped — thank you.","zh":"那個建議真的很有幫助——謝謝你。"},{"en":"He helps his grandmother with her shopping every week.","zh":"他每週幫祖母購物。"},{"en":"I cannot help how I feel about it.","zh":"我無法控制我對此的感受。"},{"en":"Please help yourself to food and drinks.","zh":"請自便，享用食物和飲料。"},{"en":"She needs help — do not pretend you do not see it.","zh":"她需要幫助——不要假裝你看不見。"},{"en":"A good friend does not wait to be asked for help.","zh":"好朋友不會等到被要求才幫忙。"},{"en":"How can I help you today?","zh":"我今天怎樣幫到你？"}]},{"word":"ask","pos":"verb","chinese":"問；請求","level":"A1","sentences":[{"en":"Can I ask you something personal?","zh":"我能問你一個私人問題嗎？"},{"en":"She asked for help and was not ashamed of it.","zh":"她請求幫助，並不為此感到羞恥。"},{"en":"He asked the question everyone was thinking.","zh":"他問了每個人都在想的問題。"},{"en":"Do not be afraid to ask when you do not understand.","zh":"不懂的時候不要害怕開口問。"},{"en":"I asked her if she was okay and she just shrugged.","zh":"我問她是否還好，她只是聳聳肩。"},{"en":"She asked to leave early — the boss said yes.","zh":"她請求提早離開——老闆答應了。"},{"en":"Ask and you might just get what you need.","zh":"開口問，你可能會得到你需要的。"},{"en":"I am just asking — no pressure at all.","zh":"我只是問問——完全沒有壓力。"},{"en":"He asked for a second opinion before deciding.","zh":"他在決定之前請求了第二意見。"},{"en":"If you do not ask, the answer is always no.","zh":"如果你不開口問，答案永遠是不。"}]},{"word":"tell","pos":"verb","chinese":"告訴；說明","level":"A1","sentences":[{"en":"Tell me what happened — from the beginning.","zh":"告訴我發生了什麼——從頭說起。"},{"en":"She told him the truth and it changed everything.","zh":"她告訴了他真相，這改變了一切。"},{"en":"I cannot tell if he is serious or joking.","zh":"我分不清楚他是認真的還是在開玩笑。"},{"en":"Can you tell me how to get there from here?","zh":"你能告訴我怎樣從這裡到那裡嗎？"},{"en":"He told me something I will never forget.","zh":"他告訴了我一些我永遠不會忘記的事情。"},{"en":"Tell me about yourself — what do you enjoy?","zh":"告訴我關於你的事情——你喜歡什麼？"},{"en":"I told you so — I knew this would happen.","zh":"我就說吧——我知道這會發生。"},{"en":"She told a story that made everyone laugh.","zh":"她講了一個讓所有人都笑了的故事。"},{"en":"You can tell a lot about a person by how they treat waiters.","zh":"你可以從一個人對待服務員的方式看出很多事情。"},{"en":"He told her he would be late but she forgot.","zh":"他告訴她他會遲到，但她忘了。"}]},{"word":"try","pos":"verb","chinese":"嘗試；試試","level":"A1","sentences":[{"en":"You will not know until you try.","zh":"你嘗試之前不會知道。"},{"en":"She tried a new recipe and it turned out perfectly.","zh":"她嘗試了一個新食譜，結果做得非常完美。"},{"en":"I tried to explain but he was not listening.","zh":"我試著解釋，但他沒有在聽。"},{"en":"Try not to worry too much — it will work out.","zh":"試著不要太擔心——事情會好起來的。"},{"en":"He tried three times before getting it right.","zh":"他嘗試了三次才做對。"},{"en":"Have you tried talking to her about it?","zh":"你有沒有嘗試和她談談這件事？"},{"en":"I always try to be on time — I hate being late.","zh":"我總是努力準時——我討厭遲到。"},{"en":"She tried something new and discovered a passion.","zh":"她嘗試了新事物，發現了一個熱情。"},{"en":"At least I tried — no regrets.","zh":"至少我嘗試了——沒有遺憾。"},{"en":"Try again. You were so close.","zh":"再試一次，你非常接近了。"}]},{"word":"talk","pos":"verb","chinese":"說話；聊天","level":"A1","sentences":[{"en":"We need to talk — do you have a few minutes?","zh":"我們需要聊聊——你有幾分鐘嗎？"},{"en":"She talks to her plants. I respect that.","zh":"她和她的植物說話，我很欣賞。"},{"en":"Can we talk about this later — I am in a meeting.","zh":"我們可以晚點聊嗎——我在開會。"},{"en":"He is the kind of person who talks to everyone.","zh":"他是那種和所有人說話的人。"},{"en":"I love talking to you — time flies.","zh":"我喜歡和你聊天——時間飛逝。"},{"en":"She talked about her trip for an hour and I loved every minute.","zh":"她談了一個小時的旅行，我每一分鐘都很享受。"},{"en":"Do not talk to me before my coffee.","zh":"在我喝咖啡之前不要和我說話。"},{"en":"Talking through a problem helps more than just thinking about it.","zh":"把問題說出來比只是想更有幫助。"},{"en":"We talked until three in the morning and did not notice the time.","zh":"我們聊到凌晨三點，沒有注意到時間。"},{"en":"He talks less but says more — I admire that.","zh":"他說的少，但說的更有意義——我很欣賞這一點。"}]},{"word":"move","pos":"verb","chinese":"移動；搬家","level":"A1","sentences":[{"en":"Can you move a little to the left? You are blocking the view.","zh":"你能往左移一點嗎？你擋住了視線。"},{"en":"She moved to a new city and started fresh.","zh":"她搬到了一個新城市，重新開始。"},{"en":"That speech moved me — I actually cried.","zh":"那篇演講讓我很感動——我真的哭了。"},{"en":"He moves so fast — I can barely keep up.","zh":"他動作那麼快——我幾乎跟不上。"},{"en":"I need to move this meeting — can we push it back?","zh":"我需要調整這個會議——我們能推遲嗎？"},{"en":"They moved in together after two years.","zh":"他們在兩年後搬到了一起。"},{"en":"Move on — dwelling on it will not help.","zh":"繼續前進——糾結於此沒有幫助。"},{"en":"She was moved by the kindness of a stranger.","zh":"她被一個陌生人的善意感動了。"},{"en":"He moved slowly but with complete intention.","zh":"他動作緩慢，但非常有目的性。"},{"en":"Moving is stressful but starting somewhere new is exciting.","zh":"搬家很有壓力，但在新的地方開始是令人興奮的。"}]},{"word":"open","pos":"verb/adjective","chinese":"打開；開放的","level":"A1","sentences":[{"en":"Can you open the window? It is stuffy in here.","zh":"你能打開窗戶嗎？這裡悶。"},{"en":"The café opens at seven — are you an early riser?","zh":"咖啡廳七點開門——你是早起的人嗎？"},{"en":"She is very open about her feelings — I respect that.","zh":"她對她的感受非常開放——我很尊重這一點。"},{"en":"He opened the email and stared at the screen for a while.","zh":"他打開了電子郵件，盯著螢幕看了一會兒。"},{"en":"Keep an open mind — you might like it.","zh":"保持開放的心態——你可能會喜歡它。"},{"en":"She opened up to me and I felt honoured.","zh":"她向我打開心扉，我感到很榮幸。"},{"en":"Are you open this weekend or fully booked?","zh":"你這個週末有空還是完全排滿了？"},{"en":"He opened the door for her — small gesture, big impact.","zh":"他為她開門——小動作，大影響。"},{"en":"I like restaurants with an open kitchen — you see everything.","zh":"我喜歡有開放式廚房的餐廳——你可以看到一切。"},{"en":"Opening up is scary but it creates real connection.","zh":"敞開心扉是可怕的，但它建立了真實的連結。"}]},{"word":"close","pos":"verb/adjective","chinese":"關閉；關上；親密的","level":"A1","sentences":[{"en":"Can you close the door behind you?","zh":"你能幫我帶上門嗎？"},{"en":"The shop closes at nine on weekdays.","zh":"這家店工作日九點關門。"},{"en":"They are very close — more like siblings than friends.","zh":"他們非常親密——與其說是朋友，不如說是兄弟姐妹。"},{"en":"Close your eyes and take a deep breath.","zh":"閉上眼睛，深深地吸一口氣。"},{"en":"The deadline is close — we need to hurry.","zh":"截止日期快到了——我們需要加快速度。"},{"en":"She was close to finishing when the power cut out.","zh":"她快要完成了，這時停電了。"},{"en":"He sat close and spoke softly.","zh":"他坐得很近，輕聲說話。"},{"en":"Closing a chapter is hard but necessary to start a new one.","zh":"結束一個章節很難，但對於開始新章節是必要的。"},{"en":"They have been close friends since childhood.","zh":"他們從童年起就是親密的朋友。"},{"en":"That was close! You almost missed the train.","zh":"好險！你差點錯過了火車。"}]},{"word":"wait","pos":"verb","chinese":"等待；等","level":"A1","sentences":[{"en":"I have been waiting for thirty minutes — where are you?","zh":"我已經等了三十分鐘了——你在哪裡？"},{"en":"Good things are worth waiting for.","zh":"好的事情值得等待。"},{"en":"She waited patiently without complaining once.","zh":"她耐心地等著，一次也沒抱怨。"},{"en":"Wait — let me explain before you make a decision.","zh":"等等——在你做決定之前讓我解釋。"},{"en":"I cannot wait to see you again.","zh":"我迫不及待地想再見到你。"},{"en":"He waited in line for two hours for that new café.","zh":"他為了那家新咖啡廳排了兩個小時的隊。"},{"en":"Do not wait for the perfect moment — make the moment.","zh":"不要等待完美的時機——創造時機。"},{"en":"I am waiting on a reply — I will know tomorrow.","zh":"我在等回覆——明天就會知道了。"},{"en":"She told me to wait outside but that was an hour ago.","zh":"她叫我在外面等，但那是一個小時前的事了。"},{"en":"Waiting is a skill — some people never master it.","zh":"等待是一種技能——有些人永遠無法掌握它。"}]},{"word":"leave","pos":"verb","chinese":"離開；留下","level":"A1","sentences":[{"en":"I have to leave now — early morning tomorrow.","zh":"我現在要走了——明天一早有事。"},{"en":"She left her job and never looked back.","zh":"她辭掉了工作，再也沒有回頭看。"},{"en":"Do not leave without saying goodbye.","zh":"不要不說再見就離開。"},{"en":"He left his phone at the restaurant — had to go back.","zh":"他把手機落在了餐廳——不得不回去拿。"},{"en":"Leave it — it is not worth your energy.","zh":"算了——不值得你花精力。"},{"en":"She always leaves things better than she found them.","zh":"她總是讓事情比她發現時更好。"},{"en":"I left the light on — again.","zh":"我又忘記關燈了。"},{"en":"Can we leave by six to beat the traffic?","zh":"我們能六點前走嗎？這樣可以避開交通堵塞。"},{"en":"He left early and missed the best part.","zh":"他提前離開，錯過了最精彩的部分。"},{"en":"Leaving is hard but sometimes it is the right thing.","zh":"離開是困難的，但有時候那是正確的事情。"}]},{"word":"start","pos":"verb","chinese":"開始；出發","level":"A1","sentences":[{"en":"Let us start — we are already behind schedule.","zh":"我們開始吧——我們已經落後於計劃了。"},{"en":"She started a new chapter and was terrified and excited.","zh":"她開始了新的篇章，既害怕又興奮。"},{"en":"Where should I start? There is so much to say.","zh":"我應該從哪裡開始？有太多要說了。"},{"en":"He started small and built something incredible.","zh":"他從小做起，建立了令人難以置信的事業。"},{"en":"Start with one thing — do not overwhelm yourself.","zh":"從一件事開始——不要讓自己不知所措。"},{"en":"She started the meeting by thanking everyone for their time.","zh":"她通過感謝大家抽出時間來開始了會議。"},{"en":"I started cooking and forgot about time completely.","zh":"我開始做飯，完全忘記了時間。"},{"en":"He started over with nothing and rebuilt everything.","zh":"他從零開始，重建了一切。"},{"en":"Start each day fresh — yesterday does not define today.","zh":"以全新的狀態開始每一天——昨天不定義今天。"},{"en":"She started her business in her bedroom — now it is international.","zh":"她在臥室裡創業——現在是國際公司了。"}]},{"word":"stop","pos":"verb","chinese":"停止；停下","level":"A1","sentences":[{"en":"Stop — you are going to hurt yourself.","zh":"停下——你會傷到自己的。"},{"en":"She could not stop laughing — it was contagious.","zh":"她停不下來笑——那是有感染力的。"},{"en":"I keep telling myself to stop overthinking.","zh":"我一直告訴自己停止過度思考。"},{"en":"Can we stop here for a while? I like this spot.","zh":"我們能在這裡停一下嗎？我喜歡這個地方。"},{"en":"He stopped the car and looked around.","zh":"他停下車，環顧四周。"},{"en":"Stop comparing yourself to others — it is not fair to you.","zh":"停止拿自己和別人比較——對你不公平。"},{"en":"She stopped complaining and started doing.","zh":"她停止了抱怨，開始行動了。"},{"en":"I cannot stop thinking about what you said.","zh":"我停不下來想你說的話。"},{"en":"Stop. Breathe. You are doing fine.","zh":"停下來，呼吸，你做得很好。"},{"en":"When do you stop working and start living?","zh":"你什麼時候停止工作，開始生活？"}]},{"word":"bring","pos":"verb","chinese":"帶來；帶","level":"A1","sentences":[{"en":"Can you bring an umbrella? It looks like rain.","zh":"你能帶把雨傘嗎？看起來要下雨了。"},{"en":"She brought homemade cookies to the office.","zh":"她帶了自制餅乾到辦公室。"},{"en":"What can I bring to the dinner party?","zh":"我可以帶什麼去晚宴？"},{"en":"He brings a positive energy wherever he goes.","zh":"他走到哪裡都帶來積極的能量。"},{"en":"That song brings back so many memories.","zh":"那首歌勾起了太多回憶。"},{"en":"She always brings out the best in people.","zh":"她總是能激發出別人最好的一面。"},{"en":"Bring your ID or they will not let you in.","zh":"帶上你的身份證，否則他們不會讓你進去。"},{"en":"I brought coffee — thought you might need it.","zh":"我帶了咖啡——我想你可能需要。"},{"en":"He brought comfort just by being there.","zh":"他只是在那裡就帶來了安慰。"},{"en":"What brings you here today?","zh":"今天什麼風把你帶來了？"}]},{"word":"find","pos":"verb","chinese":"找到；發現","level":"A1","sentences":[{"en":"I cannot find my keys — have you seen them?","zh":"我找不到我的鑰匙——你看到了嗎？"},{"en":"She found her passion at forty — better late than never.","zh":"她在四十歲發現了她的熱情——遲到總比不到好。"},{"en":"I find this really interesting — tell me more.","zh":"我覺得這非常有趣——多說點。"},{"en":"He found the perfect café and it became his second home.","zh":"他找到了完美的咖啡廳，它成了他的第二個家。"},{"en":"I find it hard to say no sometimes.","zh":"我有時候覺得說不很難。"},{"en":"She found him exactly where he said he would be.","zh":"她在他說的地方找到了他。"},{"en":"I need to find a way to fix this.","zh":"我需要找到解決這個問題的方法。"},{"en":"He found strength he did not know he had.","zh":"他發現了他不知道自己擁有的力量。"},{"en":"Finding balance is a daily practice.","zh":"找到平衡是一種日常練習。"},{"en":"I found out the hard way — but I learned.","zh":"我用艱難的方式發現的——但我學到了東西。"}]},{"word":"eat","pos":"verb","chinese":"吃","level":"A1","sentences":[{"en":"Have you eaten? You look hungry.","zh":"你吃過了嗎？你看起來很餓。"},{"en":"She eats slowly and actually tastes her food.","zh":"她吃得很慢，真正品嚐食物。"},{"en":"We ate outside by the canal — perfect evening.","zh":"我們在運河邊的戶外吃飯——完美的夜晚。"},{"en":"I eat breakfast every day without fail.","zh":"我每天都吃早餐，毫無例外。"},{"en":"He eats everything — very easy to cook for.","zh":"他什麼都吃——非常容易為他做飯。"},{"en":"What do you want to eat tonight? I can cook.","zh":"你今晚想吃什麼？我可以做。"},{"en":"Eating together is one of my favourite things.","zh":"一起吃飯是我最喜歡的事情之一。"},{"en":"She ate her feelings after that break-up.","zh":"分手後她靠吃來疏解情緒。"},{"en":"Do not eat at your desk — take a proper break.","zh":"不要在桌子前吃飯——好好休息一下。"},{"en":"He eats so fast I worry he does not taste anything.","zh":"他吃得那麼快，我擔心他沒有嚐到任何味道。"}]},{"word":"drink","pos":"verb/noun","chinese":"喝；飲料","level":"A1","sentences":[{"en":"Can I get you a drink?","zh":"我可以給你拿一杯飲料嗎？"},{"en":"She drinks two litres of water a day — skin goals.","zh":"她每天喝兩升水——護膚目標。"},{"en":"What are you drinking? It smells delicious.","zh":"你在喝什麼？聞起來很好喝。"},{"en":"He drinks his coffee black — no sugar, no milk.","zh":"他喝黑咖啡——不加糖，不加奶。"},{"en":"I need a drink after that meeting.","zh":"那個會議之後我需要喝一杯。"},{"en":"She does not drink alcohol — and she never apologises for it.","zh":"她不喝酒——她從不為此道歉。"},{"en":"Drink more water — you probably need it.","zh":"多喝水——你可能需要。"},{"en":"We grabbed drinks after work and talked for hours.","zh":"我們下班後去喝飲料，聊了好幾個小時。"},{"en":"He ordered the most expensive drink on the menu by mistake.","zh":"他不小心點了菜單上最貴的飲料。"},{"en":"Drinking slowly and savouring the flavour is the best way.","zh":"慢慢喝，細細品味是最好的方式。"}]},{"word":"sleep","pos":"verb","chinese":"睡覺；入睡","level":"A1","sentences":[{"en":"I slept so well last night — eight full hours.","zh":"我昨晚睡得很好——整整八個小時。"},{"en":"She cannot sleep when she is anxious.","zh":"她焦慮的時候睡不著。"},{"en":"Go to sleep — it is too late to fix it tonight.","zh":"去睡覺吧——今晚解決不了了。"},{"en":"He sleeps through everything — not even thunder wakes him.","zh":"他什麼都能睡過去——連雷聲都叫不醒他。"},{"en":"I need to sleep early or tomorrow will be rough.","zh":"我需要早點睡覺，否則明天會很難熬。"},{"en":"She fell asleep in the middle of the film again.","zh":"她又在電影進行中睡著了。"},{"en":"Sleep is not laziness — it is recovery.","zh":"睡覺不是懶惰——而是恢復。"},{"en":"I slept on the problem and woke up with a solution.","zh":"我把問題留到睡一覺後，醒來有了解決方案。"},{"en":"He looks like he has not slept in days.","zh":"他看起來好幾天沒睡覺了。"},{"en":"Sleep changes everything — you are a different person after good rest.","zh":"睡眠改變一切——好好休息後你是一個不同的人。"}]},{"word":"walk","pos":"verb","chinese":"走路；散步","level":"A1","sentences":[{"en":"I walk to work — forty minutes and worth every step.","zh":"我走路上班——四十分鐘，每一步都值得。"},{"en":"She walked in like she owned the place.","zh":"她走進來，好像那是她的地盤。"},{"en":"Let us walk — it is too nice a day to take the bus.","zh":"我們走路吧——天氣太好了，不想坐公車。"},{"en":"He walks his dog every morning at six.","zh":"他每天早上六點遛他的狗。"},{"en":"Walking clears my head better than anything else.","zh":"散步比任何事情都更能清理我的思緒。"},{"en":"She walked away and never looked back.","zh":"她走開了，再也沒有回頭看。"},{"en":"We walked for hours and forgot where we were going.","zh":"我們走了好幾個小時，忘記了我們要去哪裡。"},{"en":"Walking slowly and looking around is underrated.","zh":"慢慢走，四處看看，這種方式被低估了。"},{"en":"He walked into the wrong building and had to backtrack.","zh":"他走進了錯誤的大樓，不得不退回來。"},{"en":"There is wisdom in the phrase: just walk it off.","zh":"「就走一走」這句話很有智慧。"}]},{"word":"run","pos":"verb","chinese":"跑步；運行","level":"A1","sentences":[{"en":"I run three times a week — it saves my sanity.","zh":"我每週跑三次——這讓我保持理智。"},{"en":"She ran for the bus and just made it.","zh":"她跑去趕公車，剛好趕上了。"},{"en":"He runs a small business from home.","zh":"他在家裡經營一個小生意。"},{"en":"I ran into my old classmate at the supermarket.","zh":"我在超市碰到了我的老同學。"},{"en":"Run — you are going to be late.","zh":"跑——你要遲到了。"},{"en":"She ran the meeting efficiently — in and out in thirty minutes.","zh":"她高效地主持了會議——三十分鐘內結束。"},{"en":"My phone runs out of battery by noon every day.","zh":"我的手機每天中午電量就耗盡了。"},{"en":"He ran the whole marathon without stopping.","zh":"他不停地跑完了整個馬拉松。"},{"en":"Time runs faster when I am doing something I love.","zh":"當我在做我喜歡的事情時，時間過得更快。"},{"en":"She runs on coffee and good intentions.","zh":"她靠咖啡和好意運轉。"}]},{"word":"write","pos":"verb","chinese":"寫","level":"A1","sentences":[{"en":"I write down everything I want to remember.","zh":"我把所有想記住的事情都寫下來。"},{"en":"She wrote a letter to her future self.","zh":"她給未來的自己寫了一封信。"},{"en":"Have you written the email yet?","zh":"你已經寫了那封電子郵件嗎？"},{"en":"He writes beautifully — every sentence means something.","zh":"他寫得很好——每一句話都有意義。"},{"en":"I need to write this down before I forget.","zh":"我需要在忘記之前把這個寫下來。"},{"en":"She wrote in her journal every night before bed.","zh":"她每晚睡前都在日記本上寫作。"},{"en":"Writing helps me process my feelings.","zh":"寫作幫助我處理我的情緒。"},{"en":"He wrote back immediately — I liked that.","zh":"他立刻回信了——我很喜歡。"},{"en":"Write clearly and people will take you seriously.","zh":"寫得清楚，人們就會認真對待你。"},{"en":"She wrote the proposal in one sitting — impressed everyone.","zh":"她一口氣寫完了提案——讓所有人都印象深刻。"}]},{"word":"read","pos":"verb","chinese":"讀；閱讀","level":"A1","sentences":[{"en":"I read every night before sleeping — even just one page.","zh":"我每晚睡前都會讀書——哪怕只是一頁。"},{"en":"She reads faster than anyone I know.","zh":"她讀書比我認識的任何人都快。"},{"en":"Did you read the news today? Wild stuff.","zh":"你今天看新聞了嗎？太瘋狂了。"},{"en":"I read the email three times to make sure I understood.","zh":"我把電子郵件讀了三遍，確保我理解了。"},{"en":"He reads everything — books, menus, labels.","zh":"他什麼都讀——書、菜單、標籤。"},{"en":"She read the room and knew when to stop talking.","zh":"她讀懂了場合，知道什麼時候該停止說話。"},{"en":"I love reading but struggle to find the time.","zh":"我喜歡閱讀，但很難找到時間。"},{"en":"Reading one book changed how I see the world.","zh":"讀一本書改變了我看世界的方式。"},{"en":"She reads people well — very perceptive.","zh":"她很善於讀懂人——非常敏銳。"},{"en":"I read too fast and have to go back — story of my life.","zh":"我讀得太快，不得不回去重讀——我的人生寫照。"}]},{"word":"meet","pos":"verb","chinese":"遇見；見面","level":"A1","sentences":[{"en":"Nice to meet you — I have heard great things.","zh":"很高興見到你——我聽說了很多好的事情。"},{"en":"We met at a coffee shop and talked for five hours.","zh":"我們在咖啡廳相遇，聊了五個小時。"},{"en":"Can we meet next week to discuss this?","zh":"我們下週能見面討論這個嗎？"},{"en":"She met her best friend on the first day of university.","zh":"她在大學第一天遇到了她最好的朋友。"},{"en":"I love meeting new people — you never know what you will learn.","zh":"我喜歡遇見新朋友——你永遠不知道你會學到什麼。"},{"en":"He meets every challenge with a positive attitude.","zh":"他以積極的態度應對每一個挑戰。"},{"en":"We met online before we ever met in person.","zh":"我們在線上認識，後來才見面。"},{"en":"She met my eyes and I knew she understood.","zh":"她看著我的眼睛，我知道她理解了。"},{"en":"Meeting someone who just gets you is rare.","zh":"遇見一個完全理解你的人是很難得的。"},{"en":"I cannot meet that deadline — I need more time.","zh":"我無法在那個截止日期前完成——我需要更多時間。"}]},{"word":"stay","pos":"verb","chinese":"停留；留下","level":"A1","sentences":[{"en":"Can you stay a little longer? It is early.","zh":"你能多待一會兒嗎？還早呢。"},{"en":"She stayed at a tiny guesthouse and loved every minute.","zh":"她住在一家小旅馆，每一分鐘都很享受。"},{"en":"Stay focused — the finish line is close.","zh":"保持專注——終點就在眼前。"},{"en":"He stayed calm even when everything was falling apart.","zh":"即使一切都在崩潰，他也保持冷靜。"},{"en":"I want to stay here forever.","zh":"我想永遠留在這裡。"},{"en":"She stayed true to herself even when it was hard.","zh":"即使在困難時，她也忠於自己。"},{"en":"Stay out of trouble — please.","zh":"不要惹麻煩——拜託了。"},{"en":"We stayed up talking until the sun came up.","zh":"我們聊天直到太陽升起。"},{"en":"He stays consistent — same values, same principles.","zh":"他保持一致——相同的價值觀，相同的原則。"},{"en":"Stay where you are — I am coming to you.","zh":"待在原地——我去找你。"}]},{"word":"time","pos":"noun","chinese":"時間；次數","level":"A1","sentences":[{"en":"Time flies when you are having fun.","zh":"開心的時候時間過得飛快。"},{"en":"I do not have time for drama right now.","zh":"我現在沒時間處理麻煩事。"},{"en":"What time does the café open?","zh":"咖啡廳幾點開門？"},{"en":"She makes time for the people she loves.","zh":"她為她愛的人騰出時間。"},{"en":"This is not the right time — let's talk later.","zh":"現在不是好時機——我們待會兒再說。"},{"en":"I had the time of my life at that concert.","zh":"我在那場演唱會度過了最美好的時光。"},{"en":"Time is the most valuable thing you can give someone.","zh":"時間是你能給予別人最珍貴的東西。"},{"en":"It is only a matter of time — be patient.","zh":"只是時間問題——要有耐心。"},{"en":"She arrived on time, as always.","zh":"她準時到了，一如既往。"},{"en":"I waste so much time scrolling without noticing.","zh":"我刷手機浪費了太多時間，卻沒有注意到。"}]},{"word":"day","pos":"noun","chinese":"天；日子","level":"A1","sentences":[{"en":"Today is a good day — I can feel it.","zh":"今天是個好日子——我能感覺到。"},{"en":"She counts down the days until her holiday.","zh":"她倒數距離假期還有幾天。"},{"en":"What are you doing later in the day?","zh":"你今天稍晚有什麼安排？"},{"en":"Some days are just harder than others — that is okay.","zh":"有些日子就是比其他日子難——沒關係。"},{"en":"He made my day with one small gesture.","zh":"他的一個小舉動讓我整天都很開心。"},{"en":"Day by day, things are getting better.","zh":"一天一天地，事情正在好轉。"},{"en":"I have not had a proper day off in weeks.","zh":"我已經好幾週沒有好好休息一天了。"},{"en":"She starts every day with ten minutes of quiet.","zh":"她每天以十分鐘的安靜開始。"},{"en":"That was one of the best days of my life.","zh":"那是我人生中最美好的日子之一。"},{"en":"End your day with gratitude — it changes everything.","zh":"用感恩結束你的一天——它改變一切。"}]},{"word":"year","pos":"noun","chinese":"年；年份","level":"A1","sentences":[{"en":"This year has been full of changes — good and bad.","zh":"今年充滿了變化——好的和壞的。"},{"en":"She has been working there for three years.","zh":"她已經在那裡工作了三年。"},{"en":"New Year, same me — but maybe slightly better.","zh":"新的一年，還是同樣的我——但也許稍微好一點。"},{"en":"The years go by faster the older you get.","zh":"年紀越大，歲月流逝越快。"},{"en":"I have not seen her in two years — I miss her.","zh":"我兩年沒見到她了——我很想念她。"},{"en":"This was the year I finally took that leap.","zh":"今年是我終於邁出那一步的一年。"},{"en":"He has grown so much in just one year.","zh":"他在短短一年內成長了這麼多。"},{"en":"Every year I set one big goal and focus on it.","zh":"每年我設定一個大目標，然後專注於它。"},{"en":"Next year, I want to travel to somewhere new.","zh":"明年，我想去一個新的地方旅行。"},{"en":"Some years shape you more than others.","zh":"有些年份比其他年份更塑造你。"}]},{"word":"place","pos":"noun","chinese":"地方；位置","level":"A1","sentences":[{"en":"This is my favourite place in the whole city.","zh":"這是整個城市裡我最喜歡的地方。"},{"en":"Do you know a good place to eat near here?","zh":"你知道附近有什麼好吃的地方嗎？"},{"en":"She always feels at home in that place.","zh":"她在那個地方總是感到自在。"},{"en":"I need a quiet place to think.","zh":"我需要一個安靜的地方思考。"},{"en":"That place holds so many memories for me.","zh":"那個地方對我來說有太多回憶。"},{"en":"He found a place that felt like it was made for him.","zh":"他找到了一個感覺像是為他而生的地方。"},{"en":"Is there still a place for me at the table?","zh":"桌子那裡還有我的位置嗎？"},{"en":"She travelled to a different place every year.","zh":"她每年去一個不同的地方旅行。"},{"en":"Your place in someone's life shows in how they talk about you.","zh":"你在某人生命中的位置，從他們談論你的方式就能看出來。"},{"en":"There is no better place to be than right here.","zh":"沒有比此刻所在更好的地方了。"}]},{"word":"name","pos":"noun/verb","chinese":"名字；命名","level":"A1","sentences":[{"en":"What is your name? I do not think we have met.","zh":"你叫什麼名字？我想我們還沒見過。"},{"en":"She named her cat after a character from her favourite book.","zh":"她用最喜歡的書中的角色給她的貓命名。"},{"en":"I am terrible with names — please remind me.","zh":"我記人名很差——請提醒我。"},{"en":"His name was on everyone's lips that day.","zh":"那天所有人都在說他的名字。"},{"en":"She made a name for herself in the industry.","zh":"她在業界為自己建立了名聲。"},{"en":"Can I get your name for the reservation?","zh":"我可以記下您的名字作為預約嗎？"},{"en":"A name can carry a whole story.","zh":"一個名字可以承載一整個故事。"},{"en":"He goes by a nickname — no one uses his real name.","zh":"他用暱稱，沒有人叫他的本名。"},{"en":"I finally put a name to the feeling I had been carrying.","zh":"我終於找到了一個詞來形容我一直懷抱的感受。"},{"en":"She named the project after something meaningful to her.","zh":"她用對她有意義的事物來命名這個項目。"}]},{"word":"home","pos":"noun","chinese":"家；回家","level":"A1","sentences":[{"en":"There is no place like home — especially after a long trip.","zh":"沒有任何地方比得上家——尤其是長途旅行後。"},{"en":"She feels most herself when she is at home.","zh":"她在家的時候最像自己。"},{"en":"I worked from home today and loved the quiet.","zh":"我今天在家工作，很喜歡那種安靜。"},{"en":"He made everywhere he lived feel like home.","zh":"他讓他住過的每個地方都像家。"},{"en":"Home is not a place — it is a feeling.","zh":"家不是一個地方——而是一種感覺。"},{"en":"I am heading home now — see you tomorrow.","zh":"我現在要回家了——明天見。"},{"en":"She called her mum the moment she got home.","zh":"她一回到家就打電話給她媽媽。"},{"en":"Make your home a space that restores you.","zh":"把你的家變成一個恢復你的空間。"},{"en":"He was homesick for the first time in his life.","zh":"他第一次在人生中感到思鄉。"},{"en":"Coming home to someone who loves you is everything.","zh":"回家有人愛你等著你，那就是一切。"}]},{"word":"friend","pos":"noun","chinese":"朋友；好友","level":"A1","sentences":[{"en":"She is the kind of friend who shows up unannounced with food.","zh":"她是那種突然出現帶著食物的朋友。"},{"en":"A good friend tells you when you have spinach in your teeth.","zh":"好朋友會告訴你牙齒上有菜葉。"},{"en":"I made my closest friends in the most unexpected places.","zh":"我在最意想不到的地方結交了最親密的朋友。"},{"en":"He is not just a colleague — he is a real friend.","zh":"他不只是同事——他是真正的朋友。"},{"en":"I need to call a friend. I miss real conversation.","zh":"我需要打電話給朋友，我想念真正的對話。"},{"en":"She has the gift of making everyone feel like her best friend.","zh":"她有讓所有人都感覺像是她最好朋友的天賦。"},{"en":"Old friends carry your history — cherish them.","zh":"老朋友承載著你的歷史——珍惜他們。"},{"en":"Making new friends as an adult is harder but worth it.","zh":"成年後交新朋友更難，但值得。"},{"en":"A friend who listens is worth more than one who advises.","zh":"善於傾聽的朋友比給建議的朋友更珍貴。"},{"en":"Be the kind of friend you wish you had.","zh":"成為你希望擁有的那種朋友。"}]},{"word":"money","pos":"noun","chinese":"錢；金錢","level":"A1","sentences":[{"en":"I do not have a lot of money but I spend it on things I love.","zh":"我沒有很多錢，但我把它花在我喜歡的事情上。"},{"en":"She saves money by cooking at home most nights.","zh":"她大多數晚上在家做飯來省錢。"},{"en":"Money does not buy happiness but it buys options.","zh":"金錢買不到快樂，但能買到選擇。"},{"en":"He spent all his money on experiences, not things.","zh":"他把所有的錢都花在體驗上，而不是物品。"},{"en":"I need to be smarter about where my money goes.","zh":"我需要更聰明地管理我的錢去了哪裡。"},{"en":"She earns good money but never shows it off.","zh":"她賺了不少錢，但從不炫耀。"},{"en":"Talking about money is still taboo in some cultures.","zh":"在一些文化中，談論金錢仍然是禁忌。"},{"en":"Time is more valuable than money — you cannot earn it back.","zh":"時間比金錢更有價值——你無法把它賺回來。"},{"en":"He lent me money without asking when I would pay it back.","zh":"他借了我錢，沒有問我什麼時候還。"},{"en":"I stopped buying things I did not need and saved more money.","zh":"我停止購買我不需要的東西，省了更多錢。"}]},{"word":"food","pos":"noun","chinese":"食物；飲食","level":"A1","sentences":[{"en":"Food is love in my family — every gathering has a big meal.","zh":"在我家，食物就是愛——每次聚會都有一頓大餐。"},{"en":"She photographs her food before eating — every single time.","zh":"她每次吃飯前都會先拍照。"},{"en":"Good food does not have to be complicated.","zh":"好的食物不必複雜。"},{"en":"He knows every good food spot in the city.","zh":"他知道城市裡每一個美食好去處。"},{"en":"I tried a food I could not name and it was the best thing I ever ate.","zh":"我試了一種我不知道名字的食物，那是我吃過最好吃的東西。"},{"en":"The best food is usually found in the simplest places.","zh":"最好的食物通常在最簡單的地方。"},{"en":"She grew up making food from scratch — no shortcuts.","zh":"她從小就從頭開始做飯——沒有捷徑。"},{"en":"Food from home always tastes different when you are far away.","zh":"在外地的時候，家鄉的食物總是嚐起來不同了。"},{"en":"I connect with people over food more than anything.","zh":"我通過食物和人們建立聯繫，超過其他任何事情。"},{"en":"Good food shared with good people is one of life's great joys.","zh":"與好人分享好食物是人生的一大樂趣。"}]},{"word":"water","pos":"noun","chinese":"水；水分","level":"A1","sentences":[{"en":"Drink more water. I know everyone says it but it works.","zh":"多喝水，我知道所有人都這樣說，但它確實有效。"},{"en":"She carries a water bottle everywhere — good habit.","zh":"她到處帶著水瓶——好習慣。"},{"en":"The sound of running water is so calming.","zh":"流水的聲音非常讓人平靜。"},{"en":"I forgot to water my plants and they are not happy.","zh":"我忘記給植物澆水，它們不高興了。"},{"en":"He drinks cold water first thing every morning.","zh":"他每天早上第一件事就是喝冷水。"},{"en":"Water under the bridge — I have forgiven and moved on.","zh":"已經過去的事了——我已經原諒，繼續前進了。"},{"en":"Nothing beats a glass of cold water on a hot day.","zh":"在炎熱的日子裡，沒有什麼比一杯冷水更好了。"},{"en":"She swims in open water every weekend.","zh":"她每個週末在開放水域游泳。"},{"en":"Stay hydrated — your brain needs water to function.","zh":"保持補水——你的大腦需要水才能運作。"},{"en":"The river looked so still and peaceful in the early morning.","zh":"早晨的河流看起來如此平靜安詳。"}]},{"word":"work","pos":"noun/verb","chinese":"工作；運作","level":"A1","sentences":[{"en":"I love what I do — not everyone can say that.","zh":"我喜歡我所做的事——不是每個人都能這樣說。"},{"en":"Work hard but not so hard you forget why you started.","zh":"努力工作，但不要努力到忘記你為什麼開始。"},{"en":"She works best in the early morning hours.","zh":"她在清晨工作效率最高。"},{"en":"I am not working this weekend — full switch off.","zh":"我這個週末不工作——完全關機。"},{"en":"Hard work pays off — not always immediately, but it does.","zh":"努力工作會有回報——不一定立刻，但它確實會。"},{"en":"He makes everything he does look effortless.","zh":"他讓他所做的一切看起來毫不費力。"},{"en":"Work is important but it is not your whole identity.","zh":"工作很重要，但它不是你全部的身份。"},{"en":"She worked through the problem step by step.","zh":"她一步一步地解決了那個問題。"},{"en":"That plan is not going to work — let me suggest something else.","zh":"那個計畫不會奏效——讓我提議別的方法。"},{"en":"Working with great people makes all the difference.","zh":"和優秀的人一起工作會帶來巨大的不同。"}]},{"word":"school","pos":"noun","chinese":"學校；上學","level":"A1","sentences":[{"en":"She loved school — every subject was an adventure.","zh":"她喜歡上學——每個科目都是一場冒險。"},{"en":"I learned more outside of school than inside it.","zh":"我在校外學到的比在校內更多。"},{"en":"He went back to school at forty and loved it.","zh":"他四十歲回到學校，並且很喜歡。"},{"en":"School teaches you information. Life teaches you wisdom.","zh":"學校教你知識，生活教你智慧。"},{"en":"She was always the first one at school.","zh":"她總是最早到學校的人。"},{"en":"My best memories from school are the friendships.","zh":"我學校裡最美好的記憶是那些友誼。"},{"en":"Old school methods sometimes work better than modern ones.","zh":"傳統方法有時比現代方法更有效。"},{"en":"He graduated from school and had no idea what to do next.","zh":"他從學校畢業，不知道接下來要做什麼。"},{"en":"School is where you learn how to learn.","zh":"學校是你學習如何學習的地方。"},{"en":"She never let school get in the way of her education.","zh":"她從不讓學校妨礙她的教育。"}]},{"word":"book","pos":"noun/verb","chinese":"書；預約","level":"A1","sentences":[{"en":"She reads a book a week — I admire that dedication.","zh":"她每週讀一本書——我欽佩那種投入。"},{"en":"I judged a book by its cover and was completely wrong.","zh":"我以貌取書，結果完全錯了。"},{"en":"Can I book a table for two for Friday evening?","zh":"我可以預訂週五晚上兩人桌嗎？"},{"en":"He has a book recommendation for every mood.","zh":"他有適合每種心情的書籍推薦。"},{"en":"The book changed how I see the world.","zh":"那本書改變了我看世界的方式。"},{"en":"I am so booked this week — no free evenings.","zh":"我這週排得很滿——沒有空閒的晚上。"},{"en":"She wrote a book about her experience and it resonated with millions.","zh":"她寫了一本關於她經歷的書，引起了數百萬人的共鳴。"},{"en":"Some books find you at exactly the right time.","zh":"有些書在恰好合適的時候找到了你。"},{"en":"I cannot put this book down — it is that good.","zh":"我放不下這本書——它就是這麼好看。"},{"en":"Book the trip first — figure the rest out after.","zh":"先訂機票——其他的以後再說。"}]},{"word":"music","pos":"noun","chinese":"音樂","level":"A1","sentences":[{"en":"Music is the only thing that makes my commute enjoyable.","zh":"音樂是唯一讓我的通勤變得愉快的事情。"},{"en":"She puts on music when she needs to think.","zh":"她需要思考時會放音樂。"},{"en":"That song is the soundtrack to a whole chapter of my life.","zh":"那首歌是我人生某個篇章的配樂。"},{"en":"Good music makes ordinary moments feel cinematic.","zh":"好音樂讓普通的時刻感覺像電影場景。"},{"en":"He makes music in his spare time — purely for joy.","zh":"他業餘時間製作音樂——純粹是為了快樂。"},{"en":"Music has a way of saying what words cannot.","zh":"音樂有一種方式說出語言無法表達的東西。"},{"en":"I discovered this song at the right moment — it healed something.","zh":"我在正確的時刻發現了這首歌——它治癒了什麼。"},{"en":"She grew up surrounded by music and it shows.","zh":"她在音樂環繞中長大，這從她身上看得出來。"},{"en":"Live music hits differently — you feel it in your whole body.","zh":"現場音樂的感覺完全不同——你能全身感受到它。"},{"en":"Some music takes you straight back to a specific memory.","zh":"有些音樂直接帶你回到一段特定的記憶。"}]},{"word":"family","pos":"noun","chinese":"家人；家庭","level":"A1","sentences":[{"en":"Family is not always blood — it is who shows up for you.","zh":"家人不一定是血親——而是那些為你出現的人。"},{"en":"She calls her whole family every Sunday morning.","zh":"她每個週日早上打電話給全家人。"},{"en":"My family is chaotic but I would not trade it.","zh":"我的家庭很混亂，但我不會用它換任何東西。"},{"en":"He moved cities but stayed close to his family in spirit.","zh":"他搬去了另一個城市，但在精神上仍然和家人很親近。"},{"en":"Family gatherings are loud, messy and the best thing ever.","zh":"家庭聚會吵鬧、混亂，卻是最美好的事情。"},{"en":"She built a chosen family when her biological one was not there.","zh":"當她的原生家庭不在時，她建立了一個自己選擇的家庭。"},{"en":"Family is where you learn your first lessons about love.","zh":"家庭是你學習關於愛的第一課的地方。"},{"en":"He takes family time seriously — phone goes away at dinner.","zh":"他認真對待家庭時間——晚餐時手機收起來。"},{"en":"Some family relationships take work — that is normal.","zh":"一些家庭關係需要努力維繫——這是正常的。"},{"en":"The family you choose matters just as much as the one you are born into.","zh":"你選擇的家人和你出生的家庭一樣重要。"}]},{"word":"word","pos":"noun","chinese":"詞；單詞；話","level":"A1","sentences":[{"en":"She has a way with words — everything she says lands perfectly.","zh":"她有駕馭語言的天賦——她說的每句話都恰到好處。"},{"en":"I do not always have the right words but I try.","zh":"我不總是能找到合適的詞，但我會努力。"},{"en":"One kind word can turn someone's whole day around.","zh":"一句善意的話可以改變某人的整天。"},{"en":"She kept her word — that is rare these days.","zh":"她守信了——這在今天是難得的。"},{"en":"I learned a new word today: liminal.","zh":"我今天學了一個新詞：臨界。"},{"en":"His words stayed with me long after the conversation ended.","zh":"他說的話在對話結束後很久還留在我心裡。"},{"en":"Actions speak louder than words — but words still matter.","zh":"行動勝於語言——但語言仍然重要。"},{"en":"She always finds the exact word she needs.","zh":"她總是能找到她需要的確切詞語。"},{"en":"Words can heal or harm — choose them carefully.","zh":"話語可以治癒或傷害——要謹慎選擇。"},{"en":"I cannot find the words — but you already know.","zh":"我找不到語言——但你已經知道了。"}]},{"word":"life","pos":"noun","chinese":"生命；生活","level":"A1","sentences":[{"en":"Life is short — spend it on things that matter.","zh":"生命短暫——把它花在重要的事情上。"},{"en":"She approaches life with curiosity and openness.","zh":"她以好奇心和開放的態度面對生活。"},{"en":"This is not the life I planned but it is mine and I love it.","zh":"這不是我計畫的生活，但它是我的，我愛它。"},{"en":"Real life is messier than social media suggests.","zh":"真實的生活比社交媒體展示的要混亂得多。"},{"en":"He lives his life without apologising for who he is.","zh":"他過著不為自己是誰而道歉的生活。"},{"en":"Life teaches you lessons school never could.","zh":"生活教你學校永遠無法教的課。"},{"en":"Sometimes life surprises you in the best possible way.","zh":"有時候生活會以最好的方式給你驚喜。"},{"en":"She made the most of the life she had.","zh":"她充分利用了她所擁有的生活。"},{"en":"Life is a collection of small moments — make them count.","zh":"生活是由一個個小時刻組成的——讓它們有意義。"},{"en":"The good life is not about having everything — it is about enjoying what you have.","zh":"美好的生活不是擁有一切——而是享受你所擁有的。"}]},{"word":"world","pos":"noun","chinese":"世界；全球","level":"A1","sentences":[{"en":"She wants to see as much of the world as possible.","zh":"她想看盡世界上盡可能多的地方。"},{"en":"The world is so much bigger than the problems in front of you.","zh":"世界比你面前的問題大得多。"},{"en":"He created his own world through his writing.","zh":"他通過寫作創造了自己的世界。"},{"en":"In a perfect world, everyone would be kind.","zh":"在一個完美的世界裡，每個人都會善良。"},{"en":"She changed her world by changing her perspective.","zh":"她通過改變她的視角改變了她的世界。"},{"en":"That book opened up a whole new world to me.","zh":"那本書為我打開了一個全新的世界。"},{"en":"The world looks different when you travel.","zh":"旅行時世界看起來不一樣。"},{"en":"He means the world to the people who love him.","zh":"他對愛他的人來說意味著一切。"},{"en":"You do not have to change the whole world — just yours.","zh":"你不必改變整個世界——只需改變你的世界。"},{"en":"She sees the best in people and the world.","zh":"她看到人和世界最好的一面。"}]},{"word":"person","pos":"noun","chinese":"人；個人","level":"A1","sentences":[{"en":"She is the most genuine person I have ever met.","zh":"她是我遇到過的最真實的人。"},{"en":"He is a person who shows up — every single time.","zh":"他是一個每次都會出現的人。"},{"en":"Every person has a story worth listening to.","zh":"每個人都有值得傾聽的故事。"},{"en":"I am a morning person — completely useless after ten.","zh":"我是一個早晨型的人——十點之後完全沒用了。"},{"en":"She grew into the person she always wanted to be.","zh":"她成長為她一直想成為的人。"},{"en":"The wrong person in your life can drain everything.","zh":"生命中錯誤的人可以耗盡一切。"},{"en":"He is such a good person — always thinking of others.","zh":"他真的是個好人——總是為別人著想。"},{"en":"Becoming a better person takes time and honesty.","zh":"成為更好的人需要時間和誠實。"},{"en":"She is a people person — thrives in social settings.","zh":"她是一個社交型的人——在社交環境中如魚得水。"},{"en":"You cannot be everything to every person.","zh":"你無法對每個人都做到一切。"}]},{"word":"way","pos":"noun","chinese":"方式；路","level":"A1","sentences":[{"en":"She has a way of making everything look elegant.","zh":"她有讓一切看起來優雅的方式。"},{"en":"There is no one right way to do this.","zh":"沒有唯一正確的方式來做這件事。"},{"en":"Can you show me the way to the station?","zh":"你能告訴我去車站的路嗎？"},{"en":"He does things his own way and it works.","zh":"他用自己的方式做事，而且奏效。"},{"en":"I lost my way for a bit but I found it again.","zh":"我迷失了一段時間，但我又找到了方向。"},{"en":"This is the long way around but the views are worth it.","zh":"這是一條繞遠路，但風景值得。"},{"en":"She found a way when there seemed to be none.","zh":"她在似乎沒有出路的時候找到了方法。"},{"en":"By the way, have you heard the news?","zh":"順便問一下，你聽到那個消息了嗎？"},{"en":"Some things have a way of working out on their own.","zh":"有些事情有自己解決的方式。"},{"en":"He found his way in life the hard way — but he found it.","zh":"他用艱難的方式找到了人生的方向——但他找到了。"}]},{"word":"thing","pos":"noun","chinese":"東西；事情","level":"A1","sentences":[{"en":"The funny thing is, I almost did not go.","zh":"有趣的是，我差點沒有去。"},{"en":"She has this thing about being early — always first.","zh":"她有個習慣就是早到——總是第一個。"},{"en":"One thing at a time — slow down.","zh":"一次一件事——放慢腳步。"},{"en":"The best things in life are not things.","zh":"生命中最好的事情都不是物品。"},{"en":"That is the thing about him — he always surprises you.","zh":"這就是他的特點——他總是給你驚喜。"},{"en":"I collect small things that remind me of good moments.","zh":"我收集能讓我想起美好時刻的小東西。"},{"en":"The whole thing was a mess but we got through it.","zh":"整件事一團糟，但我們撐過來了。"},{"en":"She does not need things — she needs experiences.","zh":"她不需要物品——她需要體驗。"},{"en":"Next thing I knew, it was midnight.","zh":"一眨眼，已經午夜了。"},{"en":"Little things add up to big things over time.","zh":"小事情隨著時間累積成大事情。"}]},{"word":"hand","pos":"noun/verb","chinese":"手；交給","level":"A1","sentences":[{"en":"She always has a helping hand ready.","zh":"她總是隨時準備好伸出援手。"},{"en":"He held her hand and said nothing — that was enough.","zh":"他握住她的手什麼都沒說——那已經足夠了。"},{"en":"Give me a hand with this — it is too heavy.","zh":"幫我一下——這太重了。"},{"en":"She works with her hands every day — baker, crafter, maker.","zh":"她每天用雙手工作——麵包師、工藝師、製作者。"},{"en":"The situation got out of hand before anyone noticed.","zh":"情況在任何人注意到之前就失控了。"},{"en":"I have time on my hands this week — anything I can help with?","zh":"我這週有空——有什麼我能幫忙的嗎？"},{"en":"Old hands know things that cannot be taught in school.","zh":"老前輩知道一些學校教不了的東西。"},{"en":"She handed me the note without saying a word.","zh":"她把紙條遞給我，一句話都沒說。"},{"en":"Can you hand that to me? It is just out of reach.","zh":"你能把那個遞給我嗎？我就是夠不到。"},{"en":"Every great thing was built by human hands.","zh":"每一件偉大的事物都是由人的雙手建造的。"}]},{"word":"eye","pos":"noun","chinese":"眼睛；眼光","level":"A1","sentences":[{"en":"She has an eye for detail that no one else catches.","zh":"她有一種沒有人能比得上的細節眼光。"},{"en":"He could not take his eyes off the view.","zh":"他捨不得移開對那風景的目光。"},{"en":"I caught her eye across the room and smiled.","zh":"我在房間另一頭和她對上了眼，微笑了。"},{"en":"Keep an eye on this — it could be important.","zh":"注意這個——它可能很重要。"},{"en":"She sees the world through kind eyes.","zh":"她用善良的眼光看世界。"},{"en":"That painting caught my eye the moment I walked in.","zh":"那幅畫在我一走進去就吸引了我的目光。"},{"en":"In the eyes of the people who love you, you are enough.","zh":"在愛你的人眼中，你已經足夠了。"},{"en":"He had a twinkle in his eye — always up to something.","zh":"他眼睛裡有一種光芒——總是有些計謀。"},{"en":"She opened her eyes and saw things differently.","zh":"她睜開眼睛，以不同的方式看待事情。"},{"en":"I need to rest my eyes — too much screen time.","zh":"我需要讓眼睛休息——螢幕時間太多了。"}]},{"word":"heart","pos":"noun","chinese":"心臟；心","level":"A1","sentences":[{"en":"She has such a big heart — always giving.","zh":"她有一顆很大的心——總是在給予。"},{"en":"Follow your heart but take your brain with you.","zh":"跟隨你的心，但帶上你的大腦。"},{"en":"That song goes straight to my heart every time.","zh":"那首歌每次都直接打動我的心。"},{"en":"He speaks from the heart and people feel it.","zh":"他發自內心地說話，人們能感受到。"},{"en":"She put her whole heart into everything she made.","zh":"她把全心全意投入到她做的每一件事中。"},{"en":"A broken heart heals — it just takes time.","zh":"心碎會癒合——只是需要時間。"},{"en":"His heart was in the right place even when he got it wrong.","zh":"即使他做錯了，他的出發點是好的。"},{"en":"At the heart of it, we all want to feel seen.","zh":"歸根結底，我們都想要被看見。"},{"en":"She learned to listen to her heart over her fears.","zh":"她學會了傾聽自己的心而不是恐懼。"},{"en":"Home is wherever your heart is.","zh":"家在你心之所在。"}]},{"word":"mind","pos":"noun/verb","chinese":"心靈；想法；介意","level":"A1","sentences":[{"en":"She has a creative mind — always solving things differently.","zh":"她有一個創意的心靈——總是以不同的方式解決問題。"},{"en":"I cannot get it out of my mind.","zh":"我無法把它從腦海中趕走。"},{"en":"Do you mind if I sit here?","zh":"你介意我坐這裡嗎？"},{"en":"He keeps an open mind — rare and wonderful.","zh":"他保持開放的心態——難得而美好。"},{"en":"Never mind — it does not matter now.","zh":"算了——現在不重要了。"},{"en":"She changed her mind and I respected that.","zh":"她改變了主意，我尊重這一點。"},{"en":"Your mind is your most powerful tool — use it well.","zh":"你的心靈是你最強大的工具——好好使用它。"},{"en":"I spoke my mind and felt so much lighter.","zh":"我說出了心裡話，感覺輕鬆多了。"},{"en":"A calm mind makes better decisions.","zh":"平靜的心靈做出更好的決定。"},{"en":"She made up her mind and never looked back.","zh":"她下定了決心，再也沒有回頭看。"}]},{"word":"body","pos":"noun","chinese":"身體；群體","level":"A1","sentences":[{"en":"Listen to your body — it knows more than you think.","zh":"傾聽你的身體——它知道的比你想的更多。"},{"en":"She takes care of her body with movement and rest.","zh":"她通過運動和休息照顧她的身體。"},{"en":"Your body carries you through every experience — thank it.","zh":"你的身體帶你經歷每一段體驗——感謝它。"},{"en":"He learned to be comfortable in his own body.","zh":"他學會了對自己的身體感到自在。"},{"en":"Everybody reacts to stress differently — that is normal.","zh":"每個人對壓力的反應都不同——這是正常的。"},{"en":"She nourishes her body with food that makes her feel good.","zh":"她用讓她感覺良好的食物滋養身體。"},{"en":"Your body language says more than your words sometimes.","zh":"你的身體語言有時說的比你的話語更多。"},{"en":"Keep moving — a body in motion stays in motion.","zh":"保持運動——動起來的身體會持續運動。"},{"en":"She donated her body to science — a final act of generosity.","zh":"她把遺體捐給了科學——最後一個慷慨的行為。"},{"en":"The body keeps score — take care of your mental health too.","zh":"身體會記分——也要照顧好你的心理健康。"}]},{"word":"door","pos":"noun","chinese":"門；機會","level":"A1","sentences":[{"en":"She walked through the door and the room lit up.","zh":"她走進門，整個房間都亮了起來。"},{"en":"Close the door behind you — it is cold outside.","zh":"關上門——外面很冷。"},{"en":"He always holds the door for others — small but meaningful.","zh":"他總是為別人扶門——小事但有意義。"},{"en":"This opportunity is a door — open it.","zh":"這個機會是一扇門——打開它。"},{"en":"A closed door is not always a rejection — sometimes it is a redirect.","zh":"關閉的門並不總是拒絕——有時是重新導向。"},{"en":"She knocked on every door before the right one opened.","zh":"她敲了每一扇門，直到正確的一扇打開。"},{"en":"Next door neighbours can become lifelong friends.","zh":"隔壁鄰居可以成為一輩子的朋友。"},{"en":"When one door closes, another opens — believe it.","zh":"當一扇門關閉，另一扇門就會打開——相信它。"},{"en":"He left the door open — literally and figuratively.","zh":"他讓門保持開著——字面上和比喻上都是。"},{"en":"The door to change is always unlocked — you just have to turn the handle.","zh":"改變之門永遠是開著的——你只需要轉動門把。"}]},{"word":"light","pos":"noun/adjective/verb","chinese":"光；輕的；點燃","level":"A1","sentences":[{"en":"She turns on a lamp when she reads — soft light is best.","zh":"她閱讀時會打開一盞燈——柔和的光線最好。"},{"en":"Good light transforms how a place feels.","zh":"好的光線改變了一個地方的感覺。"},{"en":"He is the light in every room he enters.","zh":"他是他進入的每個房間裡的光。"},{"en":"Travel light — you do not need as much as you think.","zh":"輕裝旅行——你需要的沒有你想的那麼多。"},{"en":"Can you light the candles? I love the atmosphere.","zh":"你能點燃蠟燭嗎？我喜歡那種氣氛。"},{"en":"She saw things in a new light after their conversation.","zh":"他們對話後，她以新的眼光看待事物。"},{"en":"The morning light is my favourite time to take photos.","zh":"早晨的光線是我最喜歡拍照的時刻。"},{"en":"Make it light — this does not have to be so serious.","zh":"讓它輕鬆一點——這不必那麼嚴肅。"},{"en":"He was the light at the end of a very dark tunnel.","zh":"他是一條非常黑暗隧道盡頭的光。"},{"en":"At the end of the day, she chose lightness over heaviness.","zh":"在一天結束時，她選擇了輕盈而非沉重。"}]},{"word":"night","pos":"noun","chinese":"夜晚；晚上","level":"A1","sentences":[{"en":"Late nights are my most creative hours.","zh":"深夜是我最有創意的時間。"},{"en":"She loves the quiet of a city at night.","zh":"她喜歡城市夜晚的安靜。"},{"en":"Good night — I hope tomorrow is kinder.","zh":"晚安——希望明天更加溫柔。"},{"en":"He stayed up all night to finish the project.","zh":"他熬了一整夜完成那個項目。"},{"en":"Some nights I just want to sit by the window and think.","zh":"有些晚上我只是想坐在窗邊思考。"},{"en":"That night changed everything — in the best way.","zh":"那個夜晚改變了一切——以最好的方式。"},{"en":"She sleeps with the window open on warm nights.","zh":"在溫暖的夜晚，她開著窗睡覺。"},{"en":"The night sky here is incredible — so many stars.","zh":"這裡的夜空令人難以置信——那麼多星星。"},{"en":"Last night was one of those perfect evenings.","zh":"昨晚是那種完美的夜晚之一。"},{"en":"Night owls and early birds — both are valid.","zh":"夜貓子和早起的人——都是有效的生活方式。"}]},{"word":"room","pos":"noun","chinese":"房間；空間","level":"A1","sentences":[{"en":"She decorated her room to feel like a sanctuary.","zh":"她把房間裝飾得像一個聖所。"},{"en":"Is there room for one more at the table?","zh":"桌子旁邊還有多一個人的位子嗎？"},{"en":"He fills every room with his laugh.","zh":"他的笑聲充滿了每個房間。"},{"en":"There is always room to grow — in any area of life.","zh":"在生活的任何領域，總有成長的空間。"},{"en":"She made room in her schedule for rest.","zh":"她在日程中為休息騰出了空間。"},{"en":"Reading in a warm room on a rainy day is perfect.","zh":"在雨天的溫暖房間裡讀書是完美的。"},{"en":"He left the room before the argument could escalate.","zh":"他在爭論升級之前離開了房間。"},{"en":"Clean room, clear mind — there is definitely truth to that.","zh":"整潔的房間，清晰的心智——這確實有道理。"},{"en":"She saved room for dessert — always.","zh":"她總是留著肚子吃甜點。"},{"en":"Give yourself room to breathe — do not overschedule.","zh":"給自己喘息的空間——不要把日程排得太滿。"}]},{"word":"city","pos":"noun","chinese":"城市；都市","level":"A1","sentences":[{"en":"She fell in love with the city from the first taxi ride.","zh":"她從第一次坐計程車就愛上了這座城市。"},{"en":"Living in a big city is exciting and exhausting in equal measure.","zh":"住在大城市既令人興奮又令人疲憊，兩者兼而有之。"},{"en":"He knows every hidden gem in the city.","zh":"他知道城市裡每一個隱藏的寶藏。"},{"en":"The city at sunrise is a completely different animal.","zh":"日出時的城市是完全不同的景象。"},{"en":"She misses her home city every time she smells the food.","zh":"每次聞到那種食物的味道，她都會想念她的故鄉城市。"},{"en":"City life is not for everyone — and that is okay.","zh":"城市生活不適合所有人——這沒關係。"},{"en":"He explored a new city for three days without a plan.","zh":"他花了三天沒有計畫地探索一座新城市。"},{"en":"The city never sleeps but I need to.","zh":"城市永不入睡，但我需要。"},{"en":"She discovered her favourite café in a city she had never planned to visit.","zh":"她在一個她從未計畫參觀的城市發現了她最喜歡的咖啡廳。"},{"en":"Every city has a personality — I love finding it.","zh":"每個城市都有自己的個性——我喜歡發現它。"}]},{"word":"phone","pos":"noun","chinese":"電話；手機","level":"A1","sentences":[{"en":"My phone died at the worst possible moment.","zh":"我的手機在最糟糕的時刻沒電了。"},{"en":"She puts her phone away at dinner — I respect that.","zh":"她吃飯時把手機收起來——我很尊重這一點。"},{"en":"Can I use your phone? Mine has no signal.","zh":"我可以用你的手機嗎？我的沒有信號。"},{"en":"He talks on the phone while walking — always multitasking.","zh":"他一邊走路一邊打電話——總是在多工。"},{"en":"I dropped my phone and held my breath.","zh":"我把手機摔了，屏住呼吸。"},{"en":"She finally answered the phone after ten missed calls.","zh":"她在十個未接來電後終於接了電話。"},{"en":"The first thing I do every morning is check my phone — I want to change that.","zh":"我每天早上做的第一件事就是查看手機——我想改變這一點。"},{"en":"He left his phone at home on purpose and felt so free.","zh":"他故意把手機留在家裡，感到非常自由。"},{"en":"She called instead of texting — that felt thoughtful.","zh":"她選擇打電話而不是發訊息——這讓人感到貼心。"},{"en":"A phone-free evening once a week makes a huge difference.","zh":"每週一個不用手機的晚上會帶來巨大的改變。"}]},{"word":"car","pos":"noun","chinese":"汽車；車","level":"A1","sentences":[{"en":"She loves road trips — the car is her happy place.","zh":"她喜歡公路旅行——車是她的快樂場所。"},{"en":"He takes care of his car like it is family.","zh":"他照顧他的車就像家人一樣。"},{"en":"I take the bus instead of the car when I can.","zh":"我盡量坐公車而不開車。"},{"en":"The car broke down on the motorway — worst timing.","zh":"車在高速公路上拋錨了——最糟糕的時機。"},{"en":"She sang at the top of her lungs in the car alone.","zh":"她獨自在車裡放聲高唱。"},{"en":"His car is old but he says it has character.","zh":"他的車很舊，但他說它有個性。"},{"en":"Car journeys with good company and music — pure joy.","zh":"和好伴侶、好音樂的車程——純粹的快樂。"},{"en":"Parking in this city is a nightmare.","zh":"在這個城市停車是一場噩夢。"},{"en":"She drives the same car for ten years — why change what works?","zh":"她開了同一輛車十年——為什麼要改變有效的東西呢？"},{"en":"The car ride home was the quietest and most peaceful part of my day.","zh":"回家的車程是我一天中最安靜、最平靜的部分。"}]},{"word":"colour","pos":"noun","chinese":"顏色；色彩","level":"A1","sentences":[{"en":"She wears colour boldly and it suits her perfectly.","zh":"她大膽地穿著彩色，非常適合她。"},{"en":"The autumn colours here are breathtaking.","zh":"這裡的秋天色彩令人嘆為觀止。"},{"en":"He sees colour in places others miss.","zh":"他在別人錯過的地方看到色彩。"},{"en":"What colour should I paint this wall?","zh":"我應該把這面牆刷成什麼顏色？"},{"en":"She painted her bedroom a deep green and loved it.","zh":"她把臥室刷成深綠色，非常喜歡。"},{"en":"Colours affect your mood more than you realise.","zh":"顏色對你情緒的影響比你意識到的更大。"},{"en":"His personality adds colour to every group he joins.","zh":"他的個性為他加入的每個群體增添了色彩。"},{"en":"She added a pop of colour to an all-neutral outfit.","zh":"她在全中性色的服裝上加了一抹亮色。"},{"en":"That photo has beautiful, muted colours.","zh":"那張照片有美麗的、柔和的顏色。"},{"en":"Life is more colourful with the right people in it.","zh":"有了對的人，生活會更加多彩。"}]},{"word":"age","pos":"noun","chinese":"年齡；時代","level":"A1","sentences":[{"en":"Age is just a number — it is how you feel that matters.","zh":"年齡只是一個數字——感覺才是重要的。"},{"en":"She discovered her passion at an age when others retire.","zh":"她在別人退休的年齡發現了她的熱情。"},{"en":"He acts his age sometimes and forgets it other times.","zh":"他有時候表現得很成熟，有時候又忘記自己的年紀。"},{"en":"People of all ages can learn new things.","zh":"所有年齡的人都可以學習新事物。"},{"en":"What age were you when you realised what you wanted to do?","zh":"你幾歲的時候意識到了你想做什麼？"},{"en":"She looks younger than her age — she credits joy.","zh":"她看起來比她的年齡更年輕——她說這歸功於快樂。"},{"en":"In this day and age, information is everywhere.","zh":"在這個時代，信息無處不在。"},{"en":"Every age has its own beauty — even the hard ones.","zh":"每個年齡都有自己的美麗——即使是艱難的年齡。"},{"en":"He started over at fifty — age is just a starting point.","zh":"他在五十歲重新開始——年齡只是一個起點。"},{"en":"You are never too old or too young to follow your instincts.","zh":"你永遠不會太老或太年輕去跟隨你的直覺。"}]},{"word":"idea","pos":"noun","chinese":"想法；主意","level":"A1","sentences":[{"en":"That is a brilliant idea — why did I not think of that?","zh":"那是個好主意——我怎麼沒想到？"},{"en":"She always has an idea when everyone else is stuck.","zh":"當其他人都卡住時，她總有一個想法。"},{"en":"I had an idea in the shower — naturally.","zh":"我在淋浴時有了一個想法——當然。"},{"en":"The idea started small and grew into something huge.","zh":"這個想法一開始很小，慢慢發展成了龐大的東西。"},{"en":"He never dismisses an idea before thinking it through.","zh":"他從不在深思熟慮之前就否定一個想法。"},{"en":"That idea is ahead of its time — come back to it.","zh":"那個想法超前了——之後再回來想。"},{"en":"She shared her idea nervously and it landed perfectly.","zh":"她緊張地分享了她的想法，結果非常成功。"},{"en":"I have no idea — let me find out and get back to you.","zh":"我不知道——讓我查一下再回覆你。"},{"en":"Good ideas need action — not just conversation.","zh":"好想法需要行動——不只是討論。"},{"en":"That idea changed the whole direction of the project.","zh":"那個想法改變了整個項目的方向。"}]},{"word":"answer","pos":"noun/verb","chinese":"答案；回答","level":"A1","sentences":[{"en":"She always has an answer — and it is usually right.","zh":"她總是有答案——通常都是對的。"},{"en":"I do not have all the answers and I have made peace with that.","zh":"我沒有所有答案，我已經接受了這一點。"},{"en":"Can you answer the phone? I am in the middle of something.","zh":"你能接電話嗎？我正在忙。"},{"en":"He thought about the question before answering.","zh":"他在回答之前思考了這個問題。"},{"en":"Not every question has a clean answer.","zh":"並非每個問題都有清晰的答案。"},{"en":"She answered honestly even when it was hard.","zh":"她誠實地回答，即使這很難。"},{"en":"The answer was in front of me the whole time.","zh":"答案一直就在我面前。"},{"en":"He does not answer messages right away — she respects that.","zh":"他不會立刻回覆訊息——她尊重這一點。"},{"en":"Sometimes the answer is just: I need more time.","zh":"有時候答案就是：我需要更多時間。"},{"en":"She found the answer by asking a better question.","zh":"她通過問一個更好的問題找到了答案。"}]},{"word":"improve","pos":"verb","chinese":"改善；提升","level":"A2","sentences":[{"en":"My English has improved a lot since I started using this app.","zh":"自從我開始使用這個 App，我的英文進步了很多。"},{"en":"She improved her cooking by watching videos every weekend.","zh":"她通過每週末看視頻提升了她的廚藝。"},{"en":"There is always room to improve — never stop learning.","zh":"總有進步的空間——永遠不要停止學習。"},{"en":"He improved his mood by going for a walk.","zh":"他通過散步改善了心情。"},{"en":"We can improve the plan — let me suggest some changes.","zh":"我們可以改進這個計畫——讓我提些修改意見。"},{"en":"She improved at a pace that surprised even herself.","zh":"她進步的速度甚至讓她自己都感到驚訝。"},{"en":"Improving one small habit changed everything.","zh":"改善一個小習慣改變了一切。"},{"en":"The weather is expected to improve by the weekend.","zh":"天氣預計到週末會改善。"},{"en":"He improved his posture and his confidence followed.","zh":"他改善了姿勢，自信隨之而來。"},{"en":"Consistent practice is the only way to improve.","zh":"持續練習是進步的唯一方式。"}]},{"word":"decide","pos":"verb","chinese":"決定；下決心","level":"A2","sentences":[{"en":"She decided to stop waiting and just go for it.","zh":"她決定不再等待，直接去做。"},{"en":"Have you decided what to order yet?","zh":"你決定好要點什麼了嗎？"},{"en":"He decided against it at the last minute.","zh":"他在最後一刻決定不做了。"},{"en":"Deciding what to wear takes me longer than it should.","zh":"決定穿什麼花的時間比應該花的要長。"},{"en":"I decided to be honest even if it was uncomfortable.","zh":"我決定誠實，即使這不舒服。"},{"en":"She made the decision and never second-guessed it.","zh":"她做了決定，從未後悔。"},{"en":"You decide how you respond — that is your power.","zh":"你決定你如何回應——那是你的力量。"},{"en":"He decided that today was the day he would start.","zh":"他決定今天就是他開始的那天。"},{"en":"When you cannot decide, flip a coin and notice your reaction.","zh":"當你無法決定時，拋硬幣，注意你的反應。"},{"en":"She decided the most important things first.","zh":"她首先決定最重要的事情。"}]},{"word":"explain","pos":"verb","chinese":"解釋；說明","level":"A2","sentences":[{"en":"Can you explain that again? I did not quite follow.","zh":"你能再解釋一遍嗎？我沒有完全理解。"},{"en":"She explained the concept simply and clearly.","zh":"她簡單清楚地解釋了這個概念。"},{"en":"I cannot explain how much that moment meant to me.","zh":"我無法解釋那個時刻對我的意義有多深。"},{"en":"He explained his thinking and suddenly everyone agreed.","zh":"他解釋了他的思路，突然間大家都同意了。"},{"en":"Can you explain why you made that decision?","zh":"你能解釋為什麼你做了那個決定嗎？"},{"en":"She explained it with patience and no frustration.","zh":"她耐心而不氣餒地解釋了。"},{"en":"I do not need to explain myself to everyone.","zh":"我不需要向所有人解釋自己。"},{"en":"He explained the situation and the tension dropped.","zh":"他解釋了情況，緊張氣氛消散了。"},{"en":"Some things are hard to explain but easy to feel.","zh":"有些事情很難解釋，但很容易感受到。"},{"en":"She asked him to explain — and he finally did.","zh":"她要他解釋——他終於開口了。"}]},{"word":"suggest","pos":"verb","chinese":"建議；暗示","level":"A2","sentences":[{"en":"Can I suggest something? Try it without sugar first.","zh":"我可以建議一件事嗎？先試試不加糖的。"},{"en":"She suggested they take the scenic route and they did.","zh":"她建議他們走景觀路線，他們照做了。"},{"en":"What would you suggest for someone visiting for the first time?","zh":"你對第一次來訪的人有什麼建議？"},{"en":"He suggested a compromise and everyone was satisfied.","zh":"他提議了一個妥協方案，所有人都滿意了。"},{"en":"I am not telling you what to do — just suggesting.","zh":"我不是在告訴你怎麼做——只是建議。"},{"en":"She suggested reading the book before watching the film.","zh":"她建議先讀書再看電影。"},{"en":"The data suggests that the plan needs adjusting.","zh":"數據顯示計畫需要調整。"},{"en":"He suggested an early start to avoid the crowds.","zh":"他建議早點出發以避開人潮。"},{"en":"I would suggest sleeping on it before deciding.","zh":"我建議先睡一覺再做決定。"},{"en":"What are you suggesting — that I was wrong?","zh":"你在暗示什麼——我錯了嗎？"}]},{"word":"agree","pos":"verb","chinese":"同意；贊成","level":"A2","sentences":[{"en":"I completely agree — you put it better than I could.","zh":"我完全同意——你說得比我好。"},{"en":"She agrees with the plan but wants to adjust the timeline.","zh":"她同意這個計畫，但想調整時間線。"},{"en":"We do not always agree and that is actually healthy.","zh":"我們並不總是同意，這其實是健康的。"},{"en":"He agreed reluctantly but came through in the end.","zh":"他勉強同意了，但最後還是做到了。"},{"en":"I hate to agree with him but he has a point.","zh":"我不想同意他，但他說得有道理。"},{"en":"They agreed to disagree — and the friendship survived.","zh":"他們同意各持己見——友誼因此得以延續。"},{"en":"She agreed to help before I even finished asking.","zh":"她在我問完之前就同意幫忙了。"},{"en":"Most people agree that kindness costs nothing.","zh":"大多數人同意善良不需要任何代價。"},{"en":"I agree with the principle but question the method.","zh":"我同意這個原則，但質疑這個方法。"},{"en":"He finally agreed and everyone moved forward.","zh":"他終於同意了，大家繼續前進。"}]},{"word":"disagree","pos":"verb","chinese":"不同意；有異議","level":"A2","sentences":[{"en":"I respectfully disagree — here is my perspective.","zh":"我尊重地表示不同意——這是我的看法。"},{"en":"She disagreed but did not argue — just stated her view calmly.","zh":"她不同意，但沒有爭吵——只是冷靜地表明了自己的觀點。"},{"en":"It is okay to disagree with someone you respect.","zh":"與你尊重的人意見不同是沒關係的。"},{"en":"We disagree on methods but agree on the goal.","zh":"我們在方法上有分歧，但在目標上達成共識。"},{"en":"He disagreed strongly but listened before responding.","zh":"他強烈反對，但在回應之前先傾聽了。"},{"en":"Healthy relationships survive disagreement.","zh":"健康的關係能夠承受分歧。"},{"en":"I completely disagree — let me explain why.","zh":"我完全不同意——讓我解釋原因。"},{"en":"She was not afraid to disagree with the majority.","zh":"她不害怕與多數人意見相左。"},{"en":"They disagreed in public but worked it out privately.","zh":"他們在公眾場合有分歧，但私下解決了。"},{"en":"Disagreement done right leads to better ideas.","zh":"正確地表達不同意見會帶來更好的想法。"}]},{"word":"promise","pos":"verb/noun","chinese":"承諾；保證","level":"A2","sentences":[{"en":"She always keeps her promises — that is rare.","zh":"她總是履行承諾——這很難得。"},{"en":"I promise I will call you when I land.","zh":"我保證我落地後會打電話給你。"},{"en":"He made a promise to himself and kept it for ten years.","zh":"他對自己許下了諾言，並保守了十年。"},{"en":"Do not make promises you cannot keep.","zh":"不要做你無法兌現的承諾。"},{"en":"She promised to be honest and she was.","zh":"她承諾要誠實，她做到了。"},{"en":"That young artist shows great promise.","zh":"那位年輕藝術家展現出了巨大的潛力。"},{"en":"I promised myself one thing: no more wasted time.","zh":"我答應自己一件事：不再浪費時間。"},{"en":"He broke his promise and it damaged the trust.","zh":"他違背了承諾，這損害了信任。"},{"en":"A promise made in the dark still counts in the light.","zh":"在黑暗中許下的承諾在光天化日之下同樣有效。"},{"en":"She did not promise the outcome — just the effort.","zh":"她沒有承諾結果——只承諾努力。"}]},{"word":"remember","pos":"verb","chinese":"記得；記住","level":"A2","sentences":[{"en":"I remember exactly where I was when I heard that news.","zh":"我確切地記得我聽到那個消息時在哪裡。"},{"en":"She remembers everyone's birthday — even without reminders.","zh":"她記得每個人的生日——即使沒有提醒。"},{"en":"Remember to drink water today — you always forget.","zh":"記得今天喝水——你總是忘記。"},{"en":"I want to remember this moment forever.","zh":"我想永遠記住這個時刻。"},{"en":"He remembered the important things even when life got busy.","zh":"即使生活變得忙碌，他也記住了重要的事情。"},{"en":"Do you remember the first time we met?","zh":"你記得我們第一次見面嗎？"},{"en":"She remembered everything but pretended to forget.","zh":"她記得一切，但假裝忘記了。"},{"en":"Remember: you have come so far already.","zh":"記住：你已經走了很遠了。"},{"en":"I barely remember what I had for breakfast.","zh":"我幾乎不記得我早餐吃了什麼。"},{"en":"He is remembered for his kindness more than anything.","zh":"他最讓人記住的是他的善良。"}]},{"word":"forget","pos":"verb","chinese":"忘記；遺忘","level":"A2","sentences":[{"en":"I forgot my umbrella — again.","zh":"我又忘了帶雨傘。"},{"en":"She forgot his name the moment he said it.","zh":"她在他說出名字的那一刻就忘記了。"},{"en":"Forget it — do not waste energy on that.","zh":"算了——不要在那件事上浪費精力。"},{"en":"He forgot her birthday and spent a week making it up.","zh":"他忘記了她的生日，花了一週時間彌補。"},{"en":"I never forget a face but always forget a name.","zh":"我從不忘記一張臉，但總是忘記名字。"},{"en":"She forgot to eat when she was deep in a project.","zh":"她在深入一個項目時忘記了吃飯。"},{"en":"Forget the past — today is what matters.","zh":"忘掉過去——今天才是重要的。"},{"en":"He could not forget what she said even if he tried.","zh":"即使他努力嘗試，他也無法忘記她說的話。"},{"en":"Some things are better forgotten.","zh":"有些事情最好被遺忘。"},{"en":"She reminded me of something I had almost forgotten.","zh":"她提醒了我一件我幾乎忘記的事情。"}]},{"word":"enjoy","pos":"verb","chinese":"享受；喜歡","level":"A2","sentences":[{"en":"She genuinely enjoys the process, not just the result.","zh":"她真心享受過程，而不只是結果。"},{"en":"Do you enjoy cooking or is it just a chore?","zh":"你喜歡做飯還是它只是一件雜務？"},{"en":"I enjoy long walks without a destination.","zh":"我喜歡沒有目的地的長距離步行。"},{"en":"He enjoys being alone just as much as being with people.","zh":"他喜歡獨處，就像喜歡和人在一起一樣。"},{"en":"Enjoy this moment — it will not last forever.","zh":"享受這個時刻——它不會永遠持續。"},{"en":"She enjoys the little things more than most.","zh":"她比大多數人更享受小事情。"},{"en":"I enjoyed every second of that holiday.","zh":"我享受了那次假期的每一秒。"},{"en":"He enjoys learning but hates being tested.","zh":"他喜歡學習，但討厭被測試。"},{"en":"Enjoy the journey — not just the destination.","zh":"享受旅程——不只是目的地。"},{"en":"She found something to enjoy in every situation.","zh":"她在每個情況中都找到了可以享受的東西。"}]},{"word":"prepare","pos":"verb","chinese":"準備；預備","level":"A2","sentences":[{"en":"She prepared thoroughly and it showed in the results.","zh":"她準備充分，結果中有所體現。"},{"en":"I need to prepare for this meeting — give me ten minutes.","zh":"我需要為這個會議做準備——給我十分鐘。"},{"en":"He prepares for the worst while hoping for the best.","zh":"他做最壞的打算，同時希望最好的結果。"},{"en":"Prepare for change — it is the only constant.","zh":"為改變做準備——它是唯一不變的事物。"},{"en":"She prepared a meal for twenty people without breaking a sweat.","zh":"她為二十個人準備了一頓飯，毫不費力。"},{"en":"Being prepared builds confidence.","zh":"有準備會建立自信。"},{"en":"He prepared his speech for weeks but still seemed nervous.","zh":"他為演講準備了幾週，但仍然看起來很緊張。"},{"en":"I am not prepared for how emotional this is going to be.","zh":"我沒有為這會有多感人做好準備。"},{"en":"She prepared the room with flowers and candles — perfect.","zh":"她用花和蠟燭準備好了房間——完美。"},{"en":"Proper preparation prevents poor performance.","zh":"充分的準備防止糟糕的表現。"}]},{"word":"realise","pos":"verb","chinese":"意識到；認識到","level":"A2","sentences":[{"en":"I only realised how tired I was when I sat down.","zh":"直到我坐下來，我才意識到我有多累。"},{"en":"She realised late but she still got there.","zh":"她意識到得晚，但她還是到達了。"},{"en":"He realised he was wrong and apologised immediately.","zh":"他意識到自己錯了，立刻道歉了。"},{"en":"I did not realise how much I had grown until I looked back.","zh":"直到回顧，我才意識到我成長了多少。"},{"en":"She realised that the problem was not outside — it was inside.","zh":"她意識到問題不在外面——而在裡面。"},{"en":"Realising your worth is one of the best things you can do.","zh":"意識到你的價值是你能做的最好的事情之一。"},{"en":"He realised his dream took a completely different shape than planned.","zh":"他意識到他的夢想採取了一種與計畫完全不同的形態。"},{"en":"I just realised we have been talking for three hours.","zh":"我剛意識到我們已經聊了三個小時了。"},{"en":"She did not realise how far she had come.","zh":"她沒有意識到她已經走了多遠。"},{"en":"Realising you need help is a sign of strength.","zh":"意識到你需要幫助是一種力量的表現。"}]},{"word":"worry","pos":"verb/noun","chinese":"擔心；憂慮","level":"A2","sentences":[{"en":"I worry too much about things I cannot control.","zh":"我對我無法控制的事情擔心得太多了。"},{"en":"She worries about everyone except herself.","zh":"她為所有人擔心，唯獨不擔心自己。"},{"en":"Do not worry — I have done this a hundred times.","zh":"不要擔心——我已經做了一百次了。"},{"en":"He has a way of making you worry less.","zh":"他有一種讓你少擔心的方式。"},{"en":"I know I should not worry but I cannot help it.","zh":"我知道我不應該擔心，但我忍不住。"},{"en":"She stopped worrying when she started planning.","zh":"她開始計畫後就停止了擔心。"},{"en":"Worry is just imagination pointed in the wrong direction.","zh":"擔心只是想象力指向了錯誤的方向。"},{"en":"His biggest worry is never having enough time.","zh":"他最大的擔憂是永遠沒有足夠的時間。"},{"en":"Do not worry about tomorrow — today needs your attention.","zh":"不要擔心明天——今天需要你的注意力。"},{"en":"She carried her worries quietly but they were always there.","zh":"她默默地承受著擔憂，但它們一直都在。"}]},{"word":"hope","pos":"verb/noun","chinese":"希望；期望","level":"A2","sentences":[{"en":"I hope you know how much you matter.","zh":"我希望你知道你有多重要。"},{"en":"She holds onto hope even when things look dark.","zh":"即使情況看起來很黑暗，她也抱有希望。"},{"en":"He hoped for the best and planned for the worst.","zh":"他希望最好的結果，同時為最壞的情況做計畫。"},{"en":"I hope this works — we have given it everything.","zh":"我希望這能奏效——我們已經全力以赴了。"},{"en":"She lost hope for a while but found it again.","zh":"她一度失去了希望，但又找到了它。"},{"en":"Hope is not a strategy — but it helps.","zh":"希望不是一種策略——但它有幫助。"},{"en":"He never lost hope even when everyone else did.","zh":"即使其他人都放棄了，他也從未失去希望。"},{"en":"I hope our paths cross again someday.","zh":"我希望有一天我們的路會再次交叉。"},{"en":"She gave others hope just by showing up.","zh":"她只是出現就給了別人希望。"},{"en":"Where there is life, there is always hope.","zh":"有生命的地方，總有希望。"}]},{"word":"miss","pos":"verb","chinese":"想念；錯過","level":"A2","sentences":[{"en":"I miss her every time I hear that song.","zh":"每次聽到那首歌，我都想念她。"},{"en":"She missed the bus but found a better route.","zh":"她錯過了公車，但找到了更好的路線。"},{"en":"Do not miss this opportunity — it will not come again.","zh":"不要錯過這個機會——它不會再來了。"},{"en":"He misses home in a quiet, persistent way.","zh":"他以一種安靜、持續的方式思念家鄉。"},{"en":"I missed you so much — it is good to have you back.","zh":"我非常想念你——很高興你回來了。"},{"en":"She missed the point but arrived at a better one.","zh":"她錯過了重點，但找到了一個更好的觀點。"},{"en":"Missing someone is hard but it means they mattered.","zh":"想念某人很難，但這意味著他們很重要。"},{"en":"He would not miss a single one of his daughter's recitals.","zh":"他不會錯過女兒的任何一場音樂會。"},{"en":"I miss the version of me that had no worries.","zh":"我想念那個沒有煩惱的我。"},{"en":"She missed the detail the first time — caught it on the second read.","zh":"她第一次看時錯過了細節——第二次閱讀時才發現。"}]},{"word":"choose","pos":"verb","chinese":"選擇；挑選","level":"A2","sentences":[{"en":"She chose kindness when she could have chosen revenge.","zh":"她在可以選擇報復時選擇了善良。"},{"en":"You always have a choice — even when it does not feel like it.","zh":"你總是有選擇的——即使感覺不像。"},{"en":"I cannot choose — they are both so good.","zh":"我無法選擇——它們都太好了。"},{"en":"He chose a path less travelled and it made all the difference.","zh":"他選擇了一條少有人走的路，這帶來了巨大的差異。"},{"en":"Choose your hard: hard now or harder later.","zh":"選擇你的艱難：現在艱難，還是之後更艱難。"},{"en":"She chose rest over productivity and it was the right call.","zh":"她選擇了休息而不是生產力，這是正確的決定。"},{"en":"When in doubt, choose the option you will not regret.","zh":"有疑問時，選擇你不會後悔的選項。"},{"en":"He chose his battles carefully.","zh":"他謹慎地選擇了他的戰場。"},{"en":"I choose to see the good in this.","zh":"我選擇從中看到好的一面。"},{"en":"Choosing yourself is not selfish — it is necessary.","zh":"選擇自己並不是自私——而是必要的。"}]},{"word":"change","pos":"verb/noun","chinese":"改變；變化","level":"A2","sentences":[{"en":"She changed her life by changing one small habit.","zh":"她通過改變一個小習慣改變了她的生活。"},{"en":"Change is uncomfortable but growth lives on the other side.","zh":"改變是不舒服的，但成長就在另一面。"},{"en":"He changed so much over the years — for the better.","zh":"多年來他改變了很多——變得更好了。"},{"en":"Can you change your appointment to Thursday?","zh":"你能把預約改到星期四嗎？"},{"en":"She does not fear change — she welcomes it.","zh":"她不害怕改變——她歡迎它。"},{"en":"Change often starts with one conversation.","zh":"改變通常從一次對話開始。"},{"en":"I need a change of scenery — let's get out of here.","zh":"我需要換個環境——我們走吧。"},{"en":"He changed his mind and nobody held it against him.","zh":"他改變了主意，沒有人因此責怪他。"},{"en":"The world changes fast — learn to adapt.","zh":"世界變化很快——學會適應。"},{"en":"She changed the energy of the room just by walking in.","zh":"她只是走進來就改變了整個房間的氛圍。"}]},{"word":"plan","pos":"verb/noun","chinese":"計畫；打算","level":"A2","sentences":[{"en":"She plans everything but stays open to change.","zh":"她計畫一切，但對改變保持開放。"},{"en":"What is the plan for this weekend?","zh":"這個週末的計畫是什麼？"},{"en":"He planned the trip for six months and it was perfect.","zh":"他計畫了六個月的旅行，非常完美。"},{"en":"Plans change — that is part of the adventure.","zh":"計畫會改變——那是冒險的一部分。"},{"en":"I plan to finish this by the end of the week.","zh":"我計畫在週末之前完成這個。"},{"en":"She did not have a plan and somehow that worked.","zh":"她沒有計畫，但不知怎麼就成功了。"},{"en":"Plan for the long term but live in the short term.","zh":"為長遠計畫，但活在當下。"},{"en":"His plan B was better than his plan A.","zh":"他的計畫B比計畫A更好。"},{"en":"I plan less these days and enjoy more.","zh":"我現在計畫少了，享受多了。"},{"en":"A plan is just a good intention without action.","zh":"沒有行動，計畫只是一個美好的意願。"}]},{"word":"share","pos":"verb","chinese":"分享；共享","level":"A2","sentences":[{"en":"She shares everything — food, time, attention.","zh":"她分享一切——食物、時間、注意力。"},{"en":"I want to share something that changed my perspective.","zh":"我想分享一件改變了我視角的事情。"},{"en":"He shared the credit with the whole team.","zh":"他把功勞分給了整個團隊。"},{"en":"Can we share a dessert? I cannot finish a whole one.","zh":"我們可以分享一個甜點嗎？我吃不完一個完整的。"},{"en":"She shared her story and the response was overwhelming.","zh":"她分享了她的故事，反響非常熱烈。"},{"en":"Sharing a meal is one of my love languages.","zh":"分享一頓飯是我的一種愛的語言。"},{"en":"He does not overshare — he chooses what to offer.","zh":"他不會過度分享——他選擇分享什麼。"},{"en":"Sharing vulnerability creates connection.","zh":"分享脆弱可以建立連結。"},{"en":"She shares her knowledge freely and generously.","zh":"她慷慨地分享她的知識。"},{"en":"The best experiences are meant to be shared.","zh":"最好的體驗是要被分享的。"}]},{"word":"support","pos":"verb/noun","chinese":"支持；支援","level":"A2","sentences":[{"en":"She always supports the people she believes in.","zh":"她總是支持她相信的人。"},{"en":"I need your support right now — not your advice.","zh":"我現在需要你的支持——不是你的建議。"},{"en":"He supported her decision even when he disagreed.","zh":"即使他不同意，他也支持了她的決定。"},{"en":"Emotional support is sometimes more valuable than practical help.","zh":"情感支持有時比實際幫助更有價值。"},{"en":"She built a support system before she needed it.","zh":"她在需要之前就建立了支持系統。"},{"en":"Support does not mean agreement — it means showing up.","zh":"支持不意味著同意——而是出現。"},{"en":"I feel so supported in this team.","zh":"我在這個團隊中感到非常被支持。"},{"en":"He supported the cause with both time and money.","zh":"他用時間和金錢支持了這項事業。"},{"en":"Good support can make the impossible feel possible.","zh":"好的支持可以讓不可能的事情感覺可能。"},{"en":"She quietly supported from the background — always there.","zh":"她靜靜地在背後支持——一直都在。"}]},{"word":"experience","pos":"noun/verb","chinese":"經歷；體驗；經驗","level":"A2","sentences":[{"en":"That experience shaped who she is today.","zh":"那段經歷塑造了她今天的樣子。"},{"en":"I have never experienced anything like that before.","zh":"我以前從未經歷過那樣的事情。"},{"en":"He brings ten years of experience to every project.","zh":"他為每個項目帶來十年的經驗。"},{"en":"Every experience — good or bad — teaches you something.","zh":"每一次經歷——好的或壞的——都教你一些東西。"},{"en":"She experienced the city differently because she slowed down.","zh":"她因為放慢腳步，以不同的方式體驗了這座城市。"},{"en":"I want more experiences and fewer things.","zh":"我想要更多體驗，而不是更多物品。"},{"en":"His experience in that field is unmatched.","zh":"他在那個領域的經驗是無與倫比的。"},{"en":"The travel experience changed her entirely.","zh":"旅行體驗完全改變了她。"},{"en":"I am still processing that experience.","zh":"我仍在消化那段經歷。"},{"en":"Experience is the best teacher — and the most expensive.","zh":"經驗是最好的老師——也是最昂貴的。"}]},{"word":"clean","pos":"adjective/verb","chinese":"乾淨的；清潔","level":"A1","sentences":[{"en":"She keeps her workspace incredibly clean.","zh":"她把工作空間保持得非常整潔。"},{"en":"Clean your desk once a week — it changes your mood.","zh":"每週清理一次桌子——它能改變你的心情。"},{"en":"I feel so much better in a clean space.","zh":"在乾淨的空間裡我感覺好多了。"},{"en":"He has a very clean design aesthetic.","zh":"他有一種非常簡潔的設計美學。"},{"en":"Can I get a clean copy of this document?","zh":"我可以得到這份文件的乾淨副本嗎？"},{"en":"She comes clean about her mistakes quickly.","zh":"她很快地坦承自己的錯誤。"},{"en":"A clean break is sometimes the kindest thing.","zh":"乾淨俐落的分離有時是最善意的方式。"},{"en":"He eats clean most of the time but enjoys treats too.","zh":"他大多數時候吃得很健康，但也享受美食。"},{"en":"Clean hands, clear conscience.","zh":"乾淨的雙手，清晰的良知。"},{"en":"She started fresh with a clean slate.","zh":"她以全新的開始，乾淨的石板重新出發。"}]},{"word":"full","pos":"adjective","chinese":"滿的；完整的","level":"A1","sentences":[{"en":"I am completely full — that was the best meal.","zh":"我完全吃飽了——那是最好的一頓飯。"},{"en":"She lives a full life — always something going on.","zh":"她過著充實的生活——總是有事情發生。"},{"en":"The café was full so we waited outside.","zh":"咖啡廳滿座了，所以我們在外面等。"},{"en":"He gave his full attention and it made a difference.","zh":"他給予了全部的注意力，這帶來了差異。"},{"en":"I want a full refund — this is not what I ordered.","zh":"我要全額退款——這不是我點的東西。"},{"en":"She had a full schedule but made time anyway.","zh":"她有一個滿滿的日程，但還是抽出了時間。"},{"en":"The moon is full tonight — it looks beautiful.","zh":"今晚月圓——看起來很美麗。"},{"en":"I need the full story — not just part of it.","zh":"我需要完整的故事——不只是部分。"},{"en":"He came full circle — back where he started but different.","zh":"他兜了一個圈——回到了起點，但已不同。"},{"en":"A full heart is better than a full wallet.","zh":"充實的心比充實的錱包更好。"}]},{"word":"short","pos":"adjective/verb","chinese":"短的；矮的；缺乏","level":"A1","sentences":[{"en":"Life is short — stop waiting for the right moment.","zh":"人生短暫——停止等待正確的時機。"},{"en":"She keeps her emails short and to the point.","zh":"她的電子郵件簡短且直切重點。"},{"en":"I am a bit short on cash this month.","zh":"我這個月現金有點不夠。"},{"en":"He is short but his personality makes him the biggest person in the room.","zh":"他個子矮，但他的個性讓他成為房間裡最高大的人。"},{"en":"A short walk can solve a big problem.","zh":"短暫的散步可以解決大問題。"},{"en":"She cut her hair short and felt like a new person.","zh":"她把頭髮剪短了，感覺像換了個人。"},{"en":"I am falling short of my goals — time to reassess.","zh":"我在目標上落後了——是時候重新評估了。"},{"en":"The meeting was mercifully short.","zh":"那個會議短暫得令人慶幸。"},{"en":"She never falls short on kindness.","zh":"她在善意上從不短缺。"},{"en":"A short break can do wonders for your focus.","zh":"短暫的休息對你的專注力有神奇的效果。"}]},{"word":"long","pos":"adjective/verb","chinese":"長的；渴望","level":"A1","sentences":[{"en":"It has been a long day — I need to rest.","zh":"今天太漫長了——我需要休息。"},{"en":"She longed to travel the world before she could.","zh":"在她能夠旅行之前，她一直渴望環遊世界。"},{"en":"How long will this take? I have another meeting.","zh":"這需要多長時間？我還有另一個會議。"},{"en":"He wrote a long letter and sent it without reading it back.","zh":"他寫了一封長信，沒有重讀就寄出去了。"},{"en":"A long silence fell between them and neither broke it.","zh":"他們之間出現了長時間的沉默，誰都沒有打破它。"},{"en":"She longed for a simpler life.","zh":"她渴望一種更簡單的生活。"},{"en":"Long weekends are never long enough.","zh":"長週末永遠都不夠長。"},{"en":"It has been so long — I barely recognised him.","zh":"已經過了這麼長時間——我幾乎認不出他了。"},{"en":"She takes the long view on everything.","zh":"她對任何事情都持長遠的看法。"},{"en":"A long hug says more than any words.","zh":"一個長時間的擁抱比任何話語都說得更多。"}]},{"word":"strong","pos":"adjective","chinese":"強壯的；堅強的","level":"A1","sentences":[{"en":"She is one of the strongest people I know.","zh":"她是我認識的最堅強的人之一。"},{"en":"A strong cup of coffee is all I need.","zh":"我需要的只是一杯濃咖啡。"},{"en":"He built strong foundations — in work and in life.","zh":"他建立了牢固的基礎——在工作和生活中。"},{"en":"Strong opinions held loosely are the best kind.","zh":"以寬容態度持有強烈意見是最好的方式。"},{"en":"She stayed strong when everything told her to break.","zh":"當一切都告訴她要崩潰時，她保持堅強。"},{"en":"That argument is strong — hard to counter.","zh":"那個論點很有力——很難反駁。"},{"en":"A strong team can achieve anything.","zh":"一個強大的團隊可以實現任何事情。"},{"en":"He has a strong sense of who he is.","zh":"他對自己是誰有強烈的認知。"},{"en":"She came back stronger than before.","zh":"她比以前更強大地回來了。"},{"en":"Strength is not the absence of fear — it is moving forward despite it.","zh":"力量不是沒有恐懼——而是儘管恐懼仍然前進。"}]},{"word":"enough","pos":"adjective/adverb","chinese":"足夠的；夠了","level":"A1","sentences":[{"en":"You are enough — exactly as you are.","zh":"你就是足夠好的——就是現在的樣子。"},{"en":"I have had enough of this — let us solve it.","zh":"我受夠這個了——我們來解決它。"},{"en":"She works hard enough without needing to be told.","zh":"她不需要被告知就努力工作了。"},{"en":"Is there enough food for everyone?","zh":"食物夠所有人吃嗎？"},{"en":"He knew when enough was enough.","zh":"他知道什麼時候已經夠了。"},{"en":"Strangely, doing less sometimes is enough.","zh":"奇怪的是，有時候做少一些就足夠了。"},{"en":"She said enough to let me know but not too much.","zh":"她說的剛剛好讓我明白，但沒有說太多。"},{"en":"I do not earn enough to save much right now.","zh":"我現在賺的不夠多，無法存很多錢。"},{"en":"That apology was not enough — actions matter more.","zh":"那個道歉不夠——行動更重要。"},{"en":"Knowing you are enough changes everything.","zh":"知道你已經足夠好改變了一切。"}]},{"word":"same","pos":"adjective","chinese":"相同的；一樣的","level":"A1","sentences":[{"en":"We ordered the same thing without knowing.","zh":"我們在不知道的情況下點了相同的東西。"},{"en":"She feels the same way — you are not alone.","zh":"她有同樣的感受——你並不孤單。"},{"en":"He wears the same thing every day — frees up mental energy.","zh":"他每天穿同樣的衣服——節省心理能量。"},{"en":"Things are not the same without you here.","zh":"沒有你在這裡，一切都不一樣了。"},{"en":"I say the same thing every year and nothing changes.","zh":"我每年都說同樣的話，但什麼都沒有改變。"},{"en":"She learned the same lesson in a completely different way.","zh":"她以完全不同的方式學到了同樣的教訓。"},{"en":"At the same time, you have to consider the risk.","zh":"同時，你必須考慮風險。"},{"en":"He is not the same person he was five years ago.","zh":"他不是五年前那個人了。"},{"en":"Same time tomorrow?","zh":"明天同一時間？"},{"en":"We grew up in the same neighbourhood — that creates a bond.","zh":"我們在同一個社區長大——這建立了聯繫。"}]},{"word":"poor","pos":"adjective","chinese":"貧窮的；可憐的；差勁的","level":"A1","sentences":[{"en":"She grew up poor but never felt unloved.","zh":"她在貧困中長大，但從不感到缺乏愛。"},{"en":"Poor planning leads to poor results.","zh":"差勁的計畫帶來差勁的結果。"},{"en":"He made poor choices early but learned quickly.","zh":"他早期做了糟糕的選擇，但很快學到了教訓。"},{"en":"Poor thing — she has been working nonstop all week.","zh":"可憐的她——她整週都在不停地工作。"},{"en":"She had poor eyesight and finally got glasses.","zh":"她的視力很差，終於配了眼鏡。"},{"en":"Poor communication causes most relationship problems.","zh":"糟糕的溝通導致了大多數關係問題。"},{"en":"He is not a poor sport — takes losses gracefully.","zh":"他不是一個輸不起的人——優雅地接受失敗。"},{"en":"Poor nutrition shows up eventually.","zh":"糟糕的營養最終會顯現出來。"},{"en":"She had a poor start but a strong finish.","zh":"她有一個糟糕的開始，但有一個強勁的結局。"},{"en":"Do not mistake quiet for poor confidence.","zh":"不要把安靜誤認為是缺乏自信。"}]},{"word":"young","pos":"adjective","chinese":"年輕的；幼小的","level":"A1","sentences":[{"en":"She is young but thinks deeply about everything.","zh":"她年輕，但對一切都有深刻的思考。"},{"en":"I feel young when I am doing things I love.","zh":"當我在做我喜歡的事情時，我感到年輕。"},{"en":"He started his business while still young.","zh":"他在還年輕的時候就創業了。"},{"en":"Young people are rebuilding what they inherited.","zh":"年輕人正在重建他們繼承的東西。"},{"en":"She has been wise beyond her years since she was young.","zh":"她從年輕時就超越了她的年齡的智慧。"},{"en":"You are never too young to have strong values.","zh":"你永遠不會太年輕擁有強烈的價值觀。"},{"en":"The young artist's work took everyone by surprise.","zh":"那位年輕藝術家的作品讓所有人都感到驚訝。"},{"en":"I wish someone had told me this when I was younger.","zh":"我希望有人在我年輕的時候告訴過我這些。"},{"en":"She is young at heart and will be forever.","zh":"她心態永遠年輕。"},{"en":"Being young means making mistakes and learning fast.","zh":"年輕意味著犯錯並快速學習。"}]},{"word":"warm","pos":"adjective","chinese":"溫暖的；熱情的","level":"A1","sentences":[{"en":"She has the warmest laugh I have ever heard.","zh":"她有我聽過最溫暖的笑聲。"},{"en":"It finally got warm enough to sit outside.","zh":"終於夠暖和可以坐在外面了。"},{"en":"He has a warm personality — you feel it immediately.","zh":"他有一種溫暖的個性——你立刻就能感受到。"},{"en":"The warm light made everything look golden.","zh":"溫暖的光線讓一切看起來金黃燦爛。"},{"en":"She gave a warm welcome to everyone who walked in.","zh":"她熱情地歡迎每一個走進來的人。"},{"en":"I love warm evenings when you can leave the windows open.","zh":"我喜歡溫暖的夜晚，可以開著窗戶。"},{"en":"Warm colours make a space feel cosy.","zh":"溫暖的色彩讓空間感覺舒適。"},{"en":"He wrapped her in a warm embrace.","zh":"他用溫暖的擁抱把她包裹起來。"},{"en":"A warm cup of something always helps.","zh":"一杯熱飲總是有幫助的。"},{"en":"She made everyone feel warm and included.","zh":"她讓所有人都感到溫暖和被包容。"}]},{"word":"new","pos":"adjective","chinese":"新的；新鮮的","level":"A1","sentences":[{"en":"New year, new intentions — let us be intentional.","zh":"新年，新意圖——讓我們有意識地生活。"},{"en":"She always tries new things — no fear of the unfamiliar.","zh":"她總是嘗試新事物——不害怕陌生的東西。"},{"en":"What is new with you? I feel like we have not talked properly.","zh":"你有什麼新消息？我感覺我們已經很久沒有好好聊了。"},{"en":"He started a new chapter and the first page was terrifying.","zh":"他開始了新的篇章，第一頁令人恐懼。"},{"en":"The new café on the corner is worth trying.","zh":"街角的新咖啡廳值得一試。"},{"en":"Something new always starts right after something ends.","zh":"新事物總是在舊事物結束後開始。"},{"en":"She bought nothing new this year and loved it.","zh":"她今年什麼新東西都沒買，反而很喜歡這樣。"},{"en":"New experiences keep you young at heart.","zh":"新體驗讓你心態年輕。"},{"en":"He made a new friend in the most unexpected place.","zh":"他在最意想不到的地方交了一個新朋友。"},{"en":"New is not always better — but it is always interesting.","zh":"新的不一定更好——但它總是有趣的。"}]},{"word":"quiet","pos":"adjective/noun","chinese":"安靜的；寧靜","level":"A1","sentences":[{"en":"I need some quiet — my mind is too loud.","zh":"我需要一些安靜——我的思維太嘈雜了。"},{"en":"She is quiet but pays attention to everything.","zh":"她安靜，但關注一切。"},{"en":"The house is so quiet now the kids have gone to school.","zh":"孩子們上學後，房子現在非常安靜。"},{"en":"He has a quiet confidence that draws people in.","zh":"他有一種安靜的自信，吸引著人們。"},{"en":"Quiet mornings are my favourite part of the day.","zh":"安靜的早晨是我一天中最喜歡的部分。"},{"en":"She spoke quietly but everyone leaned in to listen.","zh":"她說話輕聲細語，但所有人都俯身傾聽。"},{"en":"Keep quiet — this moment does not need words.","zh":"保持安靜——這個時刻不需要語言。"},{"en":"Quiet does not mean absent — I am always here.","zh":"安靜不意味著缺席——我一直都在。"},{"en":"There is comfort in sitting with someone in quiet.","zh":"與某人安靜地坐在一起有一種安慰。"},{"en":"He retreats to quiet when he needs to recharge.","zh":"當他需要充電時，他退到安靜中。"}]},{"word":"loud","pos":"adjective","chinese":"大聲的；響亮的","level":"A1","sentences":[{"en":"The music was too loud to have a conversation.","zh":"音樂太大聲了，無法進行對話。"},{"en":"She laughs loud and does not apologise for it.","zh":"她大聲笑，對此不道歉。"},{"en":"He has a loud personality — never a dull moment.","zh":"他有一個響亮的個性——從來沒有無聊的時刻。"},{"en":"The city gets loud at night in ways that keep me awake.","zh":"城市在夜晚變得嘈雜，以一種讓我無法入睡的方式。"},{"en":"Actions speak loud — even quiet ones.","zh":"行動說話大聲——即使是安靜的行動。"},{"en":"She wears loud colours because she wants to be seen.","zh":"她穿著鮮豔的顏色，因為她想被看見。"},{"en":"The crowd got so loud during the final match.","zh":"在決賽期間，人群變得非常嘈雜。"},{"en":"He has a loud laugh that fills any room.","zh":"他有一種充滿任何房間的響亮笑聲。"},{"en":"Sometimes the loudest person is the most insecure.","zh":"有時候最大聲的人是最沒有安全感的。"},{"en":"She thinks loudly — she often talks to herself.","zh":"她大聲思考——她經常自言自語。"}]},{"word":"kind","pos":"adjective/noun","chinese":"善良的；種類","level":"A1","sentences":[{"en":"Be kind — everyone is fighting a battle you know nothing about.","zh":"要善良——每個人都在打一場你一無所知的戰役。"},{"en":"She is effortlessly kind — it is just who she is.","zh":"她毫不費力地善良——那就是她的本質。"},{"en":"What kind of music do you listen to?","zh":"你聽什麼類型的音樂？"},{"en":"He did a kind thing without expecting anything back.","zh":"他做了一件善事，沒有期望得到任何回報。"},{"en":"Kindness is free and yet so rare.","zh":"善良是免費的，但卻如此稀少。"},{"en":"She teaches her children that kindness is strength.","zh":"她教導她的孩子善良是力量。"},{"en":"I have never met a kind person I did not like.","zh":"我從未遇到過我不喜歡的善良的人。"},{"en":"Kind words cost nothing but mean everything.","zh":"善意的話語不需要任何代價，但卻意味著一切。"},{"en":"He is the kind of person you want in your corner.","zh":"他是那種你希望站在你這邊的人。"},{"en":"A small act of kindness ripples further than you know.","zh":"一個小小的善意行為比你知道的傳播得更遠。"}]},{"word":"serious","pos":"adjective","chinese":"認真的；嚴重的","level":"A1","sentences":[{"en":"She takes her work seriously without losing her humour.","zh":"她認真對待工作，但不失幽默。"},{"en":"Are you serious? I cannot believe that happened.","zh":"你是認真的嗎？我不敢相信那發生了。"},{"en":"He has a serious side that surprises people who only see him joke.","zh":"他有一面嚴肅的一面，讓只見到他開玩笑的人感到驚訝。"},{"en":"This is a serious issue — we cannot ignore it.","zh":"這是一個嚴重的問題——我們不能忽視它。"},{"en":"She takes her health seriously now.","zh":"她現在認真對待自己的健康。"},{"en":"I was not being serious — it was a joke.","zh":"我不是認真的——那是個玩笑。"},{"en":"Serious conversations need proper time and space.","zh":"認真的對話需要適當的時間和空間。"},{"en":"He is serious about making this work.","zh":"他認真地要讓這個成功。"},{"en":"Are you seriously considering that idea?","zh":"你認真在考慮那個想法嗎？"},{"en":"She does not always look serious but she is always paying attention.","zh":"她不總是看起來認真，但她總是在注意著。"}]},{"word":"angry","pos":"adjective","chinese":"生氣的；憤怒的","level":"A1","sentences":[{"en":"I was angry but I waited before responding.","zh":"我很生氣，但我等到平靜再回應。"},{"en":"She rarely gets angry — when she does, it means something.","zh":"她很少生氣——當她生氣時，那意味著某件事。"},{"en":"He was angry for a day then let it go.","zh":"他生氣了一天，然後放下了。"},{"en":"I am not angry — I am just disappointed.","zh":"我不是生氣——我只是失望。"},{"en":"Staying angry wastes energy you need elsewhere.","zh":"保持憤怒浪費了你在其他地方需要的能量。"},{"en":"She expressed her anger calmly and it was more powerful.","zh":"她平靜地表達了她的憤怒，反而更有力量。"},{"en":"Do not make permanent decisions when angry.","zh":"生氣時不要做永久性的決定。"},{"en":"He was angry at the situation — not at her.","zh":"他對情況感到憤怒——不是對她。"},{"en":"Her anger was valid — something had gone wrong.","zh":"她的憤怒是合理的——有什麼東西出了問題。"},{"en":"I am not angry anymore. I am just done.","zh":"我不再生氣了，我只是放棄了。"}]},{"word":"comfortable","pos":"adjective","chinese":"舒適的；自在的","level":"A2","sentences":[{"en":"Make yourself comfortable — treat this like your home.","zh":"讓自己舒適——把這裡當自己家。"},{"en":"She feels comfortable in her own skin now.","zh":"她現在對自己的樣子感到自在了。"},{"en":"This sofa is so comfortable I never want to leave.","zh":"這個沙發太舒適了，我永遠不想離開。"},{"en":"He is not comfortable with conflict and avoids it.","zh":"他對衝突感到不自在，並避免它。"},{"en":"Are you comfortable with the pace of this?","zh":"你對這個節奏感到自在嗎？"},{"en":"She created a comfortable routine that grounds her.","zh":"她建立了一個讓她安定下來的舒適常規。"},{"en":"Getting comfortable with uncertainty is a life skill.","zh":"對不確定性感到自在是一種生活技能。"},{"en":"He sat back, crossed his legs and looked very comfortable.","zh":"他向後靠，翹起腿，看起來非常自在。"},{"en":"Comfortable silence is a sign of real connection.","zh":"舒適的沉默是真實連結的標誌。"},{"en":"She finally found a job that feels comfortable and meaningful.","zh":"她終於找到了一份感覺舒適且有意義的工作。"}]},{"word":"correct","pos":"adjective/verb","chinese":"正確的；糾正","level":"A2","sentences":[{"en":"That is correct — you got it right on the first try.","zh":"那是正確的——你第一次就做對了。"},{"en":"She corrected me kindly — no embarrassment.","zh":"她善意地糾正了我——沒有讓我難堪。"},{"en":"If I am wrong, please correct me.","zh":"如果我錯了，請糾正我。"},{"en":"He had the correct answer but doubted himself.","zh":"他有正確答案，但卻懷疑自己。"},{"en":"Correcting someone in public is never comfortable.","zh":"在公眾場合糾正某人從來都不舒適。"},{"en":"She made the correct call under pressure.","zh":"她在壓力下做出了正確的決定。"},{"en":"There is no single correct way to grieve.","zh":"沒有唯一正確的悲傷方式。"},{"en":"He corrected the mistake before anyone noticed.","zh":"他在任何人注意到之前糾正了錯誤。"},{"en":"Politically correct or not — honesty matters.","zh":"不管是否政治正確——誠實很重要。"},{"en":"She always gets the tone correct in difficult emails.","zh":"她在難寫的電子郵件中總能把語氣拿捏得恰到好處。"}]},{"word":"available","pos":"adjective","chinese":"有空的；可用的","level":"A2","sentences":[{"en":"Are you available this Friday evening?","zh":"你這個週五晚上有空嗎？"},{"en":"She makes herself available to her team always.","zh":"她總是讓自己的團隊可以找到她。"},{"en":"The table is available — shall we sit down?","zh":"那張桌子空著——我們坐下嗎？"},{"en":"He is not available until three — can you wait?","zh":"他三點前都沒空——你能等嗎？"},{"en":"Is that item still available? I saw it last week.","zh":"那件商品還有嗎？我上週看到的。"},{"en":"The information is freely available online.","zh":"這些資訊可以在網上免費獲取。"},{"en":"She checked her calendar before saying she was available.","zh":"她查看了日曆後才說自己有空。"},{"en":"He makes himself available in ways others do not.","zh":"他以其他人不會的方式讓自己可以被聯繫到。"},{"en":"New products become available every season.","zh":"每個季節都有新產品上市。"},{"en":"I am not available for drama — only good things.","zh":"我沒空搞戲劇——只有好的事情。"}]},{"word":"dangerous","pos":"adjective","chinese":"危險的","level":"A2","sentences":[{"en":"That road is dangerous at night — take the other one.","zh":"那條路在晚上很危險——走另一條路。"},{"en":"She is dangerously good at her job.","zh":"她的工作能力好得驚人。"},{"en":"Assumptions are dangerous — ask before you assume.","zh":"假設是危險的——假設之前先問清楚。"},{"en":"He avoided dangerous situations through careful planning.","zh":"他通過謹慎計畫避免了危險情況。"},{"en":"The most dangerous thing is feeling too comfortable.","zh":"最危險的事情是感到過於舒適。"},{"en":"She takes calculated risks — nothing recklessly dangerous.","zh":"她承擔計算過的風險——沒有魯莽危險的事。"},{"en":"Comfortable lies are more dangerous than uncomfortable truths.","zh":"舒適的謊言比不舒適的真相更危險。"},{"en":"That neighbourhood used to be dangerous but has improved.","zh":"那個社區以前很危險，但已有改善。"},{"en":"He is dangerously charming — be careful.","zh":"他有一種危險的魅力——要小心。"},{"en":"Ignoring a small problem can become dangerously large.","zh":"忽視一個小問題可能會變得危險地大。"}]},{"word":"familiar","pos":"adjective","chinese":"熟悉的；常見的","level":"A2","sentences":[{"en":"This place feels familiar — have I been here before?","zh":"這個地方感覺很熟悉——我以前來過這裡嗎？"},{"en":"She has a familiar face but I cannot place her.","zh":"她的臉很熟悉，但我認不出她是誰。"},{"en":"He made a familiar mistake and finally stopped repeating it.","zh":"他犯了一個熟悉的錯誤，終於停止了重複。"},{"en":"The smell was familiar and comforting.","zh":"那個氣味很熟悉，令人安慰。"},{"en":"Are you familiar with this author's work?","zh":"你熟悉這位作者的作品嗎？"},{"en":"She felt familiar in a city she had never visited.","zh":"她在一個從未去過的城市感到熟悉。"},{"en":"The pattern was familiar — she had seen it before.","zh":"這個模式很熟悉——她以前見過。"},{"en":"He became too familiar too fast and it felt uncomfortable.","zh":"他太快變得過於熟絡，感覺不舒服。"},{"en":"That tune is so familiar but I cannot name it.","zh":"那個曲調非常熟悉，但我叫不出名字。"},{"en":"Growing up with the same values creates a familiar bond.","zh":"在相同價值觀中長大建立了一種熟悉的聯繫。"}]},{"word":"patient","pos":"adjective/noun","chinese":"有耐心的；病人","level":"A2","sentences":[{"en":"She is remarkably patient — even with difficult people.","zh":"她非常有耐心——即使對難相處的人也是。"},{"en":"Be patient — the good things are still coming.","zh":"要有耐心——好的事情還在路上。"},{"en":"He is a patient teacher who explains things multiple times.","zh":"他是一個有耐心的老師，會多次解釋事情。"},{"en":"The doctor sees fifty patients a day.","zh":"那位醫生每天看五十個病人。"},{"en":"I am not naturally patient — I work at it.","zh":"我天生不耐心——但我努力改善。"},{"en":"Patient people achieve more in the long run.","zh":"有耐心的人從長遠來看能實現更多。"},{"en":"She waited patiently and the right moment came.","zh":"她耐心地等待，正確的時機來了。"},{"en":"He was a patient investor — never rushed.","zh":"他是一個有耐心的投資者——從不急躁。"},{"en":"Patience is not passive — it is active and disciplined.","zh":"耐心不是被動的——它是主動且有紀律的。"},{"en":"The patient had a long recovery but made a full comeback.","zh":"那個病人恢復了很長時間，但完全康復了。"}]},{"word":"nervous","pos":"adjective","chinese":"緊張的；焦慮的","level":"A2","sentences":[{"en":"I am nervous but that means I care about this.","zh":"我很緊張，但這意味著我在乎這件事。"},{"en":"She gets nervous before any public speaking.","zh":"她在任何公開演講前都會緊張。"},{"en":"He was nervous to ask but he asked anyway.","zh":"他很緊張要開口問，但還是問了。"},{"en":"Nervous energy can be channelled into focus.","zh":"緊張的能量可以被引導成專注力。"},{"en":"I always feel nervous meeting new people.","zh":"我每次見新朋友都會感到緊張。"},{"en":"She admitted she was nervous and everyone relaxed.","zh":"她承認她很緊張，所有人都放鬆了。"},{"en":"He made me nervous in the best possible way.","zh":"他讓我緊張，但是以最好的方式。"},{"en":"Being nervous just means something matters.","zh":"緊張只是意味著某件事很重要。"},{"en":"She practised until the nervousness became excitement.","zh":"她練習直到緊張變成了興奮。"},{"en":"A little nervous energy sharpens performance.","zh":"一點緊張能量讓表現更加鋒利。"}]},{"word":"excited","pos":"adjective","chinese":"興奮的；激動的","level":"A2","sentences":[{"en":"She is so excited about the trip — counting down the days.","zh":"她對這次旅行非常興奮——在倒數日子。"},{"en":"I am genuinely excited — not just saying that.","zh":"我真的很興奮——不只是說說而已。"},{"en":"He gets excited about learning new things.","zh":"他對學習新事物感到興奮。"},{"en":"What are you most excited about this year?","zh":"今年你最興奮什麼？"},{"en":"She was excited but tried to hide it — unsuccessfully.","zh":"她很興奮，但試圖隱藏——沒有成功。"},{"en":"The crowd was excited and so was I.","zh":"人群很興奮，我也是。"},{"en":"I have not been this excited about something in a long time.","zh":"我很久沒有對某件事這麼興奮了。"},{"en":"He excitedly showed me the project he had been working on.","zh":"他興奮地向我展示他一直在做的項目。"},{"en":"Being excited about the future means you have hope.","zh":"對未來感到興奮意味著你有希望。"},{"en":"She was quietly excited — the best kind.","zh":"她默默地興奋著——最好的那種興奮。"}]},{"word":"surprised","pos":"adjective","chinese":"驚訝的；出乎意料","level":"A2","sentences":[{"en":"I was completely surprised — did not see that coming.","zh":"我完全沒有料到——完全出乎意料。"},{"en":"She was surprised by how much she enjoyed it.","zh":"她對自己有多喜歡感到驚訝。"},{"en":"He surprised her with flowers for no reason.","zh":"他無緣無故地用花驚喜了她。"},{"en":"People surprise you when you give them a chance.","zh":"當你給人們一個機會時，他們會讓你驚訝。"},{"en":"I was not surprised — I had a feeling it would happen.","zh":"我並不驚訝——我有預感它會發生。"},{"en":"She always surprises me with how thoughtful she is.","zh":"她總是用她的體貼讓我感到驚訝。"},{"en":"That plot twist surprised everyone.","zh":"那個劇情轉折讓所有人都感到驚訝。"},{"en":"He was surprised to find he actually enjoyed it.","zh":"他很驚訝地發現自己實際上很喜歡。"},{"en":"A good surprise can change the whole mood.","zh":"一個好的驚喜可以改變整個氛圍。"},{"en":"She surprised herself by how brave she was.","zh":"她因自己的勇敢而感到驚訝。"}]},{"word":"bored","pos":"adjective","chinese":"無聊的；厭倦的","level":"A2","sentences":[{"en":"I am bored of the same routine — something needs to change.","zh":"我對同樣的例行程序感到無聊——某些事情需要改變。"},{"en":"She never gets bored — she always finds something interesting.","zh":"她從不感到無聊——她總能找到有趣的事情。"},{"en":"He was bored in meetings that could have been emails.","zh":"他在本可以是電子郵件的會議中感到無聊。"},{"en":"Boredom is actually the birthplace of creativity.","zh":"無聊其實是創意的發源地。"},{"en":"I get bored easily unless I am genuinely engaged.","zh":"除非我真正投入，否則我很容易感到無聊。"},{"en":"She used bored moments to learn something new.","zh":"她用無聊的時刻學習新事物。"},{"en":"Are you bored? I can suggest something.","zh":"你無聊嗎？我可以建議些什麼。"},{"en":"He said he was bored but what he meant was restless.","zh":"他說他無聊，但他的意思是坐立不安。"},{"en":"Bored people make the most interesting discoveries.","zh":"無聊的人會做出最有趣的發現。"},{"en":"I would rather be bored alone than with the wrong company.","zh":"我寧願獨自無聊，也不願和錯誤的人在一起。"}]},{"word":"travel","pos":"verb/noun","chinese":"旅行；旅遊","level":"A2","sentences":[{"en":"She travels light and never checks luggage.","zh":"她旅行只帶隨身行李，從不托運。"},{"en":"Travelling solo changed how I see myself.","zh":"獨自旅行改變了我對自己的看法。"},{"en":"He has travelled to forty countries but says home is best.","zh":"他去過四十個國家，但說家才是最好的。"},{"en":"Travel opens your mind in ways nothing else can.","zh":"旅行以其他任何方式都無法做到的方式開闊你的視野。"},{"en":"She travels for the food more than the sights.","zh":"她旅行更多是為了食物，而不是景點。"},{"en":"How do you afford to travel so much?","zh":"你怎麼能夠那麼頻繁地旅行？"},{"en":"He travelled through six countries on a single train ticket.","zh":"他用一張火車票穿越了六個國家。"},{"en":"Slow travel beats rushing through a checklist.","zh":"慢旅行勝過匆匆完成清單。"},{"en":"She plans the next trip before the current one ends.","zh":"她在當前旅行結束前就開始計畫下一次。"},{"en":"Travel does not have to be expensive to be meaningful.","zh":"旅行不必昂貴才有意義。"}]},{"word":"describe","pos":"verb","chinese":"描述；形容","level":"A2","sentences":[{"en":"How would you describe yourself in three words?","zh":"你會用三個詞怎麼描述自己？"},{"en":"She described the scene so vividly I could picture it.","zh":"她描述那個場景是那麼生動，我能想象出來。"},{"en":"It is hard to describe how much that meant to me.","zh":"很難描述那對我意味著多少。"},{"en":"He described his ideal job and then found it.","zh":"他描述了他理想的工作，然後找到了。"},{"en":"Can you describe what happened in your own words?","zh":"你能用自己的話描述發生了什麼嗎？"},{"en":"She described the dish perfectly — now I have to try it.","zh":"她完美地描述了那道菜——我現在必須試試。"},{"en":"Words cannot fully describe what I felt in that moment.","zh":"語言無法完全描述我在那一刻的感受。"},{"en":"He described her laugh and I knew exactly who he meant.","zh":"他描述了她的笑聲，我立刻知道他說的是誰。"},{"en":"Describing emotions accurately is a real skill.","zh":"準確地描述情緒是一種真正的技能。"},{"en":"She described the city and made me want to go immediately.","zh":"她描述了那個城市，讓我立刻想去。"}]},{"word":"offer","pos":"verb/noun","chinese":"提供；提議；提議","level":"A2","sentences":[{"en":"Can I offer you a coffee while you wait?","zh":"您等待的時候我可以給您一杯咖啡嗎？"},{"en":"She offered to help without being asked.","zh":"她沒有被要求就主動提出幫忙。"},{"en":"He offered a compromise that satisfied everyone.","zh":"他提出了一個讓所有人都滿意的妥協方案。"},{"en":"That is a generous offer — thank you.","zh":"這是一個慷慨的提議——謝謝你。"},{"en":"I will not offer advice unless asked.","zh":"除非被要求，否則我不會提供建議。"},{"en":"She offered her seat to the elderly man.","zh":"她把座位讓給了那位老人。"},{"en":"He turned down the offer because it did not feel right.","zh":"他拒絕了那個提議，因為感覺不對。"},{"en":"Offering kindness costs nothing.","zh":"給予善意不需要任何代價。"},{"en":"She offered a different perspective and it helped.","zh":"她提供了一個不同的視角，這很有幫助。"},{"en":"What does this role offer in terms of growth?","zh":"這個職位在成長方面能提供什麼？"}]},{"word":"refuse","pos":"verb","chinese":"拒絕；不接受","level":"A2","sentences":[{"en":"She refused politely but firmly.","zh":"她禮貌但堅定地拒絕了。"},{"en":"He refused to give up even when everyone else had.","zh":"即使其他人都放棄了，他也拒絕放棄。"},{"en":"I refuse to apologise for something I did not do.","zh":"我拒絕為我沒有做的事道歉。"},{"en":"She refused the promotion — valued her personal time more.","zh":"她拒絕了升職——她更重視個人時間。"},{"en":"Refusing a request does not make you a bad person.","zh":"拒絕一個請求不會讓你成為壞人。"},{"en":"He refused dessert but regretted it immediately.","zh":"他拒絕了甜點，但立刻後悔了。"},{"en":"She learned to refuse without explaining herself.","zh":"她學會了拒絕而不必解釋原因。"},{"en":"Refusing sometimes is the most respectful response.","zh":"有時拒絕是最尊重的回應。"},{"en":"He refused the shortcut and took the proper path.","zh":"他拒絕了捷徑，走了正確的路。"},{"en":"She refuses to let negativity take root.","zh":"她拒絕讓消極情緒生根。"}]},{"word":"accept","pos":"verb","chinese":"接受；承認","level":"A2","sentences":[{"en":"She accepted the award with grace and humility.","zh":"她優雅而謙遜地接受了獎項。"},{"en":"Accept what you cannot change — focus on what you can.","zh":"接受你無法改變的——專注於你能改變的。"},{"en":"He accepted the feedback and improved immediately.","zh":"他接受了反饋，立刻有所改進。"},{"en":"I accept that I was wrong and I am sorry.","zh":"我承認我錯了，我很抱歉。"},{"en":"She accepted help when she needed it — that is strength.","zh":"她在需要的時候接受幫助——那是力量。"},{"en":"Accepting uncertainty is one of life's hardest lessons.","zh":"接受不確定性是生活中最難的功課之一。"},{"en":"He accepted the job offer before thinking it through.","zh":"他在深思熟慮之前就接受了工作邀約。"},{"en":"She accepts people as they are without trying to fix them.","zh":"她接受人們本來的樣子，不試圖改變他們。"},{"en":"Accepting your emotions is the first step to understanding them.","zh":"接受你的情緒是理解它們的第一步。"},{"en":"He finally accepted that rest is not laziness.","zh":"他終於接受了休息並不是懒惰。"}]},{"word":"continue","pos":"verb","chinese":"繼續；持續","level":"A2","sentences":[{"en":"Please continue — I did not mean to interrupt.","zh":"請繼續——我不是故意打斷的。"},{"en":"She continued studying even when it got hard.","zh":"即使變得困難，她也繼續學習。"},{"en":"He continued to show up long after the excitement faded.","zh":"在興奮消退後很久，他仍然繼續堅持。"},{"en":"To be continued — the best and worst four words.","zh":"待續——最好又最糟糕的四個字。"},{"en":"She continued the conversation in a text message.","zh":"她通過訊息繼續了對話。"},{"en":"I will continue as long as I see progress.","zh":"只要我看到進步，我就會繼續。"},{"en":"He continued his education at forty and loved it.","zh":"他在四十歲繼續了他的教育，非常喜歡。"},{"en":"Continue doing what is working — small changes add up.","zh":"繼續做有效的事情——小改變會累積。"},{"en":"She continued to trust herself even when others doubted her.","zh":"即使其他人懷疑她，她也繼續相信自己。"},{"en":"The project continues — just at a different pace.","zh":"這個項目繼續進行——只是速度不同了。"}]},{"word":"practise","pos":"verb","chinese":"練習；實踐","level":"A2","sentences":[{"en":"She practises English every day for thirty minutes.","zh":"她每天練習英文三十分鐘。"},{"en":"Practise does not make perfect — it makes permanent.","zh":"練習不會讓你完美——它會讓你固定。"},{"en":"He practised the speech until it felt natural.","zh":"他練習演講直到感覺自然為止。"},{"en":"Practise patience — it does not come automatically.","zh":"練習耐心——它不是自動就有的。"},{"en":"She practises what she preaches and people notice.","zh":"她說到做到，人們都注意到了。"},{"en":"I have been practising mindfulness every morning.","zh":"我每天早上都在練習正念。"},{"en":"He practised the instrument daily for three years.","zh":"他每天練習那種樂器，持續了三年。"},{"en":"Practising gratitude changes your default state.","zh":"練習感恩改變你的預設狀態。"},{"en":"She practised in front of the mirror until she felt confident.","zh":"她在鏡子前練習直到感到自信為止。"},{"en":"The more you practise, the less conscious the effort becomes.","zh":"你練習得越多，所需的意識努力就越少。"}]},{"word":"introduce","pos":"verb","chinese":"介紹；引入","level":"A2","sentences":[{"en":"She introduced herself with a warm smile and a handshake.","zh":"她帶著溫暖的微笑和握手介紹了自己。"},{"en":"Can I introduce you to my friend? She is brilliant.","zh":"我可以把你介紹給我的朋友嗎？她非常出色。"},{"en":"He introduced a new system that saved everyone hours.","zh":"他引入了一個為每個人節省了幾個小時的新系統。"},{"en":"She introduced me to her favourite book and I loved it.","zh":"她把她最喜歡的書介紹給我，我非常喜歡。"},{"en":"Introduce yourself with confidence — first impressions matter.","zh":"自信地介紹自己——第一印象很重要。"},{"en":"He introduced changes gradually so no one felt overwhelmed.","zh":"他逐漸引入變化，這樣沒有人感到不知所措。"},{"en":"She was introduced to yoga at a difficult time and it helped.","zh":"她在困難時期接觸了瑜伽，這很有幫助。"},{"en":"Introducing new ideas into a resistant culture takes patience.","zh":"向抵制的文化引入新想法需要耐心。"},{"en":"Can you introduce me to whoever made this dish?","zh":"你能把做這道菜的人介紹給我嗎？"},{"en":"He introduced the concept gently and people received it well.","zh":"他溫和地介紹了這個概念，人們接受得很好。"}]},{"word":"notice","pos":"verb/noun","chinese":"注意到；告知","level":"A2","sentences":[{"en":"She notices things others miss — a real gift.","zh":"她注意到別人錯過的事情——真正的天賦。"},{"en":"Did you notice the detail in the background?","zh":"你注意到背景中的細節了嗎？"},{"en":"He notices when you are not quite yourself.","zh":"他會注意到你不太像平時的自己。"},{"en":"I notice how I feel more when I put down my phone.","zh":"當我放下手機時，我更能注意到自己的感受。"},{"en":"She gave two weeks notice before leaving.","zh":"她在離開之前提前兩週通知了。"},{"en":"Nobody noticed the mistake — lucky.","zh":"沒有人注意到那個錯誤——很幸運。"},{"en":"He noticed the small things that made big differences.","zh":"他注意到了造成巨大差異的小事情。"},{"en":"I notice I am happiest when I am creating.","zh":"我注意到當我在創作時我最快樂。"},{"en":"She noticed the shift in the room before anyone else.","zh":"她比任何人都先注意到房間裡的氛圍變化。"},{"en":"Notice how your body feels — it is telling you something.","zh":"注意你身體的感受——它在告訴你一些事情。"}]},{"word":"connect","pos":"verb","chinese":"連接；溝通；聯繫","level":"A2","sentences":[{"en":"She connects with people instantly — rare quality.","zh":"她能立刻和人建立連結——難得的品質。"},{"en":"We connected over our shared love of bad films.","zh":"我們通過對爛片的共同喜愛建立了連結。"},{"en":"He connects the dots in ways others miss.","zh":"他以別人錯過的方式連接點點滴滴。"},{"en":"Good stories connect strangers.","zh":"好故事能連結陌生人。"},{"en":"She connected her work to a purpose bigger than herself.","zh":"她把工作連結到一個比自己更大的目的。"},{"en":"I feel most connected when I am with people I trust.","zh":"當我和我信任的人在一起時，我感到最有連結感。"},{"en":"Connecting online is real but in-person is different.","zh":"在線連結是真實的，但面對面是不同的。"},{"en":"He connected the idea to her experience and it clicked.","zh":"他把這個想法和她的經歷聯繫起來，她一下子就明白了。"},{"en":"She connects effortlessly across different groups.","zh":"她毫不費力地跨越不同群體建立連結。"},{"en":"True connection requires vulnerability.","zh":"真正的連結需要脆弱。"}]},{"word":"discuss","pos":"verb","chinese":"討論；談論","level":"A2","sentences":[{"en":"Let us discuss this properly — not over text.","zh":"讓我們好好討論這個——不要用訊息。"},{"en":"She discussed the problem openly and found solutions.","zh":"她公開討論了問題，找到了解決方案。"},{"en":"He discussed his concerns without blaming anyone.","zh":"他討論了他的擔憂，沒有指責任何人。"},{"en":"We discussed it for hours and still disagreed.","zh":"我們討論了幾個小時，仍然意見不一。"},{"en":"She discusses difficult topics with grace.","zh":"她優雅地討論困難的話題。"},{"en":"Can we discuss this at a better time?","zh":"我們可以在更好的時間討論這個嗎？"},{"en":"He discussed his goals with a mentor and it changed everything.","zh":"他和導師討論了他的目標，這改變了一切。"},{"en":"Discussing money is less taboo than people think.","zh":"討論金錢不像人們認為的那麼禁忌。"},{"en":"She discussed the idea as if it were already happening.","zh":"她討論這個想法，好像它已經在發生一樣。"},{"en":"Open discussion leads to better decisions.","zh":"開放的討論帶來更好的決定。"}]},{"word":"consider","pos":"verb","chinese":"考慮；思考","level":"A2","sentences":[{"en":"Have you considered taking a break?","zh":"你有考慮過休息一下嗎？"},{"en":"She considered every option before deciding.","zh":"她在決定之前考慮了每一個選項。"},{"en":"He considered others before himself — always.","zh":"他總是先考慮別人，再考慮自己。"},{"en":"I am considering a career change — early stages.","zh":"我在考慮換職業——初步階段。"},{"en":"She considered the long-term impact before acting.","zh":"她在行動之前考慮了長遠影響。"},{"en":"Consider how your words land before you speak.","zh":"說話之前考慮你的話會如何落地。"},{"en":"He did not consider the consequences — lesson learned.","zh":"他沒有考慮後果——得到了教訓。"},{"en":"I am seriously considering moving to a quieter city.","zh":"我正在認真考慮搬到一個更安靜的城市。"},{"en":"She considered every perspective before forming an opinion.","zh":"她在形成意見之前考慮了每個角度。"},{"en":"Consider yourself lucky — this rarely happens.","zh":"認為自己很幸運——這很少發生。"}]},{"word":"achieve","pos":"verb","chinese":"實現；達到","level":"A2","sentences":[{"en":"She achieved more by doing less — smarter not harder.","zh":"她通過少做更多來實現了更多——更聰明而不是更努力。"},{"en":"What do you want to achieve this year?","zh":"你今年想實現什麼？"},{"en":"He achieved his goal and immediately set a new one.","zh":"他實現了他的目標，立刻設定了一個新目標。"},{"en":"She achieved something she once thought impossible.","zh":"她實現了她曾經認為不可能的事情。"},{"en":"Achieving small things daily builds momentum.","zh":"每天實現小事情能建立動力。"},{"en":"I am proud of what she has achieved.","zh":"我為她所取得的成就感到驕傲。"},{"en":"He achieved balance between work and life — eventually.","zh":"他最終實現了工作和生活之間的平衡。"},{"en":"Achieving your goal quietly is still an achievement.","zh":"悄悄實現你的目標仍然是一個成就。"},{"en":"She achieved it without the recognition she deserved.","zh":"她在沒有得到應有認可的情況下實現了它。"},{"en":"Achieving clarity takes time but it is worth it.","zh":"獲得清晰需要時間，但這是值得的。"}]},{"word":"manage","pos":"verb","chinese":"管理；設法做到","level":"A2","sentences":[{"en":"She manages her time so well — nothing falls through the cracks.","zh":"她的時間管理很好——沒有任何事情會被遺漏。"},{"en":"I managed to finish just before the deadline.","zh":"我設法在截止日期之前完成了。"},{"en":"He manages stress by moving his body every day.","zh":"他每天通過運動來管理壓力。"},{"en":"I cannot manage everything at once — something has to give.","zh":"我無法同時管理一切——某些事情必須讓步。"},{"en":"She manages the team with firmness and warmth.","zh":"她用堅定和溫暖管理團隊。"},{"en":"How do you manage to stay so calm?","zh":"你怎麼設法保持那麼冷靜？"},{"en":"He managed the situation better than anyone expected.","zh":"他處理情況比任何人預期的都要好。"},{"en":"Managing energy is more important than managing time.","zh":"管理精力比管理時間更重要。"},{"en":"She manages to find joy even in mundane tasks.","zh":"她設法在平凡的任務中找到快樂。"},{"en":"I cannot manage alone — I need support.","zh":"我無法獨自應付——我需要支持。"}]},{"word":"attend","pos":"verb","chinese":"參加；出席","level":"A2","sentences":[{"en":"She attends every meeting on time — no exceptions.","zh":"她準時出席每個會議——沒有例外。"},{"en":"I attended the event and made three new connections.","zh":"我參加了那個活動，結交了三個新朋友。"},{"en":"He attended a workshop that changed his career.","zh":"他參加了一個改變他職業的研討會。"},{"en":"She attends to detail in everything she does.","zh":"她在她所做的每件事中都注重細節。"},{"en":"I cannot attend — please share the notes with me.","zh":"我無法出席——請把筆記分享給我。"},{"en":"Attending in person is different from joining online.","zh":"親身出席和在線參加是不同的。"},{"en":"She has attended the same conference for ten years.","zh":"她已經連續十年參加同一個會議了。"},{"en":"He attended the ceremony despite feeling unwell.","zh":"儘管感到不適，他還是出席了典禮。"},{"en":"Attending to your mental health is not optional.","zh":"關注你的心理健康不是可選的。"},{"en":"She attended the class out of curiosity and stayed for years.","zh":"她出於好奇參加了那個課程，後來堅持了多年。"}]},{"word":"borrow","pos":"verb","chinese":"借用；借","level":"A2","sentences":[{"en":"Can I borrow your charger? Mine is dead.","zh":"我可以借你的充電器嗎？我的沒電了。"},{"en":"She borrowed the book and returned it with notes inside.","zh":"她借了那本書，歸還時裡面有筆記。"},{"en":"He borrows freely and returns promptly.","zh":"他經常借東西，但總是及時歸還。"},{"en":"I borrowed this idea from someone smarter than me.","zh":"我從比我更聰明的人那裡借來了這個想法。"},{"en":"Borrow what works and make it your own.","zh":"借用有效的方法，讓它成為你自己的。"},{"en":"She borrowed confidence she did not have and faked it till she had it.","zh":"她借用了她沒有的自信，直到她真的有了為止。"},{"en":"Do not borrow trouble — deal with things as they come.","zh":"不要自找麻煩——隨機應變。"},{"en":"He borrowed a bit of her calm when his ran out.","zh":"當他的平靜耗盡時，他借了一點她的平靜。"},{"en":"Borrow an idea from history — everything has been done before.","zh":"從歷史中借用一個想法——一切都曾被做過。"},{"en":"She borrowed the recipe and improved it.","zh":"她借用了那個食譜並加以改進。"}]},{"word":"spend","pos":"verb","chinese":"花費；度過","level":"A2","sentences":[{"en":"I want to spend more time on things that matter.","zh":"我想把更多時間花在重要的事情上。"},{"en":"She spends her energy carefully — never on drama.","zh":"她謹慎地花費她的精力——從不花在麻煩事上。"},{"en":"How did you spend your weekend?","zh":"你週末是怎麼度過的？"},{"en":"He spends Sunday mornings without a phone.","zh":"他週日早上不用手機。"},{"en":"I spent too long worrying about what others think.","zh":"我花了太長時間擔心別人的看法。"},{"en":"She spent three years learning the craft.","zh":"她花了三年學習這門技藝。"},{"en":"Spend your money on experiences, not things.","zh":"把錢花在體驗上，而不是物品上。"},{"en":"He spent the whole afternoon reading and was perfectly happy.","zh":"他花了整個下午閱讀，非常開心。"},{"en":"Quality time spent together matters more than quantity.","zh":"在一起度過的高質量時光比數量更重要。"},{"en":"She spends wisely and lives well on less.","zh":"她明智地消費，用更少的錢過得很好。"}]},{"word":"earn","pos":"verb","chinese":"賺取；贏得","level":"A2","sentences":[{"en":"She earned her success through years of consistent work.","zh":"她通過多年持續的工作贏得了成功。"},{"en":"He earns enough to live comfortably.","zh":"他賺得足夠讓他生活舒適。"},{"en":"Earning trust takes time — losing it takes a second.","zh":"贏得信任需要時間——失去它只需要一秒。"},{"en":"I earned the right to rest by working hard all week.","zh":"我通過整週努力工作贏得了休息的權利。"},{"en":"She earned respect without demanding it.","zh":"她贏得了尊重，而不需要要求它。"},{"en":"He earns more than he spends — smart.","zh":"他賺的比花的多——很聰明。"},{"en":"You earn loyalty by being loyal first.","zh":"你通過首先忠誠來贏得忠誠。"},{"en":"She earned her place at the table.","zh":"她贏得了她在桌子旁的位置。"},{"en":"Earning a living and living your life are two different things.","zh":"謀生和生活是兩件不同的事。"},{"en":"He earned every single achievement through effort.","zh":"他通過努力贏得了每一個成就。"}]},{"word":"save","pos":"verb","chinese":"節省；保存；拯救","level":"A2","sentences":[{"en":"She saves a fixed amount every month — no exceptions.","zh":"她每個月存一個固定金額——沒有例外。"},{"en":"He saved the file just in time — that was close.","zh":"他及時保存了文件——好險。"},{"en":"I am saving for something that will take three years.","zh":"我在為一件需要三年才能實現的事情存錢。"},{"en":"Saving ten minutes a day by being organised adds up.","zh":"通過有組織每天節省十分鐘，積少成多。"},{"en":"She saved her energy for what actually mattered.","zh":"她把精力節省給真正重要的事情。"},{"en":"That one piece of advice saved me from a big mistake.","zh":"那一條建議讓我避免了一個大錯誤。"},{"en":"He saves receipts for three months — very organised.","zh":"他保存收據三個月——非常有組織。"},{"en":"Saving your best ideas for the right moment pays off.","zh":"把最好的想法保存到正確的時機是值得的。"},{"en":"She saved the relationship by having the hard conversation.","zh":"她通過進行艱難的對話拯救了那段關係。"},{"en":"Saving time is saving life.","zh":"節省時間就是節省生命。"}]},{"word":"search","pos":"verb/noun","chinese":"搜尋；尋找","level":"A2","sentences":[{"en":"She searched everywhere and found it in the last place she looked.","zh":"她到處搜尋，在最後一個地方找到了它。"},{"en":"I have been searching for that book for years.","zh":"我多年來一直在尋找那本書。"},{"en":"He searched himself honestly and did not like what he found.","zh":"他誠實地反省自己，不喜歡他所發現的。"},{"en":"She searched for a word that fit perfectly and found it.","zh":"她搜尋了一個完全合適的詞，找到了。"},{"en":"I searched the internet for three hours for an answer.","zh":"我在網上搜尋了三個小時尋找答案。"},{"en":"He is searching for his direction — that is okay.","zh":"他在尋找他的方向——這沒關係。"},{"en":"She searched for meaning and found it in small things.","zh":"她尋找意義，在小事情中找到了它。"},{"en":"Stop searching for perfect — start with good enough.","zh":"停止尋找完美——從足夠好開始。"},{"en":"He searched his memory but could not recall her name.","zh":"他搜尋了記憶，但想不起她的名字。"},{"en":"The search for belonging is universal.","zh":"對歸屬感的尋求是普遍的。"}]},{"word":"check","pos":"verb","chinese":"檢查；確認","level":"A2","sentences":[{"en":"Can you check if the door is locked?","zh":"你能確認門是否鎖好了嗎？"},{"en":"She checks her work twice before submitting.","zh":"她在提交之前把工作檢查兩遍。"},{"en":"Check in on the people you love — not just during hard times.","zh":"關心你愛的人——不只是在困難時期。"},{"en":"He checked the time and realised he was late.","zh":"他查看時間，意識到他遲到了。"},{"en":"I check the weather before deciding what to wear.","zh":"我在決定穿什麼之前查看天氣。"},{"en":"She checked her assumptions at the door.","zh":"她在門口檢查了她的假設。"},{"en":"Can you check the figures? Something does not add up.","zh":"你能核對一下數字嗎？有些地方不對勁。"},{"en":"He checks in with himself every morning.","zh":"他每天早上與自己進行檢查。"},{"en":"She checked on her friend every day during the hard week.","zh":"在困難的那週，她每天都去看望她的朋友。"},{"en":"Check your ego before entering the room.","zh":"進入房間之前先收起你的自我。"}]},{"word":"measure","pos":"verb/noun","chinese":"測量；衡量","level":"A2","sentences":[{"en":"She measures success differently to everyone else.","zh":"她對成功的衡量標準與其他人不同。"},{"en":"You cannot measure kindness — but you can feel it.","zh":"你無法測量善良——但你能感受到它。"},{"en":"He measured the room before buying furniture.","zh":"他在買家具之前測量了房間。"},{"en":"Measure twice, cut once.","zh":"量兩次，切一次。"},{"en":"She measures her progress by how she feels, not what she owns.","zh":"她通過自己的感受而不是擁有的東西來衡量進步。"},{"en":"The measure of a person is how they treat those who cannot help them.","zh":"一個人的衡量標準是他們如何對待那些無法幫助他們的人。"},{"en":"He measured his words carefully and spoke with precision.","zh":"他謹慎地斟酌措辭，說得非常精準。"},{"en":"She does not measure herself against others.","zh":"她不把自己和別人比較。"},{"en":"Measuring productivity by hours alone is outdated.","zh":"僅靠小時數來衡量生產力是過時的。"},{"en":"You can only measure what you track.","zh":"你只能衡量你追蹤的東西。"}]},{"word":"fail","pos":"verb","chinese":"失敗；不及格","level":"A2","sentences":[{"en":"She failed and then learned more than she ever did from success.","zh":"她失敗了，然後學到了比任何成功都更多的東西。"},{"en":"Failing is not the opposite of succeeding — it is part of it.","zh":"失敗不是成功的反面——而是其中的一部分。"},{"en":"He failed the exam but passed life.","zh":"他考試不及格，但通過了生活。"},{"en":"I failed to meet the deadline and took responsibility.","zh":"我未能在截止日期前完成，並承擔了責任。"},{"en":"She failed publicly and handled it with grace.","zh":"她公開失敗了，但優雅地處理了它。"},{"en":"Failing fast teaches faster.","zh":"快速失敗能更快地教你。"},{"en":"He failed so many times before finding his way.","zh":"他在找到方向之前失敗了很多次。"},{"en":"Fail forward — every stumble is a step.","zh":"向前失敗——每次跌倒都是一步。"},{"en":"She failed to see what was right in front of her.","zh":"她沒能看到就在她面前的東西。"},{"en":"Failing at the right things means you are trying.","zh":"在正確的事情上失敗意味著你在嘗試。"}]},{"word":"allow","pos":"verb","chinese":"允許；讓","level":"A2","sentences":[{"en":"She allows herself one guilty pleasure a day.","zh":"她每天允許自己一個小罪惡享受。"},{"en":"Allow yourself to feel it — then move on.","zh":"允許自己感受它——然後繼續前進。"},{"en":"He does not allow negativity to stay too long.","zh":"他不允許消極情緒停留太久。"},{"en":"Are phones allowed in the exam room?","zh":"考試室允許帶手機嗎？"},{"en":"She allowed herself to be vulnerable — and it paid off.","zh":"她允許自己變得脆弱——這得到了回報。"},{"en":"Allow for more time than you think you need.","zh":"預留比你認為需要的更多時間。"},{"en":"He allows his team to lead on projects.","zh":"他允許他的團隊主導項目。"},{"en":"Allowing change is not the same as losing control.","zh":"允許改變並不等於失去控制。"},{"en":"She allows herself to start over without judgment.","zh":"她允許自己在沒有評判的情況下重新開始。"},{"en":"Allow the silence — not every pause needs to be filled.","zh":"允許沉默——不是每個停頓都需要被填補。"}]},{"word":"believe","pos":"verb","chinese":"相信；認為","level":"A2","sentences":[{"en":"She believes in people before they believe in themselves.","zh":"她在人們相信自己之前就相信他們。"},{"en":"Believe in the process even when results are slow.","zh":"即使結果緩慢，也要相信這個過程。"},{"en":"He did not believe in himself until she did.","zh":"他不相信自己，直到她相信了他。"},{"en":"I believe everything happens for a reason — most of the time.","zh":"我相信一切都有其原因——大多數時候。"},{"en":"She believes that showing up is ninety percent of success.","zh":"她相信出現就是百分之九十的成功。"},{"en":"Do not believe everything you think.","zh":"不要相信你所有的想法。"},{"en":"He believed the risk was worth it and he was right.","zh":"他相信那個風險是值得的，他是對的。"},{"en":"Believe in yourself quietly — you do not need an audience.","zh":"悄悄地相信自己——你不需要觀眾。"},{"en":"She believes in being kind even when it is hard.","zh":"即使很難，她也相信善良。"},{"en":"Believing in someone changes how they see themselves.","zh":"相信某人改變了他們看待自己的方式。"}]},{"word":"approach","pos":"verb/noun","chinese":"方法；接近；處理方式","level":"B1","sentences":[{"en":"Her approach to problems is calm and methodical.","zh":"她處理問題的方法冷靜而有條不紊。"},{"en":"He approached the conversation with honesty and care.","zh":"他以誠實和關心的態度接近那次對話。"},{"en":"A fresh approach can solve an old problem.","zh":"新鮮的方法可以解決老問題。"},{"en":"She approaches feedback as a gift, not a threat.","zh":"她把反饋當作禮物，而不是威脅。"},{"en":"His approach to leadership is collaborative.","zh":"他的領導方式是協作的。"},{"en":"Try a different approach — the old one clearly is not working.","zh":"嘗試不同的方法——舊方法顯然不奏效。"},{"en":"She approached the task with energy and focus.","zh":"她以精力和專注力接近那個任務。"},{"en":"A gentle approach is often more effective than force.","zh":"溫和的方法通常比強迫更有效。"},{"en":"His creative approach sets him apart.","zh":"他的創意方法讓他與眾不同。"},{"en":"She approaches every day as if it is an opportunity.","zh":"她把每一天都當作一個機會來對待。"}]},{"word":"challenge","pos":"noun/verb","chinese":"挑戰；質疑","level":"B1","sentences":[{"en":"She challenges herself to grow every single year.","zh":"她每年都挑戰自己成長。"},{"en":"That project was the biggest challenge of my career.","zh":"那個項目是我職業生涯中最大的挑戰。"},{"en":"He challenges ideas respectfully — never people.","zh":"他尊重地挑戰想法——從不挑戰人。"},{"en":"Challenges reveal what you are made of.","zh":"挑戰揭示你是什麼樣的人。"},{"en":"She challenged the norm and created something new.","zh":"她挑戰了規範，創造了新事物。"},{"en":"The challenge is not the obstacle — it is the invitation.","zh":"挑戰不是障礙——而是邀請。"},{"en":"He challenged himself to read one book a week.","zh":"他挑戰自己每週讀一本書。"},{"en":"She accepted the challenge and surprised everyone.","zh":"她接受了挑戰，讓所有人都感到驚訝。"},{"en":"Challenging your assumptions is the start of growth.","zh":"挑戰你的假設是成長的開始。"},{"en":"The biggest challenge was trusting the process.","zh":"最大的挑戰是信任這個過程。"}]},{"word":"opportunity","pos":"noun","chinese":"機會；良機","level":"B1","sentences":[{"en":"She took every opportunity to learn something new.","zh":"她抓住每一個機會學習新事物。"},{"en":"Opportunities rarely announce themselves.","zh":"機會很少會自我宣布。"},{"en":"He created his own opportunities when none appeared.","zh":"當沒有機會出現時，他創造了自己的機會。"},{"en":"Every setback contains a hidden opportunity.","zh":"每次挫折都包含隱藏的機會。"},{"en":"She saw the opportunity where others saw a problem.","zh":"她在別人看到問題的地方看到了機會。"},{"en":"Opportunity knocks quietly — you have to be listening.","zh":"機會輕聲敲門——你必須在傾聽。"},{"en":"He gave others opportunities before taking them himself.","zh":"他在自己把握機會之前，先給了別人機會。"},{"en":"She is an opportunity in human form — opens doors for everyone.","zh":"她是人形的機會——為每個人開門。"},{"en":"The right opportunity at the right time changes everything.","zh":"在正確的時間出現的正確機會改變一切。"},{"en":"Creating opportunity is the real skill.","zh":"創造機會才是真正的技能。"}]},{"word":"responsibility","pos":"noun","chinese":"責任；職責","level":"B1","sentences":[{"en":"She takes responsibility for her choices without drama.","zh":"她毫無戲劇性地對她的選擇承擔責任。"},{"en":"Responsibility is not a burden — it is a privilege.","zh":"責任不是負擔——而是特權。"},{"en":"He takes on responsibility naturally and it suits him.","zh":"他自然地承擔責任，這很適合他。"},{"en":"She felt the weight of responsibility and rose to meet it.","zh":"她感受到了責任的重量，並迎頭而上。"},{"en":"Taking responsibility is the fastest way to rebuild trust.","zh":"承擔責任是重建信任的最快方式。"},{"en":"He shared responsibility equally across the team.","zh":"他在整個團隊中平均分配責任。"},{"en":"Growing up means accepting more responsibility willingly.","zh":"成長意味著願意接受更多責任。"},{"en":"She holds herself accountable before anyone else does.","zh":"她在任何人之前就讓自己負責。"},{"en":"Responsibility without authority is the worst combination.","zh":"沒有權力的責任是最糟糕的組合。"},{"en":"He models responsibility for those who look up to him.","zh":"他為那些仰望他的人樹立責任的榜樣。"}]},{"word":"significant","pos":"adjective","chinese":"重要的；顯著的","level":"B1","sentences":[{"en":"That decision was more significant than I realised at the time.","zh":"那個決定比我當時意識到的更重要。"},{"en":"She made a significant difference to everyone she knew.","zh":"她對她認識的每個人都產生了顯著的影響。"},{"en":"He achieved something significant without seeking applause.","zh":"他在不尋求掌聲的情況下取得了重要的成就。"},{"en":"The results show a significant improvement.","zh":"結果顯示出顯著的改善。"},{"en":"She marked the significant moments with small rituals.","zh":"她用小儀式標誌著重要的時刻。"},{"en":"Significant change starts with small consistent steps.","zh":"重要的變化始於小而持續的步驟。"},{"en":"He had no idea how significant that meeting would be.","zh":"他不知道那次會議將有多重要。"},{"en":"Something small can have a significant impact.","zh":"小事情可以產生重大影響。"},{"en":"She played a significant role in shaping the outcome.","zh":"她在塑造結果方面發揮了重要作用。"},{"en":"What seems insignificant today might be significant later.","zh":"今天看起來微不足道的事情，以後可能會很重要。"}]},{"word":"effective","pos":"adjective","chinese":"有效的；奏效的","level":"B1","sentences":[{"en":"She is one of the most effective communicators I know.","zh":"她是我認識的最有效的溝通者之一。"},{"en":"That strategy was surprisingly effective.","zh":"那個策略出奇地有效。"},{"en":"He finds the most effective path, not just the obvious one.","zh":"他找到最有效的路徑，而不只是顯而易見的路徑。"},{"en":"Effective feedback is specific and kind.","zh":"有效的反饋是具體而善意的。"},{"en":"She built an effective system for staying organised.","zh":"她建立了一個有效的系統來保持有組織。"},{"en":"The simplest solutions are often the most effective.","zh":"最簡單的解決方案通常是最有效的。"},{"en":"He learned to ask effective questions instead of guessing.","zh":"他學會了提出有效的問題，而不是猜測。"},{"en":"Effective rest is just as important as effective work.","zh":"有效的休息和有效的工作一樣重要。"},{"en":"She leads an effective team because she listens first.","zh":"她領導著一個有效的團隊，因為她首先傾聽。"},{"en":"Effective habits compound over time.","zh":"有效的習慣隨著時間複利增長。"}]},{"word":"perspective","pos":"noun","chinese":"觀點；看法；視角","level":"B1","sentences":[{"en":"Changing your perspective changes everything.","zh":"改變你的視角改變了一切。"},{"en":"She brings a fresh perspective to every discussion.","zh":"她為每次討論帶來了新鮮的視角。"},{"en":"Gain perspective — look at the bigger picture.","zh":"獲得視角——看大局。"},{"en":"He gained perspective through travel and it shows.","zh":"他通過旅行獲得了視角，這從他身上可以看出來。"},{"en":"Her perspective on failure completely shifted mine.","zh":"她對失敗的看法完全改變了我的看法。"},{"en":"Different perspectives create better solutions.","zh":"不同的視角創造更好的解決方案。"},{"en":"She keeps perspective by remembering what truly matters.","zh":"她通過記住真正重要的事情來保持視角。"},{"en":"His perspective is shaped by experiences most people never have.","zh":"他的視角是由大多數人從未有過的經歷所塑造的。"},{"en":"Perspective is a gift — share it generously.","zh":"視角是一份禮物——慷慨地分享它。"},{"en":"She sees things from a perspective I had never considered.","zh":"她從一個我從未考慮過的視角看事情。"}]},{"word":"attitude","pos":"noun","chinese":"態度；姿態","level":"B1","sentences":[{"en":"Her attitude in difficult situations inspires everyone.","zh":"她在困難情況下的態度激勵了所有人。"},{"en":"Attitude is the one thing you can always control.","zh":"態度是你唯一能始終控制的事情。"},{"en":"He walks in with a positive attitude and changes the room.","zh":"他帶著積極的態度走進來，改變了整個房間。"},{"en":"A grateful attitude is the foundation of happiness.","zh":"感恩的態度是幸福的基礎。"},{"en":"She adjusted her attitude and everything else followed.","zh":"她調整了態度，其他一切都隨之而來。"},{"en":"The right attitude turns obstacles into stepping stones.","zh":"正確的態度把障礙變成踏腳石。"},{"en":"He has an attitude of curiosity about everything.","zh":"他對一切都保持好奇的態度。"},{"en":"Your attitude toward the problem is the problem.","zh":"你對問題的態度才是真正的問題。"},{"en":"She has a no-nonsense attitude that commands respect.","zh":"她有一種直截了當的態度，讓人肅然起敬。"},{"en":"Attitude is contagious — be careful whose you catch.","zh":"態度是有感染力的——小心你感染到誰的。"}]},{"word":"influence","pos":"noun/verb","chinese":"影響；影響力","level":"B1","sentences":[{"en":"She influences people by being genuine, not by trying.","zh":"她通過真實而非刻意地影響人們。"},{"en":"His influence on the team is quiet but profound.","zh":"他對團隊的影響雖然低調，但卻深遠。"},{"en":"She was influenced by her grandmother's resilience.","zh":"她受到了祖母堅韌的影響。"},{"en":"Influence is earned through trust over time.","zh":"影響力是通過時間積累的信任而獲得的。"},{"en":"He uses his influence to open doors for others.","zh":"他利用他的影響力為他人開門。"},{"en":"Your environment influences you more than you realise.","zh":"你的環境對你的影響比你意識到的更大。"},{"en":"She had a quiet influence that shaped careers.","zh":"她有一種無聲的影響力，塑造了許多職業生涯。"},{"en":"Influence without integrity is just manipulation.","zh":"沒有誠信的影響力只是操縱。"},{"en":"He influenced me to read more through his passion.","zh":"他通過他的熱情影響我多讀書。"},{"en":"The books we read influence how we think.","zh":"我們讀的書影響我們的思維方式。"}]},{"word":"contribute","pos":"verb","chinese":"貢獻；捐獻","level":"B1","sentences":[{"en":"She contributes to every meeting with something valuable.","zh":"她在每次會議上都貢獻了有價值的東西。"},{"en":"He contributed his skills freely to the community project.","zh":"他為社區項目自由地貢獻了他的技能。"},{"en":"Everyone contributes differently — all contributions matter.","zh":"每個人的貢獻方式不同——所有貢獻都很重要。"},{"en":"She contributed to the team in ways that never got recognition.","zh":"她以從未得到認可的方式為團隊做出了貢獻。"},{"en":"Contributing to something bigger than yourself is fulfilling.","zh":"為比自己更大的事情做出貢獻是令人滿足的。"},{"en":"He contributed ideas that changed the direction of the project.","zh":"他貢獻了改變項目方向的想法。"},{"en":"Small contributions consistently made are powerful.","zh":"持續做出的小貢獻是有力量的。"},{"en":"She contributes her best work even when no one is watching.","zh":"即使沒有人在看，她也貢獻出最好的工作。"},{"en":"Contributing to others well-being contributes to your own.","zh":"為他人的幸福做出貢獻也有助於你自己的幸福。"},{"en":"He contributed to the conversation without dominating it.","zh":"他在沒有主導的情況下為對話做出了貢獻。"}]},{"word":"opinion","pos":"noun","chinese":"意見；看法","level":"A2","sentences":[{"en":"What is your opinion on working from home?","zh":"你對居家辦公有什麼看法？"},{"en":"She shares her opinions openly and without apology.","zh":"她坦率地分享意見，不道歉。"},{"en":"My opinion changed completely after reading that book.","zh":"讀了那本書後，我的看法完全改變了。"},{"en":"Everyone has an opinion — the skill is knowing when to share it.","zh":"每個人都有意見——技巧在於知道什麼時候分享。"},{"en":"He values other opinions before forming his own.","zh":"他在形成自己的意見之前重視別人的意見。"},{"en":"She has strong opinions held lightly — always open to changing.","zh":"她有強烈的意見，但持有得很輕——總是願意改變。"},{"en":"In my opinion, this is the best version yet.","zh":"在我看來，這是迄今為止最好的版本。"},{"en":"He gave his honest opinion even when it was not popular.","zh":"即使不受歡迎，他也給出了誠實的意見。"},{"en":"Opinions are not facts — remember that.","zh":"意見不是事實——記住這一點。"},{"en":"She changed her opinion gracefully when given new information.","zh":"當獲得新信息時，她優雅地改變了她的意見。"}]},{"word":"advantage","pos":"noun","chinese":"優勢；好處","level":"A2","sentences":[{"en":"What is the main advantage of this approach?","zh":"這種方法的主要優勢是什麼？"},{"en":"She used every advantage she had to get ahead.","zh":"她利用她擁有的每一個優勢來取得進步。"},{"en":"The advantage of starting early is time on your side.","zh":"早起步的優勢是時間站在你那邊。"},{"en":"He took advantage of every learning opportunity.","zh":"他利用了每一個學習機會。"},{"en":"She turned her disadvantage into a unique advantage.","zh":"她把劣勢轉化為獨特的優勢。"},{"en":"The biggest advantage is consistency over time.","zh":"最大的優勢是長期的一致性。"},{"en":"He has the advantage of experience — hard earned.","zh":"他擁有經驗的優勢——這是艱難贏得的。"},{"en":"Take advantage of your strengths before worrying about weaknesses.","zh":"在擔心弱點之前，先利用你的優勢。"},{"en":"That location is a major advantage for the business.","zh":"那個地點對業務來說是一個主要優勢。"},{"en":"She gave herself the advantage by being well prepared.","zh":"她通過充分準備給了自己優勢。"}]},{"word":"communicate","pos":"verb","chinese":"溝通；交流","level":"A2","sentences":[{"en":"She communicates clearly and people always understand her.","zh":"她溝通清晰，人們總是理解她。"},{"en":"How you communicate is just as important as what you say.","zh":"你如何溝通和你說什麼一樣重要。"},{"en":"He communicates his needs without drama.","zh":"他不帶戲劇性地表達他的需求。"},{"en":"Communicating kindly in hard conversations is a real skill.","zh":"在困難的對話中善意地溝通是一種真正的技能。"},{"en":"She communicates across cultures effortlessly.","zh":"她毫不費力地跨文化溝通。"},{"en":"Good relationships depend on good communication.","zh":"好的關係取決於好的溝通。"},{"en":"He learned to communicate his feelings after years of silence.","zh":"他在多年的沉默後學會了表達自己的感受。"},{"en":"Communicating in writing is a different skill than speaking.","zh":"書面溝通是與口頭不同的技能。"},{"en":"She communicates her vision so well that others believe in it too.","zh":"她對願景的表達如此清晰，讓其他人也相信了它。"},{"en":"Communicate early and often — do not let things fester.","zh":"儘早並經常溝通——不要讓問題惡化。"}]},{"word":"develop","pos":"verb","chinese":"發展；培養","level":"A2","sentences":[{"en":"She developed her skills over years of daily practice.","zh":"她通過多年的日常練習培養了她的技能。"},{"en":"Developing a habit takes twenty-one days minimum.","zh":"養成一個習慣至少需要二十一天。"},{"en":"He developed a reputation for reliability.","zh":"他培養了可靠的聲譽。"},{"en":"She is developing something exciting — details to follow.","zh":"她正在開發一些令人興奮的東西——詳情隨後。"},{"en":"Developing patience is a lifelong practice.","zh":"培養耐心是一種終身的練習。"},{"en":"He developed his ideas by talking them through with others.","zh":"他通過和別人討論來發展他的想法。"},{"en":"She developed the confidence to speak first.","zh":"她培養了首先發言的自信。"},{"en":"Developing resilience is the most useful life skill.","zh":"培養韌性是最有用的生活技能。"},{"en":"He developed his craft with obsessive attention to detail.","zh":"他以對細節的執著關注來精進他的技藝。"},{"en":"Slowly developed ideas are the ones that last.","zh":"慢慢發展的想法才是能持久的。"}]},{"word":"identify","pos":"verb","chinese":"識別；確認","level":"A2","sentences":[{"en":"She identified the problem before anyone else noticed.","zh":"她在其他人注意到之前就識別了問題。"},{"en":"He identifies as someone who learns from failure.","zh":"他認同自己是一個從失敗中學習的人。"},{"en":"Can you identify which part is causing the issue?","zh":"你能識別是哪個部分導致了問題嗎？"},{"en":"She identified her strengths and built on them.","zh":"她識別了自己的優勢，並在此基礎上繼續發展。"},{"en":"Identifying the root cause saves time.","zh":"識別根本原因可以節省時間。"},{"en":"He identified a gap in the market and filled it.","zh":"他識別了市場上的空缺並填補了它。"},{"en":"She identified her values early and let them guide her.","zh":"她很早就確認了自己的價值觀，讓它們指引她。"},{"en":"Identifying your triggers helps you respond better.","zh":"識別你的觸發點幫助你更好地回應。"},{"en":"He identified his ideal customer and spoke directly to them.","zh":"他識別了他的理想客戶，並直接與他們交流。"},{"en":"She identifies with the character so deeply it hurts.","zh":"她對那個角色的認同如此深刻，感覺心痛。"}]},{"word":"protect","pos":"verb","chinese":"保護；防護","level":"A2","sentences":[{"en":"She protects her energy like it is a limited resource.","zh":"她像保護有限資源一樣保護她的精力。"},{"en":"He protects his family fiercely and quietly.","zh":"他強烈而安靜地保護他的家人。"},{"en":"Protect your peace — not everything deserves your reaction.","zh":"保護你的平靜——不是每件事都值得你的反應。"},{"en":"She protects the things that matter by saying no more often.","zh":"她通過更頻繁地說不來保護重要的事情。"},{"en":"Protecting your mental health is an act of self-love.","zh":"保護你的心理健康是一種自愛的行為。"},{"en":"He protects his downtime with the same vigour as his work.","zh":"他以同等的活力保護他的休息時間。"},{"en":"She protects her creativity by keeping mornings sacred.","zh":"她通過保持早晨的神聖來保護她的創造力。"},{"en":"Protect the relationship more than you protect being right.","zh":"保護關係比保護自己的正確性更重要。"},{"en":"He protected his vision from people who did not believe.","zh":"他保護了他的願景不受那些不相信的人影響。"},{"en":"She protects her standards without being rigid about everything.","zh":"她保護自己的標準，但不對每件事都死板。"}]},{"word":"replace","pos":"verb","chinese":"替換；取代","level":"A2","sentences":[{"en":"She replaced her bad habits one by one.","zh":"她一個接一個地替換了她的壞習慣。"},{"en":"Nothing can replace human connection.","zh":"沒有什麼能取代人與人之間的連結。"},{"en":"He replaced his morning scroll with a walk.","zh":"他用散步取代了早晨刷手機的習慣。"},{"en":"She replaced complaints with questions and everything changed.","zh":"她用問題取代了抱怨，一切都改變了。"},{"en":"Replace worry with action whenever possible.","zh":"盡可能用行動取代擔憂。"},{"en":"He replaced the broken part and it worked perfectly.","zh":"他替換了壞掉的部分，效果完美。"},{"en":"She replaced the word 'but' with 'and' — game changer.","zh":"她用「而且」取代了「但是」——改變了一切。"},{"en":"Nothing replaces experience — go do the thing.","zh":"沒有什麼能取代經驗——去做那件事吧。"},{"en":"He replaced his negative self-talk with neutral observation.","zh":"他用中性的觀察取代了負面的自我對話。"},{"en":"She replaced the things that drained her with things that filled her.","zh":"她用充實她的事物取代了耗盡她的事物。"}]},{"word":"reduce","pos":"verb","chinese":"減少；降低","level":"A2","sentences":[{"en":"She reduced her screen time and gained two hours a day.","zh":"她減少了螢幕使用時間，每天多出了兩個小時。"},{"en":"Reduce, reuse, recycle — still relevant.","zh":"減少、重複使用、回收——仍然有意義。"},{"en":"He reduced his spending and did not miss anything.","zh":"他減少了開支，沒有覺得缺少任何東西。"},{"en":"She reduced the complexity and suddenly it all made sense.","zh":"她降低了複雜性，突然一切都說得通了。"},{"en":"Reducing stress is not optional — it is health care.","zh":"減少壓力不是可選的——它是醫療保健。"},{"en":"He reduced his commitments to focus on what truly mattered.","zh":"他減少了承諾，以專注於真正重要的事情。"},{"en":"She reduced the noise and found the signal.","zh":"她減少了雜音，找到了信號。"},{"en":"Reducing options actually increases decision satisfaction.","zh":"減少選項實際上增加了決策滿意度。"},{"en":"He reduced his reaction time by pausing before responding.","zh":"他通過在回應前暫停來減少他的反應時間。"},{"en":"She reduced her workload without reducing her output.","zh":"她在不減少產出的情況下減少了工作量。"}]},{"word":"increase","pos":"verb","chinese":"增加；提高","level":"A2","sentences":[{"en":"She increased her income by adding one new skill.","zh":"她通過增加一項新技能來增加收入。"},{"en":"Reading daily increases vocabulary without effort.","zh":"每天閱讀可以輕鬆增加詞彙量。"},{"en":"He increased his impact by being more consistent.","zh":"他通過更加一致來增加他的影響力。"},{"en":"Small changes compound — they increase over time.","zh":"小改變會複利增長——它們隨時間增加。"},{"en":"She increased her confidence by doing the scary thing first.","zh":"她通過首先做可怕的事情來增加她的信心。"},{"en":"Increasing effort without increasing rest leads to burnout.","zh":"在不增加休息的情況下增加努力會導致倦怠。"},{"en":"He increased his network by showing genuine interest in others.","zh":"他通過對他人表現出真正的興趣來擴大人脈。"},{"en":"She increased the quality by reducing the quantity.","zh":"她通過減少數量來提高品質。"},{"en":"Increasing your awareness changes everything.","zh":"增加你的意識改變一切。"},{"en":"He increased his focus by removing distractions one by one.","zh":"他通過逐一消除干擾來增加他的專注力。"}]},{"word":"purpose","pos":"noun","chinese":"目的；意義","level":"A2","sentences":[{"en":"She lives with a sense of purpose that is contagious.","zh":"她帶著一種有感染力的目標感生活。"},{"en":"Finding your purpose is a process — not a moment.","zh":"找到你的目標是一個過程——而不是一個時刻。"},{"en":"He does everything with purpose — never by accident.","zh":"他做每件事都有目的——從不是偶然。"},{"en":"She woke up with purpose and that changed her mornings.","zh":"她帶著目的感醒來，這改變了她的早晨。"},{"en":"Purpose is not found — it is built through action.","zh":"目標不是被找到的——而是通過行動建立的。"},{"en":"He connected his work to a larger purpose and stayed motivated.","zh":"他把工作與更大的目標聯繫起來，保持了動力。"},{"en":"She designed her life around purpose, not just income.","zh":"她圍繞目標而不只是收入來設計她的生活。"},{"en":"Purpose gives you the why when the how gets hard.","zh":"當如何做變得困難時，目標給你一個為什麼。"},{"en":"He found purpose in the smallest daily acts.","zh":"他在最小的日常行為中找到了目標。"},{"en":"A sense of purpose is the best motivator that exists.","zh":"目標感是最好的激勵因素。"}]},{"word":"effort","pos":"noun","chinese":"努力；付出","level":"A2","sentences":[{"en":"She puts genuine effort into everything — no half measures.","zh":"她在每件事上都付出真正的努力——沒有半途而廢。"},{"en":"Effort without direction is just exhaustion.","zh":"沒有方向的努力只是疲憊。"},{"en":"He noticed the effort behind her work and said so.","zh":"他注意到了她工作背後的努力，並說了出來。"},{"en":"Small consistent efforts beat occasional bursts every time.","zh":"小而持續的努力每次都勝過偶爾的爆發。"},{"en":"She makes the effort to stay in touch — I appreciate it.","zh":"她努力保持聯繫——我很感激。"},{"en":"Effort is visible — people notice when you try.","zh":"努力是顯而易見的——人們注意到你在嘗試。"},{"en":"He makes every effort look effortless — that is mastery.","zh":"他讓每一份努力看起來毫不費力——那就是精通。"},{"en":"She puts effort into the things others take for granted.","zh":"她在別人視為理所當然的事情上付出努力。"},{"en":"Effort compounds — small daily work adds up to big results.","zh":"努力會複利增長——每天的小工作積累成大成果。"},{"en":"The quality of your effort determines the quality of your results.","zh":"你努力的質量決定了你結果的質量。"}]},{"word":"pattern","pos":"noun","chinese":"模式；規律","level":"A2","sentences":[{"en":"She noticed the pattern and broke it.","zh":"她注意到了這個模式並打破了它。"},{"en":"Patterns repeat until you see them.","zh":"模式會重複，直到你看見它們。"},{"en":"He identified the pattern in his thinking and changed course.","zh":"他識別了自己思維中的模式並改變了方向。"},{"en":"She broke a generational pattern and created something new.","zh":"她打破了代際模式，創造了新的東西。"},{"en":"Recognising patterns is the first step to changing them.","zh":"識別模式是改變它們的第一步。"},{"en":"His daily pattern is simple but remarkably effective.","zh":"他的日常模式很簡單，但非常有效。"},{"en":"She saw the pattern in her relationships and made changes.","zh":"她看到了她關係中的模式並做了改變。"},{"en":"Patterns in nature are the universe's way of showing order.","zh":"自然界的模式是宇宙展示秩序的方式。"},{"en":"He studied the patterns in his own behaviour with curiosity.","zh":"他帶著好奇心研究自己行為中的模式。"},{"en":"A healthy pattern maintained consistently becomes a lifestyle.","zh":"持續保持的健康模式成為一種生活方式。"}]},{"word":"solve","pos":"verb","chinese":"解決；解答","level":"A2","sentences":[{"en":"She solves problems the way others see opportunities.","zh":"她用別人看到機會的方式解決問題。"},{"en":"He solved the issue quietly without making it dramatic.","zh":"他安靜地解決了問題，沒有讓它變得戲劇化。"},{"en":"Can you solve this or do we need extra help?","zh":"你能解決這個問題還是我們需要額外的幫助？"},{"en":"She solves puzzles for fun — her mind works differently.","zh":"她為了樂趣解謎——她的思維運作方式不同。"},{"en":"Solving the right problem is harder than solving any problem.","zh":"解決正確的問題比解決任何問題都難。"},{"en":"He solved it in three steps that took everyone else thirty.","zh":"他用三個步驟解決了別人需要三十個步驟的問題。"},{"en":"She solves conflicts by addressing the emotion first.","zh":"她通過首先處理情緒來解決衝突。"},{"en":"Not every problem can be solved — some just pass with time.","zh":"並非每個問題都能被解決——有些只是隨時間消退。"},{"en":"He solved the problem by reframing the question.","zh":"他通過重新框架問題來解決它。"},{"en":"She teaches her team to solve problems, not just report them.","zh":"她教她的團隊解決問題，而不只是報告它們。"}]},{"word":"consequently","pos":"adverb","chinese":"因此；結果","level":"B1","sentences":[{"en":"She prepared thoroughly; consequently, the presentation was flawless.","zh":"她充分準備；因此，演講完美無瑕。"},{"en":"He ignored the warning and consequently missed the deadline.","zh":"他忽略了警告，因此錯過了截止日期。"},{"en":"The team communicated well and consequently the project succeeded.","zh":"團隊溝通良好，因此項目成功了。"},{"en":"She invested early; consequently, she retired comfortably.","zh":"她早期投資；因此，她舒適地退休了。"},{"en":"He was consistently kind and consequently earned people's trust.","zh":"他一貫善良，因此贏得了人們的信任。"},{"en":"She adapted quickly and consequently thrived in the new role.","zh":"她快速適應，因此在新職位上茁壯成長。"},{"en":"He burned out and consequently took a long break.","zh":"他倦怠了，因此休了很長的假。"},{"en":"She listened well; consequently, people told her everything.","zh":"她善於傾聽；因此，人們告訴了她一切。"},{"en":"He planned carefully and consequently nothing surprised him.","zh":"他仔細計劃，因此沒有任何事情讓他驚訝。"},{"en":"She set clear boundaries; consequently, her stress reduced.","zh":"她設立了清晰的界限；因此，她的壓力減少了。"}]},{"word":"involve","pos":"verb","chinese":"涉及；包含","level":"B1","sentences":[{"en":"The project involves a lot of moving parts.","zh":"這個項目涉及很多移動的部分。"},{"en":"She involves her team in every major decision.","zh":"她讓她的團隊參與每一個重大決定。"},{"en":"He did not realise how much work it would involve.","zh":"他沒有意識到這需要多少工作。"},{"en":"Success involves discomfort — that is part of the deal.","zh":"成功涉及不舒適——那是交易的一部分。"},{"en":"She involves herself in things that align with her values.","zh":"她讓自己參與與她價值觀一致的事情。"},{"en":"He got involved and it changed everything.","zh":"他參與進去了，一切都改變了。"},{"en":"Involving others in the process leads to better outcomes.","zh":"讓其他人參與這個過程帶來更好的結果。"},{"en":"She involves herself in too many projects at once.","zh":"她一次讓自己參與太多項目。"},{"en":"He is involved in three community organisations.","zh":"他參與了三個社區組織。"},{"en":"Getting involved is the first step to making a difference.","zh":"參與進去是有所不同的第一步。"}]},{"word":"maintain","pos":"verb","chinese":"維持；保持","level":"B1","sentences":[{"en":"She maintains her standards even under pressure.","zh":"她即使在壓力下也保持她的標準。"},{"en":"He maintains a consistent routine no matter what.","zh":"無論發生什麼，他都保持一貫的日常規律。"},{"en":"Maintaining focus is harder than finding it.","zh":"保持專注比找到它更難。"},{"en":"She maintains her relationships with intentional effort.","zh":"她以有意識的努力維護她的關係。"},{"en":"He maintains a healthy scepticism about everything.","zh":"他對每件事都保持健康的懷疑態度。"},{"en":"Maintaining balance is not a state — it is a daily practice.","zh":"保持平衡不是一種狀態——而是一種日常練習。"},{"en":"She maintains her calm by choosing her battles.","zh":"她通過選擇她的戰役來保持她的冷靜。"},{"en":"He maintains his integrity when it would be easy not to.","zh":"當不這樣做很容易時，他依然保持他的誠信。"},{"en":"Maintaining momentum is as hard as building it.","zh":"保持勢頭和建立勢頭一樣難。"},{"en":"She maintains perspective by reminding herself of the bigger picture.","zh":"她通過提醒自己看大局來保持視角。"}]},{"word":"assume","pos":"verb","chinese":"假設；承擔","level":"B1","sentences":[{"en":"Never assume — always check.","zh":"永遠不要假設——總是去確認。"},{"en":"She assumed the best and was rarely disappointed.","zh":"她假設最好的情況，很少失望。"},{"en":"He assumed responsibility without being asked.","zh":"他未被要求就承擔了責任。"},{"en":"Do not assume silence means agreement.","zh":"不要假設沉默意味著同意。"},{"en":"She assumed it was obvious and did not explain — mistake.","zh":"她假設這是顯而易見的，沒有解釋——這是個錯誤。"},{"en":"Assuming good intent makes interactions smoother.","zh":"假設好意讓互動更順暢。"},{"en":"He assumed the role of leader naturally.","zh":"他自然地承擔了領導者的角色。"},{"en":"She challenges her assumptions daily.","zh":"她每天挑戰她的假設。"},{"en":"Assumptions are not knowledge — confirm before acting.","zh":"假設不是知識——在行動前確認。"},{"en":"He assumed more than he could handle and learned from it.","zh":"他承擔了超過他能應付的，並從中學習。"}]},{"word":"establish","pos":"verb","chinese":"建立；確立","level":"B1","sentences":[{"en":"She established trust before asking for anything.","zh":"她在要求任何事情之前建立了信任。"},{"en":"He established a system that outlasted him.","zh":"他建立了一個比他更長久的系統。"},{"en":"Establishing habits early makes life easier later.","zh":"早期建立習慣讓以後的生活更容易。"},{"en":"She established herself as the expert through consistent output.","zh":"她通過持續的輸出確立了自己的專家地位。"},{"en":"He established clear expectations from day one.","zh":"他從第一天就確立了明確的期望。"},{"en":"Establishing a reputation takes years — protect it.","zh":"建立聲譽需要多年——保護它。"},{"en":"She established her brand on honesty and it never wavered.","zh":"她在誠實的基礎上建立了她的品牌，從未動搖。"},{"en":"He established the foundation before building the walls.","zh":"他在建牆之前先建立了地基。"},{"en":"Establishing routines removes the need for daily willpower.","zh":"建立例行程序消除了每日意志力的需要。"},{"en":"She established herself in the industry before she was thirty.","zh":"她在三十歲前就在業界確立了自己的地位。"}]},{"word":"assess","pos":"verb","chinese":"評估；評價","level":"B1","sentences":[{"en":"She assesses situations calmly before reacting.","zh":"她在反應之前冷靜地評估情況。"},{"en":"He assesses his progress monthly and adjusts accordingly.","zh":"他每月評估他的進度，並相應調整。"},{"en":"Can you assess the risk before we commit?","zh":"在我們承諾之前你能評估風險嗎？"},{"en":"She assesses people's energy before investing hers.","zh":"她在投入自己的精力之前評估別人的能量。"},{"en":"Accurately assessing your own skills is surprisingly hard.","zh":"準確評估自己的技能出奇地難。"},{"en":"He assesses value, not just price.","zh":"他評估價值，而不只是價格。"},{"en":"She assesses feedback objectively — without ego.","zh":"她客觀地評估反饋——沒有自我。"},{"en":"Assessing the situation honestly leads to better decisions.","zh":"誠實地評估情況帶來更好的決定。"},{"en":"He was assessed and found ready for the next level.","zh":"他被評估後，被認為已準備好進入下一個階段。"},{"en":"She assesses herself as harshly as she assesses her work.","zh":"她對自己的評估和對她工作的評估一樣嚴苛。"}]},{"word":"generate","pos":"verb","chinese":"產生；生成","level":"B1","sentences":[{"en":"She generates ideas constantly — the challenge is choosing one.","zh":"她不斷產生想法——挑戰在於選擇一個。"},{"en":"He generates trust by being consistent.","zh":"他通過一貫性來建立信任。"},{"en":"That content generated more engagement than expected.","zh":"那個內容產生了比預期更多的互動。"},{"en":"She generates energy in every room she enters.","zh":"她在她進入的每個房間都產生能量。"},{"en":"How do you generate ideas when you feel stuck?","zh":"當你感到卡住時，你如何產生想法？"},{"en":"He generates multiple solutions before choosing one.","zh":"他在選擇之前產生多個解決方案。"},{"en":"She generates revenue through multiple streams.","zh":"她通過多個渠道產生收入。"},{"en":"Generating momentum is about small consistent actions.","zh":"產生動力在於小而持續的行動。"},{"en":"He generates loyalty by giving more than he takes.","zh":"他通過給予多於索取來產生忠誠度。"},{"en":"She generates calm by being calm — it radiates.","zh":"她通過保持冷靜來產生平靜——它向外輻射。"}]},{"word":"resolve","pos":"verb","chinese":"解決；下決心","level":"B1","sentences":[{"en":"She resolved to make the change and never looked back.","zh":"她下決心做出改變，從此再沒有回頭看。"},{"en":"He resolved the conflict by listening first.","zh":"他通過首先傾聽來解決了衝突。"},{"en":"They resolved their differences with honesty and respect.","zh":"他們以誠實和尊重解決了他們的分歧。"},{"en":"She resolved to be kinder to herself this year.","zh":"她今年下決心對自己更善良。"},{"en":"Resolving issues early prevents bigger problems later.","zh":"早期解決問題可以防止以後出現更大的問題。"},{"en":"He resolved the uncertainty by asking a direct question.","zh":"他通過提出一個直接的問題解決了不確定性。"},{"en":"She resolved to finish what she started.","zh":"她下決心完成她開始的事情。"},{"en":"Resolving a conflict with grace requires maturity.","zh":"優雅地解決衝突需要成熟。"},{"en":"He resolved the tension with humour at just the right moment.","zh":"他在恰當的時刻用幽默化解了緊張氣氛。"},{"en":"She resolved every doubt by taking action.","zh":"她通過採取行動解決了每一個疑慮。"}]},{"word":"adapt","pos":"verb","chinese":"適應；調整","level":"B1","sentences":[{"en":"She adapts to new situations faster than anyone I know.","zh":"她比我認識的任何人都更快適應新情況。"},{"en":"He adapted his approach when the first one failed.","zh":"當第一個方法失敗時，他調整了他的方式。"},{"en":"Adapting is not giving up — it is being intelligent.","zh":"適應不是放棄——而是有智慧。"},{"en":"She adapted the recipe to suit her dietary needs.","zh":"她根據她的飲食需求調整了食譜。"},{"en":"He adapts his communication style to his audience.","zh":"他根據他的聽眾調整他的溝通方式。"},{"en":"Adapting quickly is the most valuable skill in uncertainty.","zh":"在不確定性中，快速適應是最有價值的技能。"},{"en":"She adapted to working remotely better than expected.","zh":"她比預期更好地適應了遠程工作。"},{"en":"He adapted his plans when circumstances changed.","zh":"當情況改變時，他調整了他的計畫。"},{"en":"Adapting does not mean abandoning your values.","zh":"適應並不意味著放棄你的價值觀。"},{"en":"She adapted the idea to fit the local context perfectly.","zh":"她調整了這個想法，使其完美地適應當地情況。"}]},{"word":"demonstrate","pos":"verb","chinese":"展示；證明","level":"B1","sentences":[{"en":"She demonstrated her ability through results, not words.","zh":"她通過結果而不是言語展示了她的能力。"},{"en":"He demonstrated patience in a situation that would test anyone.","zh":"他在一個會考驗任何人的情況下展示了耐心。"},{"en":"She demonstrated the technique step by step.","zh":"她一步一步地展示了這個技術。"},{"en":"He demonstrates leadership by putting his team first.","zh":"他通過把他的團隊放在首位來展示領導力。"},{"en":"She demonstrated resilience in the face of real adversity.","zh":"她在真正的逆境中展示了韌性。"},{"en":"How you treat people in small moments demonstrates character.","zh":"你在小事情上如何對待人展示了你的品格。"},{"en":"He demonstrated the idea clearly and everyone understood.","zh":"他清楚地展示了這個想法，每個人都理解了。"},{"en":"She demonstrates genuine care by following up consistently.","zh":"她通過持續的跟進展示了真正的關心。"},{"en":"He demonstrated that quiet people can lead loudly.","zh":"他展示了安靜的人也能做出有力的領導。"},{"en":"She demonstrated the impact of small, daily choices.","zh":"她展示了每天微小選擇的影響力。"}]},{"word":"create","pos":"verb","chinese":"創造；製作","level":"A2","sentences":[{"en":"She creates something every single day.","zh":"她每天都創造一些東西。"},{"en":"He created a system that works for everyone.","zh":"他創造了一個對每個人都有效的系統。"},{"en":"I want to create more and consume less.","zh":"我想多創造，少消費。"},{"en":"Creating is how she processes the world.","zh":"創造是她處理世界的方式。"},{"en":"He creates space for others to shine.","zh":"他為別人創造發光的空間。"},{"en":"She created a business from a simple idea.","zh":"她從一個簡單的想法創造了一個生意。"},{"en":"Create the life you want, do not wait for it.","zh":"創造你想要的生活，不要等待它。"},{"en":"He creates calm wherever he goes.","zh":"他走到哪裡都創造平靜。"},{"en":"I create best in the early morning hours.","zh":"我在清晨創作得最好。"},{"en":"She creates without worrying if it is perfect.","zh":"她創作時不擔心它是否完美。"}]},{"word":"imagine","pos":"verb","chinese":"想像；設想","level":"A2","sentences":[{"en":"Imagine what you could do with no fear.","zh":"想像一下沒有恐懼你能做什麼。"},{"en":"She imagined a different life and then built it.","zh":"她想像了一種不同的生活，然後建立了它。"},{"en":"I cannot imagine my life without this.","zh":"我無法想像沒有這個的生活。"},{"en":"He imagines the best outcome before he starts.","zh":"他在開始之前想像最好的結果。"},{"en":"Imagine if everyone was just a little kinder.","zh":"想像一下如果每個人都稍微善良一點。"},{"en":"She has an incredible ability to imagine possibilities.","zh":"她有令人難以置信的想像可能性的能力。"},{"en":"Imagine where you will be in five years.","zh":"想像五年後你會在哪裡。"},{"en":"He imagined success so vividly it became real.","zh":"他如此生動地想像成功，以至於它成真了。"},{"en":"I imagine a world with more empathy.","zh":"我想像一個有更多同理心的世界。"},{"en":"Imagine doing what you love every single day.","zh":"想像每天做你喜歡的事情。"}]},{"word":"expect","pos":"verb","chinese":"期望；預期","level":"A2","sentences":[{"en":"Do not expect others to read your mind.","zh":"不要期望別人讀懂你的心思。"},{"en":"She expected the worst but hoped for the best.","zh":"她預期最壞的，但希望最好的。"},{"en":"I did not expect it to be this hard.","zh":"我沒有預期它會這麼難。"},{"en":"He exceeds expectations every time.","zh":"他每次都超出期望。"},{"en":"Expect nothing and appreciate everything.","zh":"期望什麼都沒有，欣賞一切。"},{"en":"She expects a lot from herself, gently.","zh":"她對自己期望很高，但很溫和。"},{"en":"I expect honesty above everything else.","zh":"我期望誠實高於一切。"},{"en":"He expected resistance and prepared for it.","zh":"他預期阻力並為之做準備。"},{"en":"Lower your expectations of others, raise them of yourself.","zh":"降低對別人的期望，提高對自己的期望。"},{"en":"She did better than anyone expected.","zh":"她做得比任何人預期的都好。"}]},{"word":"avoid","pos":"verb","chinese":"避免；迴避","level":"A2","sentences":[{"en":"I avoid drama whenever I possibly can.","zh":"我盡可能避免麻煩事。"},{"en":"She avoids people who drain her energy.","zh":"她避開耗盡她精力的人。"},{"en":"He avoided the topic for as long as he could.","zh":"他盡可能長時間地迴避這個話題。"},{"en":"Avoid making big decisions when you are tired.","zh":"累的時候避免做重大決定。"},{"en":"I learned to avoid comparing myself to others.","zh":"我學會了避免把自己和別人比較。"},{"en":"She avoids saying yes when she means no.","zh":"她避免在想說不的時候說好。"},{"en":"He avoids gossip — it never serves him.","zh":"他避免八卦——它從不對他有益。"},{"en":"Avoid the trap of waiting for perfect.","zh":"避免等待完美的陷阱。"},{"en":"I avoid screens for the first hour of the day.","zh":"我在一天的第一個小時避免使用螢幕。"},{"en":"She avoids overcommitting and stays present.","zh":"她避免過度承諾，保持當下。"}]},{"word":"prefer","pos":"verb","chinese":"偏好；更喜歡","level":"A2","sentences":[{"en":"I prefer a quiet evening over a loud party.","zh":"我更喜歡安靜的夜晚而不是吵鬧的派對。"},{"en":"She prefers honesty even when it stings.","zh":"她更喜歡誠實，即使它刺痛。"},{"en":"He prefers to listen before he speaks.","zh":"他更喜歡在說話之前傾聽。"},{"en":"I prefer quality over quantity in everything.","zh":"我在一切事情上都更喜歡品質而不是數量。"},{"en":"She prefers walking to driving when she can.","zh":"她盡可能更喜歡走路而不是開車。"},{"en":"He prefers deep conversations to small talk.","zh":"他更喜歡深入的對話而不是閒聊。"},{"en":"I prefer to do things properly or not at all.","zh":"我更喜歡把事情做好，或者根本不做。"},{"en":"She prefers her own company more than most people.","zh":"她比大多數人更喜歡獨處。"},{"en":"He prefers giving to receiving.","zh":"他更喜歡給予而不是接受。"},{"en":"I prefer real books over digital ones.","zh":"我更喜歡實體書而不是電子書。"}]},{"word":"recommend","pos":"verb","chinese":"推薦；建議","level":"A2","sentences":[{"en":"I highly recommend that book to everyone.","zh":"我強烈向每個人推薦那本書。"},{"en":"She recommended a café and it became my favourite.","zh":"她推薦了一家咖啡廳，它成了我的最愛。"},{"en":"He recommends taking breaks more often.","zh":"他建議更頻繁地休息。"},{"en":"Can you recommend somewhere good to eat?","zh":"你能推薦一個好吃的地方嗎？"},{"en":"I would recommend sleeping on big decisions.","zh":"我建議重大決定先睡一覺再做。"},{"en":"She recommends what she genuinely loves.","zh":"她推薦她真正喜歡的東西。"},{"en":"He recommended a different approach and it worked.","zh":"他推薦了一個不同的方法，它奏效了。"},{"en":"I recommend starting small and staying consistent.","zh":"我建議從小做起，保持一致。"},{"en":"She always has a recommendation ready.","zh":"她總是準備好一個推薦。"},{"en":"He recommended the trip and I am so glad I went.","zh":"他推薦了那次旅行，我很高興我去了。"}]},{"word":"complain","pos":"verb","chinese":"抱怨；投訴","level":"A2","sentences":[{"en":"I try not to complain about things I can change.","zh":"我盡量不抱怨我能改變的事情。"},{"en":"She complained politely and got a full refund.","zh":"她禮貌地投訴，得到了全額退款。"},{"en":"He never complains — he just solves problems.","zh":"他從不抱怨——他只是解決問題。"},{"en":"Complaining feels good briefly but changes nothing.","zh":"抱怨短暫地感覺良好，但什麼都不改變。"},{"en":"I caught myself complaining and chose gratitude instead.","zh":"我發現自己在抱怨，於是選擇了感恩。"},{"en":"She raised her complaint through the right channel.","zh":"她通過正確的渠道提出了投訴。"},{"en":"He complains less and acts more.","zh":"他抱怨更少，行動更多。"},{"en":"Instead of complaining, she made a suggestion.","zh":"她沒有抱怨，而是提出了一個建議。"},{"en":"I stopped complaining and started changing things.","zh":"我停止抱怨，開始改變事情。"},{"en":"She complained once, clearly, then let it go.","zh":"她清楚地抱怨了一次，然後放下了。"}]},{"word":"apologise","pos":"verb","chinese":"道歉；致歉","level":"A2","sentences":[{"en":"He apologised properly — no excuses, just ownership.","zh":"他好好地道歉了——沒有藉口，只有承擔。"},{"en":"She apologised even when it was hard.","zh":"即使很難，她也道歉了。"},{"en":"I apologise when I am wrong, quickly and sincerely.","zh":"我錯的時候道歉，迅速而真誠。"},{"en":"Apologising is a strength, not a weakness.","zh":"道歉是一種力量，而不是軟弱。"},{"en":"He apologised and then changed his behaviour.","zh":"他道歉了，然後改變了他的行為。"},{"en":"She knows how to apologise without making excuses.","zh":"她知道如何不找藉口地道歉。"},{"en":"I apologised for my part without taking on his.","zh":"我為我的部分道歉，沒有承擔他的部分。"},{"en":"He apologised in person — it meant more that way.","zh":"他親自道歉——那樣意義更大。"},{"en":"A real apology has no 'but' in it.","zh":"真正的道歉裡沒有「但是」。"},{"en":"She apologised and gave him space to feel it.","zh":"她道歉了，並給了他空間去感受。"}]},{"word":"encourage","pos":"verb","chinese":"鼓勵；激勵","level":"A2","sentences":[{"en":"She encourages everyone around her to grow.","zh":"她鼓勵她周圍的每個人成長。"},{"en":"He encouraged me when I was about to give up.","zh":"在我快要放棄的時候，他鼓勵了我。"},{"en":"I try to encourage more than I criticise.","zh":"我盡量多鼓勵而不是批評。"},{"en":"Encourage people and watch them flourish.","zh":"鼓勵人們，看著他們茁壯成長。"},{"en":"She encourages without pressuring.","zh":"她鼓勵但不施壓。"},{"en":"He encouraged her to take the leap.","zh":"他鼓勵她邁出那一步。"},{"en":"A few encouraging words can change someone's day.","zh":"幾句鼓勵的話可以改變某人的一天。"},{"en":"I encourage my friends to chase their dreams.","zh":"我鼓勵我的朋友追逐他們的夢想。"},{"en":"She encourages herself the way she encourages others.","zh":"她像鼓勵別人一樣鼓勵自己。"},{"en":"He encouraged the team and morale soared.","zh":"他鼓勵團隊，士氣高漲。"}]},{"word":"compare","pos":"verb","chinese":"比較；對比","level":"A2","sentences":[{"en":"I stopped comparing my life to other people's.","zh":"我停止把我的生活和別人的比較。"},{"en":"She compares prices before any big purchase.","zh":"她在任何大筆購買前比較價格。"},{"en":"He never compares his children to each other.","zh":"他從不把他的孩子互相比較。"},{"en":"Comparison is the thief of joy.","zh":"比較是快樂的小偷。"},{"en":"I compare myself only to who I was yesterday.","zh":"我只把自己和昨天的我比較。"},{"en":"She compared the options carefully and chose well.","zh":"她仔細比較了選項，選得很好。"},{"en":"He compares notes with mentors he respects.","zh":"他和他尊敬的導師交流心得。"},{"en":"Comparing your start to someone's middle is unfair.","zh":"把你的起點和別人的中段比較是不公平的。"},{"en":"I compare less and appreciate more.","zh":"我比較更少，欣賞更多。"},{"en":"She compared both paths and trusted her gut.","zh":"她比較了兩條路，並相信了她的直覺。"}]},{"word":"succeed","pos":"verb","chinese":"成功；成就","level":"A2","sentences":[{"en":"She succeeded because she never stopped trying.","zh":"她成功了，因為她從未停止嘗試。"},{"en":"He succeeds quietly without needing applause.","zh":"他安靜地成功，不需要掌聲。"},{"en":"I want to succeed on my own terms.","zh":"我想以自己的方式成功。"},{"en":"Succeeding takes longer than people admit.","zh":"成功需要的時間比人們承認的更長。"},{"en":"She succeeded after failing many times.","zh":"她在多次失敗後成功了。"},{"en":"He defines success differently to most people.","zh":"他對成功的定義與大多數人不同。"},{"en":"I succeed when I help others succeed.","zh":"當我幫助別人成功時，我就成功了。"},{"en":"She succeeded by staying consistent for years.","zh":"她通過多年保持一致而成功。"},{"en":"He succeeds because he learns from every setback.","zh":"他成功是因為他從每次挫折中學習。"},{"en":"To succeed, you have to be willing to begin.","zh":"要成功，你必須願意開始。"}]},{"word":"recognise","pos":"verb","chinese":"認出；承認","level":"B1","sentences":[{"en":"I recognised her instantly even after ten years.","zh":"即使過了十年，我也立刻認出了她。"},{"en":"He recognises talent that others overlook.","zh":"他能認出別人忽略的才能。"},{"en":"She recognised the pattern before it became a problem.","zh":"她在它成為問題之前就認出了這個模式。"},{"en":"Recognising your own bias is the first step.","zh":"認識到自己的偏見是第一步。"},{"en":"He was recognised for years of quiet contribution.","zh":"他因多年的默默貢獻而獲得認可。"},{"en":"I recognise that I cannot do this alone.","zh":"我認識到我無法獨自完成這件事。"},{"en":"She recognises effort, not just results.","zh":"她認可努力，而不只是結果。"},{"en":"Recognising the signs early saved a lot of trouble.","zh":"及早認出跡象省了很多麻煩。"},{"en":"He recognised his mistake and corrected it fast.","zh":"他認識到他的錯誤並快速改正了。"},{"en":"I finally recognised my own worth.","zh":"我終於認識到自己的價值。"}]},{"word":"achievement","pos":"noun","chinese":"成就；成績","level":"B1","sentences":[{"en":"Her biggest achievement was rebuilding after failure.","zh":"她最大的成就是在失敗後重建。"},{"en":"He treats small achievements as worth celebrating.","zh":"他把小成就視為值得慶祝的。"},{"en":"That achievement took ten years of quiet work.","zh":"那個成就花了十年的默默努力。"},{"en":"She measures achievement by impact, not titles.","zh":"她用影響力而不是頭銜來衡量成就。"},{"en":"His greatest achievement is the people he helped grow.","zh":"他最大的成就是他幫助成長的人。"},{"en":"Achievement without fulfilment is empty.","zh":"沒有滿足感的成就是空洞的。"},{"en":"She listed her achievements and surprised herself.","zh":"她列出了她的成就，讓自己驚訝。"},{"en":"Every achievement started as something that scared him.","zh":"每個成就都是從讓他害怕的事情開始的。"},{"en":"Her quiet achievements speak louder than any award.","zh":"她安靜的成就比任何獎項都更響亮。"},{"en":"True achievement is becoming who you want to be.","zh":"真正的成就是成為你想成為的人。"}]},{"word":"benefit","pos":"noun/verb","chinese":"好處；受益","level":"B1","sentences":[{"en":"The benefit of waiting is clarity.","zh":"等待的好處是清晰。"},{"en":"She benefits from years of consistent habits.","zh":"她受益於多年的一致習慣。"},{"en":"Everyone benefits when one person grows.","zh":"當一個人成長時，每個人都受益。"},{"en":"The biggest benefit was unexpected — confidence.","zh":"最大的好處是意想不到的——自信。"},{"en":"He weighs the benefits before any decision.","zh":"他在任何決定之前權衡好處。"},{"en":"I benefited more from failing than succeeding.","zh":"我從失敗中受益比成功更多。"},{"en":"The benefits of rest are underestimated.","zh":"休息的好處被低估了。"},{"en":"She structured the deal so everyone benefits.","zh":"她安排了交易，讓每個人都受益。"},{"en":"The long-term benefit outweighs the short-term cost.","zh":"長期的好處超過了短期的成本。"},{"en":"He gave others the benefit of the doubt.","zh":"他給了別人善意的解讀。"}]},{"word":"attempt","pos":"noun/verb","chinese":"嘗試；企圖","level":"B1","sentences":[{"en":"Her first attempt failed but taught her everything.","zh":"她的第一次嘗試失敗了，但教會了她一切。"},{"en":"He attempts hard things knowing he might fail.","zh":"他嘗試困難的事情，明知可能失敗。"},{"en":"Every attempt brings you closer to success.","zh":"每次嘗試都讓你更接近成功。"},{"en":"She made an honest attempt and that is what counts.","zh":"她做了真誠的嘗試，那才是重要的。"},{"en":"My attempt was clumsy but I learned a lot.","zh":"我的嘗試很笨拙，但我學到了很多。"},{"en":"He attempted the impossible and partially succeeded.","zh":"他嘗試了不可能的事，並部分成功了。"},{"en":"The attempt itself was an act of courage.","zh":"嘗試本身就是一種勇氣的行為。"},{"en":"She attempted to explain but he was not listening.","zh":"她試圖解釋，但他沒有在聽。"},{"en":"It was a good attempt — try again with adjustments.","zh":"這是一次很好的嘗試——調整後再試一次。"},{"en":"Make the attempt; regret avoids those who try.","zh":"去嘗試吧；後悔避開那些嘗試的人。"}]},{"word":"emphasise","pos":"verb","chinese":"強調；著重","level":"B1","sentences":[{"en":"She emphasised the importance of small habits.","zh":"她強調了小習慣的重要性。"},{"en":"He emphasises progress over perfection.","zh":"他強調進步勝於完美。"},{"en":"I cannot emphasise enough how much it matters.","zh":"我怎麼強調它有多重要都不為過。"},{"en":"She emphasised kindness in everything she taught.","zh":"她在她教的所有東西中都強調善良。"},{"en":"The coach emphasised fundamentals above all.","zh":"教練最強調基本功。"},{"en":"He emphasised the why before the how.","zh":"他在如何做之前強調為什麼。"},{"en":"Emphasising effort builds resilience in children.","zh":"強調努力能在孩子身上建立韌性。"},{"en":"She emphasises listening as the key skill.","zh":"她強調傾聽是關鍵技能。"},{"en":"He emphasised that mistakes are part of learning.","zh":"他強調錯誤是學習的一部分。"},{"en":"I want to emphasise just one point.","zh":"我想只強調一點。"}]},{"word":"appreciate","pos":"verb","chinese":"欣賞；感激","level":"B1","sentences":[{"en":"I appreciate the small things more as I get older.","zh":"隨著年齡增長，我更欣賞小事物。"},{"en":"She appreciates honesty even when it is hard.","zh":"她欣賞誠實，即使很難。"},{"en":"He appreciated the gesture more than the gift.","zh":"他欣賞那個姿態勝過禮物本身。"},{"en":"Appreciate what you have before it is gone.","zh":"在你擁有的東西消失之前欣賞它。"},{"en":"I appreciate you taking the time to explain.","zh":"我感激你花時間解釋。"},{"en":"She appreciates effort, not just outcomes.","zh":"她欣賞努力，而不只是結果。"},{"en":"He learned to appreciate slowness.","zh":"他學會了欣賞緩慢。"},{"en":"Appreciating others openly strengthens bonds.","zh":"公開欣賞別人能加強連結。"},{"en":"I appreciate the chance to start again.","zh":"我感激重新開始的機會。"},{"en":"She appreciates beauty in ordinary moments.","zh":"她欣賞平凡時刻中的美。"}]},{"word":"consequence","pos":"noun","chinese":"後果；結果","level":"B1","sentences":[{"en":"Every choice has a consequence, seen or unseen.","zh":"每個選擇都有後果，看得見或看不見。"},{"en":"She accepted the consequences of her decision.","zh":"她接受了她決定的後果。"},{"en":"He thinks through consequences before acting.","zh":"他在行動之前仔細考慮後果。"},{"en":"The consequence of avoidance is bigger problems.","zh":"逃避的後果是更大的問題。"},{"en":"Actions have consequences; so does inaction.","zh":"行動有後果；不行動也有。"},{"en":"She faced the consequences without blaming anyone.","zh":"她面對後果，沒有責怪任何人。"},{"en":"The long-term consequences are worth considering.","zh":"長期後果值得考慮。"},{"en":"He weighed the consequences and chose courage.","zh":"他權衡了後果，選擇了勇氣。"},{"en":"Small daily choices have compounding consequences.","zh":"每天的小選擇有複利的後果。"},{"en":"The consequence of honesty is usually trust.","zh":"誠實的後果通常是信任。"}]},{"word":"indicate","pos":"verb","chinese":"表明；指示","level":"B1","sentences":[{"en":"The data indicates a clear upward trend.","zh":"數據表明了明顯的上升趨勢。"},{"en":"Her silence indicated she needed space.","zh":"她的沉默表明她需要空間。"},{"en":"All signs indicate this is the right path.","zh":"所有跡象都表明這是正確的道路。"},{"en":"He indicated his agreement with a nod.","zh":"他點頭表示同意。"},{"en":"The results indicate significant improvement.","zh":"結果表明顯著的改善。"},{"en":"Body language often indicates more than words.","zh":"肢體語言往往比言語表明更多。"},{"en":"The symptoms indicate it is time to rest.","zh":"這些症狀表明是時候休息了。"},{"en":"Her tone indicated she was not convinced.","zh":"她的語氣表明她不信服。"},{"en":"Early indicators suggested it would work.","zh":"早期指標顯示它會奏效。"},{"en":"The map indicates the fastest route.","zh":"地圖指示最快的路線。"}]},{"word":"reflect","pos":"verb","chinese":"反映；反思","level":"B1","sentences":[{"en":"She reflects on her day every evening.","zh":"她每晚反思她的一天。"},{"en":"His work reflects years of dedication.","zh":"他的作品反映了多年的奉獻。"},{"en":"Take time to reflect before deciding.","zh":"決定前花時間反思。"},{"en":"The lake reflected the mountains perfectly.","zh":"湖水完美地映出了群山。"},{"en":"Her actions reflect her values.","zh":"她的行動反映了她的價值觀。"},{"en":"I reflect on what went well each week.","zh":"我每週反思什麼進展順利。"},{"en":"The data reflects a clear trend.","zh":"數據反映了一個明顯的趨勢。"},{"en":"He reflected quietly before answering.","zh":"他在回答前安靜地反思。"},{"en":"Your environment reflects your mind.","zh":"你的環境反映你的內心。"},{"en":"Reflecting on failure teaches the most.","zh":"反思失敗教會最多。"}]},{"word":"reveal","pos":"verb","chinese":"揭示；透露","level":"B1","sentences":[{"en":"The results revealed an unexpected truth.","zh":"結果揭示了意想不到的真相。"},{"en":"She revealed her plan at the right moment.","zh":"她在恰當的時刻揭示了她的計畫。"},{"en":"Time reveals everything eventually.","zh":"時間最終會揭示一切。"},{"en":"His reaction revealed how he really felt.","zh":"他的反應揭示了他真正的感受。"},{"en":"The study revealed surprising patterns.","zh":"研究揭示了令人驚訝的模式。"},{"en":"She revealed a side of herself few had seen.","zh":"她展現了少有人見過的一面。"},{"en":"The data revealed the root cause.","zh":"數據揭示了根本原因。"},{"en":"He slowly revealed the full story.","zh":"他慢慢揭示了完整的故事。"},{"en":"Pressure reveals character.","zh":"壓力揭示品格。"},{"en":"The map revealed a hidden path.","zh":"地圖揭示了一條隱藏的路。"}]},{"word":"remain","pos":"verb","chinese":"保持；仍然","level":"B1","sentences":[{"en":"She remained calm under pressure.","zh":"她在壓力下保持冷靜。"},{"en":"Some questions remain unanswered.","zh":"有些問題仍然沒有答案。"},{"en":"He remained loyal through hard times.","zh":"他在艱難時期保持忠誠。"},{"en":"The core values remain the same.","zh":"核心價值觀保持不變。"},{"en":"I remain hopeful despite everything.","zh":"儘管一切，我仍然抱有希望。"},{"en":"She remained true to herself.","zh":"她忠於自己。"},{"en":"The challenge remains significant.","zh":"挑戰仍然重大。"},{"en":"He remained focused on the goal.","zh":"他保持專注於目標。"},{"en":"Much remains to be done.","zh":"還有很多要做的。"},{"en":"They remained friends for decades.","zh":"他們保持了幾十年的友誼。"}]},{"word":"obtain","pos":"verb","chinese":"獲得；取得","level":"B1","sentences":[{"en":"She obtained the information she needed.","zh":"她獲得了她需要的信息。"},{"en":"He obtained his goal through patience.","zh":"他通過耐心獲得了他的目標。"},{"en":"You can obtain it for free online.","zh":"你可以在網上免費獲得它。"},{"en":"She obtained permission before proceeding.","zh":"她在進行之前獲得了許可。"},{"en":"They obtained excellent results.","zh":"他們獲得了出色的結果。"},{"en":"He obtained the skills through practice.","zh":"他通過練習獲得了技能。"},{"en":"I obtained a copy of the report.","zh":"我獲得了一份報告的副本。"},{"en":"She obtained funding for the project.","zh":"她為項目獲得了資金。"},{"en":"Obtaining trust takes consistency.","zh":"獲得信任需要一致性。"},{"en":"He obtained the qualification last year.","zh":"他去年獲得了資格。"}]},{"word":"pursue","pos":"verb","chinese":"追求；從事","level":"B1","sentences":[{"en":"She pursues her passion relentlessly.","zh":"她不懈地追求她的熱情。"},{"en":"He pursued a different path entirely.","zh":"他追求了一條完全不同的道路。"},{"en":"Pursue what matters, not what impresses.","zh":"追求重要的，而不是令人印象深刻的。"},{"en":"She pursued the opportunity boldly.","zh":"她大膽地追求那個機會。"},{"en":"He pursued knowledge for its own sake.","zh":"他為了知識本身而追求知識。"},{"en":"Pursue excellence, not perfection.","zh":"追求卓越，而不是完美。"},{"en":"She pursued her dream against all odds.","zh":"她不顧一切地追求她的夢想。"},{"en":"He pursued the matter until it was resolved.","zh":"他追究這件事直到解決。"},{"en":"Pursuing growth keeps life interesting.","zh":"追求成長讓生活有趣。"},{"en":"She pursued a career she truly loved.","zh":"她追求了一份她真正熱愛的職業。"}]},{"word":"acquire","pos":"verb","chinese":"獲得；學到","level":"B1","sentences":[{"en":"She acquired the skill faster than expected.","zh":"她比預期更快地學到了這項技能。"},{"en":"He acquired a taste for classical music.","zh":"他培養了對古典音樂的喜好。"},{"en":"They acquired the company last year.","zh":"他們去年收購了那家公司。"},{"en":"She acquired wisdom through experience.","zh":"她通過經驗獲得了智慧。"},{"en":"He acquired fluency through immersion.","zh":"他通過沉浸獲得了流利。"},{"en":"Acquiring knowledge is a lifelong process.","zh":"獲取知識是一個終身的過程。"},{"en":"She acquired a reputation for reliability.","zh":"她贏得了可靠的聲譽。"},{"en":"He acquired new habits slowly.","zh":"他慢慢養成了新習慣。"},{"en":"They acquired valuable experience.","zh":"他們獲得了寶貴的經驗。"},{"en":"She acquired the confidence to lead.","zh":"她獲得了領導的信心。"}]},{"word":"examine","pos":"verb","chinese":"檢查；審視","level":"B1","sentences":[{"en":"She examined the problem from every angle.","zh":"她從每個角度審視這個問題。"},{"en":"He examined his own motives honestly.","zh":"他誠實地審視自己的動機。"},{"en":"Let us examine the evidence carefully.","zh":"讓我們仔細審視證據。"},{"en":"She examined the details no one else noticed.","zh":"她審視了沒有人注意到的細節。"},{"en":"He examined the data before concluding.","zh":"他在下結論之前審視了數據。"},{"en":"Examine your assumptions regularly.","zh":"定期審視你的假設。"},{"en":"She examined both sides fairly.","zh":"她公平地審視了雙方。"},{"en":"He examined the contract line by line.","zh":"他逐行審視合同。"},{"en":"Examining failure leads to growth.","zh":"審視失敗導致成長。"},{"en":"She examined her priorities and adjusted.","zh":"她審視了她的優先順序並調整了。"}]},{"word":"observe","pos":"verb","chinese":"觀察；遵守","level":"B1","sentences":[{"en":"She observes more than she speaks.","zh":"她觀察多於說話。"},{"en":"He observed the change immediately.","zh":"他立刻觀察到了變化。"},{"en":"Observe carefully before you judge.","zh":"評判之前仔細觀察。"},{"en":"She observed the tradition every year.","zh":"她每年遵守那個傳統。"},{"en":"He observed how others handled it.","zh":"他觀察別人如何處理它。"},{"en":"Observing nature calms the mind.","zh":"觀察大自然能讓心平靜。"},{"en":"She observed the patterns over time.","zh":"她隨時間觀察模式。"},{"en":"He observed a moment of silence.","zh":"他默哀了一刻。"},{"en":"Observe without immediately reacting.","zh":"觀察而不立刻反應。"},{"en":"She observed the rules without complaint.","zh":"她毫無怨言地遵守規則。"}]},{"word":"perceive","pos":"verb","chinese":"察覺；理解","level":"B1","sentences":[{"en":"How we perceive things shapes our reality.","zh":"我們如何感知事物塑造我們的現實。"},{"en":"She perceived the tension in the room.","zh":"她察覺到了房間裡的緊張。"},{"en":"He perceived an opportunity others missed.","zh":"他察覺到了別人錯過的機會。"},{"en":"We perceive the world through our experiences.","zh":"我們透過經驗感知世界。"},{"en":"She perceived his kindness immediately.","zh":"她立刻察覺到了他的善意。"},{"en":"Perceiving subtle cues is a skill.","zh":"察覺微妙的線索是一種技能。"},{"en":"He perceived the risk before it grew.","zh":"他在風險增大之前察覺到了它。"},{"en":"She perceived more than she let on.","zh":"她察覺到的比她表現出來的更多。"},{"en":"How you perceive failure matters most.","zh":"你如何感知失敗最重要。"},{"en":"He perceived the truth behind her words.","zh":"他察覺到了她話語背後的真相。"}]},{"word":"determine","pos":"verb","chinese":"決定；確定","level":"B1","sentences":[{"en":"She determined to finish what she started.","zh":"她決心完成她開始的事情。"},{"en":"The cause was hard to determine.","zh":"原因很難確定。"},{"en":"He determined his own path forward.","zh":"他決定了自己前進的道路。"},{"en":"Your effort determines your results.","zh":"你的努力決定你的結果。"},{"en":"She determined the priorities clearly.","zh":"她清楚地確定了優先順序。"},{"en":"Let the data determine the decision.","zh":"讓數據決定決定。"},{"en":"He was determined to make it work.","zh":"他決心讓它奏效。"},{"en":"She determined what truly mattered.","zh":"她確定了什麼真正重要。"},{"en":"Determine your values before your goals.","zh":"在目標之前確定你的價值觀。"},{"en":"He determined to change his habits.","zh":"他決心改變他的習慣。"}]},{"word":"conclude","pos":"verb","chinese":"總結；斷定","level":"B1","sentences":[{"en":"She concluded the meeting on a positive note.","zh":"她以積極的語氣結束了會議。"},{"en":"He concluded that change was necessary.","zh":"他斷定改變是必要的。"},{"en":"Let us conclude with the main point.","zh":"讓我們以要點結束。"},{"en":"She concluded her speech with gratitude.","zh":"她以感恩結束她的演講。"},{"en":"He concluded the deal successfully.","zh":"他成功地完成了交易。"},{"en":"The study concluded with clear findings.","zh":"研究以明確的發現結束。"},{"en":"She concluded it was worth the risk.","zh":"她斷定值得冒這個險。"},{"en":"He concluded the project ahead of time.","zh":"他提前完成了項目。"},{"en":"Concluding too early leads to mistakes.","zh":"過早斷定會導致錯誤。"},{"en":"She concluded that honesty was best.","zh":"她斷定誠實是最好的。"}]},{"word":"evaluate","pos":"verb","chinese":"評估","level":"B1","sentences":[{"en":"She evaluates options before committing.","zh":"她在承諾之前評估選項。"},{"en":"He evaluated the risk honestly.","zh":"他誠實地評估了風險。"},{"en":"Evaluate progress, not just outcomes.","zh":"評估進步，而不只是結果。"},{"en":"She evaluated each candidate fairly.","zh":"她公平地評估每位候選人。"},{"en":"He evaluated his own performance critically.","zh":"他批判性地評估自己的表現。"},{"en":"Evaluating regularly prevents big mistakes.","zh":"定期評估能防止大錯誤。"},{"en":"She evaluated the situation calmly.","zh":"她冷靜地評估情況。"},{"en":"He evaluated the costs and benefits.","zh":"他評估了成本和收益。"},{"en":"Evaluate what is working and do more.","zh":"評估什麼有效，並多做。"},{"en":"She evaluated the plan before approving.","zh":"她在批准前評估了計畫。"}]},{"word":"interpret","pos":"verb","chinese":"解釋；詮釋","level":"B1","sentences":[{"en":"She interprets the data thoughtfully.","zh":"她深思熟慮地解釋數據。"},{"en":"He interpreted her silence as agreement.","zh":"他把她的沉默解釋為同意。"},{"en":"We each interpret events differently.","zh":"我們各自以不同的方式解釋事件。"},{"en":"She interpreted the dream symbolically.","zh":"她象徵性地解釋了那個夢。"},{"en":"He interpreted the rules generously.","zh":"他寬鬆地解釋規則。"},{"en":"Interpreting context correctly is key.","zh":"正確解釋語境是關鍵。"},{"en":"She interpreted the poem beautifully.","zh":"她美麗地詮釋了那首詩。"},{"en":"He interpreted the signs accurately.","zh":"他準確地解釋了跡象。"},{"en":"How you interpret it changes everything.","zh":"你如何解釋它改變一切。"},{"en":"She interpreted between the two languages.","zh":"她在兩種語言之間翻譯。"}]},{"word":"illustrate","pos":"verb","chinese":"說明；舉例","level":"B1","sentences":[{"en":"She illustrated her point with a story.","zh":"她用一個故事說明她的觀點。"},{"en":"This example illustrates the concept well.","zh":"這個例子很好地說明了這個概念。"},{"en":"He illustrated the idea with a diagram.","zh":"他用圖表說明了這個想法。"},{"en":"Her life illustrates the power of persistence.","zh":"她的生活說明了堅持的力量。"},{"en":"Let me illustrate with a simple analogy.","zh":"讓我用一個簡單的比喻來說明。"},{"en":"The data illustrates the trend clearly.","zh":"數據清楚地說明了趨勢。"},{"en":"He illustrated the process step by step.","zh":"他一步一步地說明了過程。"},{"en":"She illustrated children's books for years.","zh":"她為兒童書籍畫插圖多年。"},{"en":"This case illustrates why it matters.","zh":"這個案例說明了為什麼它重要。"},{"en":"He illustrated his argument with evidence.","zh":"他用證據說明他的論點。"}]},{"word":"highlight","pos":"verb","chinese":"強調；突出","level":"B1","sentences":[{"en":"She highlighted the most important point.","zh":"她強調了最重要的觀點。"},{"en":"The report highlights key findings.","zh":"報告突出了關鍵發現。"},{"en":"He highlighted the risks clearly.","zh":"他清楚地強調了風險。"},{"en":"Let me highlight what changed.","zh":"讓我強調一下什麼改變了。"},{"en":"The trip highlighted how much she had grown.","zh":"這次旅行突顯了她成長了多少。"},{"en":"She highlights progress to stay motivated.","zh":"她強調進步以保持動力。"},{"en":"The data highlights an urgent need.","zh":"數據突顯了一個緊迫的需求。"},{"en":"He highlighted the team's achievements.","zh":"他強調了團隊的成就。"},{"en":"This highlights the importance of rest.","zh":"這突顯了休息的重要性。"},{"en":"She highlighted the lessons learned.","zh":"她強調了學到的教訓。"}]},{"word":"convince","pos":"verb","chinese":"說服；使信服","level":"B1","sentences":[{"en":"She convinced me to take the chance.","zh":"她說服我抓住機會。"},{"en":"He convinced himself it would work.","zh":"他說服自己它會奏效。"},{"en":"The evidence convinced everyone.","zh":"證據說服了每個人。"},{"en":"She convinced them with calm logic.","zh":"她用冷靜的邏輯說服了他們。"},{"en":"He was convinced he could do better.","zh":"他確信他能做得更好。"},{"en":"Convincing yourself is the hardest part.","zh":"說服自己是最難的部分。"},{"en":"She convinced the team to try a new way.","zh":"她說服團隊嘗試新方法。"},{"en":"He convinced her gently, not forcefully.","zh":"他溫和地而不是強硬地說服她。"},{"en":"The results convinced the sceptics.","zh":"結果說服了懷疑者。"},{"en":"She convinced him by showing, not telling.","zh":"她通過展示而不是說教來說服他。"}]},{"word":"persuade","pos":"verb","chinese":"勸說；說服","level":"B1","sentences":[{"en":"She persuaded him to rest and recover.","zh":"她勸他休息和恢復。"},{"en":"He persuaded the group to reconsider.","zh":"他勸說小組重新考慮。"},{"en":"Persuading requires understanding first.","zh":"說服首先需要理解。"},{"en":"She persuaded them with genuine care.","zh":"她以真誠的關心說服了他們。"},{"en":"He persuaded her to apply for the role.","zh":"他勸她申請那個職位。"},{"en":"Good persuasion respects the other person.","zh":"好的說服尊重對方。"},{"en":"She persuaded them through patience.","zh":"她通過耐心說服了他們。"},{"en":"He persuaded the board to invest.","zh":"他說服董事會投資。"},{"en":"Persuade with facts and empathy.","zh":"用事實和同理心說服。"},{"en":"She persuaded herself to be brave.","zh":"她說服自己要勇敢。"}]},{"word":"inspire","pos":"verb","chinese":"激勵；啟發","level":"B1","sentences":[{"en":"She inspires everyone she works with.","zh":"她激勵她共事的每個人。"},{"en":"His story inspired me to start.","zh":"他的故事激勵我開始。"},{"en":"Inspire by example, not by lecture.","zh":"以身作則來激勵，而不是說教。"},{"en":"She inspires through quiet consistency.","zh":"她通過安靜的一致性激勵人。"},{"en":"He inspired a whole generation.","zh":"他激勵了整整一代人。"},{"en":"Inspiring others starts with being inspired.","zh":"激勵別人始於被激勵。"},{"en":"Her courage inspired the team.","zh":"她的勇氣激勵了團隊。"},{"en":"He inspires confidence in those around him.","zh":"他激勵周圍的人產生信心。"},{"en":"She inspired me to keep going.","zh":"她激勵我繼續前進。"},{"en":"Inspire people and they exceed expectations.","zh":"激勵人們，他們會超出期望。"}]},{"word":"motivate","pos":"verb","chinese":"激勵；驅動","level":"B1","sentences":[{"en":"She motivates herself with small wins.","zh":"她用小勝利激勵自己。"},{"en":"What motivates you on hard days?","zh":"在艱難的日子裡是什麼激勵你？"},{"en":"He motivates his team through trust.","zh":"他通過信任激勵他的團隊。"},{"en":"Purpose motivates more than pressure.","zh":"目標比壓力更能激勵人。"},{"en":"She stays motivated by remembering why.","zh":"她通過記住原因來保持動力。"},{"en":"He motivated me when I felt stuck.","zh":"當我感到卡住時，他激勵了我。"},{"en":"Intrinsic motivation lasts the longest.","zh":"內在動機持續最久。"},{"en":"She motivates through encouragement.","zh":"她通過鼓勵來激勵。"},{"en":"Fear motivates briefly; meaning motivates lastingly.","zh":"恐懼短暫地激勵；意義持久地激勵。"},{"en":"He motivated the group toward the goal.","zh":"他激勵小組朝目標前進。"}]},{"word":"hesitate","pos":"verb","chinese":"猶豫；遲疑","level":"B1","sentences":[{"en":"She hesitated, then took the leap.","zh":"她猶豫了一下，然後邁出了一步。"},{"en":"Do not hesitate to ask for help.","zh":"不要猶豫尋求幫助。"},{"en":"He hesitated at the door for a moment.","zh":"他在門口猶豫了一會兒。"},{"en":"She never hesitates to speak the truth.","zh":"她從不猶豫說真話。"},{"en":"I hesitated and missed the chance.","zh":"我猶豫了，錯過了機會。"},{"en":"He hesitated before making the call.","zh":"他在打電話前猶豫了。"},{"en":"She hesitated, unsure of the answer.","zh":"她猶豫了，不確定答案。"},{"en":"Don't hesitate when you know it's right.","zh":"當你知道它對的時候不要猶豫。"},{"en":"He hesitated, then decided to trust her.","zh":"他猶豫了一下，然後決定相信她。"},{"en":"She acted without hesitating.","zh":"她毫不猶豫地行動了。"}]},{"word":"anticipate","pos":"verb","chinese":"預期；期待","level":"B1","sentences":[{"en":"She anticipates problems before they happen.","zh":"她在問題發生之前預見它們。"},{"en":"He anticipated the question and prepared.","zh":"他預見了問題並做了準備。"},{"en":"I anticipate a busy week ahead.","zh":"我預期未來一週很忙。"},{"en":"She anticipated his needs without asking.","zh":"她不問就預見了他的需求。"},{"en":"Anticipating change keeps you ready.","zh":"預見變化讓你保持準備。"},{"en":"He anticipated the outcome correctly.","zh":"他正確地預見了結果。"},{"en":"She anticipates the next step intuitively.","zh":"她直覺地預見下一步。"},{"en":"I eagerly anticipate the trip.","zh":"我熱切地期待這次旅行。"},{"en":"He anticipated the challenge calmly.","zh":"他冷靜地預見了挑戰。"},{"en":"She anticipated the reaction and stayed calm.","zh":"她預見了反應並保持冷靜。"}]},{"word":"recall","pos":"verb","chinese":"回想；召回","level":"B1","sentences":[{"en":"I cannot recall where I put it.","zh":"我想不起我把它放在哪裡了。"},{"en":"She recalled the moment vividly.","zh":"她生動地回憶起那一刻。"},{"en":"He recalled every detail of the day.","zh":"他回憶起那天的每一個細節。"},{"en":"I recall reading about this somewhere.","zh":"我記得在某處讀過這個。"},{"en":"She recalled the advice at the right time.","zh":"她在恰當的時刻回憶起那個建議。"},{"en":"Recalling good memories lifts the mood.","zh":"回憶美好的記憶能提升情緒。"},{"en":"He recalled her name just in time.","zh":"他及時想起了她的名字。"},{"en":"I recall it differently than you do.","zh":"我對它的記憶和你不同。"},{"en":"She recalled the lesson her mother taught.","zh":"她回憶起母親教的功課。"},{"en":"He could not recall the exact words.","zh":"他想不起確切的話。"}]},{"word":"relate","pos":"verb","chinese":"聯繫；相關","level":"B1","sentences":[{"en":"She relates well to people of all ages.","zh":"她與各個年齡的人都相處得很好。"},{"en":"I cannot relate to that experience.","zh":"我無法理解那種經歷。"},{"en":"He relates everything back to his values.","zh":"他把一切都聯繫回他的價值觀。"},{"en":"She relates to others through empathy.","zh":"她通過同理心與別人聯繫。"},{"en":"How do these ideas relate?","zh":"這些想法如何相關？"},{"en":"I relate to her struggle deeply.","zh":"我深深地理解她的掙扎。"},{"en":"He related the story with warmth.","zh":"他溫暖地講述了那個故事。"},{"en":"She relates her work to a bigger purpose.","zh":"她把她的工作聯繫到一個更大的目的。"},{"en":"The two events are closely related.","zh":"這兩個事件密切相關。"},{"en":"I relate best to honest people.","zh":"我和誠實的人最合得來。"}]},{"word":"represent","pos":"verb","chinese":"代表；表示","level":"B1","sentences":[{"en":"She represents the team with pride.","zh":"她自豪地代表團隊。"},{"en":"This symbol represents hope.","zh":"這個符號代表希望。"},{"en":"He represents everything I admire.","zh":"他代表了我欽佩的一切。"},{"en":"These numbers represent real people.","zh":"這些數字代表真實的人。"},{"en":"She represented her country at the games.","zh":"她在比賽中代表她的國家。"},{"en":"The colour represents energy and warmth.","zh":"這個顏色代表能量和溫暖。"},{"en":"He represents a new way of thinking.","zh":"他代表一種新的思維方式。"},{"en":"This moment represents a turning point.","zh":"這一刻代表一個轉折點。"},{"en":"She represents her values consistently.","zh":"她始終如一地代表她的價值觀。"},{"en":"The logo represents the whole brand.","zh":"這個標誌代表整個品牌。"}]},{"word":"transform","pos":"verb","chinese":"轉變；改造","level":"B1","sentences":[{"en":"She transformed her life in two years.","zh":"她在兩年內改變了她的生活。"},{"en":"Reading transformed how he thinks.","zh":"閱讀改變了他的思維方式。"},{"en":"The space was transformed completely.","zh":"這個空間被完全改造了。"},{"en":"She transformed a setback into a comeback.","zh":"她把挫折轉化為反擊。"},{"en":"Small habits transform over time.","zh":"小習慣隨時間轉變。"},{"en":"He transformed the team's culture.","zh":"他改變了團隊的文化。"},{"en":"Travel transformed her perspective.","zh":"旅行改變了她的視角。"},{"en":"She transformed fear into fuel.","zh":"她把恐懼轉化為燃料。"},{"en":"The experience transformed him deeply.","zh":"這段經歷深刻地改變了他。"},{"en":"Transforming requires letting go of the old.","zh":"轉變需要放下舊的。"}]},{"word":"emerge","pos":"verb","chinese":"出現；浮現","level":"B1","sentences":[{"en":"She emerged stronger after the hardship.","zh":"她在艱難之後變得更強大。"},{"en":"A clear pattern emerged from the data.","zh":"一個清晰的模式從數據中浮現。"},{"en":"He emerged as a natural leader.","zh":"他成為了一個天生的領導者。"},{"en":"New opportunities emerged unexpectedly.","zh":"新的機會意外地出現了。"},{"en":"She emerged from the crisis with clarity.","zh":"她從危機中走出來，帶著清晰。"},{"en":"A solution emerged after much thought.","zh":"經過深思熟慮，一個解決方案浮現了。"},{"en":"He emerged from his shell slowly.","zh":"他慢慢地走出了他的殼。"},{"en":"Truth emerges with time.","zh":"真相隨時間浮現。"},{"en":"She emerged as the obvious choice.","zh":"她成為了顯而易見的選擇。"},{"en":"New ideas emerge when you rest.","zh":"當你休息時，新想法浮現。"}]},{"word":"decline","pos":"verb","chinese":"下降；婉拒","level":"B1","sentences":[{"en":"She politely declined the invitation.","zh":"她禮貌地婉拒了邀請。"},{"en":"His health declined gradually.","zh":"他的健康逐漸下降。"},{"en":"He declined to comment further.","zh":"他拒絕進一步評論。"},{"en":"Sales declined over the quarter.","zh":"銷售額在這個季度下降了。"},{"en":"She declined the offer without regret.","zh":"她毫無遺憾地婉拒了提議。"},{"en":"Their interest declined over time.","zh":"他們的興趣隨時間下降。"},{"en":"He declined the promotion for family.","zh":"他為了家庭婉拒了升職。"},{"en":"The quality declined when they rushed.","zh":"當他們匆忙時，品質下降了。"},{"en":"She declined gracefully and explained why.","zh":"她優雅地婉拒並解釋了原因。"},{"en":"His energy declined without proper rest.","zh":"沒有適當的休息，他的能量下降了。"}]},{"word":"expand","pos":"verb","chinese":"擴展；擴大","level":"B1","sentences":[{"en":"She expanded her business steadily.","zh":"她穩步擴展她的生意。"},{"en":"Reading expands your worldview.","zh":"閱讀擴展你的世界觀。"},{"en":"He expanded the idea into a full plan.","zh":"他把這個想法擴展成一個完整的計畫。"},{"en":"The company expanded internationally.","zh":"公司向國際擴展。"},{"en":"Travel expands your sense of possibility.","zh":"旅行擴展你對可能性的感覺。"},{"en":"She expanded her skills every year.","zh":"她每年擴展她的技能。"},{"en":"They expanded the team carefully.","zh":"他們謹慎地擴大了團隊。"},{"en":"His mind expanded through new experiences.","zh":"他的思維通過新經歷擴展。"},{"en":"She expanded on the point with examples.","zh":"她用例子擴展了這個觀點。"},{"en":"Expanding too fast carries risk.","zh":"擴展太快有風險。"}]},{"word":"genuine","pos":"adjective","chinese":"真誠的；真正的","level":"B1","sentences":[{"en":"Her warmth is completely genuine.","zh":"她的溫暖是完全真誠的。"},{"en":"He gave a genuine apology.","zh":"他給了一個真誠的道歉。"},{"en":"Genuine connection cannot be faked.","zh":"真正的連結無法偽裝。"},{"en":"She has a genuine interest in people.","zh":"她對人有真正的興趣。"},{"en":"His genuine curiosity is refreshing.","zh":"他真誠的好奇心令人耳目一新。"},{"en":"A genuine compliment lands differently.","zh":"真誠的讚美感覺不同。"},{"en":"She is genuine in everything she does.","zh":"她在她做的每件事中都很真誠。"},{"en":"He showed genuine concern for her.","zh":"他對她表現出真誠的關心。"},{"en":"Genuine effort is always visible.","zh":"真誠的努力總是顯而易見的。"},{"en":"Her genuine smile put everyone at ease.","zh":"她真誠的微笑讓每個人都放鬆。"}]},{"word":"essential","pos":"adjective","chinese":"必要的；本質的","level":"B1","sentences":[{"en":"Sleep is essential, not optional.","zh":"睡眠是必要的，而不是可選的。"},{"en":"She focuses on the essential few.","zh":"她專注於必要的少數。"},{"en":"Trust is essential in any relationship.","zh":"信任在任何關係中都是必要的。"},{"en":"He stripped it down to the essentials.","zh":"他把它精簡到必要的部分。"},{"en":"Rest is an essential part of growth.","zh":"休息是成長的必要部分。"},{"en":"Clear communication is essential.","zh":"清晰的溝通是必要的。"},{"en":"She identified the essential tasks first.","zh":"她首先識別了必要的任務。"},{"en":"Water is essential for the body.","zh":"水對身體是必要的。"},{"en":"The essential question is simple.","zh":"本質的問題很簡單。"},{"en":"He keeps only what is essential.","zh":"他只保留必要的東西。"}]},{"word":"relevant","pos":"adjective","chinese":"相關的；切題的","level":"B1","sentences":[{"en":"She shared only the relevant details.","zh":"她只分享了相關的細節。"},{"en":"Is this still relevant to the goal?","zh":"這對目標仍然相關嗎？"},{"en":"He kept the discussion relevant.","zh":"他讓討論保持切題。"},{"en":"Relevant experience matters more than years.","zh":"相關經驗比年數更重要。"},{"en":"She made the lesson relevant to their lives.","zh":"她讓課程與他們的生活相關。"},{"en":"Stay relevant by always learning.","zh":"通過不斷學習保持相關。"},{"en":"The advice was surprisingly relevant.","zh":"那個建議出奇地相關。"},{"en":"He filtered out everything not relevant.","zh":"他過濾掉所有不相關的東西。"},{"en":"Relevant skills open the most doors.","zh":"相關技能打開最多的門。"},{"en":"She asked a relevant and sharp question.","zh":"她問了一個相關而尖銳的問題。"}]},{"word":"appropriate","pos":"adjective","chinese":"適當的；合適的","level":"B1","sentences":[{"en":"She chose an appropriate response.","zh":"她選擇了一個適當的回應。"},{"en":"Wear something appropriate for the event.","zh":"穿適合活動的衣服。"},{"en":"He found the appropriate moment to speak.","zh":"他找到了適當的時刻說話。"},{"en":"An appropriate boundary protects everyone.","zh":"適當的界限保護每個人。"},{"en":"She gave an appropriate amount of detail.","zh":"她給出了適當數量的細節。"},{"en":"It is appropriate to thank them.","zh":"感謝他們是適當的。"},{"en":"He responded in an appropriate tone.","zh":"他以適當的語氣回應。"},{"en":"Choose the appropriate tool for the task.","zh":"為任務選擇適當的工具。"},{"en":"She kept her feedback appropriate and kind.","zh":"她讓她的反饋適當而善意。"},{"en":"The timing was entirely appropriate.","zh":"時機完全適當。"}]},{"word":"obvious","pos":"adjective","chinese":"明顯的；顯而易見的","level":"B1","sentences":[{"en":"The solution was obvious in hindsight.","zh":"解決方案事後看來是顯而易見的。"},{"en":"She made the obvious choice confidently.","zh":"她自信地做出了顯而易見的選擇。"},{"en":"It was obvious he cared deeply.","zh":"很明顯他非常在乎。"},{"en":"The answer is not always obvious.","zh":"答案並不總是顯而易見的。"},{"en":"He stated the obvious to confirm.","zh":"他陳述了顯而易見的事情以確認。"},{"en":"Her talent was obvious to everyone.","zh":"她的才華對每個人都顯而易見。"},{"en":"Sometimes the obvious path is right.","zh":"有時顯而易見的道路是對的。"},{"en":"It became obvious over time.","zh":"隨時間它變得明顯。"},{"en":"The obvious answer is rarely complete.","zh":"顯而易見的答案很少完整。"},{"en":"She noticed what was not obvious.","zh":"她注意到了不明顯的東西。"}]},{"word":"complex","pos":"adjective","chinese":"複雜的","level":"B1","sentences":[{"en":"The situation was more complex than it seemed.","zh":"情況比看起來更複雜。"},{"en":"She simplifies complex ideas beautifully.","zh":"她美麗地簡化複雜的想法。"},{"en":"Human emotions are deeply complex.","zh":"人類的情感極其複雜。"},{"en":"He handled the complex problem calmly.","zh":"他冷靜地處理了複雜的問題。"},{"en":"Complex does not mean impossible.","zh":"複雜不意味著不可能。"},{"en":"She broke the complex task into steps.","zh":"她把複雜的任務分解成步驟。"},{"en":"The truth is often complex.","zh":"真相往往是複雜的。"},{"en":"He thrives on complex challenges.","zh":"他在複雜的挑戰中茁壯成長。"},{"en":"A complex system needs simple rules.","zh":"複雜的系統需要簡單的規則。"},{"en":"She navigated the complex situation well.","zh":"她很好地駕馭了複雜的情況。"}]},{"word":"flexible","pos":"adjective","chinese":"靈活的；有彈性的","level":"B1","sentences":[{"en":"She stays flexible when plans change.","zh":"當計畫改變時，她保持靈活。"},{"en":"A flexible mind adapts faster.","zh":"靈活的頭腦適應得更快。"},{"en":"He keeps his schedule flexible.","zh":"他保持他的時間表靈活。"},{"en":"Being flexible is a strength, not weakness.","zh":"靈活是一種力量，而不是軟弱。"},{"en":"She offered a flexible solution.","zh":"她提供了一個靈活的解決方案。"},{"en":"Flexible thinking solves more problems.","zh":"靈活的思維解決更多問題。"},{"en":"He remained flexible under pressure.","zh":"他在壓力下保持靈活。"},{"en":"A flexible approach works best here.","zh":"靈活的方法在這裡最有效。"},{"en":"She balances structure with flexibility.","zh":"她平衡結構與靈活性。"},{"en":"Stay flexible but keep your core values.","zh":"保持靈活，但保持你的核心價值觀。"}]},{"word":"reliable","pos":"adjective","chinese":"可靠的","level":"B1","sentences":[{"en":"She is the most reliable person I know.","zh":"她是我認識的最可靠的人。"},{"en":"He built a reputation for being reliable.","zh":"他建立了可靠的聲譽。"},{"en":"Reliable habits create reliable results.","zh":"可靠的習慣創造可靠的結果。"},{"en":"She delivers reliable work every time.","zh":"她每次都交付可靠的工作。"},{"en":"A reliable friend shows up consistently.","zh":"可靠的朋友持續地出現。"},{"en":"He is reliable when it matters most.","zh":"在最重要的時候他是可靠的。"},{"en":"Reliable systems reduce daily stress.","zh":"可靠的系統減少日常壓力。"},{"en":"She is calm, kind and reliable.","zh":"她冷靜、善良且可靠。"},{"en":"Being reliable builds deep trust.","zh":"可靠建立深厚的信任。"},{"en":"He proved reliable through hard times.","zh":"他在艱難時期證明了可靠。"}]},{"word":"consistent","pos":"adjective","chinese":"一致的；穩定的","level":"B1","sentences":[{"en":"She is remarkably consistent in her habits.","zh":"她的習慣非常一致。"},{"en":"Consistent effort beats occasional bursts.","zh":"一致的努力勝過偶爾的爆發。"},{"en":"He stays consistent regardless of mood.","zh":"無論情緒如何，他都保持一致。"},{"en":"Consistency is the secret most people miss.","zh":"一致性是大多數人錯過的秘訣。"},{"en":"She delivers consistent quality.","zh":"她交付一致的品質。"},{"en":"Being consistent builds momentum.","zh":"保持一致建立動力。"},{"en":"His values stay consistent over time.","zh":"他的價值觀隨時間保持一致。"},{"en":"Consistent small steps lead far.","zh":"一致的小步驟能走很遠。"},{"en":"She is consistent in word and action.","zh":"她言行一致。"},{"en":"Consistency turns goals into reality.","zh":"一致性把目標變成現實。"}]},{"word":"efficient","pos":"adjective","chinese":"高效的","level":"B1","sentences":[{"en":"She works efficiently without rushing.","zh":"她高效地工作，不匆忙。"},{"en":"An efficient system saves hours weekly.","zh":"高效的系統每週節省幾個小時。"},{"en":"He found a more efficient way to do it.","zh":"他找到了一個更高效的方法來做它。"},{"en":"Efficient does not mean rushed.","zh":"高效不意味著匆忙。"},{"en":"She streamlined the process to be efficient.","zh":"她簡化了流程使其高效。"},{"en":"Being efficient frees time for what matters.","zh":"高效為重要的事情騰出時間。"},{"en":"He is efficient with both time and energy.","zh":"他在時間和能量上都很高效。"},{"en":"Efficient habits compound over years.","zh":"高效的習慣多年複利增長。"},{"en":"She made the meeting efficient and short.","zh":"她讓會議高效而簡短。"},{"en":"Efficient work leaves room for rest.","zh":"高效的工作為休息留出空間。"}]},{"word":"sufficient","pos":"adjective","chinese":"足夠的；充足的","level":"B1","sentences":[{"en":"She had sufficient time to prepare.","zh":"她有足夠的時間準備。"},{"en":"Is this sufficient for your needs?","zh":"這對你的需求足夠嗎？"},{"en":"He gathered sufficient evidence first.","zh":"他首先收集了足夠的證據。"},{"en":"Sufficient sleep changes everything.","zh":"足夠的睡眠改變一切。"},{"en":"She saved a sufficient amount each month.","zh":"她每個月存了足夠的金額。"},{"en":"Good enough is sometimes sufficient.","zh":"足夠好有時就足夠了。"},{"en":"He had sufficient reason to be confident.","zh":"他有足夠的理由自信。"},{"en":"Sufficient rest prevents burnout.","zh":"足夠的休息防止倦怠。"},{"en":"She allowed sufficient room for error.","zh":"她為錯誤留出了足夠的空間。"},{"en":"Sufficient preparation reduces anxiety.","zh":"足夠的準備減少焦慮。"}]},{"word":"crucial","pos":"adjective","chinese":"關鍵的；至關重要的","level":"B1","sentences":[{"en":"The first step is absolutely crucial.","zh":"第一步絕對至關重要。"},{"en":"Trust is crucial in any team.","zh":"信任在任何團隊中都至關重要。"},{"en":"She made a crucial decision calmly.","zh":"她冷靜地做出了一個關鍵決定。"},{"en":"Timing is crucial in this situation.","zh":"在這種情況下時機至關重要。"},{"en":"He played a crucial role in the project.","zh":"他在項目中扮演了關鍵角色。"},{"en":"Rest is crucial for sustained performance.","zh":"休息對持續的表現至關重要。"},{"en":"This crucial detail is easy to miss.","zh":"這個關鍵細節容易被錯過。"},{"en":"Her support was crucial to my success.","zh":"她的支持對我的成功至關重要。"},{"en":"A crucial moment defined his career.","zh":"一個關鍵時刻定義了他的職業生涯。"},{"en":"Listening is crucial before advising.","zh":"在建議之前傾聽至關重要。"}]},{"word":"specific","pos":"adjective","chinese":"具體的；特定的","level":"B1","sentences":[{"en":"She gave specific, actionable feedback.","zh":"她給了具體、可行的反饋。"},{"en":"Be specific about what you need.","zh":"明確說明你需要什麼。"},{"en":"He set specific, measurable goals.","zh":"他設定了具體、可衡量的目標。"},{"en":"Specific praise means more than general praise.","zh":"具體的讚美比籠統的讚美更有意義。"},{"en":"She asked a specific question.","zh":"她問了一個具體的問題。"},{"en":"Specific goals are easier to achieve.","zh":"具體的目標更容易實現。"},{"en":"He focused on one specific skill.","zh":"他專注於一個具體的技能。"},{"en":"Being specific removes confusion.","zh":"具體能消除混亂。"},{"en":"She had a specific vision in mind.","zh":"她心中有一個具體的願景。"},{"en":"Specific action beats vague intention.","zh":"具體的行動勝過模糊的意圖。"}]},{"word":"accurate","pos":"adjective","chinese":"準確的","level":"B1","sentences":[{"en":"Her assessment was completely accurate.","zh":"她的評估完全準確。"},{"en":"He keeps accurate records of everything.","zh":"他保持所有事情的準確記錄。"},{"en":"Accurate information leads to good decisions.","zh":"準確的信息導致好的決定。"},{"en":"She gave an accurate account of events.","zh":"她準確地描述了事件。"},{"en":"Being accurate matters more than being fast.","zh":"準確比快速更重要。"},{"en":"His memory is surprisingly accurate.","zh":"他的記憶出奇地準確。"},{"en":"She made an accurate prediction.","zh":"她做出了一個準確的預測。"},{"en":"Accurate self-knowledge is rare.","zh":"準確的自我認識是罕見的。"},{"en":"He aims for accurate, not impressive.","zh":"他追求準確，而不是令人印象深刻。"},{"en":"An accurate map saves a lot of time.","zh":"準確的地圖省很多時間。"}]},{"word":"aware","pos":"adjective","chinese":"意識到的；知道的","level":"B1","sentences":[{"en":"She is deeply aware of her impact.","zh":"她深刻地意識到她的影響。"},{"en":"Being aware is the first step to change.","zh":"意識到是改變的第一步。"},{"en":"He became aware of the pattern.","zh":"他意識到了這個模式。"},{"en":"She stays aware of her own biases.","zh":"她保持對自己偏見的意識。"},{"en":"Self-aware people grow faster.","zh":"有自我意識的人成長得更快。"},{"en":"He is aware of what he does not know.","zh":"他意識到他不知道什麼。"},{"en":"She is aware of her surroundings always.","zh":"她總是意識到她的周圍環境。"},{"en":"Becoming aware changed his behaviour.","zh":"意識到改變了他的行為。"},{"en":"She is keenly aware of others' feelings.","zh":"她敏銳地意識到別人的感受。"},{"en":"Awareness without action changes nothing.","zh":"沒有行動的意識什麼都不改變。"}]},{"word":"capable","pos":"adjective","chinese":"有能力的","level":"B1","sentences":[{"en":"She is far more capable than she realises.","zh":"她比她意識到的更有能力。"},{"en":"He proved capable under real pressure.","zh":"他在真正的壓力下證明了有能力。"},{"en":"You are capable of more than you think.","zh":"你比你認為的更有能力。"},{"en":"She felt capable after months of practice.","zh":"幾個月的練習後她感到有能力。"},{"en":"A capable team handles anything.","zh":"有能力的團隊能處理任何事。"},{"en":"He is quietly capable, never boastful.","zh":"他默默地有能力，從不自誇。"},{"en":"She is capable of deep focus.","zh":"她能夠深度專注。"},{"en":"Believing you are capable is half the battle.","zh":"相信你有能力是成功的一半。"},{"en":"He is capable and humble at once.","zh":"他同時有能力和謙遜。"},{"en":"She became capable through doing hard things.","zh":"她通過做困難的事情變得有能力。"}]},{"word":"confident","pos":"adjective","chinese":"自信的","level":"B1","sentences":[{"en":"She walks into rooms confident and calm.","zh":"她自信而冷靜地走進房間。"},{"en":"Confidence comes from preparation.","zh":"自信來自準備。"},{"en":"He grew confident through small wins.","zh":"他通過小勝利變得自信。"},{"en":"Being confident is not being arrogant.","zh":"自信不是傲慢。"},{"en":"She speaks with quiet confidence.","zh":"她以安靜的自信說話。"},{"en":"Confident people lift others up.","zh":"自信的人提升別人。"},{"en":"He felt confident in his decision.","zh":"他對他的決定感到自信。"},{"en":"Confidence is built, not born.","zh":"自信是建立的，不是天生的。"},{"en":"She stayed confident despite setbacks.","zh":"儘管挫折，她保持自信。"},{"en":"True confidence is quiet and steady.","zh":"真正的自信是安靜而穩定的。"}]},{"word":"curious","pos":"adjective","chinese":"好奇的","level":"B1","sentences":[{"en":"She stays endlessly curious about the world.","zh":"她對世界保持無盡的好奇。"},{"en":"Curious people never stop learning.","zh":"好奇的人從不停止學習。"},{"en":"He approached the problem with curiosity.","zh":"他帶著好奇心處理問題。"},{"en":"Stay curious and life stays interesting.","zh":"保持好奇，生活就保持有趣。"},{"en":"She is curious without being intrusive.","zh":"她好奇但不冒犯。"},{"en":"Curiosity led him to a new passion.","zh":"好奇心引領他找到新的熱情。"},{"en":"Being curious beats being right.","zh":"保持好奇勝過爭對錯。"},{"en":"She asks curious, open questions.","zh":"她問好奇、開放的問題。"},{"en":"Curiosity keeps the mind young.","zh":"好奇心讓頭腦年輕。"},{"en":"He remained curious about everything.","zh":"他對一切保持好奇。"}]},{"word":"listen","pos":"verb","chinese":"聆聽；聽","level":"A1","sentences":[{"en":"I listen to music while I work.","zh":"我工作時聽音樂。"},{"en":"She listens more than she talks.","zh":"她聽多於說。"},{"en":"Listen carefully before you answer.","zh":"回答前仔細聆聽。"},{"en":"He listens to understand, not to reply.","zh":"他傾聽是為了理解，而不是回答。"},{"en":"I love listening to the rain at night.","zh":"我喜歡晚上聽雨聲。"},{"en":"She listened to every word he said.","zh":"她聆聽他說的每一個字。"},{"en":"Listen to your body when it is tired.","zh":"當你的身體累了，傾聽它。"},{"en":"He listens to a podcast every morning.","zh":"他每天早上聽播客。"},{"en":"I listen to my friends when they need me.","zh":"當我的朋友需要我時，我聆聽他們。"},{"en":"Good leaders listen first.","zh":"好的領導者首先傾聽。"}]},{"word":"visit","pos":"verb","chinese":"拜訪；參觀","level":"A2","sentences":[{"en":"We visit my grandparents every Sunday.","zh":"我們每個星期日拜訪我的祖父母。"},{"en":"She visited three countries last year.","zh":"她去年參觀了三個國家。"},{"en":"Please visit whenever you like.","zh":"你隨時可以來拜訪。"},{"en":"I want to visit Japan in spring.","zh":"我想在春天參觀日本。"},{"en":"He visits the gym before work.","zh":"他在上班前去健身房。"},{"en":"They visited the museum together.","zh":"他們一起參觀了博物館。"},{"en":"Visit a new place every month.","zh":"每個月參觀一個新地方。"},{"en":"She visits her old friends often.","zh":"她經常拜訪她的老朋友。"},{"en":"We visited the coast for the weekend.","zh":"我們週末去了海岸。"},{"en":"Come visit us when you are free.","zh":"你有空時來拜訪我們。"}]},{"word":"arrive","pos":"verb","chinese":"到達","level":"A2","sentences":[{"en":"We arrived just in time.","zh":"我們及時到達了。"},{"en":"She arrives early to everything.","zh":"她做任何事都早到。"},{"en":"The train arrives at nine.","zh":"火車九點到達。"},{"en":"He arrived home late again.","zh":"他又晚回家了。"},{"en":"They arrived safely after the long trip.","zh":"長途旅行後他們安全到達。"},{"en":"I arrived to find everyone waiting.","zh":"我到達時發現每個人都在等。"},{"en":"Arrive ten minutes before the meeting.","zh":"會議前十分鐘到達。"},{"en":"She arrived with a big smile.","zh":"她帶著燦爛的笑容到達。"},{"en":"We arrived at the same conclusion.","zh":"我們得出了相同的結論。"},{"en":"He arrived when I least expected it.","zh":"他在我最意想不到的時候到達。"}]},{"word":"return","pos":"verb","chinese":"返回","level":"A2","sentences":[{"en":"I will return the book tomorrow.","zh":"我明天會還書。"},{"en":"She returned home after many years.","zh":"多年後她回家了。"},{"en":"He returned my call right away.","zh":"他立刻回了我的電話。"},{"en":"Return to the basics when you feel lost.","zh":"當你感到迷失時，回歸基礎。"},{"en":"They returned the favour generously.","zh":"他們慷慨地回報了恩情。"},{"en":"I returned to a place I once loved.","zh":"我回到了一個我曾經愛的地方。"},{"en":"She returns every summer without fail.","zh":"她每年夏天都會回來。"},{"en":"He returned stronger than before.","zh":"他比以前更強大地回來了。"},{"en":"Return what you borrow, always.","zh":"永遠歸還你借的東西。"},{"en":"We returned home with full hearts.","zh":"我們帶著滿滿的心回家了。"}]},{"word":"carry","pos":"verb","chinese":"攜帶","level":"A2","sentences":[{"en":"I carry a notebook everywhere.","zh":"我到處攜帶一個筆記本。"},{"en":"She carries herself with confidence.","zh":"她舉止自信。"},{"en":"He carried the heavy bags upstairs.","zh":"他把沉重的袋子搬上樓。"},{"en":"Carry less and travel lighter.","zh":"攜帶更少，旅行更輕鬆。"},{"en":"She carries the weight of the team.","zh":"她承擔著團隊的重量。"},{"en":"I carry good memories with me.","zh":"我帶著美好的回憶。"},{"en":"He carried on despite the pain.","zh":"儘管疼痛，他繼續前進。"},{"en":"Carry yourself the way you want to be seen.","zh":"以你希望被看待的方式舉止。"},{"en":"She carried the conversation gracefully.","zh":"她優雅地主導了對話。"},{"en":"They carried the tradition forward.","zh":"他們把傳統傳承下去。"}]},{"word":"push","pos":"verb","chinese":"推","level":"A2","sentences":[{"en":"Push gently, do not force it.","zh":"輕輕推，不要強迫。"},{"en":"She pushes herself to grow.","zh":"她推動自己成長。"},{"en":"He pushed through the hard part.","zh":"他撐過了困難的部分。"},{"en":"Push the door, do not pull.","zh":"推門，不要拉。"},{"en":"Sometimes you need a small push.","zh":"有時你需要一個小小的推動。"},{"en":"She pushed past her own doubt.","zh":"她超越了自己的懷疑。"},{"en":"Do not push people away when you need them.","zh":"當你需要人們時不要推開他們。"},{"en":"He pushed the boundaries of what was possible.","zh":"他推動了可能性的界限。"},{"en":"Push forward even when it is slow.","zh":"即使緩慢也要向前推進。"},{"en":"She gave me the push I needed.","zh":"她給了我需要的推動。"}]},{"word":"pull","pos":"verb","chinese":"拉","level":"A2","sentences":[{"en":"Pull the door towards you.","zh":"把門拉向你。"},{"en":"She pulled herself together quickly.","zh":"她很快振作起來。"},{"en":"He pulled an all-nighter to finish.","zh":"他熬夜完成它。"},{"en":"Pull back when you feel overwhelmed.","zh":"當你感到不知所措時退一步。"},{"en":"They pulled together as a team.","zh":"他們作為團隊團結一致。"},{"en":"She pulled off the impossible.","zh":"她做到了不可能的事。"},{"en":"Pull your focus back to the present.","zh":"把你的注意力拉回當下。"},{"en":"He pulled me out of a dark place.","zh":"他把我從黑暗的地方拉出來。"},{"en":"Pull weeds before they spread.","zh":"在雜草蔓延之前拔除它們。"},{"en":"She pulled strength from somewhere deep.","zh":"她從深處汲取力量。"}]},{"word":"hold","pos":"verb","chinese":"握住","level":"A2","sentences":[{"en":"Hold on, better days are coming.","zh":"堅持住，更好的日子即將到來。"},{"en":"She holds her ground calmly.","zh":"她冷靜地堅守立場。"},{"en":"He held the door for everyone.","zh":"他為每個人扶著門。"},{"en":"Hold your standards even when tired.","zh":"即使累了也要堅持你的標準。"},{"en":"I hold onto hope through hard times.","zh":"我在艱難時期抓住希望。"},{"en":"She held the team together.","zh":"她把團隊凝聚在一起。"},{"en":"Hold space for your own feelings.","zh":"為你自己的感受留出空間。"},{"en":"He held back his tears bravely.","zh":"他勇敢地忍住淚水。"},{"en":"Hold the moment, it will not last.","zh":"抓住這一刻，它不會持久。"},{"en":"She holds her values close.","zh":"她把她的價值觀緊緊抱住。"}]},{"word":"cover","pos":"verb","chinese":"覆蓋","level":"A2","sentences":[{"en":"Cover the basics before the extras.","zh":"在額外的東西之前先涵蓋基礎。"},{"en":"She covered for me when I was sick.","zh":"我生病時她替我頂班。"},{"en":"He covered the topic thoroughly.","zh":"他徹底地涵蓋了這個話題。"},{"en":"Cover your bases before you start.","zh":"開始前做好準備。"},{"en":"The blanket covered them both.","zh":"毯子蓋住了他們兩個。"},{"en":"She covered her costs within a month.","zh":"她在一個月內收回了成本。"},{"en":"Cover the essentials, skip the rest.","zh":"涵蓋必需品，跳過其餘的。"},{"en":"He covered a lot of ground today.","zh":"他今天取得了很大進展。"},{"en":"Snow covered the whole valley.","zh":"雪覆蓋了整個山谷。"},{"en":"She covered the news from the front line.","zh":"她從前線報導新聞。"}]},{"word":"break","pos":"verb","chinese":"打破","level":"A2","sentences":[{"en":"Take a break before you burn out.","zh":"在你倦怠之前休息一下。"},{"en":"She broke the cycle of bad habits.","zh":"她打破了壞習慣的循環。"},{"en":"He broke the news gently.","zh":"他溫和地告知了消息。"},{"en":"Break big goals into small steps.","zh":"把大目標分解成小步驟。"},{"en":"They broke the record this year.","zh":"他們今年打破了紀錄。"},{"en":"She broke free from old patterns.","zh":"她從舊模式中解放出來。"},{"en":"Break the silence with kindness.","zh":"用善意打破沉默。"},{"en":"He broke down the problem clearly.","zh":"他清楚地分解了問題。"},{"en":"A short break boosts focus.","zh":"短暫的休息能提升專注力。"},{"en":"She broke the tension with a joke.","zh":"她用一個笑話打破了緊張氣氛。"}]},{"word":"fix","pos":"verb","chinese":"修理","level":"A2","sentences":[{"en":"She fixed the problem in minutes.","zh":"她幾分鐘內解決了問題。"},{"en":"He fixed his attention on the goal.","zh":"他把注意力固定在目標上。"},{"en":"Fix what is broken, keep what works.","zh":"修理壞掉的，保留有效的。"},{"en":"I fixed the issue and moved on.","zh":"我修好了問題，然後繼續。"},{"en":"She fixed us a wonderful meal.","zh":"她為我們做了一頓美味的飯。"},{"en":"Do not try to fix people, support them.","zh":"不要試圖修理人們，支持他們。"},{"en":"He fixed the date for the wedding.","zh":"他確定了婚禮的日期。"},{"en":"Fix small problems before they grow.","zh":"在小問題變大之前解決它們。"},{"en":"She fixed her eyes on the horizon.","zh":"她把目光固定在地平線上。"},{"en":"Fixing it yourself builds confidence.","zh":"自己修理它能建立信心。"}]},{"word":"build","pos":"verb","chinese":"建造","level":"A2","sentences":[{"en":"She built a business from nothing.","zh":"她從零開始建立了一個生意。"},{"en":"Build habits that serve your future.","zh":"建立服務你未來的習慣。"},{"en":"He built trust slowly and surely.","zh":"他緩慢而確定地建立了信任。"},{"en":"They built a home full of love.","zh":"他們建立了一個充滿愛的家。"},{"en":"Build on your strengths, not your fears.","zh":"建立在你的優勢上，而不是恐懼。"},{"en":"She built her confidence step by step.","zh":"她一步一步建立了她的信心。"},{"en":"Build something that outlasts you.","zh":"建立比你更長久的東西。"},{"en":"He built a strong team over years.","zh":"他多年建立了一個強大的團隊。"},{"en":"Build the life you actually want.","zh":"建立你真正想要的生活。"},{"en":"She builds people up, never down.","zh":"她提升人們，從不貶低。"}]},{"word":"draw","pos":"verb","chinese":"畫","level":"A2","sentences":[{"en":"She draws inspiration from nature.","zh":"她從大自然汲取靈感。"},{"en":"He draws every single morning.","zh":"他每天早上都畫畫。"},{"en":"Draw on your past experience.","zh":"利用你過去的經驗。"},{"en":"The event drew a huge crowd.","zh":"這個活動吸引了一大群人。"},{"en":"She drew a clear boundary.","zh":"她劃了一條清晰的界限。"},{"en":"He draws strength from his family.","zh":"他從家人那裡汲取力量。"},{"en":"Draw the line where it matters.","zh":"在重要的地方劃線。"},{"en":"She drew the room's attention instantly.","zh":"她立刻吸引了房間的注意。"},{"en":"Draw conclusions only from facts.","zh":"只從事實得出結論。"},{"en":"He drew a map from memory.","zh":"他憑記憶畫了一張地圖。"}]},{"word":"cook","pos":"verb","chinese":"烹飪","level":"A2","sentences":[{"en":"She cooks dinner from scratch nightly.","zh":"她每晚從頭做晚餐。"},{"en":"He cooks to relax after work.","zh":"他下班後做飯來放鬆。"},{"en":"Cook with what you have.","zh":"用你有的東西做飯。"},{"en":"She cooked a feast for ten people.","zh":"她為十個人做了一頓盛宴。"},{"en":"Cooking together brings people closer.","zh":"一起做飯讓人更親近。"},{"en":"He cooks the same dish perfectly.","zh":"他把同一道菜做得完美。"},{"en":"She cooks by instinct, not recipe.","zh":"她憑直覺做飯，而不是食譜。"},{"en":"Cook more, order in less.","zh":"多做飯，少叫外賣。"},{"en":"He learned to cook from his mother.","zh":"他從母親那裡學會了做飯。"},{"en":"She cooks with so much love.","zh":"她用很多愛來做飯。"}]},{"word":"collect","pos":"verb","chinese":"收集","level":"A2","sentences":[{"en":"She collects vintage postcards.","zh":"她收集復古明信片。"},{"en":"He collects experiences, not things.","zh":"他收集體驗，而不是物品。"},{"en":"Collect your thoughts before speaking.","zh":"說話前整理你的思緒。"},{"en":"She collected the data carefully.","zh":"她仔細地收集了數據。"},{"en":"They collect memories from each trip.","zh":"他們從每次旅行中收集回憶。"},{"en":"Collect feedback and act on it.","zh":"收集反饋並採取行動。"},{"en":"He collected himself before responding.","zh":"他在回應前鎮定下來。"},{"en":"She collects small moments of joy.","zh":"她收集小小的快樂時刻。"},{"en":"Collect what serves you, release the rest.","zh":"收集對你有用的，釋放其餘的。"},{"en":"He collected stamps as a child.","zh":"他小時候收集郵票。"}]},{"word":"hurry","pos":"verb","chinese":"趕快","level":"A2","sentences":[{"en":"Do not hurry, do it well.","zh":"不要急，把它做好。"},{"en":"She hurried to catch the train.","zh":"她趕著去趕火車。"},{"en":"There is no need to hurry.","zh":"沒有必要急。"},{"en":"He hurried through breakfast.","zh":"他匆匆吃完早餐。"},{"en":"Hurry less, notice more.","zh":"少急一點，多留意一點。"},{"en":"She hurried but stayed calm.","zh":"她趕時間但保持冷靜。"},{"en":"Do not let others hurry you.","zh":"不要讓別人催促你。"},{"en":"He hurried home in the rain.","zh":"他在雨中匆匆回家。"},{"en":"Slow mornings beat hurried ones.","zh":"悠閒的早晨勝過匆忙的。"},{"en":"She rarely hurries, yet finishes first.","zh":"她很少急，卻最先完成。"}]},{"word":"rest","pos":"verb","chinese":"休息","level":"A2","sentences":[{"en":"Rest is part of the work.","zh":"休息是工作的一部分。"},{"en":"She rests without feeling guilty.","zh":"她休息而不感到愧疚。"},{"en":"He rests fully so he works fully.","zh":"他充分休息，所以充分工作。"},{"en":"Rest before you are exhausted.","zh":"在你筋疲力盡之前休息。"},{"en":"Your body needs rest to heal.","zh":"你的身體需要休息來癒合。"},{"en":"She schedules rest like meetings.","zh":"她像安排會議一樣安排休息。"},{"en":"Rest is productive, not lazy.","zh":"休息是有成效的，不是懶惰。"},{"en":"He found rest in quiet mornings.","zh":"他在安靜的早晨找到休息。"},{"en":"Rest your mind as well as your body.","zh":"休息你的頭腦，也休息你的身體。"},{"en":"Real rest makes everything easier.","zh":"真正的休息讓一切都更容易。"}]},{"word":"relax","pos":"verb","chinese":"放鬆","level":"A2","sentences":[{"en":"Learn to relax without a screen.","zh":"學會在沒有螢幕的情況下放鬆。"},{"en":"She relaxes by walking in nature.","zh":"她通過在大自然中散步來放鬆。"},{"en":"Relax your shoulders and breathe.","zh":"放鬆你的肩膀並呼吸。"},{"en":"He relaxes fully on weekends.","zh":"他週末完全放鬆。"},{"en":"Relax, everything will work out.","zh":"放鬆，一切都會解決。"},{"en":"She relaxed for the first time in weeks.","zh":"幾週來她第一次放鬆。"},{"en":"Relax into the moment.","zh":"放鬆地融入當下。"},{"en":"He relaxes by playing music.","zh":"他通過彈音樂來放鬆。"},{"en":"Relaxing is a skill worth learning.","zh":"放鬆是一種值得學習的技能。"},{"en":"She finally let herself relax.","zh":"她終於讓自己放鬆。"}]},{"word":"breathe","pos":"verb","chinese":"呼吸","level":"A2","sentences":[{"en":"Breathe deeply when you feel anxious.","zh":"當你感到焦慮時深呼吸。"},{"en":"She breathes before she reacts.","zh":"她在反應之前呼吸。"},{"en":"Just breathe, one moment at a time.","zh":"只是呼吸，一次一個時刻。"},{"en":"He learned to breathe through stress.","zh":"他學會了通過呼吸來應對壓力。"},{"en":"Breathe in calm, breathe out tension.","zh":"吸入平靜，呼出緊張。"},{"en":"She breathes fresh air every morning.","zh":"她每天早上呼吸新鮮空氣。"},{"en":"Breathe slowly to calm your mind.","zh":"慢慢呼吸來平靜你的心。"},{"en":"He stopped to breathe and refocus.","zh":"他停下來呼吸並重新集中。"},{"en":"Breathe before a difficult conversation.","zh":"在困難的對話前呼吸。"},{"en":"She breathes life into every project.","zh":"她為每個項目注入生命力。"}]},{"word":"smile","pos":"verb","chinese":"微笑","level":"A2","sentences":[{"en":"Her smile lights up the room.","zh":"她的微笑照亮了整個房間。"},{"en":"He smiles even on hard days.","zh":"即使在艱難的日子，他也微笑。"},{"en":"Smile at strangers, it spreads.","zh":"對陌生人微笑，它會傳播。"},{"en":"She smiled through the tears.","zh":"她含淚微笑。"},{"en":"A genuine smile changes everything.","zh":"真誠的微笑改變一切。"},{"en":"He smiled when he saw her.","zh":"他看到她時微笑了。"},{"en":"Smile first, talk second.","zh":"先微笑，再說話。"},{"en":"Her smile put everyone at ease.","zh":"她的微笑讓每個人都放鬆。"},{"en":"Smile because it happened.","zh":"微笑因為它發生過。"},{"en":"He greeted me with a warm smile.","zh":"他用溫暖的微笑迎接我。"}]},{"word":"laugh","pos":"verb","chinese":"笑","level":"A2","sentences":[{"en":"She laughs easily and often.","zh":"她笑得輕鬆而頻繁。"},{"en":"Laugh at yourself, it helps.","zh":"嘲笑自己，這有幫助。"},{"en":"He made the whole room laugh.","zh":"他讓整個房間都笑了。"},{"en":"We laughed until we cried.","zh":"我們笑到哭。"},{"en":"Laughter is the best medicine.","zh":"笑聲是最好的良藥。"},{"en":"She laughs at her own mistakes.","zh":"她嘲笑自己的錯誤。"},{"en":"Laugh more, worry less.","zh":"多笑，少擔心。"},{"en":"He has a laugh that is contagious.","zh":"他的笑聲很有感染力。"},{"en":"They laughed about it years later.","zh":"幾年後他們還笑著談論它。"},{"en":"A good laugh resets the whole day.","zh":"一場好笑重置了整天。"}]},{"word":"repeat","pos":"verb","chinese":"重複","level":"A2","sentences":[{"en":"Repeat the words until they stick.","zh":"重複這些詞直到它們記住。"},{"en":"She repeats affirmations every morning.","zh":"她每天早上重複肯定語。"},{"en":"Do not repeat the same mistake.","zh":"不要重複同樣的錯誤。"},{"en":"He repeated the lesson patiently.","zh":"他耐心地重複了那一課。"},{"en":"Repeat what works, drop what does not.","zh":"重複有效的，放棄無效的。"},{"en":"She repeated it until it felt natural.","zh":"她重複它直到感覺自然。"},{"en":"History repeats when we forget.","zh":"當我們忘記時歷史會重演。"},{"en":"Repeat the good habits daily.","zh":"每天重複好習慣。"},{"en":"He repeated her name to remember it.","zh":"他重複她的名字以記住它。"},{"en":"Repetition is how we learn.","zh":"重複是我們學習的方式。"}]},{"word":"translate","pos":"verb","chinese":"翻譯","level":"A2","sentences":[{"en":"She translates between two languages.","zh":"她在兩種語言之間翻譯。"},{"en":"Translate your ideas into action.","zh":"把你的想法轉化為行動。"},{"en":"He translates complex ideas simply.","zh":"他把複雜的想法簡單地翻譯出來。"},{"en":"Some feelings do not translate.","zh":"有些感覺無法翻譯。"},{"en":"She translated the poem beautifully.","zh":"她美麗地翻譯了那首詩。"},{"en":"Translate effort into results.","zh":"把努力轉化為結果。"},{"en":"He translates for visitors often.","zh":"他經常為訪客翻譯。"},{"en":"Translating cultures is an art.","zh":"翻譯文化是一門藝術。"},{"en":"She translated his silence correctly.","zh":"她正確地解讀了他的沉默。"},{"en":"Translate knowledge into wisdom.","zh":"把知識轉化為智慧。"}]},{"word":"teach","pos":"verb","chinese":"教","level":"A2","sentences":[{"en":"She teaches with patience and warmth.","zh":"她以耐心和溫暖教學。"},{"en":"Teach what you wish you had learned.","zh":"教你希望你曾學過的東西。"},{"en":"He teaches by example, not lecture.","zh":"他以身作則教學，而不是說教。"},{"en":"Teaching others deepens your own learning.","zh":"教別人加深你自己的學習。"},{"en":"She teaches her kids to be kind.","zh":"她教她的孩子要善良。"},{"en":"Teach less, ask more.","zh":"少教，多問。"},{"en":"He teaches a skill every weekend.","zh":"他每個週末教一項技能。"},{"en":"Teaching is the best way to learn.","zh":"教學是最好的學習方式。"},{"en":"She taught me to believe in myself.","zh":"她教我相信自己。"},{"en":"Teach values along with facts.","zh":"在事實之外也教價值觀。"}]},{"word":"study","pos":"verb","chinese":"學習","level":"A2","sentences":[{"en":"She studies a little every day.","zh":"她每天學習一點。"},{"en":"Study smart, not just hard.","zh":"聰明地學習，而不只是努力。"},{"en":"He studies what genuinely interests him.","zh":"他學習真正讓他感興趣的東西。"},{"en":"Study the problem before the solution.","zh":"在解決方案之前研究問題。"},{"en":"She studied late into the night.","zh":"她學習到深夜。"},{"en":"Study people you admire.","zh":"研究你欽佩的人。"},{"en":"He studies one topic deeply.","zh":"他深入研究一個主題。"},{"en":"Study with focus, then fully rest.","zh":"專注地學習，然後充分休息。"},{"en":"She studies for understanding, not grades.","zh":"她為了理解而學習，而不是成績。"},{"en":"Studying daily beats cramming.","zh":"每天學習勝過臨時抱佛腳。"}]},{"word":"review","pos":"verb","chinese":"複習","level":"A2","sentences":[{"en":"Review your goals every month.","zh":"每個月回顧你的目標。"},{"en":"She reviews her notes before sleep.","zh":"她睡前複習她的筆記。"},{"en":"Review the day with gratitude.","zh":"帶著感恩回顧這一天。"},{"en":"He reviewed the plan one last time.","zh":"他最後一次審查了計畫。"},{"en":"Review what worked and repeat it.","zh":"回顧什麼有效並重複它。"},{"en":"She reviews her spending weekly.","zh":"她每週審查她的開支。"},{"en":"Review mistakes without judgment.","zh":"不帶評判地回顧錯誤。"},{"en":"He reviews his progress quarterly.","zh":"他每季度回顧他的進度。"},{"en":"Review and adjust, do not abandon.","zh":"回顧並調整，不要放棄。"},{"en":"She reviewed the contract carefully.","zh":"她仔細審查了合同。"}]},{"word":"dream","pos":"verb","chinese":"做夢；夢想","level":"A2","sentences":[{"en":"She dreams big and acts daily.","zh":"她夢想遠大，每天行動。"},{"en":"Dream, then build it step by step.","zh":"做夢，然後一步一步建立它。"},{"en":"He never stopped dreaming.","zh":"他從未停止做夢。"},{"en":"Dreams need action to become real.","zh":"夢想需要行動才能成真。"},{"en":"She follows her dreams quietly.","zh":"她安靜地追隨她的夢想。"},{"en":"Dream beyond what seems possible.","zh":"夢想超越看似可能的範圍。"},{"en":"He dreams of a simpler life.","zh":"他夢想一種更簡單的生活。"},{"en":"Hold onto your dreams gently.","zh":"溫柔地抓住你的夢想。"},{"en":"She turned a dream into a plan.","zh":"她把夢想變成了計畫。"},{"en":"Dream awake and make it happen.","zh":"清醒地做夢並讓它實現。"}]},{"word":"wish","pos":"verb","chinese":"希望；願望","level":"A2","sentences":[{"en":"I wish you nothing but good things.","zh":"我祝你只有好事。"},{"en":"She made a wish and worked for it.","zh":"她許了一個願望並為之努力。"},{"en":"Wish less, do more.","zh":"少許願，多行動。"},{"en":"He wished he had started sooner.","zh":"他希望他更早開始。"},{"en":"Wishing is the start, action is the rest.","zh":"許願是開始，行動是其餘。"},{"en":"She wishes everyone well, genuinely.","zh":"她真誠地祝願每個人都好。"},{"en":"I wish for peace more than success.","zh":"我希望平靜多於成功。"},{"en":"He got everything he wished for.","zh":"他得到了他希望的一切。"},{"en":"Wish for growth, not just comfort.","zh":"希望成長，而不只是舒適。"},{"en":"She wished him luck and meant it.","zh":"她祝他好運，並且是真心的。"}]},{"word":"doubt","pos":"verb","chinese":"懷疑","level":"A2","sentences":[{"en":"Doubt your fears, not your worth.","zh":"懷疑你的恐懼，而不是你的價值。"},{"en":"She pushed through the doubt.","zh":"她克服了懷疑。"},{"en":"Do not let doubt stop you.","zh":"不要讓懷疑阻止你。"},{"en":"He had doubts but acted anyway.","zh":"他有懷疑，但還是行動了。"},{"en":"Doubt is normal before big steps.","zh":"在重大步驟前懷疑是正常的。"},{"en":"She silenced her inner doubt.","zh":"她讓內心的懷疑安靜下來。"},{"en":"When in doubt, choose kindness.","zh":"當有疑問時，選擇善良。"},{"en":"He replaced doubt with curiosity.","zh":"他用好奇心取代了懷疑。"},{"en":"Doubt less, trust yourself more.","zh":"少懷疑，多相信自己。"},{"en":"She moved forward despite the doubt.","zh":"儘管有懷疑，她還是前進了。"}]},{"word":"guess","pos":"verb","chinese":"猜測","level":"A2","sentences":[{"en":"Take a guess and adjust later.","zh":"猜一下，稍後調整。"},{"en":"She guessed correctly the first time.","zh":"她第一次就猜對了。"},{"en":"Do not guess, ask directly.","zh":"不要猜，直接問。"},{"en":"He made an educated guess.","zh":"他做了一個有根據的猜測。"},{"en":"My guess is it will work out.","zh":"我猜它會解決的。"},{"en":"She guessed what he was thinking.","zh":"她猜到了他在想什麼。"},{"en":"Guess less, gather more facts.","zh":"少猜，多收集事實。"},{"en":"He guessed the answer instinctively.","zh":"他憑直覺猜到了答案。"},{"en":"Your guess is as good as mine.","zh":"你的猜測和我的一樣好。"},{"en":"She stopped guessing and started testing.","zh":"她停止猜測，開始測試。"}]},{"word":"organise","pos":"verb","chinese":"組織","level":"A2","sentences":[{"en":"She organises her week on Sunday.","zh":"她在週日組織她的一週。"},{"en":"Organise your space, clear your mind.","zh":"整理你的空間，清理你的頭腦。"},{"en":"He organises everything by priority.","zh":"他按優先順序組織一切。"},{"en":"Organise less, but organise well.","zh":"組織更少，但組織得好。"},{"en":"She organised the whole event alone.","zh":"她獨自組織了整個活動。"},{"en":"Organising reduces daily stress.","zh":"組織減少日常壓力。"},{"en":"He organises his thoughts by writing.","zh":"他通過寫作組織他的思緒。"},{"en":"Organise around what matters most.","zh":"圍繞最重要的事情組織。"},{"en":"She organises with calm efficiency.","zh":"她以冷靜的效率組織。"},{"en":"Organising is self-care in disguise.","zh":"組織是偽裝的自我照顧。"}]},{"word":"arrange","pos":"verb","chinese":"安排","level":"A2","sentences":[{"en":"She arranged the flowers beautifully.","zh":"她美麗地擺放了花朵。"},{"en":"Arrange a time that works for both.","zh":"安排一個對雙方都合適的時間。"},{"en":"He arranged everything in advance.","zh":"他提前安排了一切。"},{"en":"Arrange your day around your energy.","zh":"圍繞你的能量安排你的一天。"},{"en":"She arranged a surprise for him.","zh":"她為他安排了一個驚喜。"},{"en":"Arrange the priorities clearly.","zh":"清楚地安排優先順序。"},{"en":"He arranged to meet next week.","zh":"他安排了下週見面。"},{"en":"She arranges her books by colour.","zh":"她按顏色擺放她的書。"},{"en":"Arrange help before you need it.","zh":"在你需要之前安排幫助。"},{"en":"They arranged the room together.","zh":"他們一起佈置了房間。"}]},{"word":"control","pos":"verb","chinese":"控制","level":"A2","sentences":[{"en":"Control what you can, release the rest.","zh":"控制你能控制的，釋放其餘的。"},{"en":"She controls her reactions well.","zh":"她很好地控制她的反應。"},{"en":"He stays in control under pressure.","zh":"他在壓力下保持控制。"},{"en":"Control your attention, not others.","zh":"控制你的注意力，而不是別人。"},{"en":"She took control of her own life.","zh":"她掌控了自己的生活。"},{"en":"Control the controllables.","zh":"控制可控的東西。"},{"en":"He controlled his temper calmly.","zh":"他冷靜地控制了他的脾氣。"},{"en":"Letting go of control brings peace.","zh":"放下控制帶來平靜。"},{"en":"She controls her schedule firmly.","zh":"她堅定地控制她的時間表。"},{"en":"Self-control is the highest strength.","zh":"自我控制是最高的力量。"}]},{"word":"follow","pos":"verb","chinese":"跟隨","level":"A2","sentences":[{"en":"Follow your curiosity, not the crowd.","zh":"跟隨你的好奇心，而不是人群。"},{"en":"She follows through on her promises.","zh":"她履行她的承諾。"},{"en":"Follow the process, trust the result.","zh":"遵循過程，相信結果。"},{"en":"He follows a simple morning routine.","zh":"他遵循一個簡單的早晨例行程序。"},{"en":"Follow up after every meeting.","zh":"每次會議後跟進。"},{"en":"She follows her own path.","zh":"她走自己的路。"},{"en":"Follow advice that fits your life.","zh":"遵循適合你生活的建議。"},{"en":"He followed the map and got there.","zh":"他跟著地圖到達了那裡。"},{"en":"Follow what energises you.","zh":"跟隨讓你充滿活力的東西。"},{"en":"She follows her values consistently.","zh":"她始終如一地遵循她的價值觀。"}]},{"word":"lead","pos":"verb","chinese":"領導","level":"A2","sentences":[{"en":"She leads with empathy and clarity.","zh":"她以同理心和清晰度領導。"},{"en":"Lead by example, not by title.","zh":"以身作則領導，而不是靠頭銜。"},{"en":"He led the team through the crisis.","zh":"他帶領團隊度過了危機。"},{"en":"Lead yourself before leading others.","zh":"在領導別人之前先領導自己。"},{"en":"She leads quietly but powerfully.","zh":"她安靜但有力地領導。"},{"en":"Lead with questions, not answers.","zh":"用問題領導，而不是答案。"},{"en":"He learned to lead by serving.","zh":"他通過服務學會了領導。"},{"en":"Lead where you are, with what you have.","zh":"在你所在的地方，用你擁有的領導。"},{"en":"She leads conversations with care.","zh":"她小心地主導對話。"},{"en":"Good leaders create more leaders.","zh":"好的領導者創造更多領導者。"}]},{"word":"weather","pos":"noun","chinese":"天氣","level":"A2","sentences":[{"en":"The weather is lovely today.","zh":"今天天氣很好。"},{"en":"She checks the weather every morning.","zh":"她每天早上查看天氣。"},{"en":"Bad weather changed our plans.","zh":"壞天氣改變了我們的計畫。"},{"en":"He loves cold weather.","zh":"他喜歡寒冷的天氣。"},{"en":"The weather affects my mood.","zh":"天氣影響我的情緒。"},{"en":"We waited for better weather.","zh":"我們等待更好的天氣。"},{"en":"The weather turned suddenly.","zh":"天氣突然轉變。"},{"en":"Whatever the weather, she walks.","zh":"無論天氣如何，她都散步。"},{"en":"The weather here is unpredictable.","zh":"這裡的天氣難以預測。"},{"en":"Sunny weather lifts everyone's spirits.","zh":"晴朗的天氣提升每個人的情緒。"}]},{"word":"holiday","pos":"noun","chinese":"假期","level":"A2","sentences":[{"en":"We need a real holiday soon.","zh":"我們很快需要一個真正的假期。"},{"en":"She planned the holiday for months.","zh":"她計畫這個假期好幾個月。"},{"en":"Holidays are for resting, not rushing.","zh":"假期是用來休息的，不是趕的。"},{"en":"He spends holidays with family.","zh":"他和家人一起度過假期。"},{"en":"The holiday was exactly what I needed.","zh":"這個假期正是我需要的。"},{"en":"We took a holiday by the sea.","zh":"我們在海邊度假。"},{"en":"A short holiday can reset you.","zh":"短暫的假期可以讓你重置。"},{"en":"She came back from holiday glowing.","zh":"她度假回來容光煥發。"},{"en":"Holidays remind us to slow down.","zh":"假期提醒我們放慢腳步。"},{"en":"They booked a holiday for the spring.","zh":"他們預訂了春天的假期。"}]},{"word":"weekend","pos":"noun","chinese":"週末","level":"A2","sentences":[{"en":"I look forward to the weekend.","zh":"我期待週末。"},{"en":"She works hard but protects her weekends.","zh":"她努力工作但保護她的週末。"},{"en":"Weekends are for the people I love.","zh":"週末是給我愛的人的。"},{"en":"He spends weekends in nature.","zh":"他週末在大自然中度過。"},{"en":"A slow weekend is the best kind.","zh":"悠閒的週末是最好的。"},{"en":"We made big plans for the weekend.","zh":"我們為週末做了大計畫。"},{"en":"The weekend flew by too fast.","zh":"週末飛逝得太快。"},{"en":"She rests fully every weekend.","zh":"她每個週末充分休息。"},{"en":"Weekends recharge me for the week.","zh":"週末為這一週給我充電。"},{"en":"Long weekends are pure joy.","zh":"長週末是純粹的快樂。"}]},{"word":"market","pos":"noun","chinese":"市場","level":"A2","sentences":[{"en":"She shops at the local market.","zh":"她在當地市場購物。"},{"en":"The market opens early on Saturdays.","zh":"市場週六很早開門。"},{"en":"He sells his crafts at the market.","zh":"他在市場上賣他的手工藝品。"},{"en":"Fresh produce fills the market.","zh":"新鮮農產品擺滿了市場。"},{"en":"We wandered through the market for hours.","zh":"我們在市場逛了幾個小時。"},{"en":"The market was full of colour and life.","zh":"市場充滿色彩和生機。"},{"en":"She knows every vendor at the market.","zh":"她認識市場上的每個攤販。"},{"en":"Markets are the heart of a town.","zh":"市場是一個城鎮的心臟。"},{"en":"I prefer markets to supermarkets.","zh":"我喜歡市場勝過超市。"},{"en":"The morning market smelled of bread.","zh":"早市聞起來有麵包的味道。"}]},{"word":"garden","pos":"noun","chinese":"花園","level":"A2","sentences":[{"en":"She grows herbs in her garden.","zh":"她在花園裡種香草。"},{"en":"The garden is his happy place.","zh":"花園是他快樂的地方。"},{"en":"A garden teaches patience.","zh":"花園教會耐心。"},{"en":"They planted a garden together.","zh":"他們一起種了一個花園。"},{"en":"The garden bloomed in spring.","zh":"花園在春天綻放。"},{"en":"She reads in the garden every morning.","zh":"她每天早上在花園裡閱讀。"},{"en":"Our garden attracts butterflies.","zh":"我們的花園吸引蝴蝶。"},{"en":"Gardening calms his busy mind.","zh":"園藝平靜他忙碌的心。"},{"en":"The garden gives more than it takes.","zh":"花園給予的比索取的多。"},{"en":"She tends her garden with love.","zh":"她用愛照料她的花園。"}]},{"word":"kitchen","pos":"noun","chinese":"廚房","level":"A2","sentences":[{"en":"The kitchen is the heart of the home.","zh":"廚房是家的心臟。"},{"en":"She cooks in a small but cosy kitchen.","zh":"她在一個小而溫馨的廚房做飯。"},{"en":"We gather in the kitchen every evening.","zh":"我們每晚在廚房聚集。"},{"en":"A clean kitchen makes cooking joyful.","zh":"乾淨的廚房讓做飯變得愉快。"},{"en":"He organised the kitchen perfectly.","zh":"他把廚房整理得完美。"},{"en":"The kitchen smelled of fresh coffee.","zh":"廚房聞起來有新鮮咖啡的味道。"},{"en":"Good conversations happen in the kitchen.","zh":"好的對話發生在廚房。"},{"en":"She redesigned her kitchen herself.","zh":"她自己重新設計了她的廚房。"},{"en":"The kitchen table holds many memories.","zh":"廚房的桌子承載著許多回憶。"},{"en":"A well-stocked kitchen inspires cooking.","zh":"儲備充足的廚房激發烹飪。"}]},{"word":"journey","pos":"noun","chinese":"旅程","level":"A2","sentences":[{"en":"Enjoy the journey, not just the destination.","zh":"享受旅程，而不只是目的地。"},{"en":"Her journey inspired many people.","zh":"她的旅程激勵了許多人。"},{"en":"Every journey begins with one step.","zh":"每段旅程都從一步開始。"},{"en":"The journey changed how he saw the world.","zh":"這段旅程改變了他看世界的方式。"},{"en":"We are on this journey together.","zh":"我們一起踏上這段旅程。"},{"en":"Her healing journey took years.","zh":"她的療癒之旅花了多年。"},{"en":"The journey was harder than expected.","zh":"這段旅程比預期更難。"},{"en":"Trust the journey even when it is unclear.","zh":"即使不清楚也要相信旅程。"},{"en":"His journey was full of surprises.","zh":"他的旅程充滿驚喜。"},{"en":"Make the journey meaningful.","zh":"讓旅程有意義。"}]},{"word":"goal","pos":"noun","chinese":"目標","level":"A2","sentences":[{"en":"She writes her goals down every year.","zh":"她每年寫下她的目標。"},{"en":"Break a big goal into small ones.","zh":"把大目標分解成小目標。"},{"en":"His goal is simple but powerful.","zh":"他的目標簡單但有力。"},{"en":"Set goals that excite you.","zh":"設定讓你興奮的目標。"},{"en":"She reached her goal step by step.","zh":"她一步一步達到了她的目標。"},{"en":"A goal without a plan is a wish.","zh":"沒有計畫的目標只是願望。"},{"en":"He keeps his goals visible.","zh":"他讓他的目標可見。"},{"en":"Her goal aligned with her values.","zh":"她的目標與她的價值觀一致。"},{"en":"Reaching one goal opens new ones.","zh":"達到一個目標開啟新的目標。"},{"en":"She set a goal and stuck to it.","zh":"她設定了一個目標並堅持。"}]},{"word":"habit","pos":"noun","chinese":"習慣","level":"A2","sentences":[{"en":"Small habits create big change.","zh":"小習慣創造大改變。"},{"en":"She built one good habit at a time.","zh":"她一次建立一個好習慣。"},{"en":"Habits shape who we become.","zh":"習慣塑造我們成為誰。"},{"en":"He broke a bad habit slowly.","zh":"他慢慢戒掉了一個壞習慣。"},{"en":"Good habits make hard days easier.","zh":"好習慣讓艱難的日子更容易。"},{"en":"Her morning habit grounds her.","zh":"她的早晨習慣讓她踏實。"},{"en":"Replace habits, do not just remove them.","zh":"替換習慣，而不只是移除它們。"},{"en":"A habit takes weeks to form.","zh":"一個習慣需要幾週才能形成。"},{"en":"His reading habit changed his life.","zh":"他的閱讀習慣改變了他的生活。"},{"en":"Build habits you can keep forever.","zh":"建立你能永遠保持的習慣。"}]},{"word":"choice","pos":"noun","chinese":"選擇","level":"A2","sentences":[{"en":"Every choice shapes your future.","zh":"每個選擇塑造你的未來。"},{"en":"She made a brave choice.","zh":"她做了一個勇敢的選擇。"},{"en":"The choice was harder than it looked.","zh":"選擇比看起來更難。"},{"en":"He owns his choices fully.","zh":"他完全承擔他的選擇。"},{"en":"Make the choice that you can live with.","zh":"做你能接受的選擇。"},{"en":"She had a choice and chose growth.","zh":"她有選擇，並選擇了成長。"},{"en":"Small choices add up to a life.","zh":"小選擇累積成一生。"},{"en":"Give people the choice to grow.","zh":"給人們成長的選擇。"},{"en":"His choice surprised everyone.","zh":"他的選擇讓每個人都驚訝。"},{"en":"Freedom is having a real choice.","zh":"自由是有真正的選擇。"}]},{"word":"mistake","pos":"noun","chinese":"錯誤","level":"A2","sentences":[{"en":"She learns from every mistake.","zh":"她從每個錯誤中學習。"},{"en":"Mistakes are proof you are trying.","zh":"錯誤是你在嘗試的證明。"},{"en":"He owns his mistakes quickly.","zh":"他迅速承認他的錯誤。"},{"en":"Make new mistakes, not the same ones.","zh":"犯新的錯誤，而不是同樣的。"},{"en":"A mistake is a lesson in disguise.","zh":"錯誤是偽裝的教訓。"},{"en":"She forgave herself for the mistake.","zh":"她原諒了自己的錯誤。"},{"en":"Mistakes teach more than success.","zh":"錯誤教的比成功更多。"},{"en":"He turned a mistake into a win.","zh":"他把錯誤變成了勝利。"},{"en":"Do not fear mistakes, fear not trying.","zh":"不要害怕錯誤，害怕不嘗試。"},{"en":"Her biggest mistake became her best lesson.","zh":"她最大的錯誤成了她最好的教訓。"}]},{"word":"reason","pos":"noun","chinese":"原因；理由","level":"A2","sentences":[{"en":"There is a reason for everything.","zh":"凡事都有原因。"},{"en":"She gave a clear reason for leaving.","zh":"她給了一個離開的明確理由。"},{"en":"Know your reason and stay strong.","zh":"知道你的原因並保持堅強。"},{"en":"His reason made perfect sense.","zh":"他的理由完全合理。"},{"en":"Find a reason to keep going.","zh":"找一個繼續前進的理由。"},{"en":"She had every reason to quit but did not.","zh":"她有充分的理由放棄，但沒有。"},{"en":"The real reason is often hidden.","zh":"真正的原因往往是隱藏的。"},{"en":"Lead with reason, not emotion.","zh":"用理智領導，而不是情緒。"},{"en":"Give me one good reason.","zh":"給我一個好理由。"},{"en":"Her reason was simple and true.","zh":"她的理由簡單而真實。"}]},{"word":"result","pos":"noun","chinese":"結果","level":"A2","sentences":[{"en":"The results spoke for themselves.","zh":"結果不言自明。"},{"en":"She focuses on effort, not just results.","zh":"她專注於努力，而不只是結果。"},{"en":"Good habits produce good results.","zh":"好習慣產生好結果。"},{"en":"The result surprised everyone.","zh":"結果讓每個人都驚訝。"},{"en":"Trust the process and the results follow.","zh":"相信過程，結果隨之而來。"},{"en":"He measures results honestly.","zh":"他誠實地衡量結果。"},{"en":"The result was worth the wait.","zh":"結果值得等待。"},{"en":"Small actions create big results.","zh":"小行動創造大結果。"},{"en":"She got results by staying consistent.","zh":"她通過保持一致獲得了結果。"},{"en":"Results take longer than we hope.","zh":"結果比我們希望的需要更長時間。"}]},{"word":"chance","pos":"noun","chinese":"機會；機率","level":"A2","sentences":[{"en":"Take the chance while you can.","zh":"趁你還能的時候抓住機會。"},{"en":"She gave him a second chance.","zh":"她給了他第二次機會。"},{"en":"Every chance is worth considering.","zh":"每個機會都值得考慮。"},{"en":"He took a chance and it paid off.","zh":"他冒了險，得到了回報。"},{"en":"Chances are rare, do not waste them.","zh":"機會稀有，不要浪費它們。"},{"en":"She created her own chances.","zh":"她創造了自己的機會。"},{"en":"Give yourself the chance to fail.","zh":"給自己失敗的機會。"},{"en":"By chance, we met again.","zh":"偶然地，我們再次相遇。"},{"en":"This is your chance to shine.","zh":"這是你發光的機會。"},{"en":"He never let a chance slip away.","zh":"他從不讓機會溜走。"}]},{"word":"value","pos":"noun/verb","chinese":"價值；重視","level":"A2","sentences":[{"en":"She values honesty above all.","zh":"她最重視誠實。"},{"en":"Know your worth and your values.","zh":"了解你的價值和你的價值觀。"},{"en":"He values time more than money.","zh":"他重視時間勝過金錢。"},{"en":"Add value before you ask for anything.","zh":"在你要求任何東西之前增加價值。"},{"en":"She values deep over shallow.","zh":"她重視深刻勝過膚淺。"},{"en":"Real value is rarely loud.","zh":"真正的價值很少喧嘩。"},{"en":"He values the people who stayed.","zh":"他重視留下來的人。"},{"en":"Value experiences over possessions.","zh":"重視體驗勝過財產。"},{"en":"She knows her own value.","zh":"她知道自己的價值。"},{"en":"Value what cannot be bought.","zh":"重視買不到的東西。"}]},{"word":"future","pos":"noun","chinese":"未來","level":"A2","sentences":[{"en":"The future is built today.","zh":"未來是今天建立的。"},{"en":"She plans for the future calmly.","zh":"她冷靜地為未來計畫。"},{"en":"Your future self will thank you.","zh":"你未來的自己會感謝你。"},{"en":"He invests in his future daily.","zh":"他每天投資他的未來。"},{"en":"The future belongs to the curious.","zh":"未來屬於好奇的人。"},{"en":"She faces the future with hope.","zh":"她帶著希望面對未來。"},{"en":"Build a future you are excited about.","zh":"建立一個讓你興奮的未來。"},{"en":"The future is uncertain but full of possibility.","zh":"未來不確定但充滿可能性。"},{"en":"He stopped fearing the future.","zh":"他停止害怕未來。"},{"en":"Shape your future with daily choices.","zh":"用每天的選擇塑造你的未來。"}]},{"word":"moment","pos":"noun","chinese":"時刻；片刻","level":"A2","sentences":[{"en":"Be present in this moment.","zh":"活在當下這一刻。"},{"en":"She treasures small moments.","zh":"她珍惜小時刻。"},{"en":"That moment changed everything.","zh":"那一刻改變了一切。"},{"en":"Live for the meaningful moments.","zh":"為有意義的時刻而活。"},{"en":"He captured the moment perfectly.","zh":"他完美地捕捉了那一刻。"},{"en":"Take a moment to breathe.","zh":"花一刻呼吸。"},{"en":"Every moment is a fresh start.","zh":"每一刻都是一個新的開始。"},{"en":"She noticed the quiet moments.","zh":"她注意到了安靜的時刻。"},{"en":"Some moments stay with you forever.","zh":"有些時刻永遠留在你心中。"},{"en":"Make the most of every moment.","zh":"充分利用每一刻。"}]},{"word":"progress","pos":"noun","chinese":"進步","level":"A2","sentences":[{"en":"Progress, not perfection, is the goal.","zh":"進步，而不是完美，才是目標。"},{"en":"She celebrates small progress.","zh":"她慶祝小進步。"},{"en":"Progress is often invisible day to day.","zh":"進步往往日復一日地看不見。"},{"en":"He made steady progress all year.","zh":"他全年都穩步進步。"},{"en":"Track your progress to stay motivated.","zh":"追蹤你的進步以保持動力。"},{"en":"Slow progress is still progress.","zh":"緩慢的進步仍然是進步。"},{"en":"She measures progress by growth.","zh":"她用成長來衡量進步。"},{"en":"Progress requires patience.","zh":"進步需要耐心。"},{"en":"Any progress is worth noticing.","zh":"任何進步都值得注意。"},{"en":"He reviews his progress monthly.","zh":"他每月回顧他的進步。"}]},{"word":"balance","pos":"noun/verb","chinese":"平衡","level":"A2","sentences":[{"en":"She found balance after years of trying.","zh":"多年嘗試後她找到了平衡。"},{"en":"Balance is a daily practice.","zh":"平衡是一種日常練習。"},{"en":"He balances work and rest well.","zh":"他很好地平衡工作和休息。"},{"en":"Find balance between effort and ease.","zh":"在努力和輕鬆之間找到平衡。"},{"en":"Balance does not mean equal.","zh":"平衡不意味著相等。"},{"en":"She balances many roles gracefully.","zh":"她優雅地平衡許多角色。"},{"en":"Balance protects you from burnout.","zh":"平衡保護你免於倦怠。"},{"en":"He restored balance to his life.","zh":"他恢復了生活的平衡。"},{"en":"Balance is found, then lost, then found again.","zh":"平衡被找到、失去、再找到。"},{"en":"Seek balance, not constant intensity.","zh":"尋求平衡，而不是持續的強度。"}]},{"word":"comfort","pos":"noun/verb","chinese":"舒適；安慰","level":"A2","sentences":[{"en":"She offers comfort without judgment.","zh":"她不帶評判地提供安慰。"},{"en":"Comfort can become a trap.","zh":"舒適可能成為陷阱。"},{"en":"He found comfort in routine.","zh":"他在常規中找到舒適。"},{"en":"Step outside your comfort zone.","zh":"走出你的舒適區。"},{"en":"Her words brought real comfort.","zh":"她的話帶來了真正的安慰。"},{"en":"Comfort and growth rarely coexist.","zh":"舒適和成長很少共存。"},{"en":"She comforts others naturally.","zh":"她自然地安慰別人。"},{"en":"Find comfort in small rituals.","zh":"在小儀式中找到舒適。"},{"en":"He chose growth over comfort.","zh":"他選擇成長而不是舒適。"},{"en":"True comfort comes from within.","zh":"真正的舒適來自內心。"}]},{"word":"energy","pos":"noun","chinese":"能量；精力","level":"A2","sentences":[{"en":"Protect your energy carefully.","zh":"小心保護你的能量。"},{"en":"She brings positive energy everywhere.","zh":"她到處帶來正能量。"},{"en":"Manage energy, not just time.","zh":"管理能量，而不只是時間。"},{"en":"He guards his energy fiercely.","zh":"他強烈地守護他的能量。"},{"en":"Low energy days are normal.","zh":"低能量的日子是正常的。"},{"en":"Spend energy on what matters.","zh":"把精力花在重要的事情上。"},{"en":"Her energy is contagious.","zh":"她的能量有感染力。"},{"en":"Rest restores your energy.","zh":"休息恢復你的能量。"},{"en":"Notice what drains your energy.","zh":"注意什麼耗盡你的能量。"},{"en":"Give your energy to people who return it.","zh":"把你的能量給那些回報它的人。"}]},{"word":"focus","pos":"noun/verb","chinese":"專注；焦點","level":"A2","sentences":[{"en":"Focus on one thing at a time.","zh":"一次專注於一件事。"},{"en":"She focuses deeply for short bursts.","zh":"她在短時間內深度專注。"},{"en":"Focus is the new superpower.","zh":"專注是新的超能力。"},{"en":"He removed distractions to focus.","zh":"他消除干擾以專注。"},{"en":"Focus on what you can control.","zh":"專注於你能控制的。"},{"en":"Her focus is unshakeable.","zh":"她的專注力不可動搖。"},{"en":"Lost focus is found in silence.","zh":"失去的專注在寂靜中找到。"},{"en":"Focus turns effort into results.","zh":"專注把努力變成結果。"},{"en":"He focuses on progress, not perfection.","zh":"他專注於進步，而不是完美。"},{"en":"Protect your focus like a treasure.","zh":"像珍寶一樣保護你的專注力。"}]},{"word":"routine","pos":"noun","chinese":"例行公事；常規","level":"A2","sentences":[{"en":"A good routine frees the mind.","zh":"好的常規解放心靈。"},{"en":"She built a calm morning routine.","zh":"她建立了一個平靜的早晨常規。"},{"en":"Routine creates space for creativity.","zh":"常規為創造力創造空間。"},{"en":"He thrives on a simple routine.","zh":"他在簡單的常規中茁壯成長。"},{"en":"Change your routine to change your life.","zh":"改變你的常規來改變你的生活。"},{"en":"Her evening routine helps her sleep.","zh":"她的晚間常規幫助她睡眠。"},{"en":"Routine is underrated comfort.","zh":"常規是被低估的舒適。"},{"en":"Build a routine you do not need to escape.","zh":"建立一個你不需要逃離的常規。"},{"en":"A flexible routine works best.","zh":"靈活的常規效果最好。"},{"en":"Routine reduces decision fatigue.","zh":"常規減少決策疲勞。"}]},{"word":"attention","pos":"noun","chinese":"注意；關注","level":"A2","sentences":[{"en":"Where attention goes, energy flows.","zh":"注意力去哪裡，能量就流向哪裡。"},{"en":"She pays attention to the details.","zh":"她注意細節。"},{"en":"Attention is the rarest gift.","zh":"注意力是最稀有的禮物。"},{"en":"He gives full attention when listening.","zh":"他傾聽時給予全部注意力。"},{"en":"Protect your attention from noise.","zh":"保護你的注意力免受噪音。"},{"en":"Her attention to others is genuine.","zh":"她對別人的關注是真誠的。"},{"en":"Attention shapes what you notice.","zh":"注意力塑造你注意到什麼。"},{"en":"Give attention to what matters most.","zh":"關注最重要的事情。"},{"en":"Undivided attention is true respect.","zh":"全神貫注是真正的尊重。"},{"en":"He trained his attention like a muscle.","zh":"他像鍛鍊肌肉一樣訓練他的注意力。"}]},{"word":"success","pos":"noun","chinese":"成功","level":"A2","sentences":[{"en":"Success means different things to different people.","zh":"成功對不同的人意味著不同的東西。"},{"en":"She defines success on her own terms.","zh":"她以自己的標準定義成功。"},{"en":"Success is built on daily habits.","zh":"成功建立在每天的習慣上。"},{"en":"He found success after many failures.","zh":"他在多次失敗後找到了成功。"},{"en":"Success without fulfilment is empty.","zh":"沒有滿足感的成功是空洞的。"},{"en":"Quiet success is still success.","zh":"安靜的成功仍然是成功。"},{"en":"She measures success by impact.","zh":"她用影響力來衡量成功。"},{"en":"Success requires patience and grit.","zh":"成功需要耐心和毅力。"},{"en":"Real success is becoming yourself.","zh":"真正的成功是成為你自己。"},{"en":"Celebrate success, then keep going.","zh":"慶祝成功，然後繼續前進。"}]},{"word":"failure","pos":"noun","chinese":"失敗","level":"A2","sentences":[{"en":"Failure is part of every success story.","zh":"失敗是每個成功故事的一部分。"},{"en":"She reframed failure as feedback.","zh":"她把失敗重新框架為反饋。"},{"en":"Failure teaches what success cannot.","zh":"失敗教成功無法教的東西。"},{"en":"He embraced failure as a teacher.","zh":"他把失敗當作老師。"},{"en":"Fear of failure stops more than failure.","zh":"對失敗的恐懼比失敗本身阻止更多。"},{"en":"Every failure brought her closer.","zh":"每次失敗都讓她更接近。"},{"en":"Failure is not the opposite of success.","zh":"失敗不是成功的反面。"},{"en":"He failed forward every time.","zh":"他每次都向前失敗。"},{"en":"Failure is data, not identity.","zh":"失敗是數據，不是身份。"},{"en":"She learned more from failure than wins.","zh":"她從失敗中學到的比勝利更多。"}]},{"word":"freedom","pos":"noun","chinese":"自由","level":"A2","sentences":[{"en":"Freedom is having real choices.","zh":"自由是有真正的選擇。"},{"en":"She values freedom over comfort.","zh":"她重視自由勝過舒適。"},{"en":"Financial freedom is about options.","zh":"財務自由是關於選擇。"},{"en":"He found freedom in simplicity.","zh":"他在簡單中找到了自由。"},{"en":"Freedom comes with responsibility.","zh":"自由伴隨著責任。"},{"en":"True freedom is inner peace.","zh":"真正的自由是內心的平靜。"},{"en":"She built a life of freedom slowly.","zh":"她慢慢建立了一個自由的生活。"},{"en":"Freedom means saying no without guilt.","zh":"自由意味著無愧疚地說不。"},{"en":"He traded security for freedom.","zh":"他用安全換取了自由。"},{"en":"Freedom is a daily practice.","zh":"自由是一種日常練習。"}]},{"word":"growth","pos":"noun","chinese":"成長","level":"A2","sentences":[{"en":"Growth happens outside comfort.","zh":"成長發生在舒適區之外。"},{"en":"She chooses growth over ease.","zh":"她選擇成長而不是輕鬆。"},{"en":"Growth is rarely comfortable.","zh":"成長很少是舒適的。"},{"en":"He measures growth in small steps.","zh":"他用小步驟衡量成長。"},{"en":"Real growth is often invisible.","zh":"真正的成長往往是看不見的。"},{"en":"Growth requires letting go.","zh":"成長需要放手。"},{"en":"She embraced growth through change.","zh":"她通過改變擁抱成長。"},{"en":"Personal growth never really ends.","zh":"個人成長從不真正結束。"},{"en":"Growth comes from doing hard things.","zh":"成長來自做困難的事情。"},{"en":"Choose growth even when it scares you.","zh":"即使它讓你害怕也選擇成長。"}]},{"word":"peace","pos":"noun","chinese":"平靜；和平","level":"A2","sentences":[{"en":"She protects her peace fiercely.","zh":"她強烈地保護她的平靜。"},{"en":"Peace is worth more than being right.","zh":"平靜比爭對錯更有價值。"},{"en":"He found peace in letting go.","zh":"他在放手中找到了平靜。"},{"en":"Inner peace comes from acceptance.","zh":"內心的平靜來自接受。"},{"en":"Choose peace over unnecessary conflict.","zh":"選擇平靜而不是不必要的衝突。"},{"en":"Her calm brings peace to others.","zh":"她的冷靜給別人帶來平靜。"},{"en":"Peace is a daily choice.","zh":"平靜是每天的選擇。"},{"en":"He made peace with his past.","zh":"他與他的過去和解了。"},{"en":"Seek peace, not constant excitement.","zh":"尋求平靜，而不是持續的興奮。"},{"en":"Peace begins with a single breath.","zh":"平靜始於一次呼吸。"}]},{"word":"truth","pos":"noun","chinese":"真相；真理","level":"A2","sentences":[{"en":"The truth is often simple.","zh":"真相往往是簡單的。"},{"en":"She speaks the truth with kindness.","zh":"她以善意說真話。"},{"en":"Truth builds trust over time.","zh":"真相隨時間建立信任。"},{"en":"He values truth over comfort.","zh":"他重視真相勝過舒適。"},{"en":"The truth set her free.","zh":"真相讓她自由。"},{"en":"Speak your truth gently.","zh":"溫柔地說出你的真相。"},{"en":"Truth is rarely convenient.","zh":"真相很少方便。"},{"en":"She faced the truth bravely.","zh":"她勇敢地面對真相。"},{"en":"Half-truths cause whole problems.","zh":"半真半假導致完整的問題。"},{"en":"Live in alignment with your truth.","zh":"與你的真相一致地生活。"}]},{"word":"silence","pos":"noun","chinese":"沉默；寂靜","level":"A2","sentences":[{"en":"She finds clarity in silence.","zh":"她在寂靜中找到清晰。"},{"en":"Silence can be a full answer.","zh":"沉默可以是一個完整的答案。"},{"en":"He uses silence to think clearly.","zh":"他用沉默來清晰地思考。"},{"en":"Comfortable silence is a sign of trust.","zh":"舒適的沉默是信任的標誌。"},{"en":"Silence is sometimes the strongest reply.","zh":"沉默有時是最強的回應。"},{"en":"She craves silence after busy days.","zh":"忙碌的日子後她渴望寂靜。"},{"en":"In silence, she heard herself.","zh":"在寂靜中，她聽到了自己。"},{"en":"Silence creates space for thought.","zh":"沉默為思考創造空間。"},{"en":"He values silence as much as conversation.","zh":"他重視沉默和對話一樣多。"},{"en":"Learn to sit with silence.","zh":"學會與沉默共處。"}]},{"word":"gratitude","pos":"noun","chinese":"感恩","level":"A2","sentences":[{"en":"Gratitude changes how you see life.","zh":"感恩改變你看待生活的方式。"},{"en":"She practises gratitude every morning.","zh":"她每天早上練習感恩。"},{"en":"Gratitude turns enough into plenty.","zh":"感恩把足夠變成豐盛。"},{"en":"He keeps a gratitude journal.","zh":"他保持一個感恩日記。"},{"en":"Gratitude is the antidote to envy.","zh":"感恩是嫉妒的解藥。"},{"en":"Start the day with gratitude.","zh":"以感恩開始一天。"},{"en":"Her gratitude is genuine and quiet.","zh":"她的感恩是真誠而安靜的。"},{"en":"Gratitude grows the more you use it.","zh":"感恩越用越多。"},{"en":"Express gratitude before it is too late.","zh":"在為時已晚之前表達感恩。"},{"en":"Gratitude makes ordinary days special.","zh":"感恩讓平凡的日子變得特別。"}]},{"word":"patience","pos":"noun","chinese":"耐心","level":"A2","sentences":[{"en":"Patience is a quiet strength.","zh":"耐心是一種安靜的力量。"},{"en":"She learned patience the hard way.","zh":"她艱難地學會了耐心。"},{"en":"Patience turns dreams into reality.","zh":"耐心把夢想變成現實。"},{"en":"He waits with calm patience.","zh":"他以冷靜的耐心等待。"},{"en":"Patience is loving the process.","zh":"耐心是熱愛這個過程。"},{"en":"Her patience never seems to run out.","zh":"她的耐心似乎永不耗盡。"},{"en":"Practise patience with yourself first.","zh":"首先對自己練習耐心。"},{"en":"Patience is the companion of wisdom.","zh":"耐心是智慧的伴侶。"},{"en":"Great things take patient effort.","zh":"偉大的事情需要耐心的努力。"},{"en":"Patience is a skill, not a trait.","zh":"耐心是一種技能，不是特質。"}]},{"word":"repair","pos":"verb/noun","chinese":"修理；修補","level":"A2","sentences":[{"en":"He repairs old furniture as a hobby.","zh":"他修理舊家具作為愛好。"},{"en":"Some relationships need repair, not ending.","zh":"有些關係需要修補，而不是結束。"},{"en":"She repaired the friendship with honesty.","zh":"她用誠實修補了友誼。"},{"en":"Repair what is worth keeping.","zh":"修補值得保留的東西。"},{"en":"He repaired the bike himself.","zh":"他自己修好了自行車。"},{"en":"Trust takes time to repair.","zh":"信任需要時間來修補。"},{"en":"She made the repair quickly.","zh":"她迅速完成了修理。"},{"en":"Repairing is greener than replacing.","zh":"修補比替換更環保。"},{"en":"He repaired the damage gently.","zh":"他溫和地修補了損害。"},{"en":"A small repair prevents a big break.","zh":"小修補防止大破裂。"}]},{"word":"strategy","pos":"noun","chinese":"策略；計策","level":"B1","sentences":[{"en":"She has a clear strategy for growth.","zh":"她有一個清晰的成長策略。"},{"en":"A good strategy beats raw effort.","zh":"好的策略勝過蠻力。"},{"en":"He changed strategy when it stopped working.","zh":"當它不再奏效時他改變了策略。"},{"en":"Strategy without action is just theory.","zh":"沒有行動的策略只是理論。"},{"en":"Her strategy was simple but effective.","zh":"她的策略簡單但有效。"},{"en":"Build a strategy around your strengths.","zh":"圍繞你的優勢建立策略。"},{"en":"He thinks in strategy, not tactics.","zh":"他以策略思考，而不是戰術。"},{"en":"A long-term strategy needs patience.","zh":"長期策略需要耐心。"},{"en":"She adjusted her strategy mid-way.","zh":"她中途調整了她的策略。"},{"en":"The best strategy is often the simplest.","zh":"最好的策略往往是最簡單的。"}]},{"word":"resource","pos":"noun","chinese":"資源","level":"B1","sentences":[{"en":"She uses every resource available.","zh":"她使用所有可用的資源。"},{"en":"Time is your most valuable resource.","zh":"時間是你最寶貴的資源。"},{"en":"He is resourceful when money is tight.","zh":"當錢緊時他很機智。"},{"en":"Resources are limited, attention more so.","zh":"資源有限，注意力更是如此。"},{"en":"She turned a small resource into a lot.","zh":"她把小資源變成了很多。"},{"en":"Free resources can teach you anything.","zh":"免費資源可以教你任何東西。"},{"en":"Protect your inner resources too.","zh":"也保護你的內在資源。"},{"en":"He shared his resources generously.","zh":"他慷慨地分享他的資源。"},{"en":"Energy is a resource worth budgeting.","zh":"能量是值得預算的資源。"},{"en":"Use resources wisely, not wastefully.","zh":"明智地使用資源，而不是浪費。"}]},{"word":"impact","pos":"noun/verb","chinese":"影響；衝擊","level":"B1","sentences":[{"en":"She made a real impact quietly.","zh":"她安靜地產生了真正的影響。"},{"en":"Small actions can have a big impact.","zh":"小行動可以產生大影響。"},{"en":"He measures impact, not just activity.","zh":"他衡量影響，而不只是活動。"},{"en":"Your words impact more than you know.","zh":"你的話的影響比你知道的更大。"},{"en":"She wants to leave a positive impact.","zh":"她想留下積極的影響。"},{"en":"Impact matters more than intention.","zh":"影響比意圖更重要。"},{"en":"The impact was felt for years.","zh":"這個影響被感受了多年。"},{"en":"He focuses on high-impact work.","zh":"他專注於高影響力的工作。"},{"en":"Her kindness had a ripple impact.","zh":"她的善良產生了漣漪般的影響。"},{"en":"Impact comes from consistency.","zh":"影響來自一致性。"}]},{"word":"factor","pos":"noun","chinese":"因素；要素","level":"B1","sentences":[{"en":"Sleep is a major factor in mood.","zh":"睡眠是情緒的主要因素。"},{"en":"Consider every factor before deciding.","zh":"決定前考慮每個因素。"},{"en":"Luck is one factor, effort is another.","zh":"運氣是一個因素，努力是另一個。"},{"en":"The key factor was timing.","zh":"關鍵因素是時機。"},{"en":"Many factors shape who we become.","zh":"許多因素塑造我們成為誰。"},{"en":"She identified the deciding factor.","zh":"她識別了決定性因素。"},{"en":"Health is a factor we often ignore.","zh":"健康是我們經常忽略的因素。"},{"en":"Several factors led to success.","zh":"幾個因素導致了成功。"},{"en":"The human factor matters most.","zh":"人的因素最重要。"},{"en":"He weighed all the factors carefully.","zh":"他仔細權衡了所有因素。"}]},{"word":"process","pos":"noun","chinese":"過程；流程","level":"B1","sentences":[{"en":"Trust the process even when slow.","zh":"即使緩慢也要相信過程。"},{"en":"She enjoys the process, not just the result.","zh":"她享受過程，而不只是結果。"},{"en":"Healing is a process, not an event.","zh":"療癒是一個過程，不是一個事件。"},{"en":"He simplified the whole process.","zh":"他簡化了整個流程。"},{"en":"Fall in love with the process.","zh":"愛上這個過程。"},{"en":"The creative process takes time.","zh":"創作過程需要時間。"},{"en":"She documents her process openly.","zh":"她公開記錄她的過程。"},{"en":"Respect the process of growth.","zh":"尊重成長的過程。"},{"en":"Every process can be improved.","zh":"每個過程都可以改進。"},{"en":"Focus on process over outcome.","zh":"專注於過程而不是結果。"}]},{"word":"system","pos":"noun","chinese":"系統；制度","level":"B1","sentences":[{"en":"She built a system that runs itself.","zh":"她建立了一個自動運行的系統。"},{"en":"Systems beat motivation every time.","zh":"系統每次都勝過動機。"},{"en":"He trusts systems over willpower.","zh":"他相信系統勝過意志力。"},{"en":"A simple system is easy to keep.","zh":"簡單的系統容易保持。"},{"en":"Build systems for your weak moments.","zh":"為你軟弱的時刻建立系統。"},{"en":"The system worked even on bad days.","zh":"即使在糟糕的日子系統也能運作。"},{"en":"She designed a system for everything.","zh":"她為一切設計了一個系統。"},{"en":"Good systems reduce daily decisions.","zh":"好的系統減少日常決定。"},{"en":"Fix the system, not just the symptom.","zh":"修復系統，而不只是症狀。"},{"en":"A reliable system creates freedom.","zh":"可靠的系統創造自由。"}]},{"word":"method","pos":"noun","chinese":"方法","level":"B1","sentences":[{"en":"She found a method that suits her.","zh":"她找到了一個適合她的方法。"},{"en":"There is a method to his calm.","zh":"他的冷靜是有方法的。"},{"en":"Try a different method if one fails.","zh":"如果一個失敗就試試不同的方法。"},{"en":"His method is slow but thorough.","zh":"他的方法緩慢但徹底。"},{"en":"The method matters less than consistency.","zh":"方法不如一致性重要。"},{"en":"She teaches a simple method.","zh":"她教一個簡單的方法。"},{"en":"Choose a method you will actually use.","zh":"選擇一個你真正會用的方法。"},{"en":"The scientific method values evidence.","zh":"科學方法重視證據。"},{"en":"He refined his method over years.","zh":"他多年精煉他的方法。"},{"en":"A clear method removes confusion.","zh":"清晰的方法消除混亂。"}]},{"word":"structure","pos":"noun","chinese":"結構；架構","level":"B1","sentences":[{"en":"Structure brings freedom, not limits.","zh":"結構帶來自由，而不是限制。"},{"en":"She added structure to her chaotic days.","zh":"她為混亂的日子增加了結構。"},{"en":"A clear structure makes work easier.","zh":"清晰的結構讓工作更容易。"},{"en":"He thrives within a loose structure.","zh":"他在寬鬆的結構中茁壯成長。"},{"en":"Structure supports creativity.","zh":"結構支持創造力。"},{"en":"She built structure around her goals.","zh":"她圍繞她的目標建立了結構。"},{"en":"Too much structure can suffocate.","zh":"太多的結構會令人窒息。"},{"en":"Find the structure that fits you.","zh":"找到適合你的結構。"},{"en":"Structure your day around energy.","zh":"圍繞能量構建你的一天。"},{"en":"A good structure holds everything together.","zh":"好的結構把一切凝聚在一起。"}]},{"word":"quality","pos":"noun","chinese":"品質；質量","level":"B1","sentences":[{"en":"She chooses quality over quantity.","zh":"她選擇品質而不是數量。"},{"en":"Quality time matters more than quantity.","zh":"高質量的時間比數量更重要。"},{"en":"He builds quality into everything.","zh":"他把品質融入一切。"},{"en":"Quality work speaks for itself.","zh":"高質量的工作不言自明。"},{"en":"The quality of your questions matters.","zh":"你問題的質量很重要。"},{"en":"She values quality relationships.","zh":"她重視高質量的關係。"},{"en":"Quality requires patience and care.","zh":"品質需要耐心和關懷。"},{"en":"Choose a few quality things.","zh":"選擇少數高質量的東西。"},{"en":"Quality of life beats quantity of stuff.","zh":"生活質量勝過物質數量。"},{"en":"He maintains quality under pressure.","zh":"他在壓力下保持質量。"}]},{"word":"standard","pos":"noun","chinese":"標準","level":"B1","sentences":[{"en":"She holds herself to a high standard.","zh":"她對自己有高標準。"},{"en":"Set the standard, do not lower it.","zh":"設定標準，不要降低它。"},{"en":"His standards never slip.","zh":"他的標準從不下滑。"},{"en":"Raise your standards slowly but surely.","zh":"緩慢但確定地提高你的標準。"},{"en":"She has high standards and warm patience.","zh":"她有高標準和溫暖的耐心。"},{"en":"Standards shape what you accept.","zh":"標準塑造你接受什麼。"},{"en":"He sets the standard by example.","zh":"他以身作則設定標準。"},{"en":"Hold your standards, even when tired.","zh":"堅持你的標準，即使累了。"},{"en":"Lower your stress, not your standards.","zh":"降低你的壓力，而不是你的標準。"},{"en":"Her standard of kindness inspires others.","zh":"她的善良標準激勵別人。"}]},{"word":"principle","pos":"noun","chinese":"原則；原理","level":"B1","sentences":[{"en":"She lives by a few clear principles.","zh":"她按照幾個清晰的原則生活。"},{"en":"Principles guide better than rules.","zh":"原則比規則更能指導。"},{"en":"He never compromises his principles.","zh":"他從不妥協他的原則。"},{"en":"Build your life on solid principles.","zh":"在堅實的原則上建立你的生活。"},{"en":"A principle is a rule you choose.","zh":"原則是你選擇的規則。"},{"en":"She explained the principle simply.","zh":"她簡單地解釋了原理。"},{"en":"Principles stay; tactics change.","zh":"原則保持；戰術改變。"},{"en":"He acts from principle, not pressure.","zh":"他從原則行動，而不是壓力。"},{"en":"Know your principles before deciding.","zh":"在決定之前了解你的原則。"},{"en":"Strong principles make hard choices easier.","zh":"堅強的原則讓艱難的選擇更容易。"}]},{"word":"concept","pos":"noun","chinese":"概念；觀念","level":"B1","sentences":[{"en":"She grasps new concepts quickly.","zh":"她快速掌握新概念。"},{"en":"The concept is simple but powerful.","zh":"這個概念簡單但有力。"},{"en":"He explained the concept with a story.","zh":"他用一個故事解釋了這個概念。"},{"en":"Some concepts take time to sink in.","zh":"有些概念需要時間才能領會。"},{"en":"She challenged an old concept.","zh":"她挑戰了一個舊概念。"},{"en":"A clear concept guides good design.","zh":"清晰的概念指導好的設計。"},{"en":"He built the whole plan on one concept.","zh":"他在一個概念上建立了整個計畫。"},{"en":"The concept changed how I think.","zh":"這個概念改變了我的思維方式。"},{"en":"Understanding the concept is step one.","zh":"理解概念是第一步。"},{"en":"She turned a concept into reality.","zh":"她把一個概念變成了現實。"}]},{"word":"context","pos":"noun","chinese":"背景；脈絡","level":"B1","sentences":[{"en":"Context changes the whole meaning.","zh":"脈絡改變了整個意義。"},{"en":"She considers the context first.","zh":"她首先考慮背景。"},{"en":"Without context, facts mislead.","zh":"沒有背景，事實會誤導。"},{"en":"He always provides helpful context.","zh":"他總是提供有用的背景。"},{"en":"Context matters more than the words.","zh":"脈絡比文字更重要。"},{"en":"She read the situation in context.","zh":"她在脈絡中解讀情況。"},{"en":"Give context before giving advice.","zh":"在給建議之前提供背景。"},{"en":"The same act means different things in context.","zh":"同樣的行為在不同背景中意義不同。"},{"en":"He understood the deeper context.","zh":"他理解了更深的脈絡。"},{"en":"Always seek the full context.","zh":"總是尋求完整的脈絡。"}]},{"word":"element","pos":"noun","chinese":"元素；要素","level":"B1","sentences":[{"en":"Trust is the key element of any team.","zh":"信任是任何團隊的關鍵要素。"},{"en":"She added a playful element to her work.","zh":"她為她的工作增加了一個有趣的元素。"},{"en":"Each element plays its part.","zh":"每個元素都發揮其作用。"},{"en":"He identified the missing element.","zh":"他識別了缺失的元素。"},{"en":"Simplicity is an underrated element.","zh":"簡單是一個被低估的元素。"},{"en":"The human element makes it special.","zh":"人的因素讓它特別。"},{"en":"She balanced every element carefully.","zh":"她仔細地平衡每個元素。"},{"en":"One element can transform the whole.","zh":"一個元素可以改變整體。"},{"en":"Find the essential elements first.","zh":"首先找到基本要素。"},{"en":"He combined elements creatively.","zh":"他創造性地組合了元素。"}]},{"word":"feature","pos":"noun","chinese":"特徵；特色","level":"B1","sentences":[{"en":"Her best feature is her kindness.","zh":"她最好的特徵是她的善良。"},{"en":"This feature changed how I work.","zh":"這個功能改變了我的工作方式。"},{"en":"He highlighted the key feature.","zh":"他強調了關鍵特徵。"},{"en":"A bug is sometimes a feature.","zh":"有時候 bug 就是特色。"},{"en":"The main feature is its simplicity.","zh":"主要特色是它的簡單。"},{"en":"She loves the small features most.","zh":"她最喜歡小特色。"},{"en":"Every feature should serve a purpose.","zh":"每個功能都應該服務一個目的。"},{"en":"That feature makes all the difference.","zh":"那個功能造成了全部的差異。"},{"en":"He removed features to improve focus.","zh":"他移除功能以改善專注。"},{"en":"Her warmth is her defining feature.","zh":"她的溫暖是她的決定性特徵。"}]},{"word":"aspect","pos":"noun","chinese":"方面；層面","level":"B1","sentences":[{"en":"Every aspect was carefully planned.","zh":"每個方面都經過仔細計畫。"},{"en":"She considers all aspects of a decision.","zh":"她考慮決定的所有方面。"},{"en":"The hardest aspect was the waiting.","zh":"最難的方面是等待。"},{"en":"He enjoys every aspect of his work.","zh":"他享受他工作的每個方面。"},{"en":"Look at the positive aspect too.","zh":"也看看積極的方面。"},{"en":"One aspect often gets ignored.","zh":"一個方面經常被忽略。"},{"en":"She improved every aspect slowly.","zh":"她慢慢改善了每個方面。"},{"en":"The social aspect matters to him.","zh":"社交方面對他很重要。"},{"en":"Consider the emotional aspect.","zh":"考慮情感方面。"},{"en":"Each aspect connects to the others.","zh":"每個方面都與其他方面相連。"}]},{"word":"detail","pos":"noun","chinese":"細節","level":"B1","sentences":[{"en":"She notices details others miss.","zh":"她注意到別人錯過的細節。"},{"en":"The detail makes all the difference.","zh":"細節造成了全部的差異。"},{"en":"He cares about the small details.","zh":"他在意小細節。"},{"en":"Detail without overwhelm is the art.","zh":"細節而不過度是一門藝術。"},{"en":"She remembers tiny details.","zh":"她記得微小的細節。"},{"en":"Get the big picture, then the details.","zh":"先看大局，再看細節。"},{"en":"Attention to detail builds trust.","zh":"對細節的關注建立信任。"},{"en":"He sweats the details that matter.","zh":"他在意重要的細節。"},{"en":"Details reveal real care.","zh":"細節揭示真正的關心。"},{"en":"She balances detail with vision.","zh":"她平衡細節與願景。"}]},{"word":"situation","pos":"noun","chinese":"情況；處境","level":"B1","sentences":[{"en":"She handled the situation calmly.","zh":"她冷靜地處理了情況。"},{"en":"Assess the situation before acting.","zh":"行動前評估情況。"},{"en":"He stayed kind in a hard situation.","zh":"在艱難的情況下他保持善良。"},{"en":"Every situation teaches something.","zh":"每種情況都教會一些東西。"},{"en":"She turned the situation around.","zh":"她扭轉了情況。"},{"en":"Read the situation before speaking.","zh":"說話前讀懂情況。"},{"en":"The situation improved with patience.","zh":"情況隨著耐心改善了。"},{"en":"He saw the situation clearly.","zh":"他清楚地看到了情況。"},{"en":"Adapt to the situation you are in.","zh":"適應你所處的情況。"},{"en":"She made the best of a bad situation.","zh":"她把糟糕的情況做到最好。"}]},{"word":"condition","pos":"noun","chinese":"條件；狀況","level":"B1","sentences":[{"en":"Set clear conditions before agreeing.","zh":"同意前設定清晰的條件。"},{"en":"Her condition improved with rest.","zh":"她的狀況隨著休息改善了。"},{"en":"He works well under any condition.","zh":"他在任何條件下都工作得好。"},{"en":"On one condition, she said yes.","zh":"在一個條件下，她說好。"},{"en":"Good conditions make growth easier.","zh":"好的條件讓成長更容易。"},{"en":"The condition of the room affects mood.","zh":"房間的狀況影響情緒。"},{"en":"He set fair conditions for everyone.","zh":"他為每個人設定了公平的條件。"},{"en":"Love without conditions is rare.","zh":"無條件的愛是罕見的。"},{"en":"She accepted the terms and conditions.","zh":"她接受了條款和條件。"},{"en":"Improve the conditions, improve the result.","zh":"改善條件，改善結果。"}]},{"word":"environment","pos":"noun","chinese":"環境","level":"B1","sentences":[{"en":"Your environment shapes your habits.","zh":"你的環境塑造你的習慣。"},{"en":"She created a calm work environment.","zh":"她創造了一個平靜的工作環境。"},{"en":"A positive environment lifts everyone.","zh":"積極的環境提升每個人。"},{"en":"He thrives in a quiet environment.","zh":"他在安靜的環境中茁壯成長。"},{"en":"Change your environment to change yourself.","zh":"改變你的環境來改變你自己。"},{"en":"The environment encourages focus.","zh":"這個環境鼓勵專注。"},{"en":"She protects her home environment.","zh":"她保護她的家庭環境。"},{"en":"A supportive environment is everything.","zh":"支持性的環境就是一切。"},{"en":"Design your environment for success.","zh":"為成功設計你的環境。"},{"en":"He noticed how environment affects energy.","zh":"他注意到環境如何影響能量。"}]},{"word":"community","pos":"noun","chinese":"社區；社群","level":"B1","sentences":[{"en":"She found her community online.","zh":"她在網上找到了她的社群。"},{"en":"Community gives a sense of belonging.","zh":"社群給人歸屬感。"},{"en":"He built a community around shared values.","zh":"他圍繞共同價值觀建立了一個社群。"},{"en":"A strong community supports each other.","zh":"強大的社群互相支持。"},{"en":"She gives back to her community.","zh":"她回饋她的社區。"},{"en":"Community is built, not found.","zh":"社群是建立的，不是找到的。"},{"en":"He found belonging in a small community.","zh":"他在一個小社群中找到了歸屬感。"},{"en":"Community thrives on contribution.","zh":"社群在貢獻中蓬勃發展。"},{"en":"She values community over competition.","zh":"她重視社群勝過競爭。"},{"en":"A good community feels like home.","zh":"好的社群感覺像家。"}]},{"word":"culture","pos":"noun","chinese":"文化","level":"B1","sentences":[{"en":"Culture eats strategy for breakfast.","zh":"文化把策略當早餐吃。"},{"en":"She respects every culture she meets.","zh":"她尊重她遇到的每種文化。"},{"en":"Company culture shapes daily life.","zh":"公司文化塑造日常生活。"},{"en":"He learned the culture before judging.","zh":"他在評判之前了解了文化。"},{"en":"Culture is built by small daily actions.","zh":"文化由每天的小行動建立。"},{"en":"A healthy culture welcomes questions.","zh":"健康的文化歡迎問題。"},{"en":"She embraced a different culture fully.","zh":"她完全擁抱了一種不同的文化。"},{"en":"Culture lives in the unwritten rules.","zh":"文化存在於不成文的規則中。"},{"en":"They built a culture of trust.","zh":"他們建立了一個信任的文化。"},{"en":"Culture changes one habit at a time.","zh":"文化一次改變一個習慣。"}]},{"word":"society","pos":"noun","chinese":"社會","level":"B1","sentences":[{"en":"Society shapes us more than we notice.","zh":"社會對我們的塑造比我們注意到的更多。"},{"en":"She questions what society expects.","zh":"她質疑社會期望什麼。"},{"en":"A kind society starts with individuals.","zh":"善良的社會始於個人。"},{"en":"He contributes to society quietly.","zh":"他默默地貢獻社會。"},{"en":"Society moves slowly, then suddenly.","zh":"社會緩慢移動，然後突然。"},{"en":"She wants a fairer society.","zh":"她想要一個更公平的社會。"},{"en":"Society values speed over depth.","zh":"社會重視速度勝過深度。"},{"en":"Real change in society takes time.","zh":"社會的真正改變需要時間。"},{"en":"He studies how society works.","zh":"他研究社會如何運作。"},{"en":"Every society has its own rhythm.","zh":"每個社會都有自己的節奏。"}]},{"word":"generation","pos":"noun","chinese":"世代","level":"B1","sentences":[{"en":"Each generation learns differently.","zh":"每一代學習方式不同。"},{"en":"She bridges two generations easily.","zh":"她輕鬆地連接兩代人。"},{"en":"The next generation will solve this.","zh":"下一代會解決這個。"},{"en":"He broke a generational pattern.","zh":"他打破了一個代際模式。"},{"en":"Every generation faces new challenges.","zh":"每一代都面臨新的挑戰。"},{"en":"She learned wisdom from an older generation.","zh":"她從老一輩學到了智慧。"},{"en":"Generations share more than they differ.","zh":"世代之間的共同點多於差異。"},{"en":"He thinks about future generations.","zh":"他考慮未來的世代。"},{"en":"This generation values meaning.","zh":"這一代重視意義。"},{"en":"Pass kindness to the next generation.","zh":"把善良傳給下一代。"}]},{"word":"relationship","pos":"noun","chinese":"關係","level":"B1","sentences":[{"en":"Every relationship needs maintenance.","zh":"每段關係都需要維護。"},{"en":"She invests in her relationships daily.","zh":"她每天投資她的關係。"},{"en":"A good relationship feels easy and safe.","zh":"好的關係感覺輕鬆而安全。"},{"en":"He values the relationship over being right.","zh":"他重視關係勝過爭對錯。"},{"en":"Relationships grow through honesty.","zh":"關係通過誠實成長。"},{"en":"She left a relationship that drained her.","zh":"她離開了一段耗盡她的關係。"},{"en":"The relationship deepened over time.","zh":"關係隨時間加深。"},{"en":"Build a relationship with yourself first.","zh":"首先與自己建立關係。"},{"en":"Healthy relationships require boundaries.","zh":"健康的關係需要界限。"},{"en":"She nurtures every relationship gently.","zh":"她溫柔地培育每段關係。"}]},{"word":"connection","pos":"noun","chinese":"連結；聯繫","level":"B1","sentences":[{"en":"She craves genuine connection.","zh":"她渴望真正的連結。"},{"en":"Connection matters more than perfection.","zh":"連結比完美更重要。"},{"en":"He builds connection through listening.","zh":"他通過傾聽建立連結。"},{"en":"A real connection cannot be forced.","zh":"真正的連結無法強迫。"},{"en":"She felt an instant connection.","zh":"她感到了即刻的連結。"},{"en":"Deep connection requires vulnerability.","zh":"深層的連結需要脆弱。"},{"en":"He values quality of connection.","zh":"他重視連結的質量。"},{"en":"Connection is the heart of belonging.","zh":"連結是歸屬感的核心。"},{"en":"She maintains connection across distance.","zh":"她跨越距離維持連結。"},{"en":"Human connection heals more than advice.","zh":"人與人的連結比建議更能療癒。"}]},{"word":"knowledge","pos":"noun","chinese":"知識","level":"B1","sentences":[{"en":"Knowledge grows when you share it.","zh":"知識在你分享它時成長。"},{"en":"She applies knowledge, not just collects it.","zh":"她應用知識，而不只是收集它。"},{"en":"Knowledge without action is useless.","zh":"沒有行動的知識是無用的。"},{"en":"He seeks knowledge for its own sake.","zh":"他為了知識本身而尋求知識。"},{"en":"Knowledge is power only when used.","zh":"知識只有在使用時才是力量。"},{"en":"She built deep knowledge over years.","zh":"她多年建立了深厚的知識。"},{"en":"Share your knowledge generously.","zh":"慷慨地分享你的知識。"},{"en":"Knowledge opens unexpected doors.","zh":"知識打開意想不到的門。"},{"en":"Turn knowledge into wisdom.","zh":"把知識轉化為智慧。"},{"en":"Knowledge is the one thing no one can take.","zh":"知識是沒有人能拿走的東西。"}]},{"word":"wisdom","pos":"noun","chinese":"智慧","level":"B1","sentences":[{"en":"Wisdom is knowledge plus experience.","zh":"智慧是知識加經驗。"},{"en":"She speaks with quiet wisdom.","zh":"她以安靜的智慧說話。"},{"en":"Wisdom knows when to stay silent.","zh":"智慧知道何時保持沉默。"},{"en":"He gained wisdom through failure.","zh":"他通過失敗獲得了智慧。"},{"en":"Wisdom is using what you know well.","zh":"智慧是好好運用你所知道的。"},{"en":"Old wisdom still holds true.","zh":"古老的智慧仍然成立。"},{"en":"She shares wisdom without lecturing.","zh":"她分享智慧而不說教。"},{"en":"Wisdom grows from reflection.","zh":"智慧從反思中成長。"},{"en":"True wisdom is humble.","zh":"真正的智慧是謙遜的。"},{"en":"Seek wisdom, not just information.","zh":"尋求智慧，而不只是信息。"}]},{"word":"insight","pos":"noun","chinese":"洞察；見解","level":"B1","sentences":[{"en":"One insight can change everything.","zh":"一個洞察可以改變一切。"},{"en":"She offers sharp, kind insights.","zh":"她提供敏銳、善意的見解。"},{"en":"His insight came from deep listening.","zh":"他的洞察來自深度傾聽。"},{"en":"Insight without action fades.","zh":"沒有行動的洞察會消退。"},{"en":"She had an insight in the shower.","zh":"她在淋浴時有了一個洞察。"},{"en":"A small insight led to a big shift.","zh":"一個小洞察導致了一個大轉變。"},{"en":"He gathers insights from everyone.","zh":"他從每個人那裡收集見解。"},{"en":"Real insight feels both new and obvious.","zh":"真正的洞察既新又顯而易見。"},{"en":"Her insights helped me see clearly.","zh":"她的見解幫助我看清楚。"},{"en":"Capture insights before they vanish.","zh":"在洞察消失之前捕捉它們。"}]},{"word":"awareness","pos":"noun","chinese":"意識；覺察","level":"B1","sentences":[{"en":"Awareness is the first step to change.","zh":"覺察是改變的第一步。"},{"en":"She practises daily self-awareness.","zh":"她每天練習自我覺察。"},{"en":"Awareness without judgment heals.","zh":"不帶評判的覺察能療癒。"},{"en":"He brought awareness to his habits.","zh":"他把覺察帶到他的習慣中。"},{"en":"Greater awareness brings more choice.","zh":"更大的覺察帶來更多選擇。"},{"en":"Awareness changes the experience.","zh":"覺察改變體驗。"},{"en":"She raised awareness through her work.","zh":"她通過她的工作提高了意識。"},{"en":"Mindful awareness calms the mind.","zh":"正念覺察平靜心靈。"},{"en":"Awareness of your patterns is power.","zh":"對你模式的覺察是力量。"},{"en":"Start with awareness, then act.","zh":"從覺察開始，然後行動。"}]},{"word":"discipline","pos":"noun","chinese":"紀律；自律","level":"B1","sentences":[{"en":"Discipline is choosing what you want most.","zh":"自律是選擇你最想要的。"},{"en":"She built discipline through small wins.","zh":"她通過小勝利建立了自律。"},{"en":"Discipline beats motivation long-term.","zh":"長期來看自律勝過動機。"},{"en":"He values discipline over intensity.","zh":"他重視自律勝過強度。"},{"en":"Discipline is self-respect in action.","zh":"自律是行動中的自我尊重。"},{"en":"Gentle discipline lasts longer.","zh":"溫和的自律持續更久。"},{"en":"She has the discipline to rest too.","zh":"她也有休息的自律。"},{"en":"Discipline creates real freedom.","zh":"自律創造真正的自由。"},{"en":"Build discipline like a muscle.","zh":"像鍛鍊肌肉一樣建立自律。"},{"en":"Discipline turns dreams into routines.","zh":"自律把夢想變成常規。"}]},{"word":"courage","pos":"noun","chinese":"勇氣","level":"B1","sentences":[{"en":"Courage is acting despite fear.","zh":"勇氣是儘管恐懼仍然行動。"},{"en":"She found the courage to begin.","zh":"她找到了開始的勇氣。"},{"en":"Courage grows each time you use it.","zh":"勇氣每次使用都會增長。"},{"en":"He showed quiet courage daily.","zh":"他每天展現安靜的勇氣。"},{"en":"It takes courage to be honest.","zh":"誠實需要勇氣。"},{"en":"Courage is a choice, not a feeling.","zh":"勇氣是一個選擇，不是一種感覺。"},{"en":"She had the courage to start over.","zh":"她有重新開始的勇氣。"},{"en":"Small acts of courage add up.","zh":"小小的勇氣行為積少成多。"},{"en":"Courage means doing it scared.","zh":"勇氣意味著害怕著去做。"},{"en":"He found courage in community.","zh":"他在社群中找到了勇氣。"}]},{"word":"resilience","pos":"noun","chinese":"韌性；復原力","level":"B1","sentences":[{"en":"Resilience is built, not born.","zh":"韌性是建立的，不是天生的。"},{"en":"She bounced back with resilience.","zh":"她以韌性反彈回來。"},{"en":"Resilience grows through hardship.","zh":"韌性通過艱難成長。"},{"en":"He has remarkable emotional resilience.","zh":"他有非凡的情緒韌性。"},{"en":"Resilience means bending, not breaking.","zh":"韌性意味著彎曲，而不是斷裂。"},{"en":"She models resilience for her kids.","zh":"她為她的孩子樹立韌性的榜樣。"},{"en":"Resilience is recovering, again and again.","zh":"韌性是一次又一次地恢復。"},{"en":"Build resilience before you need it.","zh":"在你需要之前建立韌性。"},{"en":"Resilience is quiet strength.","zh":"韌性是安靜的力量。"},{"en":"He found resilience he did not know he had.","zh":"他發現了他不知道自己擁有的韌性。"}]},{"word":"motivation","pos":"noun","chinese":"動機；動力","level":"B1","sentences":[{"en":"Motivation gets you started; habit keeps you going.","zh":"動機讓你開始；習慣讓你繼續。"},{"en":"She finds motivation in her why.","zh":"她在她的原因中找到動力。"},{"en":"Motivation comes and goes; show up anyway.","zh":"動機來來去去；無論如何都出現。"},{"en":"He does not wait for motivation.","zh":"他不等待動機。"},{"en":"Intrinsic motivation lasts longest.","zh":"內在動機持續最久。"},{"en":"Her motivation is rooted in purpose.","zh":"她的動機根植於目的。"},{"en":"Motivation follows action, not the reverse.","zh":"動機跟隨行動，而不是相反。"},{"en":"Find motivation in small wins.","zh":"在小勝利中找到動力。"},{"en":"He stays motivated by remembering why.","zh":"他通過記住原因保持動力。"},{"en":"Motivation is overrated; discipline is reliable.","zh":"動機被高估了；自律是可靠的。"}]},{"word":"potential","pos":"noun","chinese":"潛力；潛能","level":"B1","sentences":[{"en":"She sees potential in everyone.","zh":"她在每個人身上看到潛力。"},{"en":"Reaching your potential requires discomfort.","zh":"實現你的潛力需要不適。"},{"en":"He has untapped potential.","zh":"他有未開發的潛力。"},{"en":"Potential means nothing without action.","zh":"沒有行動潛力毫無意義。"},{"en":"She helps others reach their potential.","zh":"她幫助別人實現他們的潛力。"},{"en":"Your potential is bigger than your fear.","zh":"你的潛力比你的恐懼更大。"},{"en":"He worked hard to fulfil his potential.","zh":"他努力工作以實現他的潛力。"},{"en":"Potential grows when you believe in it.","zh":"當你相信它時潛力會增長。"},{"en":"She saw potential where others saw problems.","zh":"她在別人看到問題的地方看到潛力。"},{"en":"Unlock your potential one step at a time.","zh":"一步一步釋放你的潛力。"}]},{"word":"accomplish","pos":"verb","chinese":"完成；達成","level":"B1","sentences":[{"en":"She accomplished more than she planned.","zh":"她完成的比她計畫的更多。"},{"en":"Accomplish one hard thing before noon.","zh":"在中午前完成一件困難的事。"},{"en":"He accomplishes goals quietly.","zh":"他安靜地達成目標。"},{"en":"Accomplishing small tasks builds momentum.","zh":"完成小任務建立動力。"},{"en":"She felt proud of what she accomplished.","zh":"她為她完成的事感到驕傲。"},{"en":"Accomplish the essential, skip the rest.","zh":"完成必要的，跳過其餘的。"},{"en":"He accomplished it through patience.","zh":"他通過耐心完成了它。"},{"en":"What do you want to accomplish this year?","zh":"你今年想完成什麼？"},{"en":"She accomplished her dream step by step.","zh":"她一步一步實現了她的夢想。"},{"en":"Accomplishment without rest leads to burnout.","zh":"沒有休息的成就導致倦怠。"}]},{"word":"overcome","pos":"verb","chinese":"克服；戰勝","level":"B1","sentences":[{"en":"She overcame her fear of speaking.","zh":"她克服了說話的恐懼。"},{"en":"Overcome obstacles one at a time.","zh":"一次克服一個障礙。"},{"en":"He overcame huge odds quietly.","zh":"他安靜地戰勝了巨大的困難。"},{"en":"Overcoming doubt is a daily practice.","zh":"克服懷疑是一種日常練習。"},{"en":"She overcame failure with grace.","zh":"她優雅地克服了失敗。"},{"en":"Overcome the urge to quit.","zh":"克服放棄的衝動。"},{"en":"He overcame his past and grew.","zh":"他克服了他的過去並成長了。"},{"en":"Overcoming hard times builds character.","zh":"克服艱難時期建立品格。"},{"en":"She overcame what once defeated her.","zh":"她克服了曾經擊敗她的東西。"},{"en":"Overcome fear by taking action.","zh":"通過行動克服恐懼。"}]},{"word":"struggle","pos":"noun/verb","chinese":"掙扎；奮鬥","level":"B1","sentences":[{"en":"Her struggle made her stronger.","zh":"她的掙扎讓她更強大。"},{"en":"He struggles but never gives up.","zh":"他掙扎但從不放棄。"},{"en":"Every struggle holds a lesson.","zh":"每次掙扎都包含一個教訓。"},{"en":"She shared her struggle openly.","zh":"她公開分享了她的掙扎。"},{"en":"The struggle is part of the story.","zh":"掙扎是故事的一部分。"},{"en":"He struggled silently for years.","zh":"他默默掙扎了多年。"},{"en":"Struggle reveals what you are made of.","zh":"掙扎揭示你是什麼做的。"},{"en":"She turned her struggle into purpose.","zh":"她把她的掙扎變成了目的。"},{"en":"Do not hide your struggle, share it.","zh":"不要隱藏你的掙扎，分享它。"},{"en":"The struggle was worth it in the end.","zh":"掙扎最終是值得的。"}]},{"word":"sacrifice","pos":"noun/verb","chinese":"犧牲","level":"B1","sentences":[{"en":"She sacrificed comfort for growth.","zh":"她為成長犧牲了舒適。"},{"en":"Real change requires sacrifice.","zh":"真正的改變需要犧牲。"},{"en":"He sacrificed time to be present.","zh":"他犧牲時間來在場。"},{"en":"Her sacrifice was quiet but huge.","zh":"她的犧牲安靜但巨大。"},{"en":"Some sacrifices pay off slowly.","zh":"有些犧牲緩慢地得到回報。"},{"en":"He sacrificed his ego for the team.","zh":"他為團隊犧牲了他的自我。"},{"en":"Sacrifice the good for the great.","zh":"為了偉大犧牲好的。"},{"en":"She made sacrifices without complaint.","zh":"她毫無怨言地做出了犧牲。"},{"en":"Every dream demands some sacrifice.","zh":"每個夢想都需要一些犧牲。"},{"en":"He sacrificed short-term for long-term.","zh":"他為長期犧牲了短期。"}]},{"word":"commit","pos":"verb","chinese":"承諾；投入","level":"B1","sentences":[{"en":"She committed fully to the plan.","zh":"她完全投入了這個計畫。"},{"en":"Commit to the process, not the outcome.","zh":"承諾過程，而不是結果。"},{"en":"He commits to fewer things, done well.","zh":"他承諾更少的事情，但做得好。"},{"en":"Commitment beats intensity over time.","zh":"長期來看承諾勝過強度。"},{"en":"She committed to growth every day.","zh":"她每天承諾成長。"},{"en":"Do not commit to what you cannot keep.","zh":"不要承諾你無法保持的。"},{"en":"He committed to honesty above all.","zh":"他最承諾誠實。"},{"en":"Commit and the path appears.","zh":"承諾，道路就會出現。"},{"en":"She committed to her values fully.","zh":"她完全投入她的價值觀。"},{"en":"Commitment turns wishes into plans.","zh":"承諾把願望變成計畫。"}]},{"word":"dedicate","pos":"verb","chinese":"奉獻；致力於","level":"B1","sentences":[{"en":"She dedicates time to what matters.","zh":"她把時間奉獻給重要的事。"},{"en":"He dedicated years to the craft.","zh":"他多年致力於這門技藝。"},{"en":"Dedicate yourself to one thing fully.","zh":"完全致力於一件事。"},{"en":"She dedicated the book to her mother.","zh":"她把書獻給她的母親。"},{"en":"Dedication shows in the small details.","zh":"奉獻顯示在小細節中。"},{"en":"He dedicates mornings to creative work.","zh":"他把早晨奉獻給創意工作。"},{"en":"She is dedicated without being rigid.","zh":"她奉獻但不死板。"},{"en":"Dedicate energy to your priorities.","zh":"把精力奉獻給你的優先事項。"},{"en":"His dedication inspired the whole team.","zh":"他的奉獻激勵了整個團隊。"},{"en":"Dedicate yourself, then let go of pressure.","zh":"奉獻自己，然後放下壓力。"}]},{"word":"persist","pos":"verb","chinese":"堅持；持續","level":"B1","sentences":[{"en":"She persisted when others quit.","zh":"當別人放棄時她堅持。"},{"en":"Persist through the boring middle.","zh":"堅持度過無聊的中段。"},{"en":"He persisted with quiet determination.","zh":"他以安靜的決心堅持。"},{"en":"Persistence beats talent eventually.","zh":"堅持最終勝過才能。"},{"en":"She persisted until it clicked.","zh":"她堅持直到開竅。"},{"en":"Persist, but adjust as you go.","zh":"堅持，但隨時調整。"},{"en":"He persisted despite the setbacks.","zh":"儘管挫折他仍然堅持。"},{"en":"Persistence is patience in action.","zh":"堅持是行動中的耐心。"},{"en":"She persisted and it finally paid off.","zh":"她堅持，最終得到了回報。"},{"en":"Persist past the point others stop.","zh":"在別人停止的地方堅持下去。"}]},{"word":"endure","pos":"verb","chinese":"忍受；持久","level":"B1","sentences":[{"en":"She endured the hard season with grace.","zh":"她優雅地忍受了艱難的季節。"},{"en":"True friendships endure distance.","zh":"真正的友誼能經受距離。"},{"en":"He endured pain to reach his goal.","zh":"他忍受痛苦以達到目標。"},{"en":"What you build with care endures.","zh":"你用心建立的東西能持久。"},{"en":"She endured but also grew.","zh":"她忍受但也成長了。"},{"en":"Endure the storm; calm follows.","zh":"忍受風暴；平靜隨之而來。"},{"en":"His patience endured every test.","zh":"他的耐心經受了每一次考驗。"},{"en":"Some things are meant to endure.","zh":"有些東西注定要持久。"},{"en":"She endured more than anyone knew.","zh":"她忍受的比任何人知道的更多。"},{"en":"Endure with hope, not just gritted teeth.","zh":"帶著希望忍受，而不只是咬緊牙關。"}]},{"word":"thrive","pos":"verb","chinese":"茁壯成長；興旺","level":"B1","sentences":[{"en":"She thrives under a little pressure.","zh":"她在一點壓力下茁壯成長。"},{"en":"Plants thrive with the right care.","zh":"植物在適當的照顧下茁壯成長。"},{"en":"He thrives in a calm environment.","zh":"他在平靜的環境中茁壯成長。"},{"en":"Thrive, do not just survive.","zh":"茁壯成長，而不只是生存。"},{"en":"She helps her team thrive.","zh":"她幫助她的團隊茁壯成長。"},{"en":"People thrive when they feel safe.","zh":"人們在感到安全時茁壯成長。"},{"en":"He thrives on meaningful challenges.","zh":"他在有意義的挑戰中茁壯成長。"},{"en":"She created conditions to thrive.","zh":"她創造了茁壯成長的條件。"},{"en":"Thriving looks different for everyone.","zh":"茁壯成長對每個人都不同。"},{"en":"They thrive together, not apart.","zh":"他們一起茁壯成長，而不是分開。"}]},{"word":"flourish","pos":"verb","chinese":"繁榮；蓬勃發展","level":"B1","sentences":[{"en":"Her business flourished over time.","zh":"她的生意隨時間繁榮起來。"},{"en":"Creativity flourishes in freedom.","zh":"創造力在自由中蓬勃發展。"},{"en":"He flourished after the move.","zh":"搬家後他蓬勃發展。"},{"en":"Relationships flourish with attention.","zh":"關係在關注中蓬勃發展。"},{"en":"She watched her garden flourish.","zh":"她看著她的花園繁榮。"},{"en":"Talent flourishes with encouragement.","zh":"才能在鼓勵中蓬勃發展。"},{"en":"He flourished once he found his path.","zh":"一旦找到他的道路他就蓬勃發展。"},{"en":"Communities flourish through trust.","zh":"社群通過信任蓬勃發展。"},{"en":"She flourished in the new role.","zh":"她在新職位上蓬勃發展。"},{"en":"Give people room to flourish.","zh":"給人們蓬勃發展的空間。"}]},{"word":"recover","pos":"verb","chinese":"恢復；復原","level":"B1","sentences":[{"en":"She recovered fully after rest.","zh":"休息後她完全恢復了。"},{"en":"Recover before you push again.","zh":"在你再次推進之前恢復。"},{"en":"He recovered from the setback quickly.","zh":"他迅速從挫折中恢復。"},{"en":"Recovery is part of the training.","zh":"恢復是訓練的一部分。"},{"en":"She recovered her sense of self.","zh":"她恢復了她的自我感。"},{"en":"Give yourself time to recover.","zh":"給自己時間恢復。"},{"en":"He recovered what he thought was lost.","zh":"他恢復了他以為失去的東西。"},{"en":"Recovery takes longer than we expect.","zh":"恢復比我們預期的需要更長時間。"},{"en":"She recovered and came back stronger.","zh":"她恢復了，並更強大地回來。"},{"en":"Recover fully, then begin again.","zh":"完全恢復，然後重新開始。"}]},{"word":"adjust","pos":"verb","chinese":"調整；適應","level":"B1","sentences":[{"en":"She adjusts her plans without stress.","zh":"她無壓力地調整她的計畫。"},{"en":"Adjust the goal, not the values.","zh":"調整目標，而不是價值觀。"},{"en":"He adjusted quickly to the change.","zh":"他迅速適應了變化。"},{"en":"Small adjustments make big differences.","zh":"小調整造成大差異。"},{"en":"She adjusted her approach mid-way.","zh":"她中途調整了她的方法。"},{"en":"Adjust as you learn more.","zh":"隨著你學到更多而調整。"},{"en":"He adjusted his expectations gently.","zh":"他溫和地調整了他的期望。"},{"en":"Adjusting is not failing.","zh":"調整不是失敗。"},{"en":"She adjusted her routine for better sleep.","zh":"她調整了她的常規以獲得更好的睡眠。"},{"en":"Adjust the sails, do not curse the wind.","zh":"調整船帆，不要詛咒風。"}]},{"word":"enhance","pos":"verb","chinese":"增強；提升","level":"B1","sentences":[{"en":"She enhances every project she touches.","zh":"她增強她接觸的每個項目。"},{"en":"Good sleep enhances everything.","zh":"好的睡眠增強一切。"},{"en":"He enhanced the design with small touches.","zh":"他用小細節增強了設計。"},{"en":"Enhance your strengths, not just fix weaknesses.","zh":"增強你的優勢，而不只是修復弱點。"},{"en":"She enhanced the experience for everyone.","zh":"她為每個人增強了體驗。"},{"en":"Music enhances his focus.","zh":"音樂增強他的專注力。"},{"en":"Enhance the basics before adding more.","zh":"在添加更多之前增強基礎。"},{"en":"He enhanced his skills steadily.","zh":"他穩步提升他的技能。"},{"en":"She enhanced the room with warm light.","zh":"她用溫暖的光增強了房間。"},{"en":"Enhance what already works well.","zh":"增強已經運作良好的東西。"}]},{"word":"strengthen","pos":"verb","chinese":"加強；鞏固","level":"B1","sentences":[{"en":"She strengthened the friendship over time.","zh":"她隨時間鞏固了友誼。"},{"en":"Challenges strengthen character.","zh":"挑戰加強品格。"},{"en":"He strengthened his weak areas.","zh":"他加強了他的弱項。"},{"en":"Strengthen your foundation first.","zh":"首先加強你的基礎。"},{"en":"She strengthened her boundaries.","zh":"她加強了她的界限。"},{"en":"Trust strengthens with consistency.","zh":"信任隨一致性而加強。"},{"en":"He strengthened the team's bond.","zh":"他加強了團隊的紐帶。"},{"en":"Strengthen your mind like your body.","zh":"像鍛鍊身體一樣加強你的頭腦。"},{"en":"She strengthened her resolve.","zh":"她加強了她的決心。"},{"en":"Hard times can strengthen relationships.","zh":"艱難時期可以加強關係。"}]},{"word":"explore","pos":"verb","chinese":"探索；探究","level":"B1","sentences":[{"en":"She loves to explore new ideas.","zh":"她喜歡探索新想法。"},{"en":"Explore before you commit.","zh":"在你承諾之前探索。"},{"en":"He explored every option carefully.","zh":"他仔細探索了每個選項。"},{"en":"Exploring keeps life interesting.","zh":"探索讓生活有趣。"},{"en":"She explored a new city alone.","zh":"她獨自探索了一個新城市。"},{"en":"Explore your own mind too.","zh":"也探索你自己的頭腦。"},{"en":"He explored a career change.","zh":"他探索了職業轉變。"},{"en":"Exploring requires curiosity and courage.","zh":"探索需要好奇心和勇氣。"},{"en":"She explored until she found her path.","zh":"她探索直到找到她的道路。"},{"en":"Explore widely, then go deep.","zh":"廣泛探索，然後深入。"}]},{"word":"discover","pos":"verb","chinese":"發現；發覺","level":"B1","sentences":[{"en":"She discovered a passion late in life.","zh":"她在晚年發現了一種熱情。"},{"en":"Discover what truly drives you.","zh":"發現什麼真正驅動你。"},{"en":"He discovered the answer by accident.","zh":"他偶然發現了答案。"},{"en":"Discovering yourself takes a lifetime.","zh":"發現自己需要一生。"},{"en":"She discovered strength she did not know.","zh":"她發現了她不知道的力量。"},{"en":"Discover joy in ordinary moments.","zh":"在平凡的時刻發現快樂。"},{"en":"He discovered a love for writing.","zh":"他發現了對寫作的熱愛。"},{"en":"Discovery starts with a question.","zh":"發現始於一個問題。"},{"en":"She discovered a hidden talent.","zh":"她發現了一個隱藏的天賦。"},{"en":"Discover what you cannot stop thinking about.","zh":"發現你無法停止思考的東西。"}]},{"word":"design","pos":"verb/noun","chinese":"設計；構思","level":"B1","sentences":[{"en":"She designs her days with intention.","zh":"她有意識地設計她的日子。"},{"en":"Design a life you do not need a vacation from.","zh":"設計一個你不需要度假逃離的生活。"},{"en":"He designed a simple, elegant solution.","zh":"他設計了一個簡單、優雅的解決方案。"},{"en":"Good design feels effortless.","zh":"好的設計感覺毫不費力。"},{"en":"She designed her own path.","zh":"她設計了自己的道路。"},{"en":"Design your environment for success.","zh":"為成功設計你的環境。"},{"en":"He designs with the user in mind.","zh":"他以用戶為中心設計。"},{"en":"Design removes friction.","zh":"設計消除摩擦。"},{"en":"She designed a system that lasts.","zh":"她設計了一個持久的系統。"},{"en":"Design your habits deliberately.","zh":"刻意地設計你的習慣。"}]},{"word":"prioritise","pos":"verb","chinese":"優先處理；排序","level":"B1","sentences":[{"en":"She prioritises her health first.","zh":"她首先優先考慮她的健康。"},{"en":"Prioritise the few that matter most.","zh":"優先處理最重要的少數。"},{"en":"He prioritises people over tasks.","zh":"他把人放在任務之上。"},{"en":"Prioritising is saying no to good things.","zh":"排序是對好事情說不。"},{"en":"She prioritised rest without guilt.","zh":"她無愧疚地優先考慮休息。"},{"en":"Prioritise progress over perfection.","zh":"優先考慮進步而不是完美。"},{"en":"He prioritised what only he could do.","zh":"他優先處理只有他能做的事。"},{"en":"Prioritising clears the noise.","zh":"排序清除噪音。"},{"en":"She prioritises deep work in the morning.","zh":"她在早上優先進行深度工作。"},{"en":"Prioritise your energy, not just time.","zh":"優先考慮你的能量，而不只是時間。"}]},{"word":"sustain","pos":"verb","chinese":"維持；支撐","level":"B1","sentences":[{"en":"She built habits she can sustain.","zh":"她建立了她能維持的習慣。"},{"en":"Sustain the pace you can keep.","zh":"維持你能保持的速度。"},{"en":"He sustained his focus for hours.","zh":"他維持了幾個小時的專注。"},{"en":"Sustainable beats intense every time.","zh":"可持續每次都勝過激烈。"},{"en":"She sustains her energy with rest.","zh":"她用休息維持她的能量。"},{"en":"Sustain progress with small steps.","zh":"用小步驟維持進步。"},{"en":"He sustained the effort for years.","zh":"他維持了多年的努力。"},{"en":"Sustain relationships with regular care.","zh":"用定期的關懷維持關係。"},{"en":"She sustains hope through hard times.","zh":"她在艱難時期維持希望。"},{"en":"Build something you can sustain.","zh":"建立你能維持的東西。"}]},{"word":"analyse","pos":"verb","chinese":"分析","level":"B1","sentences":[{"en":"She analyses problems calmly.","zh":"她冷靜地分析問題。"},{"en":"Analyse before you react.","zh":"在你反應之前分析。"},{"en":"He analysed the data thoroughly.","zh":"他徹底分析了數據。"},{"en":"Analysing too long delays action.","zh":"分析太久延遲行動。"},{"en":"She analysed her own patterns.","zh":"她分析了她自己的模式。"},{"en":"Analyse what works and repeat it.","zh":"分析什麼有效並重複它。"},{"en":"He analysed the situation objectively.","zh":"他客觀地分析了情況。"},{"en":"Analysing failure leads to growth.","zh":"分析失敗導致成長。"},{"en":"She analyses without overthinking.","zh":"她分析而不過度思考。"},{"en":"Analyse the cause, not just the symptom.","zh":"分析原因，而不只是症狀。"}]},{"word":"summarise","pos":"verb","chinese":"總結；概括","level":"B1","sentences":[{"en":"She summarises complex ideas clearly.","zh":"她清楚地總結複雜的想法。"},{"en":"Summarise the key point in one line.","zh":"用一行總結要點。"},{"en":"He summarised the meeting well.","zh":"他很好地總結了會議。"},{"en":"Summarising helps you remember.","zh":"總結幫助你記住。"},{"en":"She summarised her year in three words.","zh":"她用三個詞總結了她的一年。"},{"en":"Summarise before moving on.","zh":"在繼續之前總結。"},{"en":"He summarised without losing meaning.","zh":"他總結而不失去意義。"},{"en":"Summarising is a thinking skill.","zh":"總結是一種思考技能。"},{"en":"She summarised the book beautifully.","zh":"她美麗地總結了那本書。"},{"en":"Summarise to clarify your own thinking.","zh":"總結以澄清你自己的思維。"}]},{"word":"clarify","pos":"verb","chinese":"澄清；闡明","level":"B1","sentences":[{"en":"She clarified her point gently.","zh":"她溫和地澄清了她的觀點。"},{"en":"Clarify before you assume.","zh":"在你假設之前澄清。"},{"en":"He clarified the confusion quickly.","zh":"他迅速澄清了混亂。"},{"en":"Clarifying saves a lot of trouble.","zh":"澄清省很多麻煩。"},{"en":"She clarified her own values first.","zh":"她首先澄清了她自己的價值觀。"},{"en":"Clarify expectations early.","zh":"及早澄清期望。"},{"en":"He clarified the goal for everyone.","zh":"他為每個人澄清了目標。"},{"en":"Clarifying questions prevent mistakes.","zh":"澄清問題防止錯誤。"},{"en":"She clarified what she actually meant.","zh":"她澄清了她實際的意思。"},{"en":"Clarify, do not assume understanding.","zh":"澄清，不要假設理解。"}]},{"word":"negotiate","pos":"verb","chinese":"談判；協商","level":"B1","sentences":[{"en":"She negotiates with calm confidence.","zh":"她以冷靜的自信談判。"},{"en":"Negotiate for what you are worth.","zh":"為你的價值談判。"},{"en":"He negotiated a fair deal.","zh":"他談判了一個公平的交易。"},{"en":"Negotiating is finding common ground.","zh":"談判是找到共同點。"},{"en":"She negotiated without aggression.","zh":"她沒有侵略性地談判。"},{"en":"Negotiate the relationship, not just the price.","zh":"談判關係，而不只是價格。"},{"en":"He negotiated with respect.","zh":"他帶著尊重談判。"},{"en":"Negotiating well requires listening.","zh":"談判得好需要傾聽。"},{"en":"She negotiated a better outcome.","zh":"她談判了一個更好的結果。"},{"en":"Negotiate from clarity, not fear.","zh":"從清晰而不是恐懼談判。"}]},{"word":"collaborate","pos":"verb","chinese":"合作；協作","level":"B1","sentences":[{"en":"She collaborates generously with others.","zh":"她慷慨地與別人合作。"},{"en":"Collaborate without losing your voice.","zh":"合作而不失去你的聲音。"},{"en":"He collaborates across teams easily.","zh":"他輕鬆地跨團隊合作。"},{"en":"Collaboration multiplies good ideas.","zh":"合作使好想法倍增。"},{"en":"She collaborated on a shared vision.","zh":"她在一個共同的願景上合作。"},{"en":"Collaborate with people who lift you.","zh":"與提升你的人合作。"},{"en":"He learned to collaborate, not control.","zh":"他學會了合作，而不是控制。"},{"en":"Collaboration requires trust.","zh":"合作需要信任。"},{"en":"She collaborates better than she competes.","zh":"她合作比競爭更好。"},{"en":"Great work comes from collaboration.","zh":"偉大的工作來自合作。"}]},{"word":"participate","pos":"verb","chinese":"參與；參加","level":"B1","sentences":[{"en":"She participates fully, never half-way.","zh":"她完全參與，從不半途而廢。"},{"en":"Participate even when you feel unsure.","zh":"即使你感到不確定也參與。"},{"en":"He participated in the discussion actively.","zh":"他積極參與了討論。"},{"en":"Participating builds belonging.","zh":"參與建立歸屬感。"},{"en":"She chose to participate, not just watch.","zh":"她選擇參與，而不只是觀看。"},{"en":"Participate in your own life.","zh":"參與你自己的生活。"},{"en":"He participates in community events.","zh":"他參與社區活動。"},{"en":"Participating is how you grow.","zh":"參與是你成長的方式。"},{"en":"She participated wholeheartedly.","zh":"她全心全意地參與。"},{"en":"Participate, do not just observe.","zh":"參與，不要只是觀察。"}]},{"word":"engage","pos":"verb","chinese":"參與；投入；吸引","level":"B1","sentences":[{"en":"She engages fully in conversation.","zh":"她完全投入對話。"},{"en":"Engage with ideas you disagree with.","zh":"與你不同意的想法接觸。"},{"en":"He engages his team with purpose.","zh":"他帶著目的吸引他的團隊。"},{"en":"Engaging deeply beats skimming widely.","zh":"深度投入勝過廣泛瀏覽。"},{"en":"She engages with life curiously.","zh":"她好奇地投入生活。"},{"en":"Engage your whole attention.","zh":"投入你全部的注意力。"},{"en":"He engaged the audience instantly.","zh":"他立刻吸引了觀眾。"},{"en":"Engage with the present moment.","zh":"投入當下這一刻。"},{"en":"She engages others with genuine interest.","zh":"她以真誠的興趣吸引別人。"},{"en":"Engage, do not just consume.","zh":"投入，不要只是消費。"}]},{"word":"empower","pos":"verb","chinese":"賦權；增強能力","level":"B1","sentences":[{"en":"She empowers others to lead.","zh":"她賦予別人領導的能力。"},{"en":"Empower people with trust.","zh":"用信任賦予人們能力。"},{"en":"He empowers his team to decide.","zh":"他賦予他的團隊決定的能力。"},{"en":"Empowering others multiplies impact.","zh":"賦予別人能力使影響力倍增。"},{"en":"She felt empowered after the course.","zh":"課程後她感到被賦予了能力。"},{"en":"Empower yourself with knowledge.","zh":"用知識賦予自己能力。"},{"en":"He empowers through encouragement.","zh":"他通過鼓勵賦予能力。"},{"en":"Empowerment starts with belief.","zh":"賦權始於信念。"},{"en":"She empowers quietly, not loudly.","zh":"她安靜地而不是大聲地賦予能力。"},{"en":"Empower people and they rise.","zh":"賦予人們能力，他們就會崛起。"}]},{"word":"guide","pos":"verb/noun","chinese":"引導；指南","level":"B1","sentences":[{"en":"She guides without controlling.","zh":"她引導而不控制。"},{"en":"Let your values guide your choices.","zh":"讓你的價值觀引導你的選擇。"},{"en":"He guided me through a hard time.","zh":"他引導我度過艱難時期。"},{"en":"A good guide asks more than tells.","zh":"好的嚮導問的比說的多。"},{"en":"She guides with patience and warmth.","zh":"她以耐心和溫暖引導。"},{"en":"Guide others the way you wished to be guided.","zh":"以你希望被引導的方式引導別人。"},{"en":"He served as a guide, not a boss.","zh":"他作為嚮導，而不是老闆。"},{"en":"Guide gently toward growth.","zh":"溫和地引導走向成長。"},{"en":"She guides her own life intentionally.","zh":"她有意識地引導自己的生活。"},{"en":"Be a guide, not a gatekeeper.","zh":"做一個嚮導，而不是守門人。"}]},{"word":"acknowledge","pos":"verb","chinese":"承認；認可","level":"B1","sentences":[{"en":"She acknowledges her mistakes openly.","zh":"她公開承認她的錯誤。"},{"en":"Acknowledge the effort, not just results.","zh":"承認努力，而不只是結果。"},{"en":"He acknowledged her hard work.","zh":"他認可了她的努力。"},{"en":"Acknowledging feelings makes them lighter.","zh":"承認感受讓它們變輕。"},{"en":"She acknowledged the truth bravely.","zh":"她勇敢地承認了真相。"},{"en":"Acknowledge people and they feel seen.","zh":"認可人們，他們就感到被看見。"},{"en":"He acknowledged the problem first.","zh":"他首先承認了問題。"},{"en":"Acknowledge progress along the way.","zh":"沿途承認進步。"},{"en":"She acknowledged her part in it.","zh":"她承認了她在其中的部分。"},{"en":"Acknowledging is the start of healing.","zh":"承認是療癒的開始。"}]},{"word":"respect","pos":"noun/verb","chinese":"尊重","level":"B1","sentences":[{"en":"She earns respect through consistency.","zh":"她通過一致性贏得尊重。"},{"en":"Respect is given before it is earned.","zh":"尊重是先給予再贏得的。"},{"en":"He respects boundaries without being told.","zh":"他不用被告知就尊重界限。"},{"en":"Respect yourself enough to rest.","zh":"足夠尊重自己去休息。"},{"en":"She treats everyone with respect.","zh":"她以尊重對待每個人。"},{"en":"Respect grows from honesty.","zh":"尊重從誠實中成長。"},{"en":"He respects different opinions.","zh":"他尊重不同的意見。"},{"en":"Self-respect sets the standard.","zh":"自我尊重設定標準。"},{"en":"She commands respect quietly.","zh":"她安靜地贏得尊重。"},{"en":"Respect is the foundation of trust.","zh":"尊重是信任的基礎。"}]},{"word":"admire","pos":"verb","chinese":"欽佩；讚賞","level":"B1","sentences":[{"en":"She admires people who stay kind.","zh":"她欽佩保持善良的人。"},{"en":"I admire his quiet discipline.","zh":"我欽佩他安靜的自律。"},{"en":"Admire others without comparing yourself.","zh":"欽佩別人而不比較自己。"},{"en":"He admired her courage deeply.","zh":"他深深欽佩她的勇氣。"},{"en":"She admires honesty above charm.","zh":"她欽佩誠實勝過魅力。"},{"en":"Admire the work, not just the outcome.","zh":"欽佩工作，而不只是結果。"},{"en":"I admire how she handles pressure.","zh":"我欽佩她如何處理壓力。"},{"en":"He admires those who keep growing.","zh":"他欽佩那些持續成長的人。"},{"en":"She admired the view in silence.","zh":"她在沉默中欣賞風景。"},{"en":"Admire freely, envy rarely.","zh":"自由地欽佩，很少嫉妒。"}]},{"word":"forgive","pos":"verb","chinese":"原諒；寬恕","level":"B1","sentences":[{"en":"She forgave him without forgetting.","zh":"她原諒了他但沒有忘記。"},{"en":"Forgive for your own peace.","zh":"為你自己的平靜而原諒。"},{"en":"He forgave himself slowly.","zh":"他慢慢原諒了自己。"},{"en":"Forgiveness frees the forgiver.","zh":"寬恕釋放寬恕者。"},{"en":"She learned to forgive deeply.","zh":"她學會了深深地原諒。"},{"en":"Forgive, but protect your boundaries.","zh":"原諒，但保護你的界限。"},{"en":"He forgave the past to free his future.","zh":"他原諒過去以解放他的未來。"},{"en":"Forgiving is a gift to yourself.","zh":"原諒是給自己的禮物。"},{"en":"She forgave and quietly moved on.","zh":"她原諒了並安靜地繼續前進。"},{"en":"Forgive without needing an apology.","zh":"不需要道歉就原諒。"}]},{"word":"embrace","pos":"verb","chinese":"擁抱；接受","level":"B1","sentences":[{"en":"She embraces change instead of fearing it.","zh":"她擁抱變化而不是害怕它。"},{"en":"Embrace the messy middle.","zh":"擁抱混亂的中段。"},{"en":"He embraced his true self fully.","zh":"他完全擁抱了他真實的自我。"},{"en":"Embrace what you cannot change.","zh":"擁抱你無法改變的。"},{"en":"She embraced the challenge gladly.","zh":"她欣然接受了挑戰。"},{"en":"Embrace imperfection in yourself.","zh":"擁抱你自己的不完美。"},{"en":"He embraced a slower pace of life.","zh":"他擁抱了更慢的生活節奏。"},{"en":"Embrace uncertainty as possibility.","zh":"把不確定性當作可能性來擁抱。"},{"en":"She embraced every season of life.","zh":"她擁抱生命的每個季節。"},{"en":"Embrace the journey, not just the goal.","zh":"擁抱旅程，而不只是目標。"}]},{"word":"cherish","pos":"verb","chinese":"珍惜；珍愛","level":"B1","sentences":[{"en":"She cherishes the quiet mornings.","zh":"她珍惜安靜的早晨。"},{"en":"Cherish people while they are here.","zh":"在人們還在的時候珍惜他們。"},{"en":"He cherishes small everyday moments.","zh":"他珍惜日常的小時刻。"},{"en":"Cherish what cannot be replaced.","zh":"珍惜無法替代的東西。"},{"en":"She cherishes deep over shallow ties.","zh":"她珍惜深刻勝過膚淺的紐帶。"},{"en":"Cherish the present; it passes fast.","zh":"珍惜當下；它過得很快。"},{"en":"He cherishes his close friendships.","zh":"他珍惜他親密的友誼。"},{"en":"Cherish memories without clinging.","zh":"珍惜回憶而不執著。"},{"en":"She cherishes her own company too.","zh":"她也珍惜獨處。"},{"en":"Cherish the ordinary; it becomes precious.","zh":"珍惜平凡；它會變得珍貴。"}]},{"word":"deserve","pos":"verb","chinese":"應得；值得","level":"B1","sentences":[{"en":"She deserves the rest she rarely takes.","zh":"她應得她很少給自己的休息。"},{"en":"You deserve kindness, especially from yourself.","zh":"你應得善良，尤其是來自你自己。"},{"en":"He earned what he deserves.","zh":"他贏得了他應得的。"},{"en":"Deserve does not mean entitled.","zh":"應得不意味著理所當然。"},{"en":"She knows what she deserves now.","zh":"她現在知道她應得什麼。"},{"en":"Deserve good things by being good.","zh":"通過做好人應得好事。"},{"en":"He deserves credit for the quiet work.","zh":"他應得安靜工作的功勞。"},{"en":"You deserve a life that fits you.","zh":"你應得一個適合你的生活。"},{"en":"She deserved better and finally chose it.","zh":"她應得更好的，並終於選擇了它。"},{"en":"Deserve trust by being trustworthy.","zh":"通過值得信賴來應得信任。"}]},{"word":"matter","pos":"verb","chinese":"重要；要緊","level":"B1","sentences":[{"en":"Do what matters, skip what does not.","zh":"做重要的，跳過不重要的。"},{"en":"She makes everyone feel they matter.","zh":"她讓每個人都感到自己重要。"},{"en":"Small things matter more than we think.","zh":"小事情比我們想的更重要。"},{"en":"What matters most rarely shouts.","zh":"最重要的東西很少大喊。"},{"en":"He focuses only on what matters.","zh":"他只專注於重要的事。"},{"en":"You matter, exactly as you are.","zh":"你很重要，就是你本來的樣子。"},{"en":"It matters how you treat people.","zh":"你如何對待人很重要。"},{"en":"She knows what truly matters to her.","zh":"她知道什麼對她真正重要。"},{"en":"Make your days matter.","zh":"讓你的日子有意義。"},{"en":"What we repeat matters most.","zh":"我們重複的東西最重要。"}]},{"word":"belong","pos":"verb","chinese":"屬於；歸屬","level":"B1","sentences":[{"en":"She finally felt like she belonged.","zh":"她終於感到她屬於這裡。"},{"en":"You belong wherever you bring your true self.","zh":"你帶著真實的自我去哪裡都屬於那裡。"},{"en":"He belongs to a supportive community.","zh":"他屬於一個支持性的社群。"},{"en":"Belonging is feeling safe to be you.","zh":"歸屬感是感到安全做你自己。"},{"en":"She created a space where all belong.","zh":"她創造了一個所有人都屬於的空間。"},{"en":"Belong to yourself first.","zh":"首先屬於你自己。"},{"en":"He found where he truly belongs.","zh":"他找到了他真正屬於的地方。"},{"en":"Belonging cannot be forced.","zh":"歸屬感無法強迫。"},{"en":"She helps others feel they belong.","zh":"她幫助別人感到歸屬。"},{"en":"We all want to belong somewhere.","zh":"我們都想屬於某個地方。"}]},{"word":"depend","pos":"verb","chinese":"依賴；取決於","level":"B1","sentences":[{"en":"It depends on what you value most.","zh":"這取決於你最重視什麼。"},{"en":"She learned not to depend on approval.","zh":"她學會了不依賴認可。"},{"en":"Others depend on his reliability.","zh":"別人依賴他的可靠性。"},{"en":"Depend on yourself first.","zh":"首先依賴你自己。"},{"en":"The outcome depends on consistency.","zh":"結果取決於一致性。"},{"en":"He is someone you can depend on.","zh":"他是你可以依賴的人。"},{"en":"Do not depend on motivation alone.","zh":"不要只依賴動機。"},{"en":"It all depends on your perspective.","zh":"這一切取決於你的視角。"},{"en":"She built a life she can depend on.","zh":"她建立了一個她可以依賴的生活。"},{"en":"Depend on systems, not willpower.","zh":"依賴系統，而不是意志力。"}]},{"word":"rely","pos":"verb","chinese":"依靠；信賴","level":"B1","sentences":[{"en":"You can always rely on her.","zh":"你總是可以依靠她。"},{"en":"Rely on habits when motivation fades.","zh":"當動機消退時依靠習慣。"},{"en":"He relies on a small trusted circle.","zh":"他依靠一個小的信任圈子。"},{"en":"Rely on yourself, but accept help.","zh":"依靠自己，但接受幫助。"},{"en":"She is someone people rely on.","zh":"她是人們依靠的人。"},{"en":"Rely on preparation, not luck.","zh":"依靠準備，而不是運氣。"},{"en":"He learned not to rely on others' opinions.","zh":"他學會了不依靠別人的意見。"},{"en":"Rely on your values in hard moments.","zh":"在艱難的時刻依靠你的價值觀。"},{"en":"She relies on routine to stay calm.","zh":"她依靠常規保持冷靜。"},{"en":"Rely on what is consistent.","zh":"依靠一致的東西。"}]},{"word":"survive","pos":"verb","chinese":"生存；倖存","level":"B1","sentences":[{"en":"She survived and then truly lived.","zh":"她生存下來，然後真正地生活。"},{"en":"Survive the hard part; growth follows.","zh":"熬過艱難的部分；成長隨之而來。"},{"en":"He survived more than people knew.","zh":"他熬過的比人們知道的更多。"},{"en":"Surviving is not the same as thriving.","zh":"生存和茁壯成長不一樣。"},{"en":"She survived by staying hopeful.","zh":"她通過保持希望而生存。"},{"en":"Survive today; you can rebuild tomorrow.","zh":"熬過今天；你明天可以重建。"},{"en":"He survived the storm and grew.","zh":"他熬過了風暴並成長了。"},{"en":"Surviving builds quiet strength.","zh":"生存建立安靜的力量。"},{"en":"She survived and helped others survive.","zh":"她生存下來並幫助別人生存。"},{"en":"Survive, then design a better life.","zh":"生存，然後設計更好的生活。"}]},{"word":"prevent","pos":"verb","chinese":"預防；阻止","level":"B1","sentences":[{"en":"She prevents problems before they grow.","zh":"她在問題變大之前預防它們。"},{"en":"Prevent burnout by resting early.","zh":"通過早休息預防倦怠。"},{"en":"He prevented a big mistake calmly.","zh":"他冷靜地阻止了一個大錯誤。"},{"en":"Prevention is easier than repair.","zh":"預防比修復容易。"},{"en":"She prevented conflict with clarity.","zh":"她用清晰預防了衝突。"},{"en":"Prevent regret by acting now.","zh":"通過現在行動預防後悔。"},{"en":"He prevents stress with good habits.","zh":"他用好習慣預防壓力。"},{"en":"Preventing small issues saves big trouble.","zh":"預防小問題省大麻煩。"},{"en":"She prevents overwhelm by planning.","zh":"她通過計畫預防不知所措。"},{"en":"Prevent, do not just react.","zh":"預防，不要只是反應。"}]},{"word":"ensure","pos":"verb","chinese":"確保；保證","level":"B1","sentences":[{"en":"She ensures everyone feels included.","zh":"她確保每個人都感到被包括。"},{"en":"Ensure your foundation is solid.","zh":"確保你的基礎是堅實的。"},{"en":"He ensured the work was done right.","zh":"他確保工作做對了。"},{"en":"Ensure rest is part of the plan.","zh":"確保休息是計畫的一部分。"},{"en":"She ensured nothing was missed.","zh":"她確保沒有遺漏任何東西。"},{"en":"Ensure clarity before you commit.","zh":"在你承諾之前確保清晰。"},{"en":"He ensures fairness for everyone.","zh":"他為每個人確保公平。"},{"en":"Ensure your habits match your goals.","zh":"確保你的習慣與你的目標一致。"},{"en":"She ensured the message was kind.","zh":"她確保信息是善意的。"},{"en":"Ensure you protect what matters.","zh":"確保你保護重要的東西。"}]},{"word":"guarantee","pos":"verb/noun","chinese":"保證；擔保","level":"B1","sentences":[{"en":"Effort guarantees growth, not outcomes.","zh":"努力保證成長，而不是結果。"},{"en":"Nothing in life is guaranteed.","zh":"生活中沒有什麼是保證的。"},{"en":"He guaranteed his full commitment.","zh":"他保證他的全力投入。"},{"en":"There is no guarantee, only effort.","zh":"沒有保證，只有努力。"},{"en":"She guarantees quality every time.","zh":"她每次都保證質量。"},{"en":"Consistency does not guarantee speed.","zh":"一致性不保證速度。"},{"en":"He offered a sincere guarantee.","zh":"他提供了一個真誠的保證。"},{"en":"Guarantee your effort, accept the result.","zh":"保證你的努力，接受結果。"},{"en":"She made no promises she could not guarantee.","zh":"她沒有做她無法保證的承諾。"},{"en":"The only guarantee is change.","zh":"唯一的保證是改變。"}]},{"word":"handle","pos":"verb","chinese":"處理；應對","level":"B1","sentences":[{"en":"She handles pressure with grace.","zh":"她優雅地處理壓力。"},{"en":"Handle one thing at a time.","zh":"一次處理一件事。"},{"en":"He handled the news calmly.","zh":"他冷靜地處理了消息。"},{"en":"Handle hard moments with kindness.","zh":"用善意處理艱難的時刻。"},{"en":"She handles conflict directly.","zh":"她直接處理衝突。"},{"en":"Handle yourself before handling others.","zh":"在處理別人之前先處理自己。"},{"en":"He handled the mistake maturely.","zh":"他成熟地處理了錯誤。"},{"en":"Handle setbacks as information.","zh":"把挫折當作信息來處理。"},{"en":"She handles everything with calm focus.","zh":"她以冷靜的專注處理一切。"},{"en":"Handle what you can; release the rest.","zh":"處理你能的；釋放其餘的。"}]},{"word":"cope","pos":"verb","chinese":"應對；應付","level":"B1","sentences":[{"en":"She copes with stress through movement.","zh":"她通過運動應對壓力。"},{"en":"Find healthy ways to cope.","zh":"找到健康的應對方式。"},{"en":"He coped by talking it through.","zh":"他通過把它談開來應對。"},{"en":"Coping is a skill you can build.","zh":"應對是一種你可以建立的技能。"},{"en":"She coped better than she expected.","zh":"她應對得比她預期的更好。"},{"en":"Cope with hard days one hour at a time.","zh":"一小時一小時地應對艱難的日子。"},{"en":"He learned new ways to cope.","zh":"他學會了新的應對方式。"},{"en":"Coping well starts with self-kindness.","zh":"應對得好始於自我善待。"},{"en":"She copes by leaning on her people.","zh":"她通過依靠她的人來應對。"},{"en":"Cope, then heal, then grow.","zh":"應對，然後療癒，然後成長。"}]},{"word":"transition","pos":"noun/verb","chinese":"過渡；轉變","level":"B1","sentences":[{"en":"She handled the transition gracefully.","zh":"她優雅地處理了過渡。"},{"en":"Transitions are uncomfortable but necessary.","zh":"過渡不舒服但必要。"},{"en":"He transitioned into a new career.","zh":"他過渡到了一個新職業。"},{"en":"Give yourself time during transitions.","zh":"在過渡期間給自己時間。"},{"en":"She is in a season of transition.","zh":"她處於一個過渡的季節。"},{"en":"Transition slowly, do not rush.","zh":"慢慢過渡，不要急。"},{"en":"He managed the transition with patience.","zh":"他以耐心管理了過渡。"},{"en":"Transitions reveal what truly matters.","zh":"過渡揭示什麼真正重要。"},{"en":"She embraced the transition fully.","zh":"她完全擁抱了過渡。"},{"en":"Every transition is a kind of rebirth.","zh":"每次過渡都是一種重生。"}]},{"word":"evolve","pos":"verb","chinese":"演變；進化","level":"B1","sentences":[{"en":"She evolves with every experience.","zh":"她隨每次經歷而演變。"},{"en":"Let your goals evolve over time.","zh":"讓你的目標隨時間演變。"},{"en":"He evolved into a calmer person.","zh":"他演變成了一個更冷靜的人。"},{"en":"Evolving means outgrowing old selves.","zh":"演變意味著超越舊的自我。"},{"en":"She allowed her views to evolve.","zh":"她允許她的觀點演變。"},{"en":"Evolve, do not just repeat.","zh":"演變，不要只是重複。"},{"en":"He evolved his approach steadily.","zh":"他穩步演變他的方法。"},{"en":"Relationships evolve or they fade.","zh":"關係演變，否則就消退。"},{"en":"She evolves without losing her core.","zh":"她演變而不失去她的核心。"},{"en":"Evolving is a sign of growth.","zh":"演變是成長的標誌。"}]},{"word":"mature","pos":"verb/adj","chinese":"成熟","level":"B1","sentences":[{"en":"She handled it in a mature way.","zh":"她以成熟的方式處理它。"},{"en":"Maturity is choosing peace over ego.","zh":"成熟是選擇平靜而不是自我。"},{"en":"He matured a lot in one hard year.","zh":"他在艱難的一年裡成熟了很多。"},{"en":"Mature people own their mistakes.","zh":"成熟的人承認他們的錯誤。"},{"en":"She matured without losing her wonder.","zh":"她成熟但沒有失去她的好奇。"},{"en":"Maturity is quiet, not loud.","zh":"成熟是安靜的，不是大聲的。"},{"en":"He responded with mature calm.","zh":"他以成熟的冷靜回應。"},{"en":"Mature love is steady, not dramatic.","zh":"成熟的愛是穩定的，不是戲劇性的。"},{"en":"She matured through real responsibility.","zh":"她通過真正的責任成熟了。"},{"en":"Maturity means thinking long-term.","zh":"成熟意味著長遠思考。"}]},{"word":"contemplate","pos":"verb","chinese":"沉思；考慮","level":"B1","sentences":[{"en":"She contemplates before deciding.","zh":"她在決定之前沉思。"},{"en":"Contemplate what you really want.","zh":"沉思你真正想要什麼。"},{"en":"He contemplated the question deeply.","zh":"他深深地沉思了這個問題。"},{"en":"Contemplation brings unexpected clarity.","zh":"沉思帶來意想不到的清晰。"},{"en":"She contemplates in the early morning.","zh":"她在清晨沉思。"},{"en":"Contemplate, then act decisively.","zh":"沉思，然後果斷行動。"},{"en":"He contemplated a big change.","zh":"他考慮了一個大改變。"},{"en":"Contemplating slows you in a good way.","zh":"沉思以好的方式讓你慢下來。"},{"en":"She contemplated her next step.","zh":"她考慮了她的下一步。"},{"en":"Contemplation is thinking with depth.","zh":"沉思是有深度的思考。"}]},{"word":"concentrate","pos":"verb","chinese":"集中；專注","level":"B1","sentences":[{"en":"She concentrates fully on one task.","zh":"她完全集中於一個任務。"},{"en":"Concentrate on what you can control.","zh":"集中於你能控制的。"},{"en":"He concentrates best in silence.","zh":"他在寂靜中最能集中。"},{"en":"Concentration is a trainable skill.","zh":"專注是一種可訓練的技能。"},{"en":"She concentrated despite the noise.","zh":"儘管噪音她仍然集中。"},{"en":"Concentrate your energy, do not scatter it.","zh":"集中你的能量，不要分散它。"},{"en":"He concentrates in short, deep bursts.","zh":"他在短而深的爆發中集中。"},{"en":"Concentration improves with practice.","zh":"專注隨練習改善。"},{"en":"She concentrated until it was done.","zh":"她集中直到它完成。"},{"en":"Concentrate on progress, not perfection.","zh":"集中於進步，而不是完美。"}]},{"word":"intend","pos":"verb","chinese":"打算；意圖","level":"B1","sentences":[{"en":"She intends to live with purpose.","zh":"她打算有目的地生活。"},{"en":"Intend less, do more.","zh":"少意圖，多行動。"},{"en":"He intended to call but forgot.","zh":"他打算打電話但忘了。"},{"en":"Good intentions need real action.","zh":"好的意圖需要真正的行動。"},{"en":"She intends to keep growing.","zh":"她打算繼續成長。"},{"en":"Intend kindness in every interaction.","zh":"在每次互動中意圖善良。"},{"en":"He intends to finish what he starts.","zh":"他打算完成他開始的事。"},{"en":"Intend clearly, act consistently.","zh":"清楚地意圖，一致地行動。"},{"en":"She intended no harm, only honesty.","zh":"她無意傷害，只有誠實。"},{"en":"Intentions matter, but actions matter more.","zh":"意圖重要，但行動更重要。"}]},{"word":"aim","pos":"verb/noun","chinese":"瞄準；目標","level":"B1","sentences":[{"en":"She aims high but stays grounded.","zh":"她瞄準高處但保持腳踏實地。"},{"en":"Aim for progress, not perfection.","zh":"瞄準進步，而不是完美。"},{"en":"He aims to help one person daily.","zh":"他的目標是每天幫助一個人。"},{"en":"Aim where you want to grow.","zh":"瞄準你想成長的地方。"},{"en":"Her aim was clear from the start.","zh":"她的目標從一開始就很清楚。"},{"en":"Aim carefully, then commit fully.","zh":"仔細瞄準，然後完全投入。"},{"en":"He aims to be kind above all.","zh":"他的目標是最善良。"},{"en":"Aim for depth over breadth.","zh":"瞄準深度而不是廣度。"},{"en":"She aimed to leave things better.","zh":"她的目標是讓事情變得更好。"},{"en":"Aim true, even when it is hard.","zh":"瞄準真實，即使很難。"}]},{"word":"strive","pos":"verb","chinese":"努力；力求","level":"B1","sentences":[{"en":"She strives to be a little better daily.","zh":"她努力每天好一點。"},{"en":"Strive without losing your peace.","zh":"努力而不失去你的平靜。"},{"en":"He strives for meaning, not status.","zh":"他力求意義，而不是地位。"},{"en":"Striving is good; struggling endlessly is not.","zh":"努力是好的；無休止地掙扎不是。"},{"en":"She strives and rests in equal measure.","zh":"她努力和休息同等程度。"},{"en":"Strive for what genuinely matters.","zh":"為真正重要的事努力。"},{"en":"He strives quietly, without show.","zh":"他安靜地努力，不張揚。"},{"en":"Strive for progress you can sustain.","zh":"為你能維持的進步努力。"},{"en":"She strives to understand, not to win.","zh":"她力求理解，而不是贏。"},{"en":"Strive, then surrender the outcome.","zh":"努力，然後放下結果。"}]},{"word":"seek","pos":"verb","chinese":"尋求；尋找","level":"B1","sentences":[{"en":"She seeks growth in every challenge.","zh":"她在每個挑戰中尋求成長。"},{"en":"Seek understanding before being understood.","zh":"在被理解之前尋求理解。"},{"en":"He seeks wisdom, not just facts.","zh":"他尋求智慧，而不只是事實。"},{"en":"Seek people who lift you higher.","zh":"尋找把你提升得更高的人。"},{"en":"She seeks meaning in ordinary days.","zh":"她在平凡的日子裡尋求意義。"},{"en":"Seek feedback, even when it stings.","zh":"尋求反饋，即使它刺痛。"},{"en":"He seeks calm over chaos.","zh":"他尋求平靜而不是混亂。"},{"en":"Seek to add value everywhere.","zh":"尋求在各處增加價值。"},{"en":"She seeks truth gently.","zh":"她溫和地尋求真相。"},{"en":"Seek progress, accept imperfection.","zh":"尋求進步，接受不完美。"}]},{"word":"gain","pos":"verb/noun","chinese":"獲得；增益","level":"B1","sentences":[{"en":"She gained confidence through practice.","zh":"她通過練習獲得了信心。"},{"en":"Gain perspective by stepping back.","zh":"通過退一步獲得視角。"},{"en":"He gained respect by being consistent.","zh":"他通過一致性獲得了尊重。"},{"en":"What you gain in speed you lose in depth.","zh":"你在速度上獲得的，在深度上失去。"},{"en":"She gained clarity after the break.","zh":"休息後她獲得了清晰。"},{"en":"Gain wisdom from every season.","zh":"從每個季節獲得智慧。"},{"en":"He gained more by giving freely.","zh":"他通過自由給予獲得了更多。"},{"en":"Gain strength from the struggle.","zh":"從掙扎中獲得力量。"},{"en":"She gained a new appreciation for rest.","zh":"她對休息有了新的欣賞。"},{"en":"Gain ground slowly but surely.","zh":"緩慢但確定地取得進展。"}]},{"word":"comprehend","pos":"verb","chinese":"理解；領會","level":"B1","sentences":[{"en":"She comprehends complex ideas fast.","zh":"她快速理解複雜的想法。"},{"en":"Comprehend before you judge.","zh":"在你評判之前理解。"},{"en":"He struggled to comprehend the loss.","zh":"他難以理解這個損失。"},{"en":"Comprehending takes more than reading.","zh":"理解需要的比閱讀更多。"},{"en":"She comprehends people deeply.","zh":"她深刻地理解人。"},{"en":"Comprehend the why behind the what.","zh":"理解什麼背後的為什麼。"},{"en":"He finally comprehended her point.","zh":"他終於理解了她的觀點。"},{"en":"Comprehension grows with patience.","zh":"理解隨耐心成長。"},{"en":"She comprehends both sides fairly.","zh":"她公平地理解雙方。"},{"en":"Comprehend fully, then respond.","zh":"完全理解，然後回應。"}]},{"word":"grasp","pos":"verb","chinese":"抓住；理解","level":"B1","sentences":[{"en":"She grasped the concept instantly.","zh":"她立刻理解了這個概念。"},{"en":"Grasp the main idea first.","zh":"首先抓住主要想法。"},{"en":"He grasped the opportunity quickly.","zh":"他迅速抓住了機會。"},{"en":"Grasping the basics makes the rest easy.","zh":"掌握基礎讓其餘的容易。"},{"en":"She grasped what others missed.","zh":"她理解了別人錯過的。"},{"en":"Grasp it, then let it deepen.","zh":"抓住它，然後讓它加深。"},{"en":"He grasped her meaning at once.","zh":"他立刻理解了她的意思。"},{"en":"Grasp the moment while you can.","zh":"趁你能的時候抓住這一刻。"},{"en":"She grasped the lesson fully.","zh":"她完全理解了這個教訓。"},{"en":"Grasp the principle, not just the rule.","zh":"抓住原則，而不只是規則。"}]},{"word":"absorb","pos":"verb","chinese":"吸收；理解","level":"B1","sentences":[{"en":"She absorbs knowledge like a sponge.","zh":"她像海綿一樣吸收知識。"},{"en":"Absorb the lesson, not just the words.","zh":"吸收教訓，而不只是文字。"},{"en":"He absorbs new ideas openly.","zh":"他開放地吸收新想法。"},{"en":"Absorbing takes quiet and time.","zh":"吸收需要安靜和時間。"},{"en":"She absorbed the shock calmly.","zh":"她冷靜地吸收了衝擊。"},{"en":"Absorb wisdom from those ahead of you.","zh":"從走在你前面的人那裡吸收智慧。"},{"en":"He absorbed the feedback gracefully.","zh":"他優雅地吸收了反饋。"},{"en":"Absorb less noise, more meaning.","zh":"吸收更少的噪音，更多的意義。"},{"en":"She absorbs experiences deeply.","zh":"她深刻地吸收經驗。"},{"en":"Absorb, reflect, then apply.","zh":"吸收，反思，然後應用。"}]},{"word":"express","pos":"verb","chinese":"表達；表示","level":"B1","sentences":[{"en":"She expresses herself clearly and kindly.","zh":"她清楚而善意地表達自己。"},{"en":"Express your needs, do not hint.","zh":"表達你的需求，不要暗示。"},{"en":"He expresses gratitude often.","zh":"他經常表達感激。"},{"en":"Expressing feelings makes them lighter.","zh":"表達感受讓它們變輕。"},{"en":"She expresses care through action.","zh":"她通過行動表達關心。"},{"en":"Express yourself without apology.","zh":"表達自己而不道歉。"},{"en":"He learned to express his emotions.","zh":"他學會了表達他的情緒。"},{"en":"Express appreciation before it is too late.","zh":"在為時已晚之前表達欣賞。"},{"en":"She expresses ideas with warmth.","zh":"她以溫暖表達想法。"},{"en":"Express your truth with kindness.","zh":"以善意表達你的真相。"}]},{"word":"convey","pos":"verb","chinese":"傳達；表達","level":"B1","sentences":[{"en":"She conveys warmth in a few words.","zh":"她用幾個字傳達溫暖。"},{"en":"Convey your message simply.","zh":"簡單地傳達你的信息。"},{"en":"He conveyed deep respect quietly.","zh":"他安靜地傳達了深深的尊重。"},{"en":"Tone conveys more than words.","zh":"語氣傳達的比文字更多。"},{"en":"She conveyed the idea beautifully.","zh":"她美麗地傳達了這個想法。"},{"en":"Convey care through your attention.","zh":"通過你的注意力傳達關心。"},{"en":"He conveyed honesty in every reply.","zh":"他在每個回覆中傳達誠實。"},{"en":"Convey clearly, then check understanding.","zh":"清楚地傳達，然後檢查理解。"},{"en":"She conveyed calm to a tense room.","zh":"她向緊張的房間傳達了冷靜。"},{"en":"Convey meaning, not just information.","zh":"傳達意義，而不只是信息。"}]},{"word":"join","pos":"verb","chinese":"加入；參加","level":"A2","sentences":[{"en":"She joined a community of makers.","zh":"她加入了一個創作者社群。"},{"en":"Join people who lift you higher.","zh":"加入提升你的人。"},{"en":"He joined the conversation warmly.","zh":"他熱情地加入了對話。"},{"en":"Join in, do not just watch.","zh":"加入進來，不要只是觀看。"},{"en":"She joined a class to learn something new.","zh":"她加入了一個課程來學新東西。"},{"en":"Join forces with the right people.","zh":"與對的人聯手。"},{"en":"He joined a group that shared his values.","zh":"他加入了一個分享他價值觀的團體。"},{"en":"Join early and grow with it.","zh":"早加入並與它一起成長。"},{"en":"She joined the effort wholeheartedly.","zh":"她全心全意地加入了努力。"},{"en":"Join something bigger than yourself.","zh":"加入比你自己更大的東西。"}]},{"word":"behave","pos":"verb","chinese":"表現","level":"B1","sentences":[{"en":"She behaves with quiet dignity.","zh":"她以安靜的尊嚴行事。"},{"en":"Behave the way you want to be seen.","zh":"以你希望被看待的方式表現。"},{"en":"He behaves consistently everywhere.","zh":"他到處都表現一致。"},{"en":"Behaviour reveals values more than words.","zh":"行為比言語更能揭示價值觀。"},{"en":"She behaved kindly even when tired.","zh":"即使累了她也表現善良。"},{"en":"Behave with integrity always.","zh":"永遠正直地行事。"},{"en":"He behaves calmly under pressure.","zh":"他在壓力下冷靜地表現。"},{"en":"How we behave shapes our reputation.","zh":"我們如何表現塑造聲譽。"},{"en":"She behaves the same with everyone.","zh":"她對每個人都一樣。"},{"en":"Behave in line with your values.","zh":"按你的價值觀行事。"}]},{"word":"respond","pos":"verb","chinese":"回應","level":"B1","sentences":[{"en":"She responds rather than reacts.","zh":"她回應而不是反應。"},{"en":"Respond with care, not speed.","zh":"以關心而不是速度回應。"},{"en":"He responded to criticism gracefully.","zh":"他優雅地回應批評。"},{"en":"Respond from calm, not fear.","zh":"從冷靜而不是恐懼回應。"},{"en":"She responds to kindness with kindness.","zh":"她以善意回應善意。"},{"en":"Pause before you respond.","zh":"回應前暫停。"},{"en":"He responded honestly.","zh":"他誠實地回應。"},{"en":"Respond thoughtfully, not impulsively.","zh":"深思熟慮地回應。"},{"en":"She chooses how to respond.","zh":"她選擇如何回應。"},{"en":"Respond to what is real.","zh":"回應真實的東西。"}]},{"word":"react","pos":"verb","chinese":"反應","level":"B1","sentences":[{"en":"She reacts less and reflects more.","zh":"她反應更少，反思更多。"},{"en":"React calmly, not emotionally.","zh":"冷靜地反應，而不是情緒化。"},{"en":"He reacted with surprising calm.","zh":"他以出奇的冷靜反應。"},{"en":"She learned to pause before reacting.","zh":"她學會了反應前暫停。"},{"en":"Do not react to every provocation.","zh":"不要對每個挑釁反應。"},{"en":"He reacted with grace.","zh":"他優雅地反應。"},{"en":"React to facts, not assumptions.","zh":"對事實反應，而不是假設。"},{"en":"She reacts thoughtfully now.","zh":"她現在深思熟慮地反應。"},{"en":"Choose response over reaction.","zh":"選擇回應而不是反應。"},{"en":"React slowly, decide wisely.","zh":"慢慢反應，明智決定。"}]},{"word":"deal","pos":"verb","chinese":"處理","level":"B1","sentences":[{"en":"She deals with problems head-on.","zh":"她正面處理問題。"},{"en":"Deal with it calmly.","zh":"冷靜地處理它。"},{"en":"He dealt with the loss bravely.","zh":"他勇敢地應對了損失。"},{"en":"Deal with what is in front of you.","zh":"處理你面前的東西。"},{"en":"She deals with stress through movement.","zh":"她通過運動應對壓力。"},{"en":"Deal honestly with hard truths.","zh":"誠實地處理艱難的真相。"},{"en":"He dealt with it maturely.","zh":"他成熟地處理了它。"},{"en":"Deal with one thing at a time.","zh":"一次處理一件事。"},{"en":"She deals fairly with everyone.","zh":"她公平地對待每個人。"},{"en":"Deal with the cause, not symptom.","zh":"處理原因，而不是症狀。"}]},{"word":"address","pos":"verb","chinese":"處理；提出","level":"B1","sentences":[{"en":"She addressed the issue directly.","zh":"她直接處理了問題。"},{"en":"Address problems while small.","zh":"在問題小時處理。"},{"en":"He addressed the team honestly.","zh":"他誠實地對團隊講話。"},{"en":"Address the real concern.","zh":"處理真正的擔憂。"},{"en":"She addressed her fears first.","zh":"她首先處理了她的恐懼。"},{"en":"Address it now, not later.","zh":"現在處理，不是以後。"},{"en":"He addressed the conflict calmly.","zh":"他冷靜地處理了衝突。"},{"en":"Address what matters.","zh":"處理重要的。"},{"en":"She addressed the room confidently.","zh":"她自信地對房間講話。"},{"en":"Address concerns before they grow.","zh":"在擔憂變大前處理。"}]},{"word":"settle","pos":"verb","chinese":"解決；安頓","level":"B1","sentences":[{"en":"They settled it peacefully.","zh":"他們和平地解決了它。"},{"en":"She settled into the role quickly.","zh":"她迅速適應了角色。"},{"en":"Settle your mind before deciding.","zh":"決定前安定你的心。"},{"en":"He settled the matter fairly.","zh":"他公平地解決了這件事。"},{"en":"Do not settle for less than you deserve.","zh":"不要將就低於你應得的。"},{"en":"She settled into a calm routine.","zh":"她安頓進平靜的常規。"},{"en":"Settle small things quickly.","zh":"快速解決小事。"},{"en":"He refused to settle for mediocrity.","zh":"他拒絕將就平庸。"},{"en":"She settled into herself.","zh":"她安頓進自己。"},{"en":"Settle disputes with understanding.","zh":"用理解解決爭端。"}]},{"word":"operate","pos":"verb","chinese":"運作","level":"B1","sentences":[{"en":"She operates from clear values.","zh":"她從清晰的價值觀運作。"},{"en":"Operate within your limits.","zh":"在你的限制內運作。"},{"en":"He operates calmly under pressure.","zh":"他在壓力下冷靜運作。"},{"en":"Operate with integrity.","zh":"正直地運作。"},{"en":"She operates on trust.","zh":"她基於信任運作。"},{"en":"Operate with focus.","zh":"以專注運作。"},{"en":"He knows how it operates.","zh":"他知道它如何運作。"},{"en":"Operate from rest.","zh":"從休息運作。"},{"en":"She operates at a steady pace.","zh":"她以穩定的節奏運作。"},{"en":"Operate with clarity.","zh":"以清晰運作。"}]},{"word":"perform","pos":"verb","chinese":"表現；執行","level":"B1","sentences":[{"en":"She performs best when calm.","zh":"她冷靜時表現最好。"},{"en":"Perform your role with care.","zh":"用心執行你的角色。"},{"en":"He performs consistently.","zh":"他持續表現。"},{"en":"Performance follows preparation.","zh":"表現跟隨準備。"},{"en":"She performed under pressure.","zh":"她在壓力下表現。"},{"en":"Perform from strength.","zh":"從力量表現。"},{"en":"He performs his duties faithfully.","zh":"他忠實地履行職責。"},{"en":"Performance improves with rest.","zh":"表現隨休息改善。"},{"en":"She performs at her own level.","zh":"她在自己的水平表現。"},{"en":"Perform well, then let go.","zh":"表現好，然後放手。"}]},{"word":"complete","pos":"verb","chinese":"完成","level":"B1","sentences":[{"en":"She completes what she starts.","zh":"她完成她開始的。"},{"en":"Complete the important first.","zh":"首先完成重要的。"},{"en":"He completed it early.","zh":"他提前完成了。"},{"en":"Completing builds confidence.","zh":"完成建立信心。"},{"en":"She felt complete after.","zh":"之後她感到完整。"},{"en":"Complete one thing fully.","zh":"完全完成一件事。"},{"en":"He completed it despite obstacles.","zh":"儘管障礙他完成了。"},{"en":"Completion is its own reward.","zh":"完成是它自己的回報。"},{"en":"She completes tasks calmly.","zh":"她冷靜地完成任務。"},{"en":"Complete the work, then rest.","zh":"完成工作，然後休息。"}]},{"word":"navigate","pos":"verb","chinese":"駕馭","level":"B1","sentences":[{"en":"She navigates change with grace.","zh":"她優雅地駕馭變化。"},{"en":"Navigate hard times one day at a time.","zh":"一天一天駕馭艱難時期。"},{"en":"He navigated the conflict wisely.","zh":"他明智地駕馭了衝突。"},{"en":"Navigating uncertainty takes courage.","zh":"駕馭不確定性需要勇氣。"},{"en":"She navigates relationships with care.","zh":"她小心駕馭關係。"},{"en":"Navigate by your values.","zh":"按你的價值觀導航。"},{"en":"He navigated a transition.","zh":"他駕馭了一個過渡。"},{"en":"Navigating well needs self-awareness.","zh":"駕馭得好需要自我意識。"},{"en":"She navigates complexity calmly.","zh":"她冷靜地駕馭複雜性。"},{"en":"Navigate forward, even if unclear.","zh":"向前導航，即使不清楚。"}]},{"word":"propose","pos":"verb","chinese":"提議","level":"B1","sentences":[{"en":"She proposed a simpler solution.","zh":"她提議了更簡單的方案。"},{"en":"Propose without attachment.","zh":"不帶執著地提議。"},{"en":"He proposed a fair compromise.","zh":"他提議了公平的妥協。"},{"en":"Proposing takes courage.","zh":"提議需要勇氣。"},{"en":"She proposed a new way.","zh":"她提議了一個新方式。"},{"en":"Propose, then listen.","zh":"提議，然後傾聽。"},{"en":"He proposed they try it.","zh":"他提議他們試試。"},{"en":"Proposing well means good timing.","zh":"提議得好意味著好時機。"},{"en":"She proposed it confidently.","zh":"她自信地提議。"},{"en":"Propose solutions, not problems.","zh":"提議解決方案，而不是問題。"}]},{"word":"advise","pos":"verb","chinese":"建議","level":"B1","sentences":[{"en":"She advises without imposing.","zh":"她建議而不強加。"},{"en":"Advise gently.","zh":"溫和地建議。"},{"en":"He advised me to slow down.","zh":"他建議我放慢。"},{"en":"Advise from experience.","zh":"從經驗建議。"},{"en":"She advises with care.","zh":"她以關心建議。"},{"en":"Advise only when asked.","zh":"只在被問時建議。"},{"en":"He advised patience.","zh":"他建議耐心。"},{"en":"Advise others as yourself.","zh":"像對自己一樣建議別人。"},{"en":"She advised against rushing.","zh":"她建議不要匆忙。"},{"en":"Advise wisely, then let them choose.","zh":"明智建議，然後讓他們選擇。"}]},{"word":"deliver","pos":"verb","chinese":"交付；履行","level":"B1","sentences":[{"en":"She delivers on every promise.","zh":"她履行每一個承諾。"},{"en":"Deliver value before asking.","zh":"在要求前交付價值。"},{"en":"He delivers under pressure.","zh":"他在壓力下交付。"},{"en":"Deliver quality, not just quantity.","zh":"交付質量，而不只是數量。"},{"en":"She delivered the news kindly.","zh":"她善意地傳達了消息。"},{"en":"Deliver consistently over time.","zh":"隨時間持續交付。"},{"en":"He delivered more than expected.","zh":"他交付的比預期多。"},{"en":"Deliver your best, then rest.","zh":"交付你最好的，然後休息。"},{"en":"She always delivers calmly.","zh":"她總是冷靜地交付。"},{"en":"Deliver results, not excuses.","zh":"交付結果，而不是藉口。"}]},{"word":"coordinate","pos":"verb","chinese":"協調","level":"B1","sentences":[{"en":"She coordinates the team smoothly.","zh":"她順利地協調團隊。"},{"en":"Coordinate efforts toward one goal.","zh":"協調努力朝一個目標。"},{"en":"He coordinated the event well.","zh":"他很好地協調了活動。"},{"en":"Coordinating needs clear communication.","zh":"協調需要清晰的溝通。"},{"en":"She coordinates many roles.","zh":"她協調許多角色。"},{"en":"Coordinate before acting.","zh":"行動前協調。"},{"en":"He coordinated everyone's schedules.","zh":"他協調了每個人的時間表。"},{"en":"Coordination prevents confusion.","zh":"協調防止混亂。"},{"en":"She coordinates with precision.","zh":"她精確地協調。"},{"en":"Coordinate parts into a whole.","zh":"把各部分協調成整體。"}]},{"word":"undertake","pos":"verb","chinese":"承擔","level":"B1","sentences":[{"en":"She undertook a huge challenge.","zh":"她承擔了一個巨大的挑戰。"},{"en":"Undertake what aligns with your values.","zh":"承擔與你價值觀一致的。"},{"en":"He undertook the task willingly.","zh":"他願意承擔任務。"},{"en":"Undertaking big goals needs planning.","zh":"承擔大目標需要計畫。"},{"en":"She undertook the journey alone.","zh":"她獨自踏上旅程。"},{"en":"Undertake less, do it well.","zh":"承擔更少，做得好。"},{"en":"He undertook to fix it.","zh":"他著手修理它。"},{"en":"Undertaking builds capability.","zh":"承擔建立能力。"},{"en":"She undertook a year of change.","zh":"她著手一年的改變。"},{"en":"Undertake what grows you.","zh":"承擔讓你成長的。"}]},{"word":"venture","pos":"verb","chinese":"冒險","level":"B1","sentences":[{"en":"She ventured into the unknown.","zh":"她冒險進入未知。"},{"en":"Venture beyond your comfort zone.","zh":"冒險超越舒適區。"},{"en":"He started a small venture.","zh":"他開始了一個小企業。"},{"en":"Venturing requires accepting risk.","zh":"冒險需要接受風險。"},{"en":"She ventured an honest opinion.","zh":"她大膽提出誠實的意見。"},{"en":"Venture out and see.","zh":"冒險出去看看。"},{"en":"He ventured a guess.","zh":"他大膽猜測。"},{"en":"Venturing leads to growth.","zh":"冒險導致成長。"},{"en":"She ventured into a new field.","zh":"她冒險進入新領域。"},{"en":"Venture with courage.","zh":"以勇氣冒險。"}]},{"word":"launch","pos":"verb","chinese":"推出","level":"B1","sentences":[{"en":"She launched the project boldly.","zh":"她大膽地推出項目。"},{"en":"Launch before fully ready.","zh":"在完全準備好前推出。"},{"en":"He launched a new chapter.","zh":"他開啟了新篇章。"},{"en":"Launching is scary and necessary.","zh":"推出可怕又必要。"},{"en":"She launched with confidence.","zh":"她自信地推出。"},{"en":"Launch small, then improve.","zh":"小規模推出，然後改進。"},{"en":"He launched after years of prep.","zh":"多年準備後他推出。"},{"en":"Launching teaches more than planning.","zh":"推出教的比計畫多。"},{"en":"She launched and learned.","zh":"她推出並學習。"},{"en":"Launch, then iterate.","zh":"推出，然後迭代。"}]},{"word":"found","pos":"verb","chinese":"創辦","level":"B1","sentences":[{"en":"She founded a business from passion.","zh":"她從熱情創辦了生意。"},{"en":"Found your life on values.","zh":"在價值觀上建立你的生活。"},{"en":"He founded a community.","zh":"他創辦了一個社群。"},{"en":"Founding requires courage.","zh":"創辦需要勇氣。"},{"en":"She founded it with vision.","zh":"她用願景創辦了它。"},{"en":"Found habits on consistency.","zh":"在一致性上建立習慣。"},{"en":"He founded the group on trust.","zh":"他在信任上創辦了團體。"},{"en":"Founding is the brave first step.","zh":"創辦是勇敢的第一步。"},{"en":"She founded a lasting tradition.","zh":"她創辦了一個持久的傳統。"},{"en":"Found your days on what matters.","zh":"在重要的事上建立你的日子。"}]},{"word":"predict","pos":"verb","chinese":"預測","level":"B1","sentences":[{"en":"No one can predict the future.","zh":"沒有人能預測未來。"},{"en":"She predicted it correctly.","zh":"她正確地預測了它。"},{"en":"Predict less, prepare more.","zh":"少預測，多準備。"},{"en":"He predicted the outcome calmly.","zh":"他冷靜地預測了結果。"},{"en":"Hard to predict, easy to prepare for.","zh":"難以預測，容易準備。"},{"en":"She predicted the trend early.","zh":"她及早預測了趨勢。"},{"en":"Predicting is guessing with data.","zh":"預測是用數據猜測。"},{"en":"He could not predict her response.","zh":"他無法預測她的回應。"},{"en":"Predict the obstacles ahead.","zh":"預測前方的障礙。"},{"en":"She rarely tries to predict.","zh":"她很少試圖預測。"}]},{"word":"prove","pos":"verb","chinese":"證明","level":"B1","sentences":[{"en":"She proved them wrong gracefully.","zh":"她優雅地證明他們錯了。"},{"en":"Prove it through action.","zh":"通過行動證明它。"},{"en":"He proved reliable over time.","zh":"他隨時間證明了可靠。"},{"en":"Prove yourself to yourself first.","zh":"首先向自己證明自己。"},{"en":"She proved her point with evidence.","zh":"她用證據證明了她的觀點。"},{"en":"Time proves what is real.","zh":"時間證明什麼是真的。"},{"en":"He proved he could be trusted.","zh":"他證明了他可以被信任。"},{"en":"Prove your worth quietly.","zh":"安靜地證明你的價值。"},{"en":"She proved capable under pressure.","zh":"她在壓力下證明了有能力。"},{"en":"Prove nothing to people who doubt you.","zh":"對懷疑你的人什麼都不證明。"}]},{"word":"confirm","pos":"verb","chinese":"確認","level":"B1","sentences":[{"en":"She confirmed the plan calmly.","zh":"她冷靜地確認了計畫。"},{"en":"Confirm before assuming.","zh":"假設前確認。"},{"en":"He confirmed the details twice.","zh":"他確認了細節兩次。"},{"en":"Confirm what matters in writing.","zh":"用書面確認重要的。"},{"en":"She confirmed she could attend.","zh":"她確認她能參加。"},{"en":"Confirm the facts first.","zh":"首先確認事實。"},{"en":"He confirmed his commitment.","zh":"他確認了他的承諾。"},{"en":"Confirm understanding before moving on.","zh":"繼續前確認理解。"},{"en":"She confirmed the appointment.","zh":"她確認了預約。"},{"en":"Confirm, do not just hope.","zh":"確認，不要只是希望。"}]},{"word":"admit","pos":"verb","chinese":"承認","level":"B1","sentences":[{"en":"She admits her mistakes openly.","zh":"她公開承認她的錯誤。"},{"en":"Admit it and move forward.","zh":"承認它並前進。"},{"en":"He admitted he was wrong.","zh":"他承認他錯了。"},{"en":"Admitting is the start of change.","zh":"承認是改變的開始。"},{"en":"She admitted she needed help.","zh":"她承認她需要幫助。"},{"en":"Admit what you do not know.","zh":"承認你不知道的。"},{"en":"He admitted his fear honestly.","zh":"他誠實地承認了他的恐懼。"},{"en":"Admitting takes real courage.","zh":"承認需要真正的勇氣。"},{"en":"She admitted her part in it.","zh":"她承認了她在其中的部分。"},{"en":"Admit, apologise, then improve.","zh":"承認，道歉，然後改進。"}]},{"word":"remind","pos":"verb","chinese":"提醒","level":"B1","sentences":[{"en":"She reminds me of my own strength.","zh":"她提醒我自己的力量。"},{"en":"Remind yourself why you started.","zh":"提醒自己為什麼開始。"},{"en":"He reminded me gently.","zh":"他溫和地提醒我。"},{"en":"Remind people they matter.","zh":"提醒人們他們很重要。"},{"en":"She reminds herself to rest.","zh":"她提醒自己休息。"},{"en":"Remind yourself of how far you came.","zh":"提醒自己你走了多遠。"},{"en":"He reminded the team of the goal.","zh":"他提醒團隊目標。"},{"en":"Remind, do not nag.","zh":"提醒，不要嘮叨。"},{"en":"She reminded him kindly.","zh":"她善意地提醒他。"},{"en":"Remind yourself: this too will pass.","zh":"提醒自己：這也會過去。"}]},{"word":"warn","pos":"verb","chinese":"警告","level":"B1","sentences":[{"en":"She warned me with kindness.","zh":"她善意地警告我。"},{"en":"Warn early, not after.","zh":"及早警告，而不是之後。"},{"en":"He warned of the risk calmly.","zh":"他冷靜地警告了風險。"},{"en":"Warn people you care about.","zh":"警告你關心的人。"},{"en":"She warned against rushing.","zh":"她警告不要匆忙。"},{"en":"Warn gently, then trust them.","zh":"溫和地警告，然後信任他們。"},{"en":"He warned us in time.","zh":"他及時警告了我們。"},{"en":"Warn without scaring.","zh":"警告而不嚇唬。"},{"en":"She warned of the danger.","zh":"她警告了危險。"},{"en":"Warn once, then let go.","zh":"警告一次，然後放手。"}]},{"word":"mention","pos":"verb","chinese":"提及","level":"B1","sentences":[{"en":"She mentioned it casually.","zh":"她隨意地提到它。"},{"en":"Mention what matters, skip the rest.","zh":"提及重要的，跳過其餘的。"},{"en":"He mentioned her by name.","zh":"他用名字提到了她。"},{"en":"Mention your needs clearly.","zh":"清楚地提及你的需求。"},{"en":"She mentioned a helpful book.","zh":"她提到了一本有幫助的書。"},{"en":"Mention it once, then move on.","zh":"提及一次，然後繼續。"},{"en":"He mentioned the issue gently.","zh":"他溫和地提到了問題。"},{"en":"Mention progress to stay motivated.","zh":"提及進步以保持動力。"},{"en":"She mentioned she was proud.","zh":"她提到她很驕傲。"},{"en":"Mention, do not lecture.","zh":"提及，不要說教。"}]},{"word":"claim","pos":"verb","chinese":"聲稱","level":"B1","sentences":[{"en":"She makes no claims she cannot back.","zh":"她不做她無法支持的聲稱。"},{"en":"Claim your space confidently.","zh":"自信地佔據你的空間。"},{"en":"He claimed responsibility fully.","zh":"他完全承擔了責任。"},{"en":"Claim less, prove more.","zh":"少聲稱，多證明。"},{"en":"She claimed her power back.","zh":"她奪回了她的力量。"},{"en":"Claim what is rightfully yours.","zh":"聲明屬於你的東西。"},{"en":"He claimed the win humbly.","zh":"他謙遜地聲稱了勝利。"},{"en":"Claim your worth.","zh":"聲明你的價值。"},{"en":"She claimed her seat at the table.","zh":"她聲明了她在桌邊的位置。"},{"en":"Claim it, then earn it daily.","zh":"聲明它，然後每天贏得它。"}]},{"word":"argue","pos":"verb","chinese":"爭論","level":"B1","sentences":[{"en":"She argues with respect, not anger.","zh":"她以尊重而不是憤怒爭論。"},{"en":"Argue ideas, not people.","zh":"爭論想法，而不是人。"},{"en":"He argued his point calmly.","zh":"他冷靜地爭論他的觀點。"},{"en":"Argue to understand, not to win.","zh":"爭論為了理解，而不是贏。"},{"en":"She rarely argues but always listens.","zh":"她很少爭論但總是傾聽。"},{"en":"Argue less, ask more.","zh":"少爭論，多問。"},{"en":"He argued for fairness.","zh":"他為公平爭論。"},{"en":"Arguing well requires listening.","zh":"爭論得好需要傾聽。"},{"en":"She argued with quiet logic.","zh":"她以安靜的邏輯爭論。"},{"en":"Argue the point, keep the peace.","zh":"爭論觀點，保持和平。"}]},{"word":"defend","pos":"verb","chinese":"捍衛","level":"B1","sentences":[{"en":"She defends her boundaries calmly.","zh":"她冷靜地捍衛她的界限。"},{"en":"Defend your values, not your ego.","zh":"捍衛你的價值觀，而不是你的自我。"},{"en":"He defended his friend loyally.","zh":"他忠誠地捍衛他的朋友。"},{"en":"Defend what is right, kindly.","zh":"善意地捍衛正確的。"},{"en":"She defended her choice with clarity.","zh":"她以清晰捍衛她的選擇。"},{"en":"Defend others when they cannot.","zh":"在別人不能時捍衛他們。"},{"en":"He defended his time fiercely.","zh":"他強烈地捍衛他的時間。"},{"en":"Defend your peace.","zh":"捍衛你的平靜。"},{"en":"She defended the truth bravely.","zh":"她勇敢地捍衛真相。"},{"en":"Defend without attacking.","zh":"捍衛而不攻擊。"}]},{"word":"praise","pos":"verb","chinese":"讚揚","level":"B1","sentences":[{"en":"She praises effort, not just results.","zh":"她讚揚努力，而不只是結果。"},{"en":"Praise others sincerely.","zh":"真誠地讚揚別人。"},{"en":"He praised the team's progress.","zh":"他讚揚了團隊的進步。"},{"en":"Praise in public, correct in private.","zh":"公開讚揚，私下糾正。"},{"en":"She praises generously.","zh":"她慷慨地讚揚。"},{"en":"Praise the process, not just talent.","zh":"讚揚過程，而不只是才能。"},{"en":"He praised her quietly.","zh":"他安靜地讚揚她。"},{"en":"Praise builds confidence.","zh":"讚揚建立信心。"},{"en":"She praised what others overlooked.","zh":"她讚揚了別人忽略的。"},{"en":"Praise honestly, never falsely.","zh":"誠實地讚揚，從不虛假。"}]},{"word":"criticise","pos":"verb","chinese":"批評","level":"B1","sentences":[{"en":"She criticises ideas, not people.","zh":"她批評想法，而不是人。"},{"en":"Criticise to help, not to hurt.","zh":"批評為了幫助，而不是傷害。"},{"en":"He criticised gently and fairly.","zh":"他溫和而公平地批評。"},{"en":"Criticise less, encourage more.","zh":"少批評，多鼓勵。"},{"en":"She took criticism gracefully.","zh":"她優雅地接受批評。"},{"en":"Criticise the work, respect the person.","zh":"批評工作，尊重人。"},{"en":"He criticised his own work first.","zh":"他首先批評自己的工作。"},{"en":"Criticism stings but can help.","zh":"批評刺痛但能幫助。"},{"en":"She criticised with kindness.","zh":"她以善意批評。"},{"en":"Criticise constructively or not at all.","zh":"建設性地批評，否則就不批評。"}]},{"word":"notice_v","pos":"verb","chinese":"注意到","level":"B1","sentences":[{"en":"She notices what others miss.","zh":"她注意到別人錯過的。"},{"en":"Notice the good things daily.","zh":"每天注意好事物。"},{"en":"He noticed her effort.","zh":"他注意到了她的努力。"},{"en":"Notice without judging.","zh":"注意而不評判。"},{"en":"She noticed a small change.","zh":"她注意到了一個小變化。"},{"en":"Notice your own patterns.","zh":"注意你自己的模式。"},{"en":"He noticed the warning signs.","zh":"他注意到了警告信號。"},{"en":"Notice beauty in the ordinary.","zh":"注意平凡中的美。"},{"en":"She noticed how he felt.","zh":"她注意到了他的感受。"},{"en":"Notice more, react less.","zh":"多注意，少反應。"}]},{"word":"nuance","pos":"noun","chinese":"細微差別","level":"B2","sentences":[{"en":"She appreciates nuance in every argument.","zh":"她欣賞每個論點中的細微差別。"},{"en":"Nuance is lost in heated debate.","zh":"細微差別在激烈辯論中失去。"},{"en":"He sees nuance where others see black and white.","zh":"他在別人看到黑白的地方看到細微差別。"},{"en":"Real understanding lives in nuance.","zh":"真正的理解存在於細微差別中。"},{"en":"She handles topics with nuance.","zh":"她以細膩處理話題。"},{"en":"Nuance requires patience to perceive.","zh":"細微差別需要耐心察覺。"},{"en":"He explained the nuance carefully.","zh":"他仔細解釋了細微差別。"},{"en":"Embrace nuance over simple answers.","zh":"擁抱細微差別而不是簡單答案。"},{"en":"She writes with nuance.","zh":"她寫作有細膩。"},{"en":"Nuance marks deep thinking.","zh":"細膩標誌深度思考。"}]},{"word":"ambiguity","pos":"noun","chinese":"模糊；歧義","level":"B2","sentences":[{"en":"She tolerates ambiguity well.","zh":"她很好地容忍模糊。"},{"en":"Ambiguity is uncomfortable but normal.","zh":"模糊不舒服但正常。"},{"en":"He navigates ambiguity with calm.","zh":"他冷靜地駕馭模糊。"},{"en":"Learn to sit with ambiguity.","zh":"學會與模糊共處。"},{"en":"Ambiguity opens room for creativity.","zh":"模糊為創造力打開空間。"},{"en":"She removed ambiguity with clear words.","zh":"她用清晰的話消除歧義。"},{"en":"Ambiguity tests your patience.","zh":"模糊考驗你的耐心。"},{"en":"He thrives amid ambiguity.","zh":"他在模糊中茁壯成長。"},{"en":"Ambiguity is part of real life.","zh":"模糊是真實生活的一部分。"},{"en":"Embrace ambiguity, do not force clarity.","zh":"擁抱模糊，不要強迫清晰。"}]},{"word":"paradox","pos":"noun","chinese":"悖論","level":"B2","sentences":[{"en":"Life is full of quiet paradoxes.","zh":"生活充滿安靜的悖論。"},{"en":"The paradox is that less can be more.","zh":"悖論是少可以是多。"},{"en":"She holds the paradox gracefully.","zh":"她優雅地持有悖論。"},{"en":"Rest makes you productive — a paradox.","zh":"休息讓你有生產力——一個悖論。"},{"en":"He embraced the paradox of strength and softness.","zh":"他擁抱了力量與柔軟的悖論。"},{"en":"Paradoxes reveal deeper truths.","zh":"悖論揭示更深的真相。"},{"en":"The paradox of choice overwhelms us.","zh":"選擇的悖論壓垮我們。"},{"en":"She lives within a beautiful paradox.","zh":"她生活在美麗的悖論中。"},{"en":"Paradox is where wisdom hides.","zh":"悖論是智慧隱藏的地方。"},{"en":"Accept the paradox without solving it.","zh":"接受悖論而不解決它。"}]},{"word":"implication","pos":"noun","chinese":"含義","level":"B2","sentences":[{"en":"She considered every implication.","zh":"她考慮了每個含義。"},{"en":"The implications were larger than expected.","zh":"含義比預期大。"},{"en":"He grasped the deeper implication.","zh":"他理解了更深的含義。"},{"en":"Think through implications before acting.","zh":"行動前思考含義。"},{"en":"The implication was clear.","zh":"含義很清楚。"},{"en":"She weighed the long-term implications.","zh":"她權衡了長期含義。"},{"en":"Implications ripple further than we see.","zh":"含義漣漪比我們看到的遠。"},{"en":"He missed the implication.","zh":"他錯過了含義。"},{"en":"Consider the ethical implications.","zh":"考慮倫理含義。"},{"en":"The implication shaped her decision.","zh":"含義塑造了她的決定。"}]},{"word":"assumption","pos":"noun","chinese":"假設","level":"B2","sentences":[{"en":"She questions her assumptions daily.","zh":"她每天質疑她的假設。"},{"en":"Assumptions cause misunderstandings.","zh":"假設導致誤解。"},{"en":"He challenged the core assumption.","zh":"他挑戰了核心假設。"},{"en":"Drop the assumption and ask.","zh":"放下假設，直接問。"},{"en":"Her assumption was wrong.","zh":"她的假設是錯的。"},{"en":"Examine assumptions first.","zh":"首先檢查假設。"},{"en":"He made no assumptions.","zh":"他沒有任何假設。"},{"en":"Assumptions feel like facts but are not.","zh":"假設感覺像事實但不是。"},{"en":"She named the hidden assumption.","zh":"她說出了隱藏的假設。"},{"en":"Challenge the assumption everyone accepts.","zh":"挑戰每個人都接受的假設。"}]},{"word":"perception","pos":"noun","chinese":"感知","level":"B2","sentences":[{"en":"Perception shapes our reality.","zh":"感知塑造我們的現實。"},{"en":"She shifted his perception.","zh":"她改變了他的看法。"},{"en":"Perception and truth differ.","zh":"感知和真相不同。"},{"en":"He changed his perception of failure.","zh":"他改變了對失敗的看法。"},{"en":"Perception is influenced by mood.","zh":"感知受情緒影響。"},{"en":"Her perception was sharp.","zh":"她的感知敏銳。"},{"en":"Alter perception, alter experience.","zh":"改變感知，改變體驗。"},{"en":"Perception is not always accurate.","zh":"感知不總是準確。"},{"en":"He shifted her perception gently.","zh":"他溫和地改變了她的看法。"},{"en":"Perception can be trained.","zh":"感知可以被訓練。"}]},{"word":"coherent","pos":"adjective","chinese":"連貫的","level":"B2","sentences":[{"en":"Her argument was clear and coherent.","zh":"她的論點清晰連貫。"},{"en":"Keep your message coherent.","zh":"保持你的信息連貫。"},{"en":"He gave a coherent explanation.","zh":"他給了一個連貫的解釋。"},{"en":"A coherent plan beats a clever one.","zh":"連貫的計畫勝過聰明的。"},{"en":"She stayed coherent under stress.","zh":"她在壓力下保持連貫。"},{"en":"Coherent thinking leads to clarity.","zh":"連貫的思考導致清晰。"},{"en":"His story was perfectly coherent.","zh":"他的故事完全連貫。"},{"en":"Make your goals coherent.","zh":"讓你的目標連貫。"},{"en":"A coherent life aligns with values.","zh":"連貫的生活與價值觀一致。"},{"en":"She speaks in coherent ideas.","zh":"她以連貫的想法說話。"}]},{"word":"inevitable","pos":"adjective","chinese":"不可避免的","level":"B2","sentences":[{"en":"Change is inevitable; growth is a choice.","zh":"改變不可避免；成長是選擇。"},{"en":"The outcome felt inevitable.","zh":"結果感覺不可避免。"},{"en":"He accepted the inevitable calmly.","zh":"他冷靜地接受了不可避免的。"},{"en":"Some endings are inevitable.","zh":"有些結局不可避免。"},{"en":"She prepared for the inevitable.","zh":"她為不可避免的做準備。"},{"en":"Failure is an inevitable part of trying.","zh":"失敗是嘗試不可避免的一部分。"},{"en":"Make peace with the inevitable.","zh":"與不可避免的和解。"},{"en":"It was inevitable he would succeed.","zh":"他成功是不可避免的。"},{"en":"The inevitable came sooner than expected.","zh":"不可避免的比預期來得早。"},{"en":"Accept the inevitable, focus on response.","zh":"接受不可避免的，專注於回應。"}]},{"word":"profound","pos":"adjective","chinese":"深刻的","level":"B2","sentences":[{"en":"She had a profound effect on me.","zh":"她對我有深刻的影響。"},{"en":"That book offered profound insight.","zh":"那本書提供了深刻的洞察。"},{"en":"He spoke a profound truth simply.","zh":"他簡單地說出了深刻的真相。"},{"en":"Profound change starts small.","zh":"深刻的改變從小開始。"},{"en":"Her kindness was profound.","zh":"她的善良是深刻的。"},{"en":"A profound silence filled the room.","zh":"深刻的寂靜充滿房間。"},{"en":"He felt a profound sense of peace.","zh":"他感到深刻的平靜。"},{"en":"Profound ideas are often simple.","zh":"深刻的想法往往簡單。"},{"en":"She made a profound difference.","zh":"她造成了深刻的差異。"},{"en":"Profound growth requires discomfort.","zh":"深刻的成長需要不適。"}]},{"word":"subtle","pos":"adjective","chinese":"微妙的","level":"B2","sentences":[{"en":"The change was subtle but real.","zh":"變化微妙但真實。"},{"en":"She has a subtle sense of humour.","zh":"她有微妙的幽默感。"},{"en":"Subtle shifts add up over time.","zh":"微妙的轉變隨時間累積。"},{"en":"He noticed the subtle difference.","zh":"他注意到了微妙的差別。"},{"en":"Subtle is often more powerful.","zh":"微妙往往更有力量。"},{"en":"Her influence was subtle.","zh":"她的影響是微妙的。"},{"en":"Subtle cues reveal a lot.","zh":"微妙的線索揭示很多。"},{"en":"He made a subtle but key point.","zh":"他提出了微妙但關鍵的觀點。"},{"en":"Subtle beauty is easy to miss.","zh":"微妙的美容易錯過。"},{"en":"Notice the subtle, not just the loud.","zh":"注意微妙的，而不只是大聲的。"}]},{"word":"intricate","pos":"adjective","chinese":"錯綜複雜的","level":"B2","sentences":[{"en":"The design was beautifully intricate.","zh":"這個設計錯綜複雜地美麗。"},{"en":"She handled the intricate details.","zh":"她處理了錯綜複雜的細節。"},{"en":"Human emotions are intricate.","zh":"人類情感錯綜複雜。"},{"en":"He explained the intricate process.","zh":"他解釋了錯綜複雜的過程。"},{"en":"Intricate does not mean better.","zh":"錯綜複雜不意味著更好。"},{"en":"She wove an intricate story.","zh":"她編織了一個錯綜複雜的故事。"},{"en":"The intricate pattern took hours.","zh":"錯綜複雜的圖案花了幾個小時。"},{"en":"He admired the intricate craft.","zh":"他欽佩錯綜複雜的工藝。"},{"en":"Intricate problems need patience.","zh":"錯綜複雜的問題需要耐心。"},{"en":"She sees the intricate connections.","zh":"她看到錯綜複雜的連結。"}]},{"word":"comprehensive","pos":"adjective","chinese":"全面的","level":"B2","sentences":[{"en":"She gave a comprehensive answer.","zh":"她給了一個全面的答案。"},{"en":"Take a comprehensive view first.","zh":"首先採取全面的觀點。"},{"en":"He did comprehensive research.","zh":"他做了全面的研究。"},{"en":"A comprehensive plan covers all bases.","zh":"全面的計畫涵蓋所有方面。"},{"en":"She offered comprehensive support.","zh":"她提供了全面的支持。"},{"en":"Comprehensive does not mean complicated.","zh":"全面不意味著複雜。"},{"en":"He took a comprehensive approach.","zh":"他採取了全面的方法。"},{"en":"The guide was comprehensive.","zh":"這個指南是全面的。"},{"en":"She prepared comprehensively.","zh":"她全面地準備。"},{"en":"A comprehensive view prevents blind spots.","zh":"全面的觀點防止盲點。"}]},{"word":"pervasive","pos":"adjective","chinese":"普遍的","level":"B2","sentences":[{"en":"Stress is pervasive in modern life.","zh":"壓力在現代生活中普遍存在。"},{"en":"Her calm was pervasive.","zh":"她的冷靜無處不在。"},{"en":"A pervasive sense of hope spread.","zh":"一種普遍的希望感蔓延。"},{"en":"The problem was pervasive.","zh":"問題很普遍。"},{"en":"Kindness can be pervasive too.","zh":"善良也可以無處不在。"},{"en":"Pervasive doubt held him back.","zh":"普遍的懷疑阻礙了他。"},{"en":"The influence was pervasive.","zh":"影響很普遍。"},{"en":"She fought a pervasive myth.","zh":"她對抗一個普遍的迷思。"},{"en":"Pervasive negativity drains energy.","zh":"普遍的負面情緒耗盡能量。"},{"en":"A pervasive calm settled in.","zh":"一種普遍的平靜安頓下來。"}]},{"word":"inherent","pos":"adjective","chinese":"固有的","level":"B2","sentences":[{"en":"Risk is inherent in any growth.","zh":"風險是任何成長固有的。"},{"en":"She trusts the inherent good in people.","zh":"她相信人們固有的善。"},{"en":"There is inherent value in rest.","zh":"休息有固有的價值。"},{"en":"He has an inherent calm.","zh":"他有固有的冷靜。"},{"en":"Inherent worth needs no proof.","zh":"固有的價值不需要證明。"},{"en":"Creativity is inherent in everyone.","zh":"創造力是每個人固有的。"},{"en":"The flaw was inherent in the design.","zh":"缺陷是設計固有的。"},{"en":"She honours her inherent nature.","zh":"她尊重她固有的本性。"},{"en":"Inherent strengths grow with use.","zh":"固有的優勢隨使用成長。"},{"en":"Find the inherent meaning.","zh":"找到固有的意義。"}]},{"word":"explicit","pos":"adjective","chinese":"明確的","level":"B2","sentences":[{"en":"She was explicit about her needs.","zh":"她明確地表達她的需求。"},{"en":"Make expectations explicit.","zh":"讓期望明確。"},{"en":"He gave explicit instructions.","zh":"他給了明確的指示。"},{"en":"Explicit beats implied every time.","zh":"明確每次都勝過暗示。"},{"en":"She made her boundaries explicit.","zh":"她明確了她的界限。"},{"en":"Be explicit to avoid confusion.","zh":"明確以避免混亂。"},{"en":"His consent was explicit.","zh":"他的同意是明確的。"},{"en":"Explicit goals are easier to reach.","zh":"明確的目標更容易達到。"},{"en":"She stated it explicitly.","zh":"她明確地陳述了它。"},{"en":"Explicit communication builds trust.","zh":"明確的溝通建立信任。"}]},{"word":"implicit","pos":"adjective","chinese":"隱含的","level":"B2","sentences":[{"en":"There was an implicit trust between them.","zh":"他們之間有隱含的信任。"},{"en":"Implicit assumptions cause problems.","zh":"隱含的假設導致問題。"},{"en":"She understood the implicit meaning.","zh":"她理解了隱含的意義。"},{"en":"Implicit bias is hard to see.","zh":"隱含的偏見難以看見。"},{"en":"His approval was implicit.","zh":"他的認可是隱含的。"},{"en":"Make the implicit explicit.","zh":"把隱含的變明確。"},{"en":"There was implicit respect.","zh":"有隱含的尊重。"},{"en":"Implicit rules shape behaviour.","zh":"隱含的規則塑造行為。"},{"en":"She sensed the implicit tension.","zh":"她感覺到隱含的緊張。"},{"en":"Implicit understanding runs deep.","zh":"隱含的理解很深。"}]},{"word":"prevalent","pos":"adjective","chinese":"盛行的","level":"B2","sentences":[{"en":"That belief is prevalent today.","zh":"那個信念今天很盛行。"},{"en":"Burnout is prevalent in fast cultures.","zh":"倦怠在快節奏的文化中盛行。"},{"en":"A prevalent myth misleads many.","zh":"一個盛行的迷思誤導許多人。"},{"en":"Kindness should be more prevalent.","zh":"善良應該更盛行。"},{"en":"The trend is prevalent online.","zh":"這個趨勢在網上盛行。"},{"en":"Comparison is prevalent on social media.","zh":"比較在社交媒體上盛行。"},{"en":"That attitude is less prevalent now.","zh":"那種態度現在不那麼盛行。"},{"en":"A prevalent fear holds people back.","zh":"一種盛行的恐懼阻礙人們。"},{"en":"The idea became prevalent quickly.","zh":"這個想法很快變得盛行。"},{"en":"Prevalent does not mean true.","zh":"盛行不意味著真實。"}]},{"word":"scrutinise","pos":"verb","chinese":"仔細檢查","level":"B2","sentences":[{"en":"She scrutinises every detail.","zh":"她仔細檢查每個細節。"},{"en":"Scrutinise your own assumptions.","zh":"仔細檢查你自己的假設。"},{"en":"He scrutinised the data closely.","zh":"他仔細檢查了數據。"},{"en":"Scrutinising too much causes doubt.","zh":"檢查太多導致懷疑。"},{"en":"She scrutinised the contract.","zh":"她仔細檢查了合同。"},{"en":"Scrutinise claims before believing.","zh":"相信前仔細檢查聲稱。"},{"en":"He scrutinised his own motives.","zh":"他仔細檢查了自己的動機。"},{"en":"Scrutinise less, trust more.","zh":"少檢查，多信任。"},{"en":"She scrutinised the plan carefully.","zh":"她仔細檢查了計畫。"},{"en":"Scrutinise the source, not just the claim.","zh":"檢查來源，而不只是聲稱。"}]},{"word":"articulate","pos":"verb/adj","chinese":"清楚表達；善於表達的","level":"B2","sentences":[{"en":"She articulates ideas clearly.","zh":"她清楚地表達想法。"},{"en":"Articulate what you actually feel.","zh":"清楚表達你真正的感受。"},{"en":"He is remarkably articulate.","zh":"他非常善於表達。"},{"en":"Articulating helps you understand it.","zh":"清楚表達幫助你理解它。"},{"en":"She articulated the vision well.","zh":"她很好地表達了願景。"},{"en":"Articulate your needs plainly.","zh":"清楚表達你的需求。"},{"en":"He articulated the problem precisely.","zh":"他精確地表達了問題。"},{"en":"Articulate thoughts before speaking.","zh":"說話前清楚表達想法。"},{"en":"She is articulate yet humble.","zh":"她善於表達但謙遜。"},{"en":"Articulate clearly, then listen.","zh":"清楚表達，然後傾聽。"}]},{"word":"advocate","pos":"verb/noun","chinese":"倡導；擁護者","level":"B2","sentences":[{"en":"She advocates for those without a voice.","zh":"她為沒有聲音的人倡導。"},{"en":"Advocate for yourself respectfully.","zh":"尊重地為自己倡導。"},{"en":"He is a strong advocate for rest.","zh":"他是休息的強烈倡導者。"},{"en":"Advocate for what you believe.","zh":"為你相信的倡導。"},{"en":"She advocated quietly but firmly.","zh":"她安靜但堅定地倡導。"},{"en":"Advocate for fairness everywhere.","zh":"到處為公平倡導。"},{"en":"He became an advocate for change.","zh":"他成了改變的倡導者。"},{"en":"Advocate for others and yourself.","zh":"為別人和自己倡導。"},{"en":"She is her own best advocate.","zh":"她是她自己最好的倡導者。"},{"en":"Advocate with facts and heart.","zh":"用事實和真心倡導。"}]},{"word":"deteriorate","pos":"verb","chinese":"惡化","level":"B2","sentences":[{"en":"The situation deteriorated slowly.","zh":"情況慢慢惡化。"},{"en":"Ignored problems deteriorate.","zh":"被忽略的問題會惡化。"},{"en":"His health deteriorated without rest.","zh":"沒有休息他的健康惡化。"},{"en":"Relationships deteriorate without care.","zh":"沒有關懷關係會惡化。"},{"en":"She prevented things from deteriorating.","zh":"她防止事情惡化。"},{"en":"Deteriorating trust is hard to rebuild.","zh":"惡化的信任難以重建。"},{"en":"The mood deteriorated quickly.","zh":"氣氛迅速惡化。"},{"en":"Skills deteriorate without practice.","zh":"沒有練習技能會退化。"},{"en":"He noticed it deteriorating early.","zh":"他及早注意到它惡化。"},{"en":"Stop the deterioration before it spreads.","zh":"在惡化蔓延前阻止它。"}]},{"word":"alleviate","pos":"verb","chinese":"減輕","level":"B2","sentences":[{"en":"Rest alleviates most stress.","zh":"休息減輕大部分壓力。"},{"en":"She alleviated his worry kindly.","zh":"她善意地減輕了他的擔憂。"},{"en":"Alleviate suffering where you can.","zh":"在你能的地方減輕痛苦。"},{"en":"Exercise alleviates anxiety.","zh":"運動減輕焦慮。"},{"en":"He alleviated the tension with humour.","zh":"他用幽默減輕了緊張。"},{"en":"Small acts alleviate big burdens.","zh":"小行為減輕大負擔。"},{"en":"She alleviated their fears.","zh":"她減輕了他們的恐懼。"},{"en":"Alleviate pain, do not just mask it.","zh":"減輕痛苦，不要只是掩蓋它。"},{"en":"Kindness alleviates loneliness.","zh":"善良減輕孤獨。"},{"en":"Alleviate stress through movement.","zh":"通過運動減輕壓力。"}]},{"word":"mitigate","pos":"verb","chinese":"緩解；減輕","level":"B2","sentences":[{"en":"She mitigated the risk carefully.","zh":"她仔細地緩解了風險。"},{"en":"Mitigate problems before they grow.","zh":"在問題變大前緩解它們。"},{"en":"He mitigated the damage quickly.","zh":"他迅速緩解了損害。"},{"en":"Planning mitigates uncertainty.","zh":"計畫緩解不確定性。"},{"en":"She mitigated the impact wisely.","zh":"她明智地緩解了影響。"},{"en":"Mitigate stress with good habits.","zh":"用好習慣緩解壓力。"},{"en":"He took steps to mitigate harm.","zh":"他採取措施緩解傷害。"},{"en":"Mitigating early saves trouble.","zh":"及早緩解省麻煩。"},{"en":"She mitigated the conflict calmly.","zh":"她冷靜地緩解了衝突。"},{"en":"Mitigate the downside, embrace the upside.","zh":"緩解壞處，擁抱好處。"}]},{"word":"undermine","pos":"verb","chinese":"削弱；破壞","level":"B2","sentences":[{"en":"Doubt undermines confidence.","zh":"懷疑削弱信心。"},{"en":"Do not undermine your own progress.","zh":"不要破壞你自己的進步。"},{"en":"He never undermines his team.","zh":"他從不削弱他的團隊。"},{"en":"Comparison undermines joy.","zh":"比較削弱快樂。"},{"en":"She refused to undermine herself.","zh":"她拒絕貶低自己。"},{"en":"Gossip undermines trust.","zh":"八卦破壞信任。"},{"en":"Undermining others weakens everyone.","zh":"削弱別人削弱每個人。"},{"en":"Fear undermines clear thinking.","zh":"恐懼削弱清晰的思考。"},{"en":"He undermined his goal by quitting early.","zh":"他過早放棄破壞了他的目標。"},{"en":"Do not let doubt undermine you.","zh":"不要讓懷疑削弱你。"}]},{"word":"reinforce","pos":"verb","chinese":"強化","level":"B2","sentences":[{"en":"Praise reinforces good habits.","zh":"讚揚強化好習慣。"},{"en":"She reinforced the lesson gently.","zh":"她溫和地強化了教訓。"},{"en":"Repetition reinforces learning.","zh":"重複強化學習。"},{"en":"He reinforced his point with examples.","zh":"他用例子強化他的觀點。"},{"en":"Reinforce what works.","zh":"強化有效的。"},{"en":"Small wins reinforce momentum.","zh":"小勝利強化動力。"},{"en":"She reinforced their confidence.","zh":"她強化了他們的信心。"},{"en":"Reinforce boundaries consistently.","zh":"持續強化界限。"},{"en":"Action reinforces belief.","zh":"行動強化信念。"},{"en":"Reinforce positive behaviour.","zh":"強化積極的行為。"}]},{"word":"encompass","pos":"verb","chinese":"包含；涵蓋","level":"B2","sentences":[{"en":"Her work encompasses many fields.","zh":"她的工作涵蓋許多領域。"},{"en":"Wellbeing encompasses body and mind.","zh":"幸福涵蓋身體和心靈。"},{"en":"The plan encompasses every detail.","zh":"計畫涵蓋每個細節。"},{"en":"Love encompasses patience and trust.","zh":"愛包含耐心和信任。"},{"en":"His vision encompasses the whole team.","zh":"他的願景涵蓋整個團隊。"},{"en":"Success encompasses more than money.","zh":"成功涵蓋的不只是金錢。"},{"en":"The role encompasses many duties.","zh":"這個角色涵蓋許多職責。"},{"en":"Health encompasses rest and movement.","zh":"健康涵蓋休息和運動。"},{"en":"Her kindness encompasses everyone.","zh":"她的善良涵蓋每個人。"},{"en":"Growth encompasses failure too.","zh":"成長也涵蓋失敗。"}]},{"word":"constitute","pos":"verb","chinese":"構成","level":"B2","sentences":[{"en":"These habits constitute a good life.","zh":"這些習慣構成美好的生活。"},{"en":"Trust constitutes the foundation.","zh":"信任構成基礎。"},{"en":"Small acts constitute real change.","zh":"小行為構成真正的改變。"},{"en":"What constitutes success for you?","zh":"什麼對你構成成功？"},{"en":"These values constitute her character.","zh":"這些價值觀構成她的品格。"},{"en":"Consistency constitutes mastery.","zh":"一致性構成精通。"},{"en":"Kindness constitutes true strength.","zh":"善良構成真正的力量。"},{"en":"These steps constitute the process.","zh":"這些步驟構成過程。"},{"en":"Rest constitutes part of the work.","zh":"休息構成工作的一部分。"},{"en":"Daily choices constitute a destiny.","zh":"每天的選擇構成命運。"}]},{"word":"derive","pos":"verb","chinese":"得到；源於","level":"B2","sentences":[{"en":"She derives joy from small things.","zh":"她從小事中得到快樂。"},{"en":"He derives meaning from his work.","zh":"他從工作中得到意義。"},{"en":"Derive strength from your values.","zh":"從你的價值觀得到力量。"},{"en":"She derives calm from routine.","zh":"她從常規中得到平靜。"},{"en":"Derive lessons from every failure.","zh":"從每次失敗得到教訓。"},{"en":"He derives energy from people.","zh":"他從人們得到能量。"},{"en":"Derive confidence from preparation.","zh":"從準備得到信心。"},{"en":"She derives purpose from helping.","zh":"她從幫助中得到目的。"},{"en":"Derive wisdom from experience.","zh":"從經驗得到智慧。"},{"en":"He derives peace from nature.","zh":"他從大自然得到平靜。"}]},{"word":"attribute","pos":"verb/noun","chinese":"歸因；特質","level":"B2","sentences":[{"en":"She attributes her success to consistency.","zh":"她把成功歸因於一致性。"},{"en":"Patience is his best attribute.","zh":"耐心是他最好的特質。"},{"en":"Do not attribute malice to mistakes.","zh":"不要把錯誤歸因於惡意。"},{"en":"She attributes growth to discomfort.","zh":"她把成長歸因於不適。"},{"en":"Kindness is an underrated attribute.","zh":"善良是一個被低估的特質。"},{"en":"He attributed the win to the team.","zh":"他把勝利歸功於團隊。"},{"en":"Attribute credit generously.","zh":"慷慨地歸功。"},{"en":"Her calm is her defining attribute.","zh":"冷靜是她的決定性特質。"},{"en":"She attributes her clarity to rest.","zh":"她把她的清晰歸因於休息。"},{"en":"Attribute outcomes honestly.","zh":"誠實地歸因結果。"}]},{"word":"correlate","pos":"verb","chinese":"相關","level":"B2","sentences":[{"en":"Sleep correlates with mood.","zh":"睡眠與情緒相關。"},{"en":"Effort correlates with results.","zh":"努力與結果相關。"},{"en":"These factors correlate strongly.","zh":"這些因素強烈相關。"},{"en":"Happiness correlates with connection.","zh":"幸福與連結相關。"},{"en":"She noticed the two correlate.","zh":"她注意到兩者相關。"},{"en":"Stress correlates with poor sleep.","zh":"壓力與睡眠不足相關。"},{"en":"Consistency correlates with mastery.","zh":"一致性與精通相關。"},{"en":"Do not confuse correlation with cause.","zh":"不要混淆相關和原因。"},{"en":"Rest correlates with creativity.","zh":"休息與創造力相關。"},{"en":"These trends clearly correlate.","zh":"這些趨勢明顯相關。"}]},{"word":"differentiate","pos":"verb","chinese":"區分","level":"B2","sentences":[{"en":"She differentiates needs from wants.","zh":"她區分需要和想要。"},{"en":"Differentiate facts from feelings.","zh":"區分事實和感受。"},{"en":"He differentiates effort from outcome.","zh":"他區分努力和結果。"},{"en":"Differentiate yourself through values.","zh":"通過價值觀區分自己。"},{"en":"She differentiates busy from productive.","zh":"她區分忙碌和有生產力。"},{"en":"Differentiate signal from noise.","zh":"區分信號和噪音。"},{"en":"He learned to differentiate the two.","zh":"他學會了區分兩者。"},{"en":"Differentiate urgent from important.","zh":"區分緊急和重要。"},{"en":"She differentiates clearly and calmly.","zh":"她清晰冷靜地區分。"},{"en":"Differentiate growth from comfort.","zh":"區分成長和舒適。"}]},{"word":"facilitate","pos":"verb","chinese":"促進","level":"B2","sentences":[{"en":"She facilitates open conversation.","zh":"她促進開放的對話。"},{"en":"Good systems facilitate growth.","zh":"好的系統促進成長。"},{"en":"He facilitated the meeting smoothly.","zh":"他順利地主持了會議。"},{"en":"Facilitate, do not control.","zh":"促進，不要控制。"},{"en":"She facilitates learning gently.","zh":"她溫和地促進學習。"},{"en":"Trust facilitates collaboration.","zh":"信任促進合作。"},{"en":"He facilitates rather than dictates.","zh":"他促進而不是支配。"},{"en":"Facilitate connection between people.","zh":"促進人們之間的連結。"},{"en":"She facilitated a hard discussion.","zh":"她促進了一場艱難的討論。"},{"en":"Good design facilitates ease.","zh":"好的設計促進輕鬆。"}]},{"word":"compel","pos":"verb","chinese":"驅使；迫使","level":"B2","sentences":[{"en":"Her honesty compels respect.","zh":"她的誠實贏得尊重。"},{"en":"He felt compelled to help.","zh":"他感到被驅使去幫助。"},{"en":"A good story compels attention.","zh":"好的故事吸引注意。"},{"en":"She was compelled by curiosity.","zh":"她被好奇心驅使。"},{"en":"Compelling reasons drive action.","zh":"令人信服的理由驅動行動。"},{"en":"He made a compelling case.","zh":"他提出了一個令人信服的論點。"},{"en":"Curiosity compels us forward.","zh":"好奇心驅使我們前進。"},{"en":"Her vision is genuinely compelling.","zh":"她的願景真正令人信服。"},{"en":"He felt compelled to speak up.","zh":"他感到被驅使去發言。"},{"en":"A compelling why sustains effort.","zh":"一個令人信服的為什麼維持努力。"}]},{"word":"endeavour","pos":"verb/noun","chinese":"努力；事業","level":"B2","sentences":[{"en":"She endeavours to improve daily.","zh":"她努力每天改進。"},{"en":"A worthy endeavour takes time.","zh":"值得的事業需要時間。"},{"en":"He endeavoured to be fair.","zh":"他努力公平。"},{"en":"Every endeavour begins with a step.","zh":"每個事業都從一步開始。"},{"en":"She endeavours to listen more.","zh":"她努力多傾聽。"},{"en":"Their endeavour finally succeeded.","zh":"他們的努力終於成功了。"},{"en":"He endeavoured to understand.","zh":"他努力理解。"},{"en":"A creative endeavour needs courage.","zh":"創意的事業需要勇氣。"},{"en":"She poured herself into the endeavour.","zh":"她全身心投入這項事業。"},{"en":"Endeavour with patience and heart.","zh":"以耐心和真心努力。"}]},{"word":"aspire","pos":"verb","chinese":"渴望；立志","level":"B2","sentences":[{"en":"She aspires to live with purpose.","zh":"她渴望有目的地生活。"},{"en":"Aspire to grow, not to impress.","zh":"渴望成長，而不是給人印象。"},{"en":"He aspires to genuine kindness.","zh":"他渴望真正的善良。"},{"en":"Aspire high, stay grounded.","zh":"渴望高遠，保持腳踏實地。"},{"en":"She aspires to make a difference.","zh":"她渴望有所不同。"},{"en":"Aspire to be useful, not famous.","zh":"渴望有用，而不是出名。"},{"en":"He aspired to quiet excellence.","zh":"他渴望安靜的卓越。"},{"en":"Aspire and then take action.","zh":"渴望，然後採取行動。"},{"en":"She aspires to inner peace.","zh":"她渴望內心的平靜。"},{"en":"Aspire to become your truest self.","zh":"渴望成為你最真實的自我。"}]},{"word":"discern","pos":"verb","chinese":"辨別","level":"B2","sentences":[{"en":"She discerns truth from noise.","zh":"她辨別真相和噪音。"},{"en":"Discern what matters most.","zh":"辨別什麼最重要。"},{"en":"He discerns intentions quickly.","zh":"他迅速辨別意圖。"},{"en":"Discerning takes wisdom.","zh":"辨別需要智慧。"},{"en":"She discerned the real problem.","zh":"她辨別了真正的問題。"},{"en":"Discern good advice from bad.","zh":"辨別好建議和壞建議。"},{"en":"He discerned her true feelings.","zh":"他辨別了她真正的感受。"},{"en":"Discerning people listen well.","zh":"善於辨別的人傾聽得好。"},{"en":"She discerns nuance easily.","zh":"她容易辨別細微差別。"},{"en":"Discern, then decide.","zh":"辨別，然後決定。"}]},{"word":"transcend","pos":"verb","chinese":"超越","level":"B2","sentences":[{"en":"She transcended her circumstances.","zh":"她超越了她的處境。"},{"en":"Great art transcends time.","zh":"偉大的藝術超越時間。"},{"en":"He transcended his early failures.","zh":"他超越了他早期的失敗。"},{"en":"Love transcends distance.","zh":"愛超越距離。"},{"en":"She transcended fear through action.","zh":"她通過行動超越恐懼。"},{"en":"Transcend the need for approval.","zh":"超越對認可的需要。"},{"en":"He transcended his limits.","zh":"他超越了他的極限。"},{"en":"True connection transcends words.","zh":"真正的連結超越言語。"},{"en":"She transcended the ordinary.","zh":"她超越了平凡。"},{"en":"Transcend comparison; run your own race.","zh":"超越比較；跑你自己的賽道。"}]},{"word":"resilient","pos":"adjective","chinese":"有韌性的","level":"B2","sentences":[{"en":"She is remarkably resilient.","zh":"她非常有韌性。"},{"en":"Resilient people recover and grow.","zh":"有韌性的人恢復並成長。"},{"en":"He stayed resilient through it all.","zh":"他在一切中保持韌性。"},{"en":"Resilient does not mean unbreakable.","zh":"有韌性不意味著堅不可摧。"},{"en":"She built a resilient mindset.","zh":"她建立了有韌性的心態。"},{"en":"Resilient systems bend, not break.","zh":"有韌性的系統彎曲，而不斷裂。"},{"en":"He became more resilient each year.","zh":"他每年變得更有韌性。"},{"en":"Resilient hope survives hard times.","zh":"有韌性的希望在艱難時期存活。"},{"en":"She is gentle yet resilient.","zh":"她溫柔但有韌性。"},{"en":"Resilient people ask for help too.","zh":"有韌性的人也尋求幫助。"}]}];
